{
  "@context": {
    "@version": 1.1,
    "test": "http://example.com/context#",
    "testPredicate": { "@id": "test:predicate" }
  }
}

@prefix foaf: <http://xmlns.com/foaf/0.1/>.
@prefix solid: <http://www.w3.org/ns/solid/terms#>.

<>
    a foaf:PersonalProfileDocument;
    foaf:maker <http://localhost:6999/test/profile/card#me>;
    foaf:primaryTopic <http://localhost:6999/test/profile/card#me>.

<http://localhost:6999/test/profile/card#me>

    solid:oidcIssuer <http://localhost:6999/>;
    a foaf:Person.

@prefix acl: <http://www.w3.org/ns/auth/acl#>.
@prefix foaf: <http://xmlns.com/foaf/0.1/>.

<#public>
    a acl:Authorization;
    acl:agentClass foaf:Agent;
    acl:accessTo <./card>;
    acl:mode acl:Read.

PREFIX : <https://ruben.verborgh.org/profile/#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

:me a foaf:Person;
    foaf:name  "Ruben Verborgh"@en;
    foaf:homepage <https://ruben.verborgh.org/>.

# Root ACL resource for the agent account
@prefix acl: <http://www.w3.org/ns/auth/acl#>.
@prefix foaf: <http://xmlns.com/foaf/0.1/>.

# The homepage is readable by the public
<#public>
    a acl:Authorization;
    acl:agentClass foaf:Agent;
    acl:accessTo <./>;
    acl:mode acl:Read.

# The owner has full access to every resource in their pod.
# Other agents have no access rights,
# unless specifically authorized in other .acl resources.
<#owner>
    a acl:Authorization;
    acl:agent <{{webId}}>;
    # Optional owner email, to be used for account recovery:
    {{#if email}}acl:agent <mailto:{{{email}}}>;{{/if}}
    # Set the access to the root storage folder itself
    acl:accessTo <./>;
    # All resources will inherit this authorization, by default
    acl:default <./>;
    # The owner has all of the access modes allowed
    acl:mode
        acl:Read, acl:Write, acl:Control.

@prefix foaf: <http://xmlns.com/foaf/0.1/>.

<{{webId}}>
    a foaf:Person;
    foaf:name "{{name}}".

#!/usr/bin/env ts-node
/* eslint-disable no-console */
import fetch from 'cross-fetch';
import urljoin from 'url-join';

if (process.argv.length !== 3) {
  throw new Error('Exactly 1 parameter is needed: the server URL.');
}

const baseUrl = process.argv[2];

type User = {
  email: string;
  password: string;
  podName: string;
};

const alice: User = {
  email: 'alice@example.com',
  password: 'alice-secret',
  podName: 'alice',
};

const bob: User = {
  email: 'bob@example.com',
  password: 'bob-secret',
  podName: 'bob',
};

/**
 * Registers a user with the server and provides them with a pod.
 *
 * @param user - The user settings necessary to register a user.
 */
async function register(user: User): Promise<{ webId: string; authorization: string }> {
  // Get controls
  let res = await fetch(urljoin(baseUrl, '.account/'));
  let { controls } = await res.json();

  // Create account
  res = await fetch(controls.account.create, { method: 'POST' });
  if (res.status !== 200) {
    throw new Error(`Account creation failed: ${await res.text()}`);
  }
  const authorization = `CSS-Account-Token ${(await res.json()).authorization}`;

  // Get account controls
  res = await fetch(controls.main.index, {
    headers: { authorization },
  });
  ({ controls } = await res.json());

  // Add login method
  res = await fetch(controls.password.create, {
    method: 'POST',
    headers: { authorization, 'content-type': 'application/json' },
    body: JSON.stringify({
      email: user.email,
      password: user.password,
    }),
  });
  if (res.status !== 200) {
    throw new Error(`Login creation failed: ${await res.text()}`);
  }

  // Create pod
  res = await fetch(controls.account.pod, {
    method: 'POST',
    headers: { authorization, 'content-type': 'application/json' },
    body: JSON.stringify({ name: user.podName }),
  });
  if (res.status !== 200) {
    throw new Error(`Pod creation failed: ${await res.text()}`);
  }
  const { webId } = await res.json();

  return { webId, authorization };
}

/**
 * Requests a client credentials API token.
 *
 * @param webId - WebID to create credentials for.
 * @param authorization - Authorization header for the account that tries to create credentials.
 *
 * @returns The id/secret for the client credentials request.
 */
async function createCredentials(webId: string, authorization: string): Promise<{ id: string; secret: string }> {
  let res = await fetch(urljoin(baseUrl, '.account/'), {
    headers: { authorization },
  });
  const { controls } = await res.json();

  res = await fetch(controls.account.clientCredentials, {
    method: 'POST',
    headers: { authorization, 'content-type': 'application/json' },
    body: JSON.stringify({ name: 'token', webId }),
  });
  if (res.status !== 200) {
    throw new Error(`Token generation failed: ${await res.text()}`);
  }

  return res.json();
}

/**
 * Generates all the necessary data and outputs the necessary lines
 * that need to be added to the CTH environment file
 * so it can use client credentials.
 *
 * @param user - User for which data needs to be generated.
 */
async function outputCredentials(user: User): Promise<void> {
  const { webId, authorization } = await register(user);
  const { id, secret } = await createCredentials(webId, authorization);

  const name = user.podName.toUpperCase();
  console.log(`USERS_${name}_CLIENTID=${id}`);
  console.log(`USERS_${name}_CLIENTSECRET=${secret}`);
}

/**
 * Ends the process and writes out an error in case something goes wrong.
 */
function endProcess(error: Error): never {
  console.error(error);
  process.exit(1);
}

// Create tokens for Alice and Bob
outputCredentials(alice).catch(endProcess);
outputCredentials(bob).catch(endProcess);

{
  "extends": "../../tsconfig.json",
  "include": [
    "."
  ]
}

import fetch from 'cross-fetch';
import { parse, splitCookiesString } from 'set-cookie-parser';
import { BasicRepresentation } from '../../src/http/representation/BasicRepresentation';
import type { App } from '../../src/init/App';
import type { ResourceStore } from '../../src/storage/ResourceStore';
import { APPLICATION_X_WWW_FORM_URLENCODED } from '../../src/util/ContentTypes';
import { joinUrl } from '../../src/util/PathUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, getTestFolder, instantiateFromConfig, removeFolder } from './Config';

const port = getPort('Accounts');
const baseUrl = `http://localhost:${port}/`;

const rootFilePath = getTestFolder('Accounts');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    config: 'memory-pod.json',
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    config: 'file-pod.json',
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

// Don't send actual e-mails
jest.mock('nodemailer');

describe.each(stores)('A server with account management using %s', (name, { config, teardown }): void => {
  let app: App;
  let store: ResourceStore;
  let sendMail: jest.Mock;

  const publicContainer = joinUrl(baseUrl, '/public/');
  let cookie: string;
  const email = 'test@example.com';
  let password = 'secret';
  const indexUrl = joinUrl(baseUrl, '.account/');
  let controls: {
    main: Record<'index' | 'logins', string>;
    account: Record<'create' | 'logout' | 'pod' | 'webId' | 'clientCredentials', string>;
    password: Record<'login' | 'forgot' | 'create', string>;
  };
  let passwordResource: string;
  let pod: string;
  let podResource: string;
  let webId: string;

  beforeAll(async(): Promise<void> => {
    // Needs to happen before Components.js instantiation
    sendMail = jest.fn();
    const nodemailer = jest.requireMock('nodemailer');
    Object.assign(nodemailer, { createTransport: (): any => ({ sendMail }) });

    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath(config),
      {
        ...getDefaultVariables(port, baseUrl),
        'urn:solid-server:default:variable:rootFilePath': rootFilePath,
      },
    ) as Record<string, any>;
    ({ app, store } = instances);
    await app.start();

    // Create a public container where we can write any data
    await store.setRepresentation(
      { path: joinUrl(publicContainer, '.acl') },
      new BasicRepresentation(
        `@prefix acl: <http://www.w3.org/ns/auth/acl#>.
        @prefix foaf: <http://xmlns.com/foaf/0.1/>.
        <#public>
          a acl:Authorization;
          acl:agentClass foaf:Agent;
          acl:accessTo <./>;
          acl:default <./>;
          acl:mode acl:Read, acl:Write, acl:Control.`,
        'text/turtle',
      ),
    );

    controls = { main: {}, account: {}, login: {}, password: {}} as any;
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('can get the general index.', async(): Promise<void> => {
    const res = await fetch(indexUrl);
    expect(res.status).toBe(200);
    const json = await res.json();

    expect(json.controls.main.index).toBe(indexUrl);
    expect(json.controls.main.logins).toBeDefined();
    controls.main = json.controls.main;

    expect(json.controls.account.create).toBeDefined();
    controls.account = json.controls.account;

    expect(json.controls.password.login).toBeDefined();
    expect(json.controls.password.forgot).toBeDefined();
    controls.password = json.controls.password;

    expect(json.controls.html).toBeDefined();
    expect(json.controls.html.main).toBeDefined();
    expect(json.controls.html.password).toBeDefined();
  });

  it('can create an account.', async(): Promise<void> => {
    const res = await fetch(controls.account.create, { method: 'POST' });
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(res.headers.get('set-cookie')).toBeDefined();
    const cookies = parse(splitCookiesString(res.headers.get('set-cookie')!));
    expect(cookies).toHaveLength(1);

    cookie = `${cookies[0].name}=${cookies[0].value}`;
    expect(json.authorization).toBe(cookies[0].value);
  });

  it('can only access the account controls the cookie.', async(): Promise<void> => {
    const res = await fetch(indexUrl, { headers: { cookie }});
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json.controls.account.logout).toBeDefined();
    expect(json.controls.account.pod).toBeDefined();
    expect(json.controls.account.webId).toBeDefined();
    expect(json.controls.account.clientCredentials).toBeDefined();

    expect((await fetch(json.controls.account.pod)).status).toBe(401);

    controls.account = json.controls.account;

    expect(json.controls.password.create).toBeDefined();
    controls.password = json.controls.password;

    expect(json.controls.html.account).toBeDefined();
  });

  it('can also access the account controls using the custom authorization header.', async(): Promise<void> => {
    const res = await fetch(indexUrl, { headers:
        { authorization: `CSS-Account-Token ${cookie.split('=')[1]}` }});
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json.controls.account.pod).toEqual(controls.account.pod);
  });

  it('can not create a pod since the account has no login.', async(): Promise<void> => {
    const res = await fetch(controls.account.pod, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ name: 'test' }),
    });
    expect(res.status).toBe(400);
    expect((await res.json()).message).toBe('An account needs at least 1 login method.');
  });

  it('can add a password login to the account.', async(): Promise<void> => {
    let res = await fetch(controls.password.create, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({
        email,
        password,
      }),
    });
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json.resource).toBeDefined();
    ({ resource: passwordResource } = json);

    // Verify if the content was added to the account
    res = await fetch(controls.password.create, { headers: { cookie }});
    expect(res.status).toBe(200);
    expect((await res.json()).passwordLogins).toEqual({ [email]: passwordResource });
  });

  it('can not delete its last login method.', async(): Promise<void> => {
    const res = await fetch(passwordResource, { method: 'DELETE', headers: { cookie }});
    expect(res.status).toBe(400);
    expect((await res.json()).message).toBe('An account needs at least 1 login method.');
  });

  it('can not use the same email for a different account.', async(): Promise<void> => {
    let res = await fetch(controls.account.create, { method: 'POST' });
    const cookies = parse(splitCookiesString(res.headers.get('set-cookie')!));
    const newCookie = `${cookies[0].name}=${cookies[0].value}`;

    res = await fetch(indexUrl, { headers: { cookie: newCookie }});
    expect(res.status).toBe(200);
    const newControls: typeof controls = (await res.json()).controls;

    // This will fail because the email address is already used by a different account
    res = await fetch(newControls.password.create, {
      method: 'POST',
      headers: { cookie: newCookie, 'content-type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    expect(res.status).toBe(400);

    // Make sure the account still has no login method
    res = await fetch(newControls.password.create, { headers: { cookie: newCookie }});
    expect((await res.json()).passwordLogins).toEqual({});
  });

  it('can log out.', async(): Promise<void> => {
    const res = await fetch(controls.account.logout, { method: 'POST', headers: { cookie }});
    expect(res.status).toBe(200);
    // Cookie doesn't work anymore
    expect((await fetch(controls.account.pod, { headers: { cookie }})).status).toBe(401);
  });

  it('can login again with email/password.', async(): Promise<void> => {
    const res = await fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    expect(res.status).toBe(200);

    const cookies = parse(splitCookiesString(res.headers.get('set-cookie')!));
    expect(cookies).toHaveLength(1);
    cookie = `${cookies[0].name}=${cookies[0].value}`;
    // Cookie is valid again
    expect((await fetch(controls.account.pod, { headers: { cookie }})).status).toBe(200);
  });

  it('can change the password.', async(): Promise<void> => {
    let res = await fetch(passwordResource, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({
        oldPassword: password,
        newPassword: 'secret2',
      }),
    });
    password = 'secret2';
    expect(res.status).toBe(200);

    // Check new password
    res = await fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    expect(res.status).toBe(200);
    expect(res.headers.get('set-cookie')).toBeDefined();
  });

  it('can create a pod.', async(): Promise<void> => {
    let res = await fetch(controls.account.pod, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ name: 'test' }),
    });
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json.pod).toBeDefined();
    expect(json.podResource).toBeDefined();
    expect(json.webId).toBeDefined();
    expect(json.webIdResource).toBeDefined();
    ({ pod, webId, podResource } = json);

    // Verify if the content was added to the profile
    res = await fetch(controls.account.pod, { headers: { cookie }});
    expect(res.status).toBe(200);
    expect((await res.json()).pods[pod]).toBeDefined();
    res = await fetch(controls.account.webId, { headers: { cookie }});
    expect(res.status).toBe(200);
    expect((await res.json()).webIdLinks[webId]).toBeDefined();
  });

  it('can not remove the last owner of a pod.', async(): Promise<void> => {
    const res = await fetch(podResource, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ webId, remove: true }),
    });
    expect(res.status).toBe(400);
    await expect(res.text()).resolves.toContain('Unable to remove the last owner of a pod.');
  });

  it('can add an owner to a pod.', async(): Promise<void> => {
    let res = await fetch(podResource, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ webId: 'http://example.com/other/webID', visible: true }),
    });
    expect(res.status).toBe(200);

    // Verify that the new owner was added
    res = await fetch(podResource, { headers: { cookie }});
    expect(res.status).toBe(200);
    expect((await res.json()).owners).toEqual([
      { webId, visible: false },
      { webId: 'http://example.com/other/webID', visible: true },
    ]);

    // Verify only the new owner is exposed through a link header
    res = await fetch(pod);
    expect(res.status).toBe(200);
    const owners = res.headers.get('link')?.split(',')
      .filter((header): boolean => header.includes('rel="http://www.w3.org/ns/solid/terms#owner"'))
      .map((header): string => /<([^>]+)>/u.exec(header)![1]);
    expect(owners).toEqual([ 'http://example.com/other/webID' ]);
  });

  it('can update the visibility of an existing pod owner.', async(): Promise<void> => {
    let res = await fetch(podResource, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ webId, visible: true }),
    });
    expect(res.status).toBe(200);

    // Verify that the visibility was changed
    res = await fetch(podResource, { headers: { cookie }});
    expect(res.status).toBe(200);
    expect((await res.json()).owners).toEqual([
      { webId, visible: true },
      { webId: 'http://example.com/other/webID', visible: true },
    ]);

    // Verify both WebIDs are now visible
    res = await fetch(pod);
    expect(res.status).toBe(200);
    const owners = res.headers.get('link')?.split(',')
      .filter((header): boolean => header.includes('rel="http://www.w3.org/ns/solid/terms#owner"'))
      .map((header): string => /<([^>]+)>/u.exec(header)![1]);
    expect(owners).toEqual([ webId, 'http://example.com/other/webID' ]);
  });

  it('can remove an owner from a pod.', async(): Promise<void> => {
    let res = await fetch(podResource, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ webId: 'http://example.com/other/webID', remove: true }),
    });
    expect(res.status).toBe(200);

    // Verify that the new owner was added
    res = await fetch(podResource, { headers: { cookie }});
    expect(res.status).toBe(200);
    expect((await res.json()).owners).toEqual([
      { webId, visible: true },
    ]);
  });

  it('does not store any data if creating a pod fails on the same account.', async(): Promise<void> => {
    const oldPods = (await (await fetch(controls.account.pod, { headers: { cookie }})).json()).pods;
    const oldWebIdLinks = (await (await fetch(controls.account.webId, { headers: { cookie }})).json()).webIdLinks;

    const res = await fetch(controls.account.pod, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ name: 'test' }),
    });
    expect(res.status).toBe(400);

    // Verify nothing was added
    const newPods = (await (await fetch(controls.account.pod, { headers: { cookie }})).json()).pods;
    const newWebIdLinks = (await (await fetch(controls.account.webId, { headers: { cookie }})).json()).webIdLinks;
    expect(oldPods).toEqual(newPods);
    expect(oldWebIdLinks).toEqual(newWebIdLinks);
  });

  it('does not store any data if creating a pod fails on a different account.', async(): Promise<void> => {
    // We have to create a new account here to try to create a pod with the same name.
    // Otherwise, the server will never try to write data
    // since it would notice the account already has a pod with that name.
    let res = await fetch(controls.account.create, { method: 'POST' });
    const cookies = parse(splitCookiesString(res.headers.get('set-cookie')!));
    const newCookie = `${cookies[0].name}=${cookies[0].value}`;
    res = await fetch(indexUrl, { headers: { cookie: newCookie }});
    const json: { controls: typeof controls } = await res.json();
    res = await fetch(json.controls.password.create, {
      method: 'POST',
      headers: { cookie: newCookie, 'content-type': 'application/json' },
      body: JSON.stringify({
        email: 'differentMail@example.com',
        password,
      }),
    });
    expect(res.status).toBe(200);

    const oldPods = (await (await fetch(controls.account.pod, { headers: { cookie: newCookie }})).json()).pods;
    const oldWebIdLinks = (await (await fetch(controls.account.webId, { headers: { cookie: newCookie }})).json())
      .webIdLinks;

    // This will fail because there already is a pod with this name
    res = await fetch(json.controls.account.pod, {
      method: 'POST',
      headers: { cookie: newCookie, 'content-type': 'application/json' },
      body: JSON.stringify({ name: 'test' }),
    });
    expect(res.status).toBe(400);
    expect((await res.json()).message).toContain('Pod creation failed');

    // Make sure there is no reference in the account data
    const newPods = (await (await fetch(controls.account.pod, { headers: { cookie: newCookie }})).json()).pods;
    const newWebIdLinks = (await (await fetch(controls.account.webId, { headers: { cookie: newCookie }})).json())
      .webIdLinks;
    expect(oldPods).toEqual(newPods);
    expect(oldWebIdLinks).toEqual(newWebIdLinks);
  });

  it('can remove the WebID link.', async(): Promise<void> => {
    let res = await fetch(controls.account.webId, { headers: { cookie }});
    const webIdResource = (await res.json()).webIdLinks[webId];
    res = await fetch(webIdResource, { method: 'DELETE', headers: { cookie }});
    expect(res.status).toBe(200);
    res = await fetch(controls.account.webId, { headers: { cookie }});
    expect((await res.json()).webIdLinks[webId]).toBeUndefined();
  });

  it('can link the WebID again.', async(): Promise<void> => {
    let res = await fetch(controls.account.webId, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ webId }),
    });
    expect(res.status).toBe(200);
    let json = await res.json();
    expect(json.resource).toBeDefined();
    expect(json.oidcIssuer).toBe(baseUrl);

    // Verify if the content was added to the profile
    res = await fetch(controls.account.webId, { headers: { cookie }});
    expect(res.status).toBe(200);
    json = await res.json();
    expect(json.webIdLinks[webId]).toBeDefined();
  });

  it('needs to prove ownership when linking a WebID outside of a pod.', async(): Promise<void> => {
    const otherWebId = joinUrl(publicContainer, 'other#me');
    // Create the WebID
    let res = await fetch(otherWebId, {
      method: 'PUT',
      headers: { 'content-type': 'text/turtle' },
      body: '',
    });
    expect(res.status).toBe(201);

    // Try to link the WebID
    res = await fetch(controls.account.webId, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ webId: otherWebId }),
    });
    expect(res.status).toBe(400);
    let json = await res.json();
    expect(json.details?.quad).toBeDefined();
    const { quad } = json.details;

    // Update the WebID with the identifying quad
    await fetch(otherWebId, {
      method: 'PUT',
      headers: { 'content-type': 'text/turtle' },
      body: quad,
    });

    // Try to link the WebID again
    res = await fetch(controls.account.webId, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ webId: otherWebId }),
    });
    expect(res.status).toBe(200);

    // Verify if the content was added to the profile
    res = await fetch(controls.account.webId, { headers: { cookie }});
    expect(res.status).toBe(200);
    json = await res.json();
    // 2 linked WebIDs now
    expect(json.webIdLinks[webId]).toBeDefined();
    expect(json.webIdLinks[otherWebId]).toBeDefined();
  });

  it('can create a client credentials token.', async(): Promise<void> => {
    let res = await fetch(controls.account.clientCredentials, {
      method: 'POST',
      headers: { cookie, 'content-type': 'application/json' },
      body: JSON.stringify({ name: 'token', webId }),
    });
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json.id).toMatch(/^token/u);
    expect(json.secret).toBeDefined();
    expect(json.resource).toBeDefined();
    const { id, resource, secret } = json;

    // Verify if the content was added to the profile
    res = await fetch(controls.account.clientCredentials, { headers: { cookie }});
    expect(res.status).toBe(200);
    const { clientCredentials } = await res.json();
    expect(clientCredentials[id]).toBe(resource);

    // Request a token
    const authString = `${encodeURIComponent(id)}:${encodeURIComponent(secret)}`;
    res = await fetch(joinUrl(baseUrl, '.oidc/token'), {
      method: 'POST',
      headers: {
        authorization: `Basic ${Buffer.from(authString).toString('base64')}`,
        'content-type': APPLICATION_X_WWW_FORM_URLENCODED,
      },
      body: 'grant_type=client_credentials&scope=webid',
    });
    expect(res.status).toBe(200);
    const { access_token: token } = await res.json();
    expect(token).toBeDefined();
  });

  it('can remove registered WebIDs.', async(): Promise<void> => {
    let res = await fetch(controls.account.webId, { headers: { cookie }});
    expect(res.status).toBe(200);
    let json = await res.json();

    res = await fetch(json.webIdLinks[webId], { method: 'DELETE', headers: { cookie }});
    expect(res.status).toBe(200);

    // Make sure it's gone
    res = await fetch(controls.account.webId, { headers: { cookie }});
    json = await res.json();
    expect(json.webIdLinks[webId]).toBeUndefined();
  });

  it('can remove credential tokens.', async(): Promise<void> => {
    let res = await fetch(controls.account.clientCredentials, { headers: { cookie }});
    expect(res.status).toBe(200);
    let json = await res.json();

    const tokenUrl = Object.values(json.clientCredentials)[0] as string;
    res = await fetch(tokenUrl, { method: 'DELETE', headers: { cookie }});
    expect(res.status).toBe(200);

    // Make sure it's gone
    res = await fetch(controls.account.clientCredentials, { headers: { cookie }});
    json = await res.json();
    expect(Object.keys(json.clientCredentials)).toHaveLength(0);
  });

  it('can reset a password if forgotten.', async(): Promise<void> => {
    let res = await fetch(controls.password.forgot, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email }),
    });
    expect(res.status).toBe(200);

    expect(sendMail).toHaveBeenCalledTimes(1);

    // Parse reset URL out of mail
    const mail = sendMail.mock.calls[0][0];
    expect(mail.to).toBe(email);
    const match = /(http:.*)$/u.exec(mail.text);
    expect(match).toBeDefined();
    const resetUrl = match![1];
    res = await fetch(resetUrl);
    const url = new URL(resetUrl);
    const recordId = url.searchParams.get('rid');
    expect(recordId).toBeDefined();

    // Reset the password
    password = 'resetSecret';
    res = await fetch(resetUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ recordId, password }),
    });
    expect(res.status).toBe(200);

    // Verify logging in with the new password works
    res = await fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    expect(res.status).toBe(200);
    expect(res.headers.get('set-cookie')).toBeDefined();
  });
});

import fetch from 'cross-fetch';
import { BasicRepresentation } from '../../src/http/representation/BasicRepresentation';
import type { App } from '../../src/init/App';
import type { ResourceStore } from '../../src/storage/ResourceStore';
import { joinUrl } from '../../src/util/PathUtil';
import { AcpHelper } from '../util/AcpHelper';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';

const port = getPort('AcpServer');
const baseUrl = `http://localhost:${port}/`;

const rootFilePath = getTestFolder('full-config-acp');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    storeConfig: 'storage/backend/memory.json',
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    storeConfig: 'storage/backend/file.json',
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

describe.each(stores)('An LDP handler with ACP using %s', (name, { storeConfig, teardown }): void => {
  let app: App;
  let store: ResourceStore;
  let acpHelper: AcpHelper;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getPresetConfigPath(storeConfig),
        getTestConfigPath('ldp-with-acp.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app, store } = instances);

    await app.start();

    // Create test helper for manipulating acl
    acpHelper = new AcpHelper(store);
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('provides no access if no ACRs are defined.', async(): Promise<void> => {
    const response = await fetch(baseUrl);
    expect(response.status).toBe(401);
  });

  it('provides access if the correct ACRs are defined.', async(): Promise<void> => {
    await acpHelper.setAcp(baseUrl, acpHelper.createAcr({
      resource: baseUrl,
      policies: [ acpHelper.createPolicy({
        allow: [ 'read' ],
        anyOf: [ acpHelper.createMatcher({ publicAgent: true }) ],
      }) ],
    }));
    const response = await fetch(baseUrl);
    expect(response.status).toBe(200);
  });

  it('uses ACP inheritance.', async(): Promise<void> => {
    const target = joinUrl(baseUrl, 'foo');
    await store.setRepresentation({ path: target }, new BasicRepresentation('test', 'text/plain'));
    await acpHelper.setAcp(baseUrl, acpHelper.createAcr({
      resource: baseUrl,
      memberPolicies: [ acpHelper.createPolicy({
        allow: [ 'read' ],
        anyOf: [ acpHelper.createMatcher({ publicAgent: true }) ],
      }) ],
    }));
    await acpHelper.setAcp(target, acpHelper.createAcr({
      resource: baseUrl,
      policies: [ acpHelper.createPolicy({
        allow: [ 'write' ],
        anyOf: [ acpHelper.createMatcher({ publicAgent: true }) ],
      }) ],
    }));
    const response = await fetch(target);
    expect(response.status).toBe(200);
  });

  it('requires control permissions to access ACRs.', async(): Promise<void> => {
    const baseAcr = joinUrl(baseUrl, '.acr');
    const turtle = acpHelper.toTurtle(acpHelper.createAcr({
      resource: baseUrl,
      policies: [ acpHelper.createPolicy({
        allow: [ 'read' ],
        anyOf: [ acpHelper.createMatcher({ publicAgent: true }) ],
      }) ],
    }));
    let response = await fetch(baseAcr);
    expect(response.status).toBe(401);
    response = await fetch(baseAcr, { method: 'PUT', headers: { 'content-type': 'text/turtle' }, body: turtle });
    expect(response.status).toBe(401);

    await acpHelper.setAcp(baseUrl, acpHelper.createAcr({
      resource: baseUrl,
      policies: [ acpHelper.createPolicy({
        allow: [ 'control' ],
        anyOf: [ acpHelper.createMatcher({ publicAgent: true }) ],
      }) ],
    }));
    response = await fetch(baseAcr);
    expect(response.status).toBe(200);
    response = await fetch(baseAcr, { method: 'PUT', headers: { 'content-type': 'text/turtle' }, body: turtle });
    expect(response.status).toBe(205);
    // Can now also read root container due to updated permissions
    response = await fetch(baseUrl);
    expect(response.status).toBe(200);
  });

  it('returns the required Link headers.', async(): Promise<void> => {
    const baseAcr = joinUrl(baseUrl, '.acr');
    const response = await fetch(baseAcr, { method: 'OPTIONS' });
    const linkHeaders = response.headers.get('link');
    expect(linkHeaders).toContain('<http://www.w3.org/ns/solid/acp#AccessControlResource>; rel="type"');

    expect(linkHeaders).toContain('<http://www.w3.org/ns/auth/acl#Read>; rel="http://www.w3.org/ns/solid/acp#grant"');
    expect(linkHeaders).toContain('<http://www.w3.org/ns/auth/acl#Append>; rel="http://www.w3.org/ns/solid/acp#grant"');
    expect(linkHeaders).toContain('<http://www.w3.org/ns/auth/acl#Write>; rel="http://www.w3.org/ns/solid/acp#grant"');
    expect(linkHeaders).toContain('<http://www.w3.org/ns/auth/acl#Control>; rel="http://www.w3.org/ns/solid/acp#grant"');

    expect(linkHeaders).toContain('<http://www.w3.org/ns/solid/acp#target>; rel="http://www.w3.org/ns/solid/acp#attribute"');
    expect(linkHeaders).toContain('<http://www.w3.org/ns/solid/acp#agent>; rel="http://www.w3.org/ns/solid/acp#attribute"');
    expect(linkHeaders).toContain('<http://www.w3.org/ns/solid/acp#client>; rel="http://www.w3.org/ns/solid/acp#attribute"');
    expect(linkHeaders).toContain('<http://www.w3.org/ns/solid/acp#issuer>; rel="http://www.w3.org/ns/solid/acp#attribute"');
  });
});

import type { CliResolver } from '../../src/init/CliResolver';
import { resolveModulePath } from '../../src/util/PathUtil';
import { instantiateFromConfig } from './Config';

// Needed to prevent yargs from stopping the process on error
const error = jest.spyOn(console, 'error').mockImplementation(jest.fn());
const exit = jest.spyOn(process, 'exit').mockImplementation(jest.fn() as any);

describe('An instantiated CliResolver', (): void => {
  let cliResolver: CliResolver;

  beforeAll(async(): Promise<void> => {
    // Create the CliExtractor
    cliResolver = await instantiateFromConfig(
      'urn:solid-server-app-setup:default:CliResolver',
      resolveModulePath('config/default.json'),
    );
  });

  it('converts known abbreviations to the full parameter.', async(): Promise<void> => {
    /* eslint-disable antfu/consistent-list-newline */
    const shorthand = await cliResolver.cliExtractor.handleSafe([ 'node', 'server.js',
      '-c', 'c',
      '-m', 'm',
      '-l', 'l',
      '-b', 'b',
      '-p', '3000',
      '-f', 'f',
      '-t',
      '-s', 's',
      '-w', '2',
    ]);
    /* eslint-enable antfu/consistent-list-newline */
    expect(shorthand.config).toEqual([ 'c' ]);
    expect(shorthand.mainModulePath).toBe('m');
    expect(shorthand.loggingLevel).toBe('l');
    expect(shorthand.baseUrl).toBe('b');
    expect(shorthand.port).toBe(3000);
    expect(shorthand.rootFilePath).toBe('f');
    expect(shorthand.showStackTrace).toBe(true);
    expect(shorthand.sparqlEndpoint).toBe('s');
    expect(shorthand.workers).toBe(2);
  });

  it('errors on unknown parameters.', async(): Promise<void> => {
    await cliResolver.cliExtractor.handleSafe([ 'node', 'server.js', '-a', 'abc' ]);

    expect(exit).toHaveBeenCalledTimes(1);
    expect(error).toHaveBeenCalledWith('Unknown argument: a');
  });
});

import fetch from 'cross-fetch';
import { DataFactory } from 'n3';
import type { App } from '../../src/init/App';
import { deleteResource, expectQuads, getResource, patchResource, putResource } from '../util/FetchUtil';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';

const { namedNode, quad } = DataFactory;

const port = getPort('Conditions');
const baseUrl = `http://localhost:${port}/`;

// File stores handle last-modified dates differently so need to test both
const rootFilePath = getTestFolder('conditions');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    storeConfig: 'storage/backend/memory.json',
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    storeConfig: 'storage/backend/file.json',
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

function extractHeadersObject(response: Response): Record<string, string> {
  const result: Record<string, string> = {};
  // eslint-disable-next-line unicorn/no-array-for-each
  response.headers.forEach((value, key): void => {
    result[key] = value;
  });
  return result;
}

describe.each(stores)('A server supporting conditions with %s', (name, { storeConfig, teardown }): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getPresetConfigPath(storeConfig),
        getTestConfigPath('ldp-with-auth.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('prevents operations on existing resources with "if-none-match: *" header.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}document1.txt`;
    // PUT
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE' });

    // Overwrite fails because of header
    let response = await fetch(documentUrl, {
      method: 'PUT',
      headers: { 'content-type': 'text/plain', 'if-none-match': '*' },
      body: 'TESTFILE1',
    });
    expect(response.status).toBe(412);

    // Verify original contents stayed the same
    response = await getResource(documentUrl);
    await expect(response.text()).resolves.toBe('TESTFILE');

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('prevents creating new resources with "if-match: *" header.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}document2.txt`;
    const query = 'INSERT {<http://test.com/s1> <http://test.com/p1> <http://test.com/o1>} WHERE {}';

    // PATCH fails because of header
    let response = await fetch(documentUrl, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update', 'if-match': '*' },
      body: query,
    });
    expect(response.status).toBe(412);

    // PATCH
    await patchResource(documentUrl, query, 'sparql');

    // PATCH with header now succeeds
    const query2 = 'INSERT {<http://test.com/s2> <http://test.com/p2> <http://test.com/o2>} WHERE {}';
    response = await fetch(documentUrl, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update', 'if-match': '*' },
      body: query2,
    });
    expect(response.status).toBe(205);

    // Verify the contents got updated
    response = await getResource(documentUrl);
    const expected = [
      quad(namedNode('http://test.com/s1'), namedNode('http://test.com/p1'), namedNode('http://test.com/o1')),
      quad(namedNode('http://test.com/s2'), namedNode('http://test.com/p2'), namedNode('http://test.com/o2')),
    ];
    await expectQuads(response, expected, true);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('prevents operations if the "if-match" header does not match.', async(): Promise<void> => {
    // GET root ETag
    let response = await getResource(baseUrl);
    const eTag = response.headers.get('ETag');
    expect(typeof eTag).toBe('string');

    // POST fails because of header
    response = await fetch(baseUrl, {
      method: 'POST',
      headers: { 'content-type': 'text/plain', 'if-match': '"notAMatchingETag"' },
      body: 'TESTFILE',
    });
    expect(response.status).toBe(412);

    // POST succeeds with correct header
    response = await fetch(baseUrl, {
      method: 'POST',
      headers: { 'content-type': 'text/plain', 'if-match': eTag! },
      body: 'TESTFILE1',
    });
    expect(response.status).toBe(201);
    const documentUrl = response.headers.get('location');
    expect(typeof documentUrl).toBe('string');

    // DELETE
    await expect(deleteResource(documentUrl!)).resolves.toBeUndefined();
  });

  it('prevents operations if the "if-none-match" header does match.', async(): Promise<void> => {
    // GET root ETag
    let response = await getResource(baseUrl);
    const eTag = response.headers.get('ETag');
    expect(typeof eTag).toBe('string');

    // POST fails because of header
    response = await fetch(baseUrl, {
      method: 'POST',
      headers: { 'content-type': 'text/plain', 'if-none-match': eTag! },
      body: 'TESTFILE',
    });
    expect(response.status).toBe(412);

    // POST succeeds with correct header
    response = await fetch(baseUrl, {
      method: 'POST',
      headers: { 'content-type': 'text/plain', 'if-none-match': '"notAMatchingETag"' },
      body: 'TESTFILE1',
    });
    expect(response.status).toBe(201);
    const documentUrl = response.headers.get('location');
    expect(typeof documentUrl).toBe('string');

    // DELETE
    await expect(deleteResource(documentUrl!)).resolves.toBeUndefined();
  });

  it('throws 304 error if "if-none-match" header matches and request type is GET or HEAD.', async(): Promise<void> => {
    // GET root ETag
    let response = await getResource(baseUrl);
    const eTag = response.headers.get('ETag');
    const originalHeaders = extractHeadersObject(response);
    expect(typeof eTag).toBe('string');

    // GET fails because of header
    response = await fetch(baseUrl, {
      method: 'GET',
      headers: { 'if-none-match': eTag! },
    });
    expect(response.status).toBe(304);
    expect(response.headers.get('etag')).toBe(eTag);
    const newGetHeaders = extractHeadersObject(response);
    // Date field shouldn't be the same
    delete newGetHeaders.date;
    expect(expect.objectContaining(newGetHeaders)).toEqual(originalHeaders);

    // HEAD fails because of header
    response = await fetch(baseUrl, {
      method: 'HEAD',
      headers: { 'if-none-match': eTag! },
    });
    expect(response.status).toBe(304);
    expect(response.headers.get('etag')).toBe(eTag);
    const newHeadHeaders = extractHeadersObject(response);
    // Date field shouldn't be the same
    delete newHeadHeaders.date;
    expect(expect.objectContaining(newHeadHeaders)).toEqual(originalHeaders);

    // GET succeeds if the ETag header doesn't match
    response = await fetch(baseUrl, {
      method: 'GET',
      headers: { 'if-none-match': '"123456"' },
    });
    expect(response.status).toBe(200);
  });

  it('prevents operations if the "if-unmodified-since" header is before the modified date.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}document3.txt`;
    // PUT
    let response = await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE' });

    // GET last-modified header
    response = await getResource(documentUrl);
    const lastModifiedVal = response.headers.get('last-modified');
    expect(typeof lastModifiedVal).toBe('string');
    const lastModified = new Date(lastModifiedVal!);

    const oldDate = new Date(Date.now() - 10000);

    // DELETE fails because oldDate < lastModified
    response = await fetch(documentUrl, {
      method: 'DELETE',
      headers: { 'if-unmodified-since': oldDate.toUTCString() },
    });
    expect(response.status).toBe(412);

    // DELETE succeeds because lastModified date matches
    response = await fetch(documentUrl, {
      method: 'DELETE',
      headers: { 'if-unmodified-since': lastModified.toUTCString() },
    });
    expect(response.status).toBe(205);
  });

  it('returns different ETags for different content-types.', async(): Promise<void> => {
    let response = await getResource(baseUrl, { accept: 'text/turtle' }, { contentType: 'text/turtle' });
    const eTagTurtle = response.headers.get('ETag');
    const turtleHeaders = extractHeadersObject(response);
    response = await getResource(baseUrl, { accept: 'application/ld+json' }, { contentType: 'application/ld+json' });
    const eTagJson = response.headers.get('ETag');
    const jsonHeaders = extractHeadersObject(response);
    expect(eTagTurtle).not.toEqual(eTagJson);

    // Both ETags can be used on the same resource
    response = await fetch(baseUrl, { headers: { 'if-none-match': eTagTurtle!, accept: 'text/turtle' }});
    expect(response.status).toBe(304);
    expect(response.headers.get('etag')).toBe(eTagTurtle);
    const newTurtleHeaders = extractHeadersObject(response);
    // Date field shouldn't be the same
    delete newTurtleHeaders.date;
    expect(expect.objectContaining(newTurtleHeaders)).toEqual(turtleHeaders);

    response = await fetch(baseUrl, { headers: { 'if-none-match': eTagJson!, accept: 'application/ld+json' }});
    expect(response.status).toBe(304);
    expect(response.headers.get('etag')).toBe(eTagJson);
    const newJsonHeaders = extractHeadersObject(response);
    // Date field shouldn't be the same
    delete newJsonHeaders.date;
    expect(expect.objectContaining(newJsonHeaders)).toEqual(jsonHeaders);

    // But not for the other representation
    response = await fetch(baseUrl, { headers: { 'if-none-match': eTagTurtle!, accept: 'application/ld+json' }});
    expect(response.status).toBe(200);
  });

  it('updates the ETag if the metadata is changed.', async(): Promise<void> => {
    let response = await getResource(baseUrl);
    const originalETag = response.headers.get('ETag');
    expect(typeof originalETag).toBe('string');
    const linkHeaders = response.headers.get('link');
    expect(typeof linkHeaders).toBe('string');
    const regex = /<([^>]+)>; rel="describedby"/u.exec(linkHeaders!);
    expect(regex).toBeDefined();
    const metaUrl = regex![1];

    // Timestamp accuracy is at second level so need to make sure it changed
    await new Promise<void>((res): void => {
      setTimeout((): void => {
        res();
      }, 1000);
    });

    // PATCH .meta
    const query = 'INSERT {<http://test.com/s2> <http://test.com/p2> <http://test.com/o2>} WHERE {}';
    response = await fetch(metaUrl, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update' },
      body: query,
    });
    expect(response.status).toBeLessThan(300);

    // Check new eTag
    response = await getResource(baseUrl);
    const eTag = response.headers.get('ETag');
    expect(eTag).not.toEqual(originalETag);
  });
});

import type { IModuleState } from 'componentsjs';
import { ComponentsManager } from 'componentsjs';
import { remove } from 'fs-extra';
import { joinFilePath } from '../../src/util/PathUtil';

let cachedModuleState: IModuleState;

/**
 * Returns a component instantiated from a Components.js configuration.
 */
export async function instantiateFromConfig(
  componentUrl: string,
  configPaths: string | string[],
  variables?: Record<string, any>,
): Promise<any> {
  // Initialize the Components.js loader
  const mainModulePath = joinFilePath(__dirname, '../../');
  const manager = await ComponentsManager.build({
    mainModulePath,
    logLevel: 'error',
    moduleState: cachedModuleState,
    typeChecking: false,
  });
  cachedModuleState = manager.moduleState;

  if (!Array.isArray(configPaths)) {
    configPaths = [ configPaths ];
  }

  // Instantiate the component from the config(s)
  for (const configPath of configPaths) {
    await manager.configRegistry.register(configPath);
  }
  return manager.instantiate(componentUrl, { variables });
}

export function getTestConfigPath(configFile: string): string {
  return joinFilePath(__dirname, 'config', configFile);
}

export function getPresetConfigPath(configFile: string): string {
  return joinFilePath(__dirname, '../../config', configFile);
}

export function getTestFolder(name: string): string {
  return joinFilePath(__dirname, '../tmp', name);
}

export async function removeFolder(folder: string): Promise<void> {
  await remove(folder);
}

export function getDefaultVariables(port: number, baseUrl?: string): Record<string, any> {
  return {
    'urn:solid-server:default:variable:baseUrl': baseUrl ?? `http://localhost:${port}/`,
    'urn:solid-server:default:variable:port': port,
    'urn:solid-server:default:variable:socket': null,
    'urn:solid-server:default:variable:loggingLevel': 'off',
    'urn:solid-server:default:variable:showStackTrace': true,
    'urn:solid-server:default:variable:seedConfig': null,
    'urn:solid-server:default:variable:workers': 1,
    'urn:solid-server:default:variable:confirmMigration': false,
  };
}

