import assert from 'node:assert';
import fetch from 'cross-fetch';
import type { App } from '../../src/init/App';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, instantiateFromConfig } from './Config';

const port = getPort('ContentNegotiation');
const baseUrl = `http://localhost:${port}`;

const documents = [
  [ '/turtle', 'text/turtle', '# Test' ],
  [ '/markdown', 'text/markdown', '# Test' ],
  [ '/plain', 'text/plain; charset=utf-8', '# Test' ],
];

const cases: [string, string, string][] = [
  [ '/turtle', 'text/turtle', '' ],
  [ '/turtle', 'text/turtle', '*/*' ],
  [ '/turtle', 'text/turtle', 'text/html,*/*;q=0.1' ],
  [ '/turtle', 'application/json', 'application/json' ],
  [ '/turtle', 'application/ld+json', 'application/ld+json' ],
  [ '/turtle', 'application/octet-stream', 'application/octet-stream' ],
  [ '/markdown', 'text/markdown', '' ],
  [ '/markdown', 'text/markdown', '*/*' ],
  [ '/markdown', 'text/markdown', 'text/html,text/markdown' ],
  [ '/markdown', 'text/markdown', 'text/markdown;q=0.9, text/html;q=0.1' ],
  [ '/markdown', 'text/html', 'text/html' ],
  [ '/markdown', 'text/html', 'text/html,*/*;q=0.8' ],
  [ '/markdown', 'text/html', 'text/markdown;q=0.1, text/html;q=0.9' ],
  [ '/markdown', 'application/octet-stream', 'application/octet-stream' ],
  [ '/plain', 'text/plain; charset=utf-8', 'text/plain' ],
  [ '/plain', 'text/plain; charset=utf-8', 'text/plain;q=0.1, text/markdown;q=0.9' ],
];

describe('Content negotiation', (): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    // Start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath('server-memory.json'),
      getDefaultVariables(port, baseUrl),
    ) as Record<string, any>;
    ({ app } = instances);
    await app.start();

    // Create documents
    for (const [ slug, contentType, body ] of documents) {
      const res = await fetch(`${baseUrl}${slug}`, {
        method: 'PUT',
        headers: { 'content-type': contentType },
        body,
      });
      assert.strictEqual(res.status, 201);
    }
  });

  afterAll(async(): Promise<void> => {
    await app.stop();
  });

  describe.each(cases)('a request for %s', (name, expected, accept): void => {
    it(`results in ${expected} in response to Accept: ${accept}`, async(): Promise<void> => {
      const res = await fetch(`${baseUrl}${name}`, { headers: { accept }});
      expect(res.status).toBe(200);
      expect(res.headers.get('Content-Type')).toBe(expected);
    });
  });
});

import { mkdirSync } from 'node:fs';
import fetch from 'cross-fetch';
import type { App } from '../../src/init/App';
import { joinFilePath } from '../../src/util/PathUtil';
import { register } from '../util/AccountUtil';
import type { User } from '../util/AccountUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, getTestFolder, instantiateFromConfig, removeFolder } from './Config';

const port = getPort('DynamicPods');
const baseUrl = `http://localhost:${port}/`;
const rootFilePath = getTestFolder('dynamicPods');
const podConfigJson = joinFilePath(rootFilePath, 'config-pod.json');

const configs: [string, any][] = [
  [ 'memory.json', {
  // Need to remove the config-pod.json
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
  [ 'filesystem.json', {
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

// Using the actual templates instead of specific test ones to prevent a lot of duplication
// Tests are very similar to subdomain/pod tests. Would be nice if they can be combined
describe.each(configs)('A dynamic pod server with template config %s', (template, { teardown }): void => {
  let app: App;
  const user: User = {
    podName: 'alice',
    webId: 'http://example.com/#alice',
    email: 'alice@test.email',
    password: 'password',
    settings: {
      template,
    },
  };
  const podUrl = `${baseUrl}${user.podName}/`;
  let controls: any;
  let authorization: string;

  beforeAll(async(): Promise<void> => {
    const variables: Record<string, any> = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
      'urn:solid-server:default:variable:podConfigJson': podConfigJson,
    };

    // Need to make sure the temp folder exists so the podConfigJson can be written to it
    mkdirSync(rootFilePath, { recursive: true });

    // Create and start the HTTP handler and related components
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath('server-dynamic-unsafe.json'),
      variables,
    ) as Record<string, any>;
    ({ app } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('creates a pod with the given config.', async(): Promise<void> => {
    const result = await register(baseUrl, user);
    ({ controls, authorization } = result);
    expect(result.pod).toBe(podUrl);
  });

  it('can fetch the created pod.', async(): Promise<void> => {
    const res = await fetch(podUrl);
    expect(res.status).toBe(200);
  });

  it('should not be able to read the acl file.', async(): Promise<void> => {
    const res = await fetch(`${podUrl}.acl`);
    expect(res.status).toBe(401);
  });

  it('should be able to read acl file with the correct credentials.', async(): Promise<void> => {
    const res = await fetch(`${podUrl}.acl`, {
      headers: {
        authorization: `WebID ${user.webId}`,
      },
    });
    expect(res.status).toBe(200);
  });

  it('should be able to write to the pod now as the owner.', async(): Promise<void> => {
    let res = await fetch(`${podUrl}test`, {
      headers: {
        authorization: `WebID ${user.webId}`,
      },
    });
    expect(res.status).toBe(404);

    res = await fetch(`${podUrl}test`, {
      method: 'PUT',
      headers: {
        authorization: `WebID ${user.webId}`,
        'content-type': 'text/plain',
      },
      body: 'this is new data!',
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(`${podUrl}test`);

    res = await fetch(`${podUrl}test`, {
      headers: {
        authorization: `WebID ${user.webId}`,
      },
    });
    expect(res.status).toBe(200);
    await expect(res.text()).resolves.toBe('this is new data!');
  });

  it('should not be able to create a pod with the same name.', async(): Promise<void> => {
    const res = await fetch(controls.account.pod, {
      method: 'POST',
      headers: { authorization, 'content-type': 'application/json' },
      body: JSON.stringify({ name: user.podName, settings: { template }}),
    });
    expect(res.status).toBe(400);
    await expect(res.text()).resolves.toContain(`There already is a pod at ${podUrl}`);
  });
});

import fetch from 'cross-fetch';
import type { App } from '../../src/init/App';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getTestConfigPath,
  instantiateFromConfig,
} from './Config';

// These `doNotFake` settings are necessary to make sure the server still works
jest.useFakeTimers({ doNotFake: [ 'nextTick' ]});

const port = getPort('ExpiringDataCleanup');
const baseUrl = `http://localhost:${port}/`;

describe('A server with expiring storage', (): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath('server-memory.json'),
      getDefaultVariables(port, baseUrl),
    ) as Record<string, any>;
    ({ app } = instances);
    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await app.stop();
  });

  it('does not crash after the interval timeout.', async(): Promise<void> => {
    // Default timeout is 1 hour
    // This test would fail if something goes wrong in an interval timer
    jest.advanceTimersByTime(2 * 60 * 60 * 1000);
    const res = await fetch(baseUrl, { method: 'HEAD' });
    expect(res.status).toBe(200);
  });
});

import fetch from 'cross-fetch';
import { pathExists } from 'fs-extra';
import type { App } from '../../src/init/App';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';

const port = getPort('FileBackend');
const baseUrl = `http://localhost:${port}/`;

const rootFilePath = getTestFolder('file-backend');

describe('A server with a file backend storage', (): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    await removeFolder(rootFilePath);
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getTestConfigPath('server-file.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await removeFolder(rootFilePath);
    await app.stop();
  });

  it('can put a document for which the URI path contains URL-encoded separator characters.', async(): Promise<void> => {
    const url = `${baseUrl}c1/c2/t1%2f`;
    const res = await fetch(url, {
      method: 'PUT',
      headers: {
        'content-type': 'text/plain',
      },
      body: 'abc',
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(`${baseUrl}c1/c2/t1%2F`);

    // The resource should not be accessible through ${baseUrl}c1/c2/t1/.
    const check1 = await fetch(`${baseUrl}c1/c2/t1/}`, {
      method: 'GET',
      headers: {
        accept: 'text/plain',
      },
    });
    expect(check1.status).toBe(404);

    // Check that the created resource is not a container
    const check2 = await fetch(url, {
      method: 'GET',
      headers: {
        accept: 'text/plain',
      },
    });
    const linkHeaderValues = check2.headers.get('link')!.split(',').map((item): string => item.trim());
    expect(linkHeaderValues).not.toContain('<http://www.w3.org/ns/ldp#Container>; rel="type"');

    // Check that the appropriate file path exists
    const check3 = await pathExists(`${rootFilePath}/c1/c2/t1%2F$.txt`);
    expect(check3).toBe(true);
  });

  it('can post a document using a slug that contains URL-encoded separator characters.', async(): Promise<void> => {
    const slug = 't1%2Faa';
    const res = await fetch(baseUrl, {
      method: 'POST',
      headers: {
        'content-type': 'text/plain',
        slug,
      },
      body: 'abc',
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(`${baseUrl}${slug}`);

    // Check that the appropriate file path exists
    const check = await pathExists(`${rootFilePath}/${slug}$.txt`);
    expect(check).toBe(true);
  });

  it(
    'prevents accessing a document via a different identifier that results in the same path after URL decoding.',
    async(): Promise<void> => {
      // First put a resource using a path without encoded separator characters: foo/bar
      const url = `${baseUrl}foo/bar`;
      await fetch(url, {
        method: 'PUT',
        headers: {
          'content-type': 'text/plain',
        },
        body: 'abc',
      });

      // The resource at foo/bar should not be accessible using the url encoded variant of this path: foo%2Fbar
      const check1 = await fetch(`${baseUrl}foo%2Fbar`, {
        method: 'GET',
        headers: {
          accept: 'text/plain',
        },
      });
      // Expect foo%2Fbar to correctly refer to a different document, which does not exist.
      expect(check1.status).toBe(404);

      // Check that the the appropriate file path for foo/bar exists
      const check2 = await pathExists(`${rootFilePath}/foo/bar$.txt`);
      expect(check2).toBe(true);

      // Next, put a resource using a path with an encoded separator character: bar%2Ffoo
      await fetch(`${baseUrl}bar%2Ffoo`, {
        method: 'PUT',
        headers: {
          'content-type': 'text/plain',
        },
        body: 'abc',
      });

      // The resource at bar%2Ffoo should not be accessible through bar/foo
      const check3 = await fetch(`${baseUrl}bar/foo`, {
        method: 'GET',
        headers: {
          accept: 'text/plain',
        },
      });
      // Expect bar/foo to correctly refer to a different document, which does not exist.
      expect(check3.status).toBe(404);

      // Check that the the appropriate file path for bar%foo exists
      const check4 = await pathExists(`${rootFilePath}/bar%2Ffoo$.txt`);
      expect(check4).toBe(true);
    },
  );

  it(
    'supports content types for which no extension mapping can be found (and falls back to using .unknown).',
    async(): Promise<void> => {
      const url = `${baseUrl}test`;
      const res = await fetch(url, {
        method: 'PUT',
        headers: {
          'content-type': 'unknown/some-type',
        },
        body: 'abc',
      });
      expect(res.status).toBe(201);
      expect(res.headers.get('location')).toBe(`${baseUrl}test`);

      // Check if the document can be retrieved
      const check1 = await fetch(`${baseUrl}test`, {
        method: 'GET',
        headers: {
          accept: '*/*',
        },
      });
      const body = await check1.text();
      expect(check1.status).toBe(200);
      expect(body).toBe('abc');
      // The content-type should be unknown/some-type.
      expect(check1.headers.get('content-type')).toBe('unknown/some-type');

      // Check if the expected file was created
      const check2 = await pathExists(`${rootFilePath}/test$.unknown`);
      expect(check2).toBe(true);
    },
  );
});

import {
  BasicRepresentation,
  ChainedConverter,
  getLoggerFor,
  guardedStreamFrom,
  INTERNAL_QUADS,
  RdfToQuadConverter,
  readableToString,
  RepresentationMetadata,
} from '../../src';
import type { Logger, Representation, RepresentationConverterArgs } from '../../src';
import { BaseTypedRepresentationConverter } from '../../src/storage/conversion/BaseTypedRepresentationConverter';

jest.mock('../../src/logging/LogUtil', (): any => {
  const logger: Logger =
    { error: jest.fn(), debug: jest.fn(), warn: jest.fn(), info: jest.fn(), log: jest.fn() } as any;
  return { getLoggerFor: (): Logger => logger };
});
const logger: jest.Mocked<Logger> = getLoggerFor('GuardedStream') as any;

class DummyConverter extends BaseTypedRepresentationConverter {
  public constructor() {
    super(INTERNAL_QUADS, 'x/x');
  }

  public async handle({ representation }: RepresentationConverterArgs): Promise<Representation> {
    const data = guardedStreamFrom([ 'dummy' ]);
    const metadata = new RepresentationMetadata(representation.metadata, 'x/x');

    return { binary: true, data, metadata, isEmpty: false };
  }
}

describe('A chained converter where data gets ignored', (): void => {
  const identifier = { path: 'http://test.com/' };
  const rep = new BasicRepresentation('<a:b> <a:b> c!', identifier, 'text/turtle');
  const converter = new ChainedConverter([
    new RdfToQuadConverter(),
    new DummyConverter(),
  ]);

  it('does not throw on async crash.', async(): Promise<void> => {
    jest.useFakeTimers();
    const result = await converter.handleSafe({ identifier, representation: rep, preferences: { type: { 'x/x': 1 }}});

    await expect(readableToString(result.data)).resolves.toBe('dummy');

    jest.advanceTimersByTime(1000);
    expect(logger.error).toHaveBeenCalledTimes(1);
  });
});

import type { KeyPair } from '@inrupt/solid-client-authn-core';
import {
  buildAuthenticatedFetch,
  createDpopHeader,
  generateDpopKeyPair,
} from '@inrupt/solid-client-authn-core';
import { fetch } from 'cross-fetch';
import { parse, splitCookiesString } from 'set-cookie-parser';
import type { App } from '../../src/init/App';
import { APPLICATION_X_WWW_FORM_URLENCODED } from '../../src/util/ContentTypes';
import { joinUrl } from '../../src/util/PathUtil';
import { register } from '../util/AccountUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, getTestFolder, instantiateFromConfig, removeFolder } from './Config';
import { IdentityTestState } from './IdentityTestState';

const port = getPort('Identity');
const baseUrl = `http://localhost:${port}/`;

const rootFilePath = getTestFolder('Identity');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    config: 'server-memory.json',
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    config: 'server-file.json',
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

// Prevent panva/node-openid-client from emitting DraftWarning
jest.spyOn(process, 'emitWarning').mockImplementation();

// No way around the cookies https://github.com/panva/node-oidc-provider/issues/552 .
// They will be simulated by storing the values and passing them along.
// This is why the redirects are handled manually.
// We also need to parse the HTML in several steps since there is no API.
describe.each(stores)('A Solid server with IDP using %s', (name, { config, teardown }): void => {
  let app: App;
  const redirectUrl = 'http://mockedredirect/';
  const container = new URL('secret/', baseUrl).href;
  const oidcIssuer = baseUrl;
  const indexUrl = joinUrl(baseUrl, '.account/');
  let webId: string;
  let webId2: string;
  const email = 'test@example.com';
  const email2 = 'otherMail@example.com';
  const password = 'password!';
  let controls: {
    oidc: { webId: string; consent: string; forgetWebId: string; prompt: string };
    main: { index: string };
    account: { create: string; pod: string; logout: string };
    password: { create: string; login: string };
  };

  beforeAll(async(): Promise<void> => {
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath(config),
      {
        ...getDefaultVariables(port, baseUrl),
        'urn:solid-server:default:variable:rootFilePath': rootFilePath,
      },
    ) as Record<string, any>;
    ({ app } = instances);
    await app.start();

    // Create accounts
    ({ webId, controls } = await register(baseUrl, { email, password, podName: 'test' }));
    ({ webId: webId2 } = await register(baseUrl, { email: email2, password, podName: 'otherTest' }));

    // Create container where only webId can write
    const aclTurtle = `
@prefix acl: <http://www.w3.org/ns/auth/acl#>.
<#owner> a acl:Authorization;
         acl:agent <${webId}>;
         acl:accessTo <./>;
         acl:default <./>;
         acl:mode acl:Read, acl:Write, acl:Control.
`;
    const res = await fetch(`${container}.acl`, {
      method: 'PUT',
      headers: { 'content-type': 'text/turtle' },
      body: aclTurtle,
    });
    if (res.status !== 201) {
      throw new Error(`Something went wrong initializing the test ACL: ${await res.text()}`);
    }
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  describe('authenticating', (): void => {
    let state: IdentityTestState;

    beforeAll(async(): Promise<void> => {
      state = new IdentityTestState(baseUrl, redirectUrl, oidcIssuer);
    });

    afterAll(async(): Promise<void> => {
      await state.session.logout();
    });

    it('initializes the session.', async(): Promise<void> => {
      // This is the auth URL with all the relevant query parameters
      let url = await state.initSession();
      expect(url.startsWith(oidcIssuer)).toBeTruthy();

      // Always redirect to our index page
      url = await state.handleRedirect(url);

      // Compare received URL with login URL in our controls
      expect(controls.main.index).toBe(url);

      // Add the OIDC controls to the object
      const res = await state.fetchIdp(url);
      controls = {
        ...(await res.json()).controls,
        ...controls,
      };
    });

    it('logs in.', async(): Promise<void> => {
      // Log in using email/password
      const res = await state.fetchIdp(controls.password.login, 'POST', JSON.stringify({ email, password }));

      // Redirect to WebID picker
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);
    });

    it('sends a token for the chosen WebID.', async(): Promise<void> => {
      // See the available WebIDs
      let res = await state.fetchIdp(controls.oidc.webId);
      expect(res.status).toBe(200);
      const json = await res.json();
      expect(json.webIds).toEqual([ webId ]);

      // Pick the WebID
      // Errors if the WebID is not registered to the account
      res = await state.fetchIdp(controls.oidc.webId, 'POST', { webId: 'http://example.com/wrong' });
      expect(res.status).toBe(400);
      res = await state.fetchIdp(controls.oidc.webId, 'POST', { webId, remember: true });

      // Redirect to the consent page
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);
    });

    it('consents and redirects back to the client.', async(): Promise<void> => {
      let res = await state.fetchIdp(controls.oidc.consent);
      const json = await res.json();
      expect(json.webId).toBe(webId);
      expect(json.client.grant_types).toContain('authorization_code');
      expect(json.client.grant_types).toContain('refresh_token');

      res = await state.fetchIdp(controls.oidc.consent, 'POST');

      // Redirect back to the client and verify login success
      await state.handleIncomingRedirect(res, webId);
    });

    it('can only access the profile container when using the logged in session.', async(): Promise<void> => {
      let res = await fetch(container);
      expect(res.status).toBe(401);

      res = await state.session.fetch(container);
      expect(res.status).toBe(200);
    });

    it('can no longer access the container after logging out.', async(): Promise<void> => {
      await state.session.logout();
      const res = await state.session.fetch(container);
      expect(res.status).toBe(401);
    });

    it('immediately gets redirect to the consent page in the next session.', async(): Promise<void> => {
      const url = await state.initSession();
      await state.handleRedirect(url);

      const res = await state.fetchIdp(controls.oidc.prompt);
      expect(res.status).toBe(200);
      await expect(res.json()).resolves.toEqual(expect.objectContaining({ prompt: 'consent' }));
    });

    it('can forget the stored WebID.', async(): Promise<void> => {
      let res = await state.fetchIdp(controls.oidc.forgetWebId, 'POST');
      expect(res.status).toBe(200);

      // We have to pick a WebID again
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);
      res = await state.fetchIdp(controls.oidc.webId, 'POST', { webId });

      // Redirect back to the consent page
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);
    });

    it('can consent again.', async(): Promise<void> => {
      let res = await state.fetchIdp(controls.oidc.consent, 'POST');

      // Redirect back to the client and verify login success
      await state.handleIncomingRedirect(res, webId);

      // Verify by accessing the private container
      res = await state.session.fetch(container);
      expect(res.status).toBe(200);
    });

    it('can log out.', async(): Promise<void> => {
      // Log out
      let res = await state.fetchIdp(controls.account.logout, 'POST');
      expect(res.status).toBe(200);

      // Log out of the previous session and start a new one
      await state.session.logout();
      const url = await state.initSession();
      await state.handleRedirect(url);

      // Log in
      res = await state.fetchIdp(controls.password.login, 'POST', { email: email2, password });
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);

      // Pick the new WebID
      res = await state.fetchIdp(controls.oidc.webId, 'POST', { webId: webId2 });
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);

      // Consent again
      res = await state.fetchIdp(controls.oidc.consent, 'POST');

      // Redirect back to the client and verify login success
      await state.handleIncomingRedirect(res, webId2);
    });
  });

  describe('authenticating a client with a WebID', (): void => {
    const clientId = joinUrl(baseUrl, 'client-id');
    const badClientId = joinUrl(baseUrl, 'bad-client-id');
    const clientJson = {
      '@context': 'https://www.w3.org/ns/solid/oidc-context.jsonld',

      client_id: clientId,
      client_name: 'Solid Application Name',
      redirect_uris: [ redirectUrl ],
      post_logout_redirect_uris: [ 'https://app.example/logout' ],
      client_uri: 'https://app.example/',
      logo_uri: 'https://app.example/logo.png',
      tos_uri: 'https://app.example/tos.html',
      scope: 'openid profile offline_access webid',
      grant_types: [ 'refresh_token', 'authorization_code' ],
      response_types: [ 'code' ],
      default_max_age: 3600,
      require_auth_time: true,
    };
    // This client will always reject requests since there is no valid redirect
    const badClientJson = {
      ...clientJson,
      client_id: badClientId,
      redirect_uris: [],
    };

    let state: IdentityTestState;

    beforeAll(async(): Promise<void> => {
      state = new IdentityTestState(baseUrl, redirectUrl, oidcIssuer);

      await fetch(clientId, {
        method: 'PUT',
        headers: { 'content-type': 'application/ld+json' },
        body: JSON.stringify(clientJson),
      });

      await fetch(badClientId, {
        method: 'PUT',
        headers: { 'content-type': 'application/ld+json' },
        body: JSON.stringify(badClientJson),
      });
    });

    afterAll(async(): Promise<void> => {
      await state.session.logout();
    });

    it('initializes the session and logs in.', async(): Promise<void> => {
      const url = await state.initSession(clientId);

      // Redirect to our login page
      await state.handleRedirect(url);

      // Log in using email/password
      let res = await state.fetchIdp(controls.password.login, 'POST', { email, password });

      // Redirect to WebID picker
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);

      // Pick the WebID
      res = await state.fetchIdp(controls.oidc.webId, 'POST', { webId, remember: true });

      // Redirect to the consent page
      await expect(state.handleLocationRedirect(res)).resolves.toBe(indexUrl);

      // Verify the client information the server discovered
      res = await state.fetchIdp(controls.oidc.consent);
      expect(res.status).toBe(200);
      const json = await res.json();
      expect(json.webId).toBe(webId);
      expect(json.client.client_id).toBe(clientJson.client_id);
      expect(json.client.client_name).toBe(clientJson.client_name);
      expect(json.client.grant_types).toContain('authorization_code');
      expect(json.client.grant_types).toContain('refresh_token');

      res = await state.fetchIdp(controls.oidc.consent, 'POST');

      // Redirect back to the client and verify login success
      await state.handleIncomingRedirect(res, webId);
    });

    it('rejects requests in case the redirect URL is not accepted.', async(): Promise<void> => {
      // This test allows us to make sure the server actually uses the client WebID.
      // If it did not, it would not see the invalid redirect_url array.

      let nextUrl = '';
      await state.session.login({
        redirectUrl,
        oidcIssuer,
        clientId: badClientId,
        handleRedirect(data): void {
          nextUrl = data;
        },
      });
      expect(nextUrl.length > 0).toBeTruthy();
      expect(nextUrl.startsWith(oidcIssuer)).toBeTruthy();

      // Redirect will error due to invalid client WebID
      const res = await state.fetchIdp(nextUrl);
      expect(res.status).toBe(400);
      await expect(res.text()).resolves.toContain('invalid_redirect_uri');
    });
  });

  describe('using client_credentials', (): void => {
    const tokenUrl = joinUrl(baseUrl, '.oidc/token');
    let dpopKey: KeyPair;
    let id: string | undefined;
    let secret: string | undefined;
    let accessToken: string | undefined;

    beforeAll(async(): Promise<void> => {
      dpopKey = await generateDpopKeyPair();
    });

    it('can request a credentials token.', async(): Promise<void> => {
      // Login and save cookie
      const loginResponse = await fetch(controls.password.login, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      const cookies = parse(splitCookiesString(loginResponse.headers.get('set-cookie')!));
      const cookie = `${cookies[0].name}=${cookies[0].value}`;

      // Request token
      const accountJson = await (await fetch(indexUrl, { headers: { cookie }})).json();
      const credentialsUrl = accountJson.controls.account.clientCredentials;
      const res = await fetch(credentialsUrl, {
        method: 'POST',
        headers: { cookie, 'content-type': 'application/json' },
        body: JSON.stringify({ name: 'token', webId }),
      });

      expect(res.status).toBe(200);
      ({ id, secret } = await res.json());
    });

    it('can request an access token using the credentials.', async(): Promise<void> => {
      const dpopHeader = await createDpopHeader(tokenUrl, 'POST', dpopKey);
      const authString = `${encodeURIComponent(id!)}:${encodeURIComponent(secret!)}`;
      const res = await fetch(tokenUrl, {
        method: 'POST',
        headers: {
          authorization: `Basic ${Buffer.from(authString).toString('base64')}`,
          'content-type': APPLICATION_X_WWW_FORM_URLENCODED,
          dpop: dpopHeader,
        },
        body: 'grant_type=client_credentials&scope=webid',
      });
      expect(res.status).toBe(200);
      const json = await res.json();
      ({ access_token: accessToken } = json);
      expect(typeof accessToken).toBe('string');
    });

    it('can use the generated access token to do an authenticated call.', async(): Promise<void> => {
      const authFetch = await buildAuthenticatedFetch(accessToken!, { dpopKey });
      let res = await fetch(container);
      expect(res.status).toBe(401);
      res = await authFetch(container);
      expect(res.status).toBe(200);
    });
  });

  describe('setup', (): void => {
    it('should contain the required configuration keys.', async(): Promise<void> => {
      const res = await fetch(`${baseUrl}.well-known/openid-configuration`);
      const jsonBody = await res.json();

      expect(res.status).toBe(200);
      // https://solid.github.io/solid-oidc/#discovery
      expect(jsonBody.scopes_supported).toContain('webid');
    });

    it('should return correct error output.', async(): Promise<void> => {
      const res = await fetch(`${baseUrl}.oidc/foo`, { headers: { accept: 'application/json' }});
      expect(res.status).toBe(404);
      const json = await res.json();
      expect(json.name).toBe(`InvalidRequest`);
      expect(json.message).toBe(`invalid_request - unrecognized route or not allowed method (GET on /.oidc/foo)`);
      expect(json.statusCode).toBe(404);
      expect(json.stack).toBeDefined();
      expect(json.error).toBe('invalid_request');
    });
  });
});

import { Session } from '@inrupt/solid-client-authn-node';
import type { Response } from 'cross-fetch';
import { fetch } from 'cross-fetch';
import type { Cookie } from 'set-cookie-parser';
import { parse, splitCookiesString } from 'set-cookie-parser';

/* eslint-disable jest/no-standalone-expect */
/**
 * Helper class to track the state while going through an IDP procedure
 * and generalizes several common calls and checks.
 */
export class IdentityTestState {
  private readonly baseUrl: string;
  private readonly redirectUrl: string;
  private readonly oidcIssuer: string;

  public readonly session: Session;
  private readonly cookies: Map<string, Cookie>;
  private cookie?: string;

  public constructor(baseUrl: string, redirectUrl: string, oidcIssuer: string) {
    this.baseUrl = baseUrl;
    this.redirectUrl = redirectUrl;
    this.oidcIssuer = oidcIssuer;
    this.session = new Session();
    this.cookies = new Map();
  }

  /**
   * Performs a fetch call while keeping track of the stored cookies and preventing redirects.
   *
   * @param url - URL to call.
   * @param method - Method to use.
   * @param body - Body to send along. If this is not a string it will be JSONified.
   * @param contentType - Content-Type of the body. If not defined but there is a body, this will be set to JSON.
   */
  public async fetchIdp(url: string, method = 'GET', body?: unknown, contentType?: string): Promise<Response> {
    const options = { method, headers: { cookie: this.cookie }, body, redirect: 'manual' } as any;
    if (body && typeof body !== 'string') {
      options.body = JSON.stringify(body);
    }
    if (body && !contentType) {
      contentType = 'application/json';
    }
    if (contentType) {
      options.headers['content-type'] = contentType;
    }
    const res = await fetch(url, options);

    // Parse the cookies that need to be set and convert them to the corresponding header value
    // Make sure we don't overwrite cookies that were already present
    if (res.headers.get('set-cookie')) {
      const newCookies = parse(splitCookiesString(res.headers.get('set-cookie')!));
      for (const cookie of newCookies) {
        this.cookies.set(cookie.name, cookie);
      }
      this.cookie = Array.from(this.cookies, ([ , nom ]): string => `${nom.name}=${nom.value}`).join('; ');
    }
    return res;
  }

  /**
   * Initializes the OIDC session for the given clientId.
   * If undefined, dynamic registration will be used.
   */
  public async initSession(clientId?: string): Promise<string> {
    let nextUrl: string;
    await this.session.login({
      redirectUrl: this.redirectUrl,
      oidcIssuer: this.oidcIssuer,
      clientId,
      handleRedirect(data): void {
        nextUrl = data;
      },
    });
    return nextUrl!;
  }

  /**
   * Handles a URL that is expected to redirect and returns the target it would redirect to.
   */
  public async handleRedirect(url: string): Promise<string> {
    const res = await this.fetchIdp(url);
    expect(res.status).toBe(303);
    expect(res.headers.has('location')).toBe(true);
    return res.headers.get('location')!;
  }

  /**
   * Handles a JSON redirect. That is a request that returns a 200,
   * but has a `location` field in the JSON to indicate what it should redirect to.
   * That URL is expected to be another redirect, and this returns what it would redirect to.
   */
  public async handleLocationRedirect(res: Response): Promise<string> {
    expect(res.status).toBe(200);
    const json = await res.json();
    // The OIDC redirect
    expect(json.location).toBeDefined();

    return this.handleRedirect(json.location);
  }

  public async handleIncomingRedirect(res: Response, webId: string): Promise<void> {
    // Redirect back to the client
    const url = await this.handleLocationRedirect(res);
    expect(url.startsWith(this.redirectUrl)).toBe(true);

    const info = await this.session.handleIncomingRedirect(url);
    expect(info?.isLoggedIn).toBe(true);
    expect(info?.webId).toBe(webId);
  }
}

import { promises as fsPromises } from 'node:fs';
import fetch from 'cross-fetch';
import type { App, ResourceStore } from '../../src/';
import { BasicRepresentation, isSystemError, joinFilePath, joinUrl } from '../../src/';
import { AclHelper } from '../util/AclHelper';
import { deleteResource, getResource, postResource, putResource } from '../util/FetchUtil';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';

const port = getPort('LpdHandlerWithAuth');
const baseUrl = `http://localhost:${port}/`;

const rootFilePath = getTestFolder('full-config-acl');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    storeConfig: 'storage/backend/memory.json',
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    storeConfig: 'storage/backend/file.json',
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

describe.each(stores)('An LDP handler with auth using %s', (name, { storeConfig, teardown }): void => {
  let app: App;
  let store: ResourceStore;
  let aclHelper: AclHelper;
  const permanent = `${baseUrl}document.txt`;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getPresetConfigPath(storeConfig),
        getTestConfigPath('ldp-with-auth.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app, store } = instances);

    await app.start();

    // Create test helper for manipulating acl
    aclHelper = new AclHelper(store);
  });

  beforeEach(async(): Promise<void> => {
    // Set the root acl file to allow everything and create a single document
    await store.setRepresentation({ path: permanent }, new BasicRepresentation('PERMANENT', 'text/plain'));
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { read: true, write: true, append: true, control: true },
      agentClass: 'agent',
      accessTo: true,
      default: true,
    });
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('can add a document, read it and delete it if allowed.', async(): Promise<void> => {
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { read: true, write: true, append: true },
      agentClass: 'agent',
      accessTo: true,
      default: true,
    });

    // PUT
    const document = `${baseUrl}test.txt`;
    await putResource(document, { contentType: 'text/plain', body: 'TESTDATA', exists: false });

    // GET
    const response = await getResource(document);
    await expect(response.text()).resolves.toBe('TESTDATA');
    expect(response.headers.get('wac-allow')).toBe('user="append read write",public="append read write"');

    // DELETE
    await deleteResource(document);
  });

  it('can not add a file to the store if not allowed.', async(): Promise<void> => {
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { read: true, write: true, append: true },
      agentClass: 'authenticated',
      accessTo: true,
      default: true,
    });

    // PUT fail
    const documentUrl = `${baseUrl}test.txt`;
    const response = await fetch(documentUrl, { method: 'PUT' });
    expect(response.status).toBe(401);
  });

  it('can not add/delete if only read is allowed.', async(): Promise<void> => {
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { read: true },
      agentClass: 'agent',
      accessTo: true,
      default: true,
    });

    // PUT fail
    const document = `${baseUrl}test.txt`;
    let response = await fetch(document, { method: 'PUT' });
    expect(response.status).toBe(401);

    // GET permanent file
    response = await getResource(permanent);
    await expect(response.text()).resolves.toBe('PERMANENT');
    expect(response.headers.get('wac-allow')).toBe('user="read",public="read"');

    // DELETE fail
    response = await fetch(permanent, { method: 'DELETE' });
    expect(response.status).toBe(401);
  });

  it('can add files but not write to them if append is allowed.', async(): Promise<void> => {
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { append: true },
      agentClass: 'agent',
      accessTo: true,
      default: true,
    });

    // POST
    const slug = 'slug';
    let response = await postResource(baseUrl, { contentType: 'text/plain', slug, body: 'SLUGDATA' });
    const document = response.headers.get('location')!;

    // PUT fail
    response = await fetch(document, { method: 'PUT' });
    expect(response.status).toBe(401);

    // DELETE fail
    response = await fetch(document, { method: 'DELETE' });
    expect(response.status).toBe(401);

    // Clean up resource
    await store.deleteResource({ path: document });
  });

  it('can not access an acl file if no control rights are provided.', async(): Promise<void> => {
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { read: true, write: true, append: true },
      agentClass: 'agent',
      accessTo: true,
    });

    const response = await fetch(`${baseUrl}.acl`);
    expect(response.status).toBe(401);
  });

  it('can only access an acl file if control rights are provided.', async(): Promise<void> => {
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { control: true },
      agentClass: 'agent',
      accessTo: true,
    });

    const response = await fetch(`${baseUrl}.acl`);
    expect(response.status).toBe(200);
    expect(response.headers.get('wac-allow'))
      .toBe('user="append control read write",public="append control read write"');

    // Close response
    await response.text();
  });

  it('returns the legacy WWW-Authenticate header on 401 requests.', async(): Promise<void> => {
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: {},
      agentClass: 'agent',
      accessTo: true,
    });

    const response = await fetch(`${baseUrl}.acl`);
    expect(response.status).toBe(401);
    expect(response.headers.get('www-authenticate')).toBe('Bearer scope="openid webid"');
  });

  it('supports file paths with spaces.', async(): Promise<void> => {
    // Specific problem for file store, so only do this if the rootFilePath folder exists
    try {
      await fsPromises.lstat(rootFilePath);
    } catch (error: unknown) {
      if (isSystemError(error) && error.code === 'ENOENT') {
        return;
      }
      throw error;
    }

    // Correct identifier when there are spaces
    const identifier = { path: `${baseUrl}with%20spaces.txt` };

    // Set acl specifically for this identifier
    const acl = `@prefix acl: <http://www.w3.org/ns/auth/acl#>.
@prefix foaf: <http://xmlns.com/foaf/0.1/>.
<#authorization>
    a               acl:Authorization;
    acl:agentClass  foaf:Agent;
    acl:mode        acl:Read;
    acl:accessTo    <${identifier.path}>.`;

    // Prevent other access to make sure there is no hierarchy bug
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: {},
      agentClass: 'agent',
      default: true,
    });

    // Write files manually to make sure there are spaces
    await fsPromises.writeFile(joinFilePath(rootFilePath, 'with spaces.txt.acl'), acl);
    await fsPromises.writeFile(joinFilePath(rootFilePath, 'with spaces.txt'), 'valid data');

    // GET file
    const response = await getResource(identifier.path);
    await expect(response.text()).resolves.toContain('valid data');
  });

  it('prevents creation of intermediate intermediate containers if they are not allowed.', async(): Promise<void> => {
    const url = joinUrl(baseUrl, 'foo/bar/');
    // Not allowed since there are no append permissions on the base container
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { write: true },
      agentClass: 'agent',
      default: true,
    });
    let response = await fetch(url, { method: 'PUT' });
    expect(response.status).toBe(401);

    // Not allowed since there are no write permissions for the target
    await aclHelper.setSimpleAcl(baseUrl, {
      permissions: { append: true },
      agentClass: 'agent',
      accessTo: true,
    });
    response = await fetch(url, { method: 'PUT' });
    expect(response.status).toBe(401);

    // This covers all required permissions
    await aclHelper.setSimpleAcl(baseUrl, [
      { permissions: { append: true }, agentClass: 'agent', accessTo: true },
      { permissions: { write: true }, agentClass: 'agent', default: true },
    ]);
    await putResource(url, { contentType: 'text/plain', exists: false });
  });
});

import { createReadStream } from 'node:fs';
import fetch from 'cross-fetch';
import type { Quad } from 'n3';
import { DataFactory, Parser, Store } from 'n3';
import { joinFilePath, joinUrl, PIM, RDF, splitCommaSeparated } from '../../src/';
import type { App } from '../../src/';
import { LDP } from '../../src/util/Vocabularies';
import {
  deleteResource,
  expectQuads,
  getResource,
  patchResource,
  postResource,
  putResource,
} from '../util/FetchUtil';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';

const { literal, namedNode, quad } = DataFactory;

const port = getPort('LpdHandlerWithoutAuth');
const baseUrl = `http://localhost:${port}/`;
const metaSuffix = '.meta';
const rootFilePath = getTestFolder('full-config-no-auth');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    storeConfig: 'storage/backend/memory.json',
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    storeConfig: 'storage/backend/file.json',
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

describe.each(stores)('An LDP handler allowing all requests %s', (name, { storeConfig, teardown }): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getPresetConfigPath(storeConfig),
        getTestConfigPath('ldp-with-auth.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('returns the root container listing.', async(): Promise<void> => {
    const response = await getResource(baseUrl, {}, { contentType: 'text/turtle' });

    await expect(response.text()).resolves.toContain('ldp:BasicContainer');
    expect(response.headers.get('link')).toContain(`<${PIM.Storage}>; rel="type"`);
  });

  it('returns the root container listing when asking for */*.', async(): Promise<void> => {
    const response = await getResource(baseUrl, { accept: '*/*' }, { contentType: 'text/turtle' });

    await expect(response.text()).resolves.toContain('ldp:BasicContainer');
    expect(response.headers.get('link')).toContain(`<${PIM.Storage}>; rel="type"`);
  });

  it('can read a container listing with a query string.', async(): Promise<void> => {
    // Helper functions would fail due to query params
    const response = await fetch(`${baseUrl}?abc=def&xyz`, { headers: { accept: 'text/turtle' }});
    expect(response.status).toBe(200);
    expect(response.headers.get('content-type')).toBe('text/turtle');
    expect(response.headers.get('link')).toContain(`<${LDP.Container}>; rel="type"`);
    expect(response.headers.get('link')).toContain(`<${baseUrl}.acl>; rel="acl"`);
    expect(response.headers.get('link')).toContain(`<${PIM.Storage}>; rel="type"`);

    const parser = new Parser({ baseIRI: baseUrl });
    const quads = parser.parse(await response.text());
    const store = new Store(quads);
    expect(store.countQuads(namedNode(baseUrl), RDF.terms.type, LDP.terms.Container, null)).toBe(1);
  });

  it('can add a document to the store, read it and delete it.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}document.txt`;
    // PUT
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE0' });

    // GET
    const response = await getResource(documentUrl, {}, { contentType: 'text/plain' });
    await expect(response.text()).resolves.toBe('TESTFILE0');

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can add and overwrite a document.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}document.txt`;
    // PUT
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE0' });

    // GET
    let response = await getResource(documentUrl, {}, { contentType: 'text/plain' });
    await expect(response.text()).resolves.toBe('TESTFILE0');

    // PUT
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE1', exists: true });

    // GET
    response = await getResource(documentUrl, {}, { contentType: 'text/plain' });
    await expect(response.text()).resolves.toBe('TESTFILE1');

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can create a container and delete it.', async(): Promise<void> => {
    const containerUrl = `${baseUrl}secondContainer/`;
    // PUT
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // GET
    const response = await getResource(containerUrl);

    // Verify container listing
    await expectQuads(response, [
      quad(namedNode(containerUrl), RDF.terms.type, LDP.terms.Container),
    ]);

    // DELETE
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('can create a container and retrieve it.', async(): Promise<void> => {
    // Create container
    const containerUrl = `${baseUrl}testcontainer0/`;
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // GET representation
    const response = await getResource(containerUrl, { accept: '*/*' }, { contentType: 'text/turtle' });
    await expect(response.text()).resolves.toContain('ldp:BasicContainer');

    // DELETE
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('can create a container and view it as HTML.', async(): Promise<void> => {
    // Create container
    const containerUrl = `${baseUrl}testcontainer0/`;
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // GET representation
    const response = await getResource(containerUrl, { accept: 'text/html' }, { contentType: 'text/html' });
    await expect(response.text()).resolves.toContain('Contents of testcontainer0');

    // DELETE
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('can create a container and put a document in it.', async(): Promise<void> => {
    // Create container
    const containerUrl = `${baseUrl}testcontainer0/`;
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // Create document
    const documentUrl = `${containerUrl}testdocument0.txt`;
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE0' });

    // GET document
    const response = await getResource(documentUrl, {}, { contentType: 'text/plain' });
    await expect(response.text()).resolves.toBe('TESTFILE0');

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('can create a container without content-type.', async(): Promise<void> => {
    // Create container
    const containerUrl = `${baseUrl}testcontainer0/`;
    const slug = 'testcontainer1/';
    const putResponse = await fetch(containerUrl, {
      method: 'PUT',
    });
    const postResponse = await fetch(baseUrl, {
      method: 'Post',
      headers: {
        slug,
        link: `<http://www.w3.org/ns/ldp#Container>; rel="type"`,
      },
    });

    expect(putResponse.status).toBe(201);
    expect(putResponse.headers.get('location')).toBe(containerUrl);
    expect(postResponse.status).toBe(201);
    expect(postResponse.headers.get('location')).toBe(baseUrl + slug);

    // DELETE
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
    await expect(deleteResource(baseUrl + slug)).resolves.toBeUndefined();
  });

  it('cannot remove a container when the container contains a document.', async(): Promise<void> => {
    // Create container
    const containerUrl = `${baseUrl}testfolder1/`;
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // Create document
    const documentUrl = `${containerUrl}testdocument0.txt`;
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE0' });

    // Try to DELETE container
    const response = await fetch(containerUrl, { method: 'DELETE' });
    expect(response.status).toBe(409);
    await expect(response.text()).resolves.toContain('ConflictHttpError: Can only delete empty containers.');

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('cannot remove a container when the container contains a subfolder.', async(): Promise<void> => {
    // Create container
    const containerUrl = `${baseUrl}testcontainer2/`;
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // Create subcontainer
    const subContainerUrl = `${containerUrl}subcontainer0/`;
    await putResource(subContainerUrl, { contentType: 'text/turtle' });

    // Try to DELETE container
    const response = await fetch(containerUrl, { method: 'DELETE' });
    expect(response.status).toBe(409);
    await expect(response.text()).resolves.toContain('ConflictHttpError: Can only delete empty containers.');

    // DELETE
    await expect(deleteResource(subContainerUrl)).resolves.toBeUndefined();
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('can read the contents of a container.', async(): Promise<void> => {
    // Create container
    const containerUrl = `${baseUrl}testcontainer3/`;
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // Create subfolder
    const subContainerUrl = `${containerUrl}subcontainer0`;
    await putResource(subContainerUrl, { contentType: 'text/turtle' });

    // Create document
    const documentUrl = `${containerUrl}testfile0.txt`;
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE0' });

    const response = await getResource(containerUrl);
    await expectQuads(response, [
      quad(namedNode(containerUrl), LDP.terms.contains, namedNode(subContainerUrl)),
      quad(namedNode(containerUrl), LDP.terms.contains, namedNode(documentUrl)),
    ]);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
    await expect(deleteResource(subContainerUrl)).resolves.toBeUndefined();
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('can upload and delete an image.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}image.png`;
    const response = await fetch(documentUrl, {
      method: 'PUT',
      headers: {
        'content-type': 'image/png',
      },
      body: createReadStream(joinFilePath(__dirname, '../assets/testimage.png')) as any,
    });
    expect(response.status).toBe(201);
    expect(response.headers.get('location')).toBe(documentUrl);
    await expect(response.text()).resolves.toHaveLength(0);

    // GET
    await getResource(documentUrl, {}, { contentType: 'image/png' });

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can create a resource with a diamond identifier in the data.', async(): Promise<void> => {
    const slug = 'my-resource';

    const body = '<> <http://www.w3.org/2000/01/rdf-schema#label> "My Resource" .';
    let response = await postResource(baseUrl, { isContainer: false, contentType: 'text/turtle', slug, body });
    expect(response.headers.get('location')).toBe(`${baseUrl}${slug}`);

    // GET
    const containerUrl = `${baseUrl}${slug}`;
    response = await getResource(containerUrl);

    await expectQuads(response, [
      quad(namedNode(containerUrl), namedNode('http://www.w3.org/2000/01/rdf-schema#label'), literal('My Resource')),
    ]);

    // DELETE
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  // https://github.com/CommunitySolidServer/CommunitySolidServer/issues/498
  it('accepts a GET with Content-Length: 0.', async(): Promise<void> => {
    // PUT
    const documentUrl = `${baseUrl}foo/bar`;
    const response = await fetch(documentUrl, {
      method: 'PUT',
      headers: { 'content-length': '0', 'content-type': 'text/turtle' },
      body: '',
    });
    expect(response.status).toBe(201);
    expect(response.headers.get('location')).toBe(documentUrl);

    // GET
    await getResource(documentUrl);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can handle simple SPARQL updates.', async(): Promise<void> => {
    // POST
    const body = [
      '<http://test.com/s1> <http://test.com/p1> <http://test.com/o1>.',
      '<http://test.com/s2> <http://test.com/p2> <http://test.com/o2>.',
    ].join('\n');
    let response = await postResource(baseUrl, { contentType: 'text/turtle', body });
    const documentUrl = response.headers.get('location')!;

    // PATCH
    const query = [
      'DELETE { <http://test.com/s1> <http://test.com/p1> <http://test.com/o1> }',
      'INSERT {<http://test.com/s3> <http://test.com/p3> <http://test.com/o3>}',
      'WHERE {}',
    ].join('\n');
    await patchResource(documentUrl, query, 'sparql', true);

    // PATCH using a content-type header with charset
    const query2 = [
      'DELETE { <http://test.com/s2> <http://test.com/p2> <http://test.com/o2> }',
      'INSERT {<#s4> <#p4> <#o4>}',
      'WHERE {}',
    ].join('\n');
    response = await fetch(documentUrl, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/sparql-update ; charset=UTF-8',
      },
      body: query2,
    });
    await expect(response.text()).resolves.toHaveLength(0);
    expect(response.status).toBe(205);

    // GET
    response = await getResource(documentUrl);
    const expected = [
      quad(
        namedNode('http://test.com/s3'),
        namedNode('http://test.com/p3'),
        namedNode('http://test.com/o3'),
      ),
      quad(
        namedNode(`${documentUrl}#s4`),
        namedNode(`${documentUrl}#p4`),
        namedNode(`${documentUrl}#o4`),
      ),
    ];
    await expectQuads(response, expected, true);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can handle simple N3 Patch updates.', async(): Promise<void> => {
    // POST
    const body = [
      '<http://test.com/s1> <http://test.com/p1> <http://test.com/o1>.',
      '<http://test.com/s2> <http://test.com/p2> <http://test.com/o2>.',
    ].join('\n');
    let response = await postResource(baseUrl, { contentType: 'text/turtle', body });
    const documentUrl = response.headers.get('location')!;

    // PATCH
    const query = [
      '@prefix solid: <http://www.w3.org/ns/solid/terms#>.',
      '<> a solid:InsertDeletePatch;',
      'solid:deletes { <http://test.com/s1> <http://test.com/p1> <http://test.com/o1> };',
      'solid:inserts { <http://test.com/s3> <http://test.com/p3> <http://test.com/o3> }.',
    ].join('\n');
    await patchResource(documentUrl, query, 'n3', true);

    // PATCH using a content-type header with charset
    const query2 = [
      '@prefix solid: <http://www.w3.org/ns/solid/terms#>.',
      '<> a solid:InsertDeletePatch;',
      'solid:deletes { <http://test.com/s2> <http://test.com/p2> <http://test.com/o2> };',
      'solid:inserts {<#s4> <#p4> <#o4>}.',
    ].join('\n');
    response = await fetch(documentUrl, {
      method: 'PATCH',
      headers: {
        'content-type': 'text/n3 ; charset=UTF-8',
      },
      body: query2,
    });
    await expect(response.text()).resolves.toHaveLength(0);
    expect(response.status).toBe(205);

    // GET
    response = await getResource(documentUrl);
    const expected = [
      quad(
        namedNode('http://test.com/s3'),
        namedNode('http://test.com/p3'),
        namedNode('http://test.com/o3'),
      ),
      quad(
        namedNode(`${documentUrl}#s4`),
        namedNode(`${documentUrl}#p4`),
        namedNode(`${documentUrl}#o4`),
      ),
    ];
    await expectQuads(response, expected, true);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can not handle SPARQL updates on containers.', async(): Promise<void> => {
    // POST
    const body = [
      '<http://test.com/s1> <http://test.com/p1> <http://test.com/o1>.',
      '<http://test.com/s2> <http://test.com/p2> <http://test.com/o2>.',
    ].join('\n');
    let response = await postResource(baseUrl, { contentType: 'text/turtle', body, isContainer: true });
    const documentUrl = response.headers.get('location')!;

    // PATCH
    const query = [
      'DELETE { <http://test.com/s1> <http://test.com/p1> <http://test.com/o1> }',
      'INSERT {<http://test.com/s3> <http://test.com/p3> <http://test.com/o3>}',
      'WHERE {}',
    ].join('\n');

    // We don't want you to PATCH on containers
    response = await fetch(documentUrl, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/sparql-update',
      },
      body: query,
    });
    expect(response.status).toBe(409);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can not handle N3 Patch updates on containers.', async(): Promise<void> => {
    // POST
    const body = [
      '<http://test.com/s1> <http://test.com/p1> <http://test.com/o1>.',
      '<http://test.com/s2> <http://test.com/p2> <http://test.com/o2>.',
    ].join('\n');
    let response = await postResource(baseUrl, { contentType: 'text/turtle', body, isContainer: true });
    const documentUrl = response.headers.get('location')!;

    // PATCH
    const query = [
      '@prefix solid: <http://www.w3.org/ns/solid/terms#>.',
      '<> a solid:InsertDeletePatch;',
      'solid:deletes { <http://test.com/s1> <http://test.com/p1> <http://test.com/o1> };',
      'solid:inserts { <http://test.com/s3> <http://test.com/p3> <http://test.com/o3> }.',
    ].join('\n');

    // We don't want you to PATCH on containers
    response = await fetch(documentUrl, {
      method: 'PATCH',
      headers: {
        'content-type': 'text/n3',
      },
      body: query,
    });
    expect(response.status).toBe(409);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('returns 405 for unsupported methods.', async(): Promise<void> => {
    let response = await fetch(baseUrl, { method: 'TRACE' });
    expect(response.status).toBe(405);

    // Testing two different URLs as there used to be a problem with this
    response = await fetch(joinUrl(baseUrl, 'foo'), { method: 'TRACE' });
    expect(response.status).toBe(405);
  });

  it('returns 415 for unsupported PATCH types.', async(): Promise<void> => {
    const response = await fetch(baseUrl, { method: 'PATCH', headers: { 'content-type': 'text/plain' }, body: 'abc' });
    expect(response.status).toBe(415);
  });

  it('maintains prefixes after PATCH operations.', async(): Promise<void> => {
    // POST
    const body = [
      '@prefix test: <http://test.com/>.',
      'test:s1 test:p1 test:o1.',
      'test:s2 test:p2 test:o2.',
    ].join('\n');
    let response = await postResource(baseUrl, { contentType: 'text/turtle', body });
    const documentUrl = response.headers.get('location')!;

    // PATCH
    const query = [
      'PREFIX test: <http://test.com/>',
      'DELETE { test:s1 test:p1 test:o1 }',
      'INSERT { test:s3 test:p3 test:o3. test:s4 test:p4 test:o4 }',
      'WHERE {}',
    ].join('\n');
    await patchResource(documentUrl, query, 'sparql', true);

    // GET
    response = await getResource(documentUrl);
    const parser = new Parser();
    const quads: Quad[] = [];
    let prefixes: any = {};
    const text = await response.clone().text();
    const promise = new Promise<void>((resolve, reject): void => {
      parser.parse(text, (error, aQuad, prefixHash): any => {
        if (aQuad) {
          quads.push(aQuad);
        }
        if (!aQuad) {
          prefixes = prefixHash;
          resolve();
        }
        if (error) {
          reject(error);
        }
      });
    });

    await promise;

    const expected = [
      quad(
        namedNode('http://test.com/s2'),
        namedNode('http://test.com/p2'),
        namedNode('http://test.com/o2'),
      ),
      quad(
        namedNode('http://test.com/s3'),
        namedNode('http://test.com/p3'),
        namedNode('http://test.com/o3'),
      ),
      quad(
        namedNode('http://test.com/s4'),
        namedNode('http://test.com/p4'),
        namedNode('http://test.com/o4'),
      ),
    ];
    await expectQuads(response, expected, true);
    expect(prefixes).toEqual({
      test: 'http://test.com/',
    });
    expect(quads).toHaveLength(3);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can not delete metadata resources directly.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}document.txt`;

    // PUT
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE0' });

    // DELETE metadata attempt
    const response = await fetch(documentUrl + metaSuffix, { method: 'DELETE' });
    expect(response.status).toBe(409);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can not create metadata directly.', async(): Promise<void> => {
    const slug = `document.txt${metaSuffix}`;
    const documentMetaURL = `${baseUrl}${slug}`;

    // POST
    const postResponse = await fetch(baseUrl, {
      method: 'POST',
      headers: { 'content-type': 'text/turtle', slug },
      body: '<a> <b> <c>.',
    });
    expect(postResponse.status).toBe(403);

    // PUT
    const putResponse = await fetch(documentMetaURL, {
      method: 'PUT',
      headers: { 'content-type': 'text/turtle' },
      body: '<a> <b> <c>.',
    });
    expect(putResponse.status).toBe(405);

    // PATCH
    const patchResponse = await fetch(documentMetaURL, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update' },
      body: 'INSERT DATA {<a> <b> <c>.}',
    });
    expect(patchResponse.status).toBe(409);
  });

  it('can update metadata triples using PATCH.', async(): Promise<void> => {
    const documentUrl = `${baseUrl}document.txt`;
    const documentMetaURL = `${documentUrl}${metaSuffix}`;

    // PUT
    await putResource(documentUrl, { contentType: 'text/plain', body: 'TESTFILE0' });

    // PATCH
    const patchResponse = await fetch(documentMetaURL, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update' },
      body: 'INSERT DATA {<a> <b> <c>.}',
    });
    expect(patchResponse.status).toBe(205);

    // GET
    const response = await fetch(documentMetaURL);
    await expectQuads(response, [ quad(namedNode(`${baseUrl}a`), namedNode(`${baseUrl}b`), namedNode(`${baseUrl}c`)) ]);

    // DELETE
    await expect(deleteResource(documentUrl)).resolves.toBeUndefined();
  });

  it('can not update metadata triples that are deemed immutable.', async(): Promise<void> => {
    const containerUrl = `${baseUrl}immutable/`;
    const metaUrl = containerUrl + metaSuffix;

    // PUT
    await putResource(containerUrl, { contentType: 'text/turtle' });

    // PATCH
    const pimResponse = await fetch(metaUrl, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update' },
      body: `INSERT DATA {<${containerUrl}> <${RDF.type}> <${PIM.Storage}>.}`,
    });
    expect(pimResponse.status).toBe(409);

    const ldpResponse = await fetch(metaUrl, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update' },
      body: `INSERT DATA {<${containerUrl}> <${LDP.contains}> <b>.}`,
    });
    expect(ldpResponse.status).toBe(409);

    // DELETE
    await expect(deleteResource(containerUrl)).resolves.toBeUndefined();
  });

  it('can not create metadata resource of a metadata resource.', async(): Promise<void> => {
    const metaUrl = baseUrl + metaSuffix + metaSuffix;
    const response = await fetch(metaUrl, {
      method: 'PATCH',
      headers: { 'content-type': 'application/sparql-update' },
      body: `INSERT DATA {<a> <b> <c>.}`,
    });
    expect(response.status).toBe(409);
  });

  it('returns metadata resource location in link header.', async(): Promise<void> => {
    const response = await fetch(baseUrl, { method: 'HEAD' });
    expect(response.headers.get('link')).toContain(`<${baseUrl}${metaSuffix}>; rel="describedby"`);
  });

  it('can read metadata.', async(): Promise<void> => {
    const response = await fetch(baseUrl + metaSuffix);
    expect(response.status).toBe(200);
    const allows = splitCommaSeparated(response.headers.get('allow') ?? '');
    expect(allows.sort()).toEqual([ 'GET', 'HEAD', 'OPTIONS', 'PATCH' ]);
    expect(response.headers.get('accept-patch')).toBe('text/n3, application/sparql-update');
    await expectQuads(response, [ quad(namedNode(baseUrl), namedNode(RDF.type), namedNode(PIM.Storage)) ]);
  });

  it('preserves metadata when link header is present.', async(): Promise<void> => {
    const resourceUrl = `${baseUrl}preserved`;
    const metaUrl = resourceUrl + metaSuffix;
    // PUT
    await putResource(resourceUrl, { contentType: 'text/turtle', body: '<a> <b> <c>.' });

    // PATCH
    await patchResource(metaUrl, `INSERT DATA {<${baseUrl}a> <${baseUrl}b> <${baseUrl}c>.}`, 'sparql', true);

    // PUT
    const preserveResource = await fetch(resourceUrl, {
      method: 'PUT',
      headers: {
        'content-type': 'text/turtle',
        link: `<${metaUrl}>;rel="preserve"`,
      },
      body: '<a> <b> <d>.',
    });
    expect(preserveResource.status).toBe(205);

    const metadataResponse = await fetch(metaUrl);
    const metadata = await metadataResponse.text();
    expect(metadata).toContain(`<${baseUrl}a> <${baseUrl}b> <${baseUrl}c>.`);

    // DELETE
    await deleteResource(resourceUrl);
  });

  it('clears metadata by default.', async(): Promise<void> => {
    const resourceUrl = `${baseUrl}notPreserved`;
    const metaUrl = resourceUrl + metaSuffix;
    // PUT
    await putResource(resourceUrl, { contentType: 'text/turtle', body: '<a> <b> <c>.' });

    // PATCH
    await patchResource(metaUrl, `INSERT DATA {<a> <b> <c>.}`, 'sparql', true);

    // PUT
    await putResource(resourceUrl, { contentType: 'text/turtle', body: '<a> <b> <d>.', exists: true });

    const metadataResponse = await fetch(metaUrl);
    const metadata = await metadataResponse.text();
    expect(metadata).not.toContain(`<${baseUrl}a> <${baseUrl}b> <${baseUrl}c>.`);

    // DELETE
    await deleteResource(resourceUrl);
  });

  it('supports range requests.', async(): Promise<void> => {
    const resourceUrl = joinUrl(baseUrl, 'range');
    await putResource(resourceUrl, { contentType: 'text/plain', body: '0123456789' });

    let response = await fetch(resourceUrl, { headers: { range: 'bytes=0-5' }});
    expect(response.status).toBe(206);
    expect(response.headers.get('content-range')).toBe('bytes 0-5/10');
    expect(response.headers.get('content-length')).toBe('6');
    await expect(response.text()).resolves.toBe('012345');

    response = await fetch(resourceUrl, { headers: { range: 'bytes=5-' }});
    expect(response.status).toBe(206);
    expect(response.headers.get('content-range')).toBe('bytes 5-9/10');
    expect(response.headers.get('content-length')).toBe('5');
    await expect(response.text()).resolves.toBe('56789');

    response = await fetch(resourceUrl, { headers: { range: 'bytes=-4' }});
    expect(response.status).toBe(206);
    expect(response.headers.get('content-range')).toBe('bytes 6-9/10');
    expect(response.headers.get('content-length')).toBe('4');
    await expect(response.text()).resolves.toBe('6789');

    response = await fetch(resourceUrl, { headers: { range: 'bytes=5-15' }});
    expect(response.status).toBe(416);
  });
});

import fetch from 'cross-fetch';
import { WebSocket } from 'ws';
import type { App } from '../../src/init/App';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, instantiateFromConfig } from './Config';

const port = getPort('LegacyWebSocketsProtocol');
const serverUrl = `http://localhost:${port}/`;
const headers = { forwarded: 'host=example.pod;proto=https' };

describe('A server with the Solid WebSockets API behind a proxy', (): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    app = await instantiateFromConfig(
      'urn:solid-server:default:App',
      getTestConfigPath('legacy-websockets.json'),
      getDefaultVariables(port, 'https://example.pod/'),
    ) as App;

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await app.stop();
  });

  it('returns a 404 if there is no data.', async(): Promise<void> => {
    const response = await fetch(`${serverUrl}foo`, { headers });
    expect(response.status).toBe(404);
  });

  it('sets the Updates-Via header.', async(): Promise<void> => {
    const response = await fetch(serverUrl, { headers });
    expect(response.headers.get('Updates-Via')).toBe('wss://example.pod/');
  });

  it('exposes the Updates-Via header via CORS.', async(): Promise<void> => {
    const response = await fetch(serverUrl, { headers });
    expect(response.headers.get('Access-Control-Expose-Headers')!.split(','))
      .toContain('Updates-Via');
  });

  describe('when a WebSocket client connects', (): void => {
    let client: WebSocket;
    const messages = new Array<string>();

    beforeAll(async(): Promise<void> => {
      client = new WebSocket(`ws://localhost:${port}`, [ 'solid-0.1' ], { headers });
      client.on('message', (message: Buffer): any => messages.push(message.toString()));
      await new Promise((resolve): any => client.on('open', resolve));
    });

    afterEach((): void => {
      messages.length = 0;
    });

    afterAll((): void => {
      client.close();
    });

    it('sends the protocol version.', (): void => {
      expect(messages).toEqual([
        'protocol solid-0.1',
      ]);
    });

    describe('when the client subscribes to resources', (): void => {
      beforeAll(async(): Promise<void> => {
        client.send('sub https://example.pod/my-resource');
        client.send('sub https://example.pod/other-resource');
        client.send('sub https://example.pod/');
        await new Promise((resolve): any => client.once('message', resolve));
      });

      it('acknowledges the subscription.', async(): Promise<void> => {
        expect(messages).toEqual([
          'ack https://example.pod/my-resource',
          'ack https://example.pod/other-resource',
          'ack https://example.pod/',
        ]);
      });

      it('notifies the client of resource updates.', async(): Promise<void> => {
        await fetch(`${serverUrl}my-resource`, {
          method: 'PUT',
          headers: {
            ...headers,
            'content-type': 'application/json',
          },
          body: '{}',
        });
        expect(messages).toEqual([
          'pub https://example.pod/',
          'pub https://example.pod/my-resource',
        ]);
      });
    });
  });
});

import { RoutingAuxiliaryStrategy } from '../../src/http/auxiliary/RoutingAuxiliaryStrategy';
import { BasicRepresentation } from '../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../src/http/representation/RepresentationMetadata';
import { InMemoryDataAccessor } from '../../src/storage/accessors/InMemoryDataAccessor';
import { DataAccessorBasedStore } from '../../src/storage/DataAccessorBasedStore';
import { LockingResourceStore } from '../../src/storage/LockingResourceStore';
import type { ResourceStore } from '../../src/storage/ResourceStore';
import { APPLICATION_OCTET_STREAM, TEXT_TURTLE } from '../../src/util/ContentTypes';
import { InternalServerError } from '../../src/util/errors/InternalServerError';
import { SingleRootIdentifierStrategy } from '../../src/util/identifiers/SingleRootIdentifierStrategy';
import { EqualReadWriteLocker } from '../../src/util/locking/EqualReadWriteLocker';
import type { ExpiringReadWriteLocker } from '../../src/util/locking/ExpiringReadWriteLocker';
import { MemoryResourceLocker } from '../../src/util/locking/MemoryResourceLocker';
import type { ReadWriteLocker } from '../../src/util/locking/ReadWriteLocker';
import { WrappedExpiringReadWriteLocker } from '../../src/util/locking/WrappedExpiringReadWriteLocker';
import { guardedStreamFrom } from '../../src/util/StreamUtil';
import { PIM, RDF } from '../../src/util/Vocabularies';
import { SimpleSuffixStrategy } from '../util/SimpleSuffixStrategy';
import { flushPromises } from '../util/Util';

jest.useFakeTimers();

describe('A LockingResourceStore', (): void => {
  let path: string;
  let store: LockingResourceStore;
  let locker: ReadWriteLocker;
  let expiringLocker: ExpiringReadWriteLocker;
  let source: ResourceStore;
  let getRepresentationSpy: jest.SpyInstance;

  beforeEach(async(): Promise<void> => {
    jest.clearAllMocks();

    // Not relevant for these tests
    const strategy = new RoutingAuxiliaryStrategy([]);
    const metadataStrategy = new SimpleSuffixStrategy('.meta');

    const base = 'http://test.com/';
    path = `${base}path`;
    const idStrategy = new SingleRootIdentifierStrategy(base);
    source = new DataAccessorBasedStore(
      new InMemoryDataAccessor(idStrategy),
      idStrategy,
      strategy,
      metadataStrategy,
    );

    // Initialize store
    const metadata = new RepresentationMetadata({ path: base }, TEXT_TURTLE);
    metadata.add(RDF.terms.type, PIM.terms.Storage);
    await source.setRepresentation({ path: base }, new BasicRepresentation([], metadata));

    locker = new EqualReadWriteLocker(new MemoryResourceLocker());
    expiringLocker = new WrappedExpiringReadWriteLocker(locker, 1000);

    store = new LockingResourceStore(source, expiringLocker, strategy);

    // Spy on a real ResourceLocker and ResourceStore instance
    getRepresentationSpy = jest.spyOn(source, 'getRepresentation');
    getRepresentationSpy.mockReturnValue(new Promise((resolve): any => resolve({ data:
        guardedStreamFrom([ 1, 2, 3 ]) } as Representation)));

    // Make sure something is in the store before we read from it in our tests.
    await source.setRepresentation({ path }, new BasicRepresentation([ 1, 2, 3 ], APPLICATION_OCTET_STREAM));
  });

  it('destroys the stream when nothing is read after 1000ms.', async(): Promise<void> => {
    const representation = await store.getRepresentation({ path }, {});
    const errorCallback = jest.fn();
    representation.data.on('error', errorCallback);

    // Wait 1000ms and read
    jest.advanceTimersByTime(1000);
    await flushPromises();
    expect(representation.data.destroyed).toBe(true);

    // Verify a timeout error was thrown
    expect(errorCallback).toHaveBeenCalledTimes(1);
    expect(errorCallback).toHaveBeenLastCalledWith(new InternalServerError(`Lock expired after 1000ms on ${path}`));

    // Verify the lock was acquired and released at the right time
    expect(getRepresentationSpy).toHaveBeenCalledTimes(1);
  });

  it('destroys the stream when pauses between reads exceed 1000ms.', async(): Promise<void> => {
    const representation = await store.getRepresentation({ path }, {});
    const errorCallback = jest.fn();
    representation.data.on('error', errorCallback);

    // Wait 750ms and read
    jest.advanceTimersByTime(750);
    expect(representation.data.destroyed).toBe(false);
    representation.data.read();

    // Wait 750ms and read
    jest.advanceTimersByTime(750);
    expect(representation.data.destroyed).toBe(false);
    representation.data.read();

    // Wait 1000ms and watch the stream be destroyed
    jest.advanceTimersByTime(1000);
    await flushPromises();
    expect(representation.data.destroyed).toBe(true);

    // Verify a timeout error was thrown
    expect(errorCallback).toHaveBeenCalledTimes(1);
    expect(errorCallback).toHaveBeenLastCalledWith(new InternalServerError(`Lock expired after 1000ms on ${path}`));

    // Verify the lock was acquired and released at the right time
    expect(getRepresentationSpy).toHaveBeenCalledTimes(1);
  });
});

import type { Server } from 'node:http';
import request from 'supertest';
import type { App } from '../../src/init/App';
import type { HttpServerFactory } from '../../src/server/HttpServerFactory';
import { splitCommaSeparated } from '../../src/util/StringUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, instantiateFromConfig } from './Config';

const port = getPort('Middleware');

describe('An http server with middleware', (): void => {
  let app: App;
  let server: Server;

  beforeAll(async(): Promise<void> => {
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getTestConfigPath('server-middleware.json'),
      ],
      getDefaultVariables(port),
    ) as { app: App; factory: HttpServerFactory };

    ({ app } = instances);

    server = await instances.factory.createServer();
    server.listen(port);
  });

  afterAll(async(): Promise<void> => {
    server.close();
    // Even though the server was started separately, there might still be finalizers that need to be stopped
    await app.stop();
  });

  it('sets a Vary header containing Accept.', async(): Promise<void> => {
    const res = await request(server).get('/');
    expect(res.header).toEqual(expect.objectContaining({
      vary: expect.stringMatching(/(^|,)\s*Accept\s*(,|$)/iu),
    }));
  });

  it('sets a Vary header containing Authorization.', async(): Promise<void> => {
    const res = await request(server).get('/');
    expect(res.header).toEqual(expect.objectContaining({
      vary: expect.stringMatching(/(^|,)\s*Authorization\s*(,|$)/iu),
    }));
  });

  it('sets a Vary header containing Origin.', async(): Promise<void> => {
    const res = await request(server).get('/');
    expect(res.header).toEqual(expect.objectContaining({
      vary: expect.stringMatching(/(^|,)\s*Origin\s*(,|$)/iu),
    }));
  });

  it('sends server identification in the X-Powered-By header.', async(): Promise<void> => {
    const res = await request(server).get('/');
    expect(res.header).toEqual(expect.objectContaining({
      'x-powered-by': 'Community Solid Server',
    }));
  });

  it('returns all relevant headers for an OPTIONS request.', async(): Promise<void> => {
    const res = await request(server)
      .options('/')
      .set('Access-Control-Allow-Credentials', 'true')
      .set('Access-Control-Request-Headers', 'content-type')
      .set('Access-Control-Request-Method', 'POST')
      .set('Host', 'test.com')
      .expect(204);
    expect(res.header).toEqual(expect.objectContaining({
      'access-control-allow-origin': '*',
      'access-control-allow-headers': 'content-type',
      'x-powered-by': 'Community Solid Server',
    }));
    const { vary } = res.header;
    expect(vary).toMatch(/(^|,)\s*Accept\s*(,|$)/iu);
    expect(vary).toMatch(/(^|,)\s*Authorization\s*(,|$)/iu);
    expect(vary).toMatch(/(^|,)\s*Origin\s*(,|$)/iu);
    const corsMethods = res.header['access-control-allow-methods'].split(',')
      .map((method: string): string => method.trim());
    const allowedMethods = [ 'GET', 'HEAD', 'OPTIONS', 'POST', 'PUT', 'PATCH', 'DELETE' ];
    expect(corsMethods).toEqual(expect.arrayContaining(allowedMethods));
    expect(corsMethods).toHaveLength(allowedMethods.length);
  });

  it('specifies CORS origin header if an origin was supplied.', async(): Promise<void> => {
    const res = await request(server).options('/').set('origin', 'test.com').expect(204);
    expect(res.header).toEqual(expect.objectContaining({ 'access-control-allow-origin': 'test.com' }));
  });

  it('exposes the Accept-[Method] header via CORS.', async(): Promise<void> => {
    const res = await request(server).options('/').expect(204);
    const exposed = res.header['access-control-expose-headers'];
    expect(splitCommaSeparated(exposed)).toContain('Accept-Patch');
    expect(splitCommaSeparated(exposed)).toContain('Accept-Post');
    expect(splitCommaSeparated(exposed)).toContain('Accept-Put');
  });

  it('exposes the Last-Modified and ETag headers via CORS.', async(): Promise<void> => {
    const res = await request(server).options('/').expect(204);
    const exposed = res.header['access-control-expose-headers'];
    expect(splitCommaSeparated(exposed)).toContain('ETag');
    expect(splitCommaSeparated(exposed)).toContain('Last-Modified');
  });

  it('exposes the Link header via CORS.', async(): Promise<void> => {
    const res = await request(server).options('/').expect(204);
    const exposed = res.header['access-control-expose-headers'];
    expect(splitCommaSeparated(exposed)).toContain('Link');
  });

  it('exposes the Location header via CORS.', async(): Promise<void> => {
    const res = await request(server).options('/').expect(204);
    const exposed = res.header['access-control-expose-headers'];
    expect(splitCommaSeparated(exposed)).toContain('Location');
  });

  it('exposes the WAC-Allow header via CORS.', async(): Promise<void> => {
    const res = await request(server).options('/').expect(204);
    const exposed = res.header['access-control-expose-headers'];
    expect(splitCommaSeparated(exposed)).toContain('WAC-Allow');
  });

  it('exposes the Updates-Via header via CORS.', async(): Promise<void> => {
    const res = await request(server).options('/').expect(204);
    const exposed = res.header['access-control-expose-headers'];
    expect(splitCommaSeparated(exposed)).toContain('Updates-Via');
  });

  it('exposes the Www-Authenticate header via CORS.', async(): Promise<void> => {
    const res = await request(server).options('/').expect(204);
    const exposed = res.header['access-control-expose-headers'];
    expect(splitCommaSeparated(exposed)).toContain('Www-Authenticate');
  });
});

import 'jest-rdf';
import { fetch } from 'cross-fetch';
import { Parser } from 'n3';
import type { AclPermissionSet } from '../../src/authorization/permissions/AclPermissionSet';
import { BasicRepresentation } from '../../src/http/representation/BasicRepresentation';
import type { App } from '../../src/init/App';
import type { ResourceStore } from '../../src/storage/ResourceStore';
import { joinUrl } from '../../src/util/PathUtil';
import { AclHelper } from '../util/AclHelper';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  instantiateFromConfig,
} from './Config';

const port = getPort('N3Patch');
const baseUrl = `http://localhost:${port}/`;

let store: ResourceStore;
let aclHelper: AclHelper;

async function expectPatch(
  input: { path: string; contentType?: string; body: string },
  expected: { status: number; message?: string; turtle?: string },
): Promise<void> {
  const message = expected.message ?? '';
  const contentType = input.contentType ?? 'text/n3';

  const body = `@prefix solid: <http://www.w3.org/ns/solid/terms#>.
  ${input.body}`;

  const url = joinUrl(baseUrl, input.path);
  const res = await fetch(url, {
    method: 'PATCH',
    headers: { 'content-type': contentType },
    body,
  });
  await expect(res.text()).resolves.toContain(message);
  expect(res.status).toBe(expected.status);

  // Verify if the resource has the expected RDF data
  if (expected.turtle) {
    // Might not have read permissions so need to update
    await aclHelper.setSimpleAcl(url, { permissions: { read: true }, agentClass: 'agent', accessTo: true });
    const get = await fetch(url, {
      method: 'GET',
      headers: { accept: 'text/turtle' },
    });
    const expectedTurtle = `@prefix solid: <http://www.w3.org/ns/solid/terms#>.
    ${expected.turtle}`;

    expect(get.status).toBe(200);
    const parser = new Parser({ format: 'text/turtle', baseIRI: url });
    const actualTriples = parser.parse(await get.text());
    expect(actualTriples).toBeRdfIsomorphic(parser.parse(expectedTurtle));
  }
}

// Creates/updates a resource with the given data and permissions
async function setResource(path: string, turtle: string, permissions: AclPermissionSet): Promise<void> {
  const url = joinUrl(baseUrl, path);
  await store.setRepresentation({ path: url }, new BasicRepresentation(turtle, 'text/turtle'));
  await aclHelper.setSimpleAcl(url, { permissions, agentClass: 'agent', accessTo: true });
}

describe('A Server supporting N3 Patch', (): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getPresetConfigPath('storage/backend/memory.json'),
        getTestConfigPath('ldp-with-auth.json'),
      ],
      getDefaultVariables(port, baseUrl),
    ) as Record<string, any>;
    ({ app, store } = instances);

    await app.start();

    // Create test helper for manipulating acl
    aclHelper = new AclHelper(store);
  });

  afterAll(async(): Promise<void> => {
    await app.stop();
  });

  describe('with an invalid patch document', (): void => {
    it('requires text/n3 content-type.', async(): Promise<void> => {
      await expectPatch(
        { path: '/invalid', contentType: 'text/other', body: '' },
        { status: 415 },
      );
    });

    it('requires valid syntax.', async(): Promise<void> => {
      await expectPatch(
        { path: '/invalid', body: 'invalid syntax' },
        { status: 400, message: 'Invalid N3' },
      );
    });

    it('requires a solid:InsertDeletePatch.', async(): Promise<void> => {
      await expectPatch(
        { path: '/invalid', body: '<> a solid:Patch.' },
        {
          status: 422,
          message: 'This patcher only supports N3 Patch documents with exactly 1 solid:InsertDeletePatch entry',
        },
      );
    });
  });

  describe('inserting data', (): void => {
    it('succeeds if there is no resource.', async(): Promise<void> => {
      await expectPatch(
        { path: '/new-insert', body: `<> a solid:InsertDeletePatch; solid:inserts { <x> <y> <z>. }.` },
        { status: 201, turtle: '<x> <y> <z>.' },
      );
    });

    it('fails if there is only read access.', async(): Promise<void> => {
      await setResource('/read-only', '<a> <b> <c>.', { read: true });
      await expectPatch(
        { path: '/read-only', body: `<> a solid:InsertDeletePatch; solid:inserts { <x> <y> <z>. }.` },
        { status: 401 },
      );
    });

    it('succeeds if there is only read access.', async(): Promise<void> => {
      await setResource('/append-only', '<a> <b> <c>.', { append: true });
      await expectPatch(
        { path: '/append-only', body: `<> a solid:InsertDeletePatch; solid:inserts { <x> <y> <z>. }.` },
        { status: 205, turtle: '<a> <b> <c>. <x> <y> <z>.' },
      );
    });

    it('succeeds if there is only write access.', async(): Promise<void> => {
      await setResource('/write-only', '<a> <b> <c>.', { write: true });
      await expectPatch(
        { path: '/write-only', body: `<> a solid:InsertDeletePatch; solid:inserts { <x> <y> <z>. }.` },
        { status: 205, turtle: '<a> <b> <c>. <x> <y> <z>.' },
      );
    });
  });

  describe('inserting conditional data', (): void => {
    it('fails if there is no resource.', async(): Promise<void> => {
      await expectPatch(
        { path: '/new-insert-where', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <b> <c>. }.` },
        { status: 409, message: 'The document does not contain any matches for the N3 Patch solid:where condition.' },
      );
    });

    it('fails if there is only read access.', async(): Promise<void> => {
      await setResource('/read-only', '<a> <b> <c>.', { read: true });
      await expectPatch(
        { path: '/read-only', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <b> <c>. }.` },
        { status: 401 },
      );
    });

    it('fails if there is only append access.', async(): Promise<void> => {
      await setResource('/append-only', '<a> <b> <c>.', { append: true });
      await expectPatch(
        { path: '/append-only', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <b> <c>. }.` },
        { status: 401 },
      );
    });

    it('fails if there is only write access.', async(): Promise<void> => {
      await setResource('/write-only', '<a> <b> <c>.', { write: true });
      await expectPatch(
        { path: '/write-only', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <b> <c>. }.` },
        { status: 401 },
      );
    });

    describe('with read/append access', (): void => {
      it('succeeds if the conditions match.', async(): Promise<void> => {
        await setResource('/read-append', '<a> <b> <c>.', { read: true, append: true });
        await expectPatch(
          { path: '/read-append', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <b> <c>. }.` },
          { status: 205, turtle: '<a> <b> <c>. <a> <y> <z>.' },
        );
      });

      it('rejects if there is no match.', async(): Promise<void> => {
        await setResource('/read-append', '<a> <b> <c>.', { read: true, append: true });
        await expectPatch(
          { path: '/read-append', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <y> <z>. }.` },
          { status: 409, message: 'The document does not contain any matches for the N3 Patch solid:where condition.' },
        );
      });

      it('rejects if there are multiple matches.', async(): Promise<void> => {
        await setResource('/read-append', '<a> <b> <c>. <c> <b> <c>.', { read: true, append: true });
        await expectPatch(
          { path: '/read-append', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <b> <c>. }.` },
          { status: 409, message: 'The document contains multiple matches for the N3 Patch solid:where condition' },
        );
      });
    });

    describe('with read/write access', (): void => {
      it('succeeds if the conditions match.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { ?a <y> <z>. };
                 solid:where   { ?a <b> <c>. }.` },
          { status: 205, turtle: '<a> <b> <c>. <a> <y> <z>.' },
        );
      });
    });
  });

  describe('deleting data', (): void => {
    it('fails if there is no resource.', async(): Promise<void> => {
      await expectPatch(
        { path: '/new-delete', body: `<> a solid:InsertDeletePatch;
                 solid:deletes { <x> <y> <z>. }.` },
        { status: 409, message: 'The document does not contain all triples the N3 Patch requests to delete' },
      );
    });

    it('fails if there is only append access.', async(): Promise<void> => {
      await setResource('/append-only', '<a> <b> <c>.', { append: true });
      await expectPatch(
        { path: '/append-only', body: `<> a solid:InsertDeletePatch;
                 solid:deletes { <x> <y> <z>. }.` },
        { status: 401 },
      );
    });

    it('fails if there is only write access.', async(): Promise<void> => {
      await setResource('/write-only', '<a> <b> <c>.', { write: true });
      await expectPatch(
        { path: '/write-only', body: `<> a solid:InsertDeletePatch;
                 solid:deletes { <x> <y> <z>. }.` },
        { status: 401 },
      );
    });

    it('fails if there is only read/append access.', async(): Promise<void> => {
      await setResource('/read-append', '<a> <b> <c>.', { read: true, append: true });
      await expectPatch(
        { path: '/read-append', body: `<> a solid:InsertDeletePatch;
                 solid:deletes { <x> <y> <z>. }.` },
        { status: 401 },
      );
    });

    describe('with read/write access', (): void => {
      it('succeeds if the delete triples exist.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>. <x> <y> <z>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:deletes { <x> <y> <z>. }.` },
          { status: 205, turtle: '<a> <b> <c>.' },
        );
      });

      it('fails if the delete triples do not exist.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>. <x> <y> <z>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:deletes { <a> <y> <z>. }.` },
          { status: 409, message: 'The document does not contain all triples the N3 Patch requests to delete' },
        );
      });

      it('succeeds if the conditions match.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>. <x> <y> <z>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:where   { ?a <y> <z>. };
                 solid:deletes { ?a <y> <z>. }.` },
          { status: 205, turtle: '<a> <b> <c>.' },
        );
      });

      it('fails if the conditions do not match.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:where   { ?a <y> <z>. };
                 solid:deletes { ?a <b> <c>. }.` },
          { status: 409, message: 'The document does not contain any matches for the N3 Patch solid:where condition.' },
        );
      });
    });
  });

  describe('deleting and inserting data', (): void => {
    it('fails if there is no resource.', async(): Promise<void> => {
      await expectPatch(
        { path: '/new-delete-insert', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { <x> <y> <z>. };
                 solid:deletes { <a> <b> <c>. }.` },
        { status: 409, message: 'The document does not contain all triples the N3 Patch requests to delete' },
      );
    });

    it('fails if there is only append access.', async(): Promise<void> => {
      await setResource('/append-only', '<a> <b> <c>.', { append: true });
      await expectPatch(
        { path: '/append-only', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { <x> <y> <z>. };
                 solid:deletes { <a> <b> <c>. }.` },
        { status: 401 },
      );
    });

    it('fails if there is only write access.', async(): Promise<void> => {
      await setResource('/write-only', '<a> <b> <c>.', { write: true });
      await expectPatch(
        { path: '/write-only', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { <x> <y> <z>. };
                 solid:deletes { <a> <b> <c>. }.` },
        { status: 401 },
      );
    });

    it('fails if there is only read/append access.', async(): Promise<void> => {
      await setResource('/read-append', '<a> <b> <c>.', { read: true, append: true });
      await expectPatch(
        { path: '/read-append', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { <x> <y> <z>. };
                 solid:deletes { <a> <b> <c>. }.` },
        { status: 401 },
      );
    });

    describe('with read/write access', (): void => {
      it('executes deletes before inserts.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { <x> <y> <z>. };
                 solid:deletes { <x> <y> <z>. }.` },
          { status: 409, message: 'The document does not contain all triples the N3 Patch requests to delete' },
        );
      });

      it('succeeds if the delete triples exist.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:inserts { <x> <y> <z>. };
                 solid:deletes { <a> <b> <c>. }.` },
          { status: 205, turtle: '<x> <y> <z>.' },
        );
      });

      it('succeeds if the conditions match.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:where   { ?a <b> <c>. };
                 solid:inserts { ?a <y> <z>. };
                 solid:deletes { ?a <b> <c>. }.` },
          { status: 205, turtle: '<a> <y> <z>.' },
        );
      });

      it('fails if the conditions do not match.', async(): Promise<void> => {
        await setResource('/read-write', '<a> <b> <c>.', { read: true, write: true });
        await expectPatch(
          { path: '/read-write', body: `<> a solid:InsertDeletePatch;
                 solid:where   { ?a <y> <z>. };
                 solid:inserts { ?a <y> <z>. };
                 solid:deletes { ?a <b> <c>. }.` },
          { status: 409, message: 'The document does not contain any matches for the N3 Patch solid:where condition.' },
        );
      });
    });
  });
});

import fetch from 'cross-fetch';
import { v4 } from 'uuid';
import type { AclPermissionSet } from '../../src/authorization/permissions/AclPermissionSet';
import { AccessMode as AM } from '../../src/authorization/permissions/Permissions';
import { BasicRepresentation } from '../../src/http/representation/BasicRepresentation';
import type { App } from '../../src/init/App';
import type { ResourceStore } from '../../src/storage/ResourceStore';
import { TEXT_TURTLE } from '../../src/util/ContentTypes';
import { ConflictHttpError } from '../../src/util/errors/ConflictHttpError';
import { ensureTrailingSlash, joinUrl } from '../../src/util/PathUtil';
import { AclHelper } from '../util/AclHelper';
import { AcpHelper } from '../util/AcpHelper';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';

const DEFAULT_BODY = `@prefix solid: <http://www.w3.org/ns/solid/terms#>.
@prefix ex: <http://www.example.org/terms#>.

ex:custom ex:givenName "Claudia".`;

const INSERT = `@prefix solid: <http://www.w3.org/ns/solid/terms#>.
@prefix ex: <http://www.example.org/terms#>.
_:patch a solid:InsertDeletePatch;
  solid:inserts { ex:custom ex:givenName "Alex". }.`;

const DELETE = `@prefix solid: <http://www.w3.org/ns/solid/terms#>.
@prefix ex: <http://www.example.org/terms#>.

_:rename a solid:InsertDeletePatch;
  solid:deletes { ex:custom ex:givenName "Claudia". }.`;

const N3 = 'text/n3';
const TXT = 'text/plain';

const allModes = [ AM.read, AM.append, AM.create, AM.write, AM.delete ];

// Based on https://github.com/solid/specification/issues/14#issuecomment-683480525
// Columns: method, target, C/ permissions, C/R permissions, body, content-type, target exists, target does not exist
// `undefined` implies C/R inherits the permissions of C/
// For PUT/PATCH/DELETE we return 205 instead of 200/204
/* eslint-disable @stylistic/no-multi-spaces */
const table: [string, string, AM[], AM[] | undefined, string, string, number, number][] = [
  // No authorization headers are sent in an OPTIONS request making it impossible to grant permission.
  // See https://github.com/CommunitySolidServer/CommunitySolidServer/issues/1246#issuecomment-1087325235
  // From https://fetch.spec.whatwg.org/#cors-preflight-fetch it follows
  // that a preflight check should always return an OK response.
  [ 'OPTIONS', 'C/R', [],                     undefined,              '',     '',  204, 204 ],
  [ 'OPTIONS', 'C/R', [],                     [ AM.read ],            '',     '',  204, 204 ],
  [ 'OPTIONS', 'C/R', [ AM.read ],            undefined,              '',     '',  204, 204 ],

  [ 'HEAD',    'C/R', [],                     undefined,              '',     '',  401, 401 ],
  [ 'HEAD',    'C/R', [],                     [ AM.read ],            '',     '',  200, 404 ],
  [ 'HEAD',    'C/R', [ AM.read ],            undefined,              '',     '',  200, 404 ],

  [ 'GET',     'C/R', [],                     undefined,              '',     '',  401, 401 ],
  [ 'GET',     'C/R', [],                     [ AM.read ],            '',     '',  200, 404 ],
  [ 'GET',     'C/R', [ AM.read ],            undefined,              '',     '',  200, 404 ],
  // Agreed upon deviation from the original table; more conservative interpretation allowed.
  // Original returns 404 in the case of C/R not existing.
  [ 'GET',     'C/R', [ AM.read ],            [ AM.write ],           '',     '',  401, 401 ],

  [ 'POST',    'C/',  [],                     undefined,              '',     TXT, 401, 401 ],
  [ 'POST',    'C/',  [],                     [ AM.read ],            '',     TXT, 401, 401 ],
  [ 'POST',    'C/',  [ AM.append ],          undefined,              '',     TXT, 201, 201 ],
  [ 'POST',    'C/',  [ AM.append ],          [ AM.read ],            '',     TXT, 201, 201 ],
  [ 'POST',    'C/',  [ AM.read, AM.append ], undefined,              '',     TXT, 201, 201 ],
  [ 'POST',    'C/',  [ AM.read, AM.append ], [ AM.read ],            '',     TXT, 201, 201 ],

  [ 'PUT',     'C/',  [],                     undefined,              '',     N3,  401, 401 ],
  [ 'PUT',     'C/',  [ AM.read ],            undefined,              '',     N3,  401, 401 ],
  // We return a 409 when targeting an existing container as we only allow changes targeting the metadata directly
  [ 'PUT',     'C/',  [ AM.write ],           undefined,              '',     '',  409, 201 ],

  [ 'PUT',     'C/R', [],                     undefined,              '',     TXT, 401, 401 ],
  [ 'PUT',     'C/R', [],                     [ AM.read ],            '',     TXT, 401, 401 ],
  [ 'PUT',     'C/R', [],                     [ AM.append ],          '',     TXT, 401, 401 ],
  [ 'PUT',     'C/R', [],                     [ AM.write ],           '',     TXT, 205, 401 ],
  [ 'PUT',     'C/R', [ AM.read ],            undefined,              '',     TXT, 401, 401 ],
  [ 'PUT',     'C/R', [ AM.append ],          undefined,              '',     TXT, 401, 201 ],
  [ 'PUT',     'C/R', [ AM.write ],           undefined,              '',     TXT, 205, 201 ],
  [ 'PUT',     'C/R', [ AM.append ],          [ AM.write ],           '',     TXT, 205, 201 ],

  // All PATCH operations with read permissions return 401 instead of 404 if the target does not exist.
  // This is a consequence of PATCH always creating a resource in case it does not exist.
  // https://solidproject.org/TR/2021/protocol-20211217#n3-patch
  // "Start from the RDF dataset in the target document,
  // or an empty RDF dataset if the target resource does not exist yet."
  [ 'PATCH',   'C/R', [],                     undefined,              DELETE, N3,  401, 401 ],
  [ 'PATCH',   'C/R', [],                     [ AM.read ],            DELETE, N3,  401, 401 ],
  [ 'PATCH',   'C/R', [],                     [ AM.append ],          INSERT, N3,  205, 401 ],
  [ 'PATCH',   'C/R', [],                     [ AM.append ],          DELETE, N3,  401, 401 ],
  [ 'PATCH',   'C/R', [],                     [ AM.write ],           INSERT, N3,  205, 401 ],
  [ 'PATCH',   'C/R', [],                     [ AM.write ],           DELETE, N3,  401, 401 ],
  [ 'PATCH',   'C/R', [ AM.append ],          [ AM.write ],           INSERT, N3,  205, 201 ],
  [ 'PATCH',   'C/R', [ AM.append ],          [ AM.write ],           DELETE, N3,  401, 401 ],
  [ 'PATCH',   'C/R', [],                     [ AM.read, AM.write ],  DELETE, N3,  205, 401 ],

  [ 'DELETE',  'C/R', [],                     undefined,              '',     '',  401, 401 ],
  [ 'DELETE',  'C/R', [],                     [ AM.read ],            '',     '',  401, 404 ],
  [ 'DELETE',  'C/R', [],                     [ AM.append ],          '',     '',  401, 401 ],
  [ 'DELETE',  'C/R', [],                     [ AM.write ],           '',     '',  401, 401 ],
  [ 'DELETE',  'C/R', [ AM.read ],            undefined,              '',     '',  401, 404 ],
  [ 'DELETE',  'C/R', [ AM.append ],          undefined,              '',     '',  401, 401 ],
  [ 'DELETE',  'C/R', [ AM.append ],          [ AM.read ],            '',     '',  401, 404 ],
  [ 'DELETE',  'C/R', [ AM.write ],           undefined,              '',     '',  205, 401 ],
  [ 'DELETE',  'C/R', [ AM.write ],           [ AM.read ],            '',     '',  401, 404 ],
  [ 'DELETE',  'C/R', [ AM.write ],           [ AM.append ],          '',     '',  401, 401 ],

  [ 'DELETE',  'C/',  [],                     undefined,              '',     '',  401, 401 ],
  [ 'DELETE',  'C/',  [ AM.read ],            undefined,              '',     '',  401, 404 ],
  [ 'DELETE',  'C/',  [ AM.append ],          undefined,              '',     '',  401, 401 ],
  [ 'DELETE',  'C/',  [ AM.write ],           undefined,              '',     '',  401, 401 ],
  [ 'DELETE',  'C/',  [ AM.read, AM.write ],  undefined,              '',     '',  205, 404 ],
];
/* eslint-enable @stylistic/no-multi-spaces */

function toPermission(modes: AM[]): AclPermissionSet {
  return Object.fromEntries(modes.map((mode): [AM, boolean] => [ mode, true ]));
}

async function setWebAclPermissions(
  store: ResourceStore,
  target: string,
  permissions: AclPermissionSet,
  childPermissions: AclPermissionSet,
): Promise<void> {
  const aclHelper = new AclHelper(store);
  await aclHelper.setSimpleAcl(target, [
    { permissions, agentClass: 'agent', accessTo: true },
    { permissions: childPermissions, agentClass: 'agent', default: true },
  ]);
}

async function setAcpPermissions(
  store: ResourceStore,
  target: string,
  permissions: AclPermissionSet,
  childPermissions: AclPermissionSet,
): Promise<void> {
  const acpHelper = new AcpHelper(store);
  const publicMatcher = acpHelper.createMatcher({ publicAgent: true });
  const policies = [ acpHelper.createPolicy({
    // Casting from enum to strings
    allow: Object.keys(permissions) as any,
    anyOf: [ publicMatcher ],
  }) ];
  const memberPolicies = [ acpHelper.createPolicy({
    allow: Object.keys(childPermissions) as any,
    anyOf: [ publicMatcher ],
  }) ];
  await acpHelper.setAcp(target, acpHelper.createAcr({
    resource: target,
    policies,
    memberPolicies,
  }));
}

const port = getPort('PermissionTable');
const baseUrl = `http://localhost:${port}/`;

type AuthFunctionType = (
  store: ResourceStore,
  target: string,
  permissions: AclPermissionSet,
  childPermissions: AclPermissionSet
) => Promise<void>;

const rootFilePath = getTestFolder('permissionTable');
const stores: [string, string, { configs: string[]; authFunction: AuthFunctionType; teardown: () => Promise<void> }][] =
  [
    [
      'WebACL',
      'in-memory storage',
      {
        configs: [ 'ldp/authorization/webacl.json', 'util/auxiliary/acl.json', 'storage/backend/memory.json' ],
        authFunction: setWebAclPermissions,
        teardown: jest.fn(),
      },
    ],
    [
      'WebACL',
      'on-disk storage',
      {
        configs: [ 'ldp/authorization/webacl.json', 'util/auxiliary/acl.json', 'storage/backend/file.json' ],
        authFunction: setWebAclPermissions,
        teardown: async(): Promise<void> => removeFolder(rootFilePath),
      },
    ],
    [
      'ACP',
      'in-memory storage',
      {
        configs: [ 'ldp/authorization/acp.json', 'util/auxiliary/acr.json', 'storage/backend/memory.json' ],
        authFunction: setAcpPermissions,
        teardown: jest.fn(),
      },
    ],
    [
      'ACP',
      'on-disk storage',
      {
        configs: [ 'ldp/authorization/acp.json', 'util/auxiliary/acr.json', 'storage/backend/file.json' ],
        authFunction: setAcpPermissions,
        teardown: async(): Promise<void> => removeFolder(rootFilePath),
      },
    ],
  ];

describe.each(stores)('A request on a server with %s authorization and %s', (
  auth,
  name,
  { configs, authFunction, teardown },
): void => {
  let app: App;
  let store: ResourceStore;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        ...configs.map(getPresetConfigPath),
        getTestConfigPath('permission-table.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app, store } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  describe.each(table)('%s %s with permissions C/: %s and C/R: %s', (...entry): void => {
    const [ method, target, cPerm, crPermTemp, body, contentType, existsCode, notExistsCode ] = entry;
    const crPerm = crPermTemp ?? cPerm;
    const id = v4();
    const root = ensureTrailingSlash(joinUrl(baseUrl, id));
    const container = ensureTrailingSlash(joinUrl(root, 'container/'));
    const resource = joinUrl(container, 'resource');
    const targetingContainer = target !== 'C/R';
    const targetUrl = targetingContainer ? container : resource;
    let init: RequestInit;

    beforeEach(async(): Promise<void> => {
      // POST is special as the request targets the container but we care about the generated resource
      const parent = targetingContainer && method !== 'POST' ? root : container;

      // Create C/ and set up permissions
      try {
        await store.setRepresentation({ path: parent }, new BasicRepresentation([], TEXT_TURTLE));
      } catch (error: unknown) {
        if (!ConflictHttpError.isInstance(error)) {
          throw error;
        }
      }

      await authFunction(
        store,
        parent,
        toPermission(parent === root ? allModes : cPerm),
        toPermission(parent === root ? cPerm : crPerm),
      );

      // Set up fetch parameters
      init = { method };
      if (contentType && contentType.length > 0) {
        init.body = body;
        init.headers = { 'content-type': contentType };
      }
    });

    it('target does not exist.', async(): Promise<void> => {
      const response = await fetch(targetUrl, init);
      expect(response.status).toBe(notExistsCode);
    });

    it('target exists.', async(): Promise<void> => {
      try {
        await store.setRepresentation({ path: targetUrl }, new BasicRepresentation(DEFAULT_BODY, TEXT_TURTLE));
      } catch (error: unknown) {
        if (!ConflictHttpError.isInstance(error)) {
          throw error;
        }
      }
      const response = await fetch(targetUrl, init);
      expect(response.status).toBe(existsCode);
    });
  });
});

import type { Stats } from 'node:fs';
import fetch from 'cross-fetch';
import type { Response } from 'cross-fetch';
import { ensureDir, pathExists, stat } from 'fs-extra';
import { joinUrl } from '../../src';
import type { App } from '../../src';
import { register } from '../util/AccountUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, getTestFolder, instantiateFromConfig, removeFolder } from './Config';

/** Performs a simple PUT request to the given 'path' with a body containing 'length' amount of characters */
async function performSimplePutWithLength(path: string, length: number): Promise<Response> {
  return fetch(
    path,
    {
      method: 'PUT',
      headers: {
        'content-type': 'text/plain',
      },
      body: 'A'.repeat(length),
    },
  );
}

/** Registers two test pods on the server matching the 'baseUrl' */
async function registerTestPods(baseUrl: string, pods: string[]): Promise<void> {
  for (const pod of pods) {
    await register(baseUrl, { podName: pod, email: `${pod}@example.ai`, password: 't' });
  }
}

describe('A quota server', (): void => {
  const podName1 = 'arthur';
  const podName2 = 'abel';
  // The allowed quota depends on what filesystem/OS you are using.
  // For example: an empty folder is reported as
  //  - 0KB on NTFS (most of the time, mileage may vary)
  //  - 0-...KB on APFS (depending on its contents and settings)
  //  - 4O96KB on FAT
  // This is why we need to determine the size of a folder on the current system.
  let folderSizeTest: Stats;

  beforeAll(async(): Promise<void> => {
    // We want to use an empty folder as on APFS/Mac folder sizes vary a lot
    const tempFolder = getTestFolder('quota-temp');
    await ensureDir(tempFolder);
    folderSizeTest = await stat(tempFolder);
    await removeFolder(tempFolder);
  });

  /** Test the general functionality of the server using pod quota */
  describe('with pod quota enabled', (): void => {
    const port = getPort('PodQuota');
    const baseUrl = `http://localhost:${port}/`;
    const pod1 = joinUrl(baseUrl, podName1);
    const pod2 = joinUrl(baseUrl, podName2);
    const rootFilePath = getTestFolder('quota-pod');

    let app: App;

    beforeAll(async(): Promise<void> => {
      // Calculate the allowed quota depending on file system used
      const size = folderSizeTest.size + 4000;

      const instances = await instantiateFromConfig(
        'urn:solid-server:test:Instances',
        getTestConfigPath('quota-pod.json'),
        {
          ...getDefaultVariables(port, baseUrl),
          'urn:solid-server:default:variable:rootFilePath': rootFilePath,
          'urn:solid-server:default:variable:PodQuota': size,
        },
      ) as Record<string, any>;
      ({ app } = instances);
      await app.start();

      // Initialize 2 pods
      await registerTestPods(baseUrl, [ podName1, podName2 ]);
    });

    afterAll(async(): Promise<void> => {
      // Not cleaning up `rootFilePath` as this intermittently causes issues during CI
      await app.stop();
    });

    // Test quota in the first pod
    it('should return a 413 when the quota is exceeded during write.', async(): Promise<void> => {
      const testFile1 = `${pod1}/test1.txt`;
      const testFile2 = `${pod1}/test2.txt`;

      const response1 = performSimplePutWithLength(testFile1, 2000);
      await expect(response1).resolves.toBeDefined();
      expect((await response1).status).toBe(201);

      const response2 = performSimplePutWithLength(testFile2, 2500);
      await expect(response2).resolves.toBeDefined();
      expect((await response2).status).toBe(413);
    });

    // Test if writing in another pod is still possible
    it('should allow writing in a pod that is not full yet.', async(): Promise<void> => {
      const testFile1 = `${pod2}/test1.txt`;

      const response1 = performSimplePutWithLength(testFile1, 2000);
      await expect(response1).resolves.toBeDefined();
      expect((await response1).status).toBe(201);
    });

    // Both pods should not accept this request anymore
    it('should block PUT requests to different pods if their quota is exceeded.', async(): Promise<void> => {
      const testFile1 = `${pod1}/test2.txt`;
      const testFile2 = `${pod2}/test2.txt`;

      const response1 = performSimplePutWithLength(testFile1, 2500);
      await expect(response1).resolves.toBeDefined();
      expect((await response1).status).toBe(413);

      const response2 = performSimplePutWithLength(testFile2, 2500);
      await expect(response2).resolves.toBeDefined();
      expect((await response2).status).toBe(413);
    });

    it(
      'should not generate metadata files (the only possible entry content-length is removed after quota validation).',
      async(): Promise<void> => {
        const testFile3 = `${pod1}/test3.txt`;
        const response1 = performSimplePutWithLength(testFile3, 100);
        await expect(response1).resolves.toBeDefined();
        expect((await response1).status).toBe(201);

        // Validate that a meta file was not created
        const check = await pathExists(`${rootFilePath}/${podName1}/test3.txt.meta`);
        expect(check).toBe(false);
      },
    );
  });

  /** Test the general functionality of the server using global quota */
  describe('with global quota enabled', (): void => {
    const port = getPort('GlobalQuota');
    const baseUrl = `http://localhost:${port}/`;
    const pod1 = `${baseUrl}${podName1}`;
    const pod2 = `${baseUrl}${podName2}`;
    const rootFilePath = getTestFolder('quota-global');

    let app: App;

    beforeAll(async(): Promise<void> => {
      // Calculate the allowed quota depending on file system used
      const size = (folderSizeTest.size * 3) + 4000;

      const instances = await instantiateFromConfig(
        'urn:solid-server:test:Instances',
        getTestConfigPath('quota-global.json'),
        {
          ...getDefaultVariables(port, baseUrl),
          'urn:solid-server:default:variable:rootFilePath': rootFilePath,
          'urn:solid-server:default:variable:GlobalQuota': size,
        },
      ) as Record<string, any>;
      ({ app } = instances);
      await app.start();

      // Initialize 2 pods
      await registerTestPods(baseUrl, [ podName1, podName2 ]);
    });

    afterAll(async(): Promise<void> => {
      // Not cleaning up `rootFilePath` as this intermittently causes issues during CI
      await app.stop();
    });

    it('should return 413 when global quota is exceeded.', async(): Promise<void> => {
      const testFile1 = `${baseUrl}test1.txt`;
      const testFile2 = `${baseUrl}test2.txt`;

      const response1 = performSimplePutWithLength(testFile1, 2000);
      await expect(response1).resolves.toBeDefined();
      const awaitedRes1 = await response1;
      expect(awaitedRes1.status).toBe(201);

      const response2 = performSimplePutWithLength(testFile2, 2500);
      await expect(response2).resolves.toBeDefined();
      const awaitedRes2 = await response2;
      expect(awaitedRes2.status).toBe(413);
    });

    it('should return 413 when trying to write to any pod when global quota is exceeded.', async(): Promise<void> => {
      const testFile1 = `${pod1}/test3.txt`;
      const testFile2 = `${pod2}/test4.txt`;

      const response1 = performSimplePutWithLength(testFile1, 2500);
      await expect(response1).resolves.toBeDefined();
      const awaitedRes1 = await response1;
      expect(awaitedRes1.status).toBe(413);

      const response2 = performSimplePutWithLength(testFile2, 2500);
      await expect(response2).resolves.toBeDefined();
      const awaitedRes2 = await response2;
      expect(awaitedRes2.status).toBe(413);
    });

    it(
      'should not generate metadata files (the only possible entry content-length is removed after quota validation).',
      async(): Promise<void> => {
        const testFile3 = `${pod1}/test5.txt`;
        const response1 = performSimplePutWithLength(testFile3, 100);
        await expect(response1).resolves.toBeDefined();
        expect((await response1).status).toBe(201);

        // Validate that a meta file was not created
        const check = await pathExists(`${rootFilePath}/${podName1}/test5.txt.meta`);
        expect(check).toBe(false);
      },
    );
  });
});

import EventEmitter from 'node:events';
import fetch from 'cross-fetch';
import Redis, { ReplyError } from 'ioredis';
import type { App } from '../../src';
import type { RedisLocker } from '../../src/util/locking/RedisLocker';
import type { RedisReadWriteLock, RedisResourceLock } from '../../src/util/locking/scripts/RedisLuaScripts';
import { REDIS_LUA_SCRIPTS } from '../../src/util/locking/scripts/RedisLuaScripts';
import { describeIf, getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, instantiateFromConfig } from './Config';

/* eslint-disable jest/require-top-level-describe */
/**
 * Test the general functionality of the server using a RedisLocker with Read-Write strategy.
 */
describeIf('docker')('A server with a RedisLocker', (): void => {
  const port = getPort('RedisLocker');
  const baseUrl = `http://localhost:${port}/`;
  let app: App;
  let locker: RedisLocker;

  beforeAll(async(): Promise<void> => {
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath('server-redis-lock.json'),
      getDefaultVariables(port, baseUrl),
    ) as Record<string, any>;
    ({ app, locker } = instances);
    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await app.stop();
  });

  describe('has a locker that', (): void => {
    it('can add a file to the store, read it and delete it.', async(): Promise<void> => {
      // Create file
      const fileUrl = `${baseUrl}testfile2.txt`;
      const fileData = 'TESTFILE2';

      let response = await fetch(fileUrl, {
        method: 'PUT',
        headers: {
          'content-type': 'text/plain',
        },
        body: fileData,
      });
      expect(response.status).toBe(201);

      // Get file
      response = await fetch(fileUrl);
      expect(response.status).toBe(200);
      const body = await response.text();
      expect(body).toContain('TESTFILE2');

      // DELETE file
      response = await fetch(fileUrl, { method: 'DELETE' });
      expect(response.status).toBe(205);
      response = await fetch(fileUrl);
      expect(response.status).toBe(404);
    });

    it('can create a folder and delete it.', async(): Promise<void> => {
      const containerPath = 'secondfolder/';
      const containerUrl = `${baseUrl}${containerPath}`;
      // PUT
      let response = await fetch(containerUrl, {
        method: 'PUT',
        headers: {
          'content-type': 'text/plain',
        },
      });
      expect(response.status).toBe(201);

      // GET
      response = await fetch(containerUrl);
      expect(response.status).toBe(200);

      // DELETE
      response = await fetch(containerUrl, { method: 'DELETE' });
      expect(response.status).toBe(205);
      response = await fetch(containerUrl);
      expect(response.status).toBe(404);
    });

    it('can get a resource multiple times.', async(): Promise<void> => {
      const fileUrl = `${baseUrl}image.png`;
      const fileData = 'testtesttest';

      let response = await fetch(fileUrl, {
        method: 'PUT',
        headers: {
          'content-type': 'text/plain',
        },
        body: fileData,
      });
      expect(response.status).toBe(201);

      // GET 4 times
      for (let i = 0; i < 4; i++) {
        const res = await fetch(fileUrl);
        expect(res.status).toBe(200);
        expect(res.headers.get('content-type')).toBe('text/plain');
        const body = await res.text();
        expect(body).toContain('testtesttest');
      }

      // DELETE
      response = await fetch(fileUrl, { method: 'DELETE' });
      expect(response.status).toBe(205);
      response = await fetch(fileUrl);
      expect(response.status).toBe(404);
    });
  });

  describe('implements ResoureLocker and', (): void => {
    const identifier = { path: 'http://test.com/foo' };

    it('can acquire a resource.', async(): Promise<void> => {
      await expect(locker.acquire(identifier)).resolves.toBeUndefined();
      // Clean up lock
      await locker.release(identifier);
    });

    it('can release a resource.', async(): Promise<void> => {
      await expect(locker.acquire(identifier)).resolves.toBeUndefined();
      await expect(locker.release(identifier)).resolves.toBeUndefined();
    });

    it('can acquire different locks simultaneously.', async(): Promise<void> => {
      const lock1 = locker.acquire({ path: 'path1' });
      const lock2 = locker.acquire({ path: 'path2' });
      const lock3 = locker.acquire({ path: 'path3' });
      const release1 = locker.release({ path: 'path1' });
      const release2 = locker.release({ path: 'path2' });
      const release3 = locker.release({ path: 'path3' });

      await expect(Promise.all([ lock1, lock2, lock3 ])).resolves.toBeDefined();
      // Clean up locks
      await Promise.all([ release1, release2, release3 ]);
    });

    it('cannot acquire the same lock simultaneously.', async(): Promise<void> => {
      await expect(locker.acquire(identifier)).resolves.toBeUndefined();
      await expect(locker.acquire(identifier)).rejects
        .toThrow(/The operation did not succeed after the set maximum of tries \(\d+\)./u);
      await expect(locker.acquire(identifier)).rejects
        .toThrow(/The operation did not succeed after the set maximum of tries \(\d+\)./u);
    });
  });

  describe('implements ReadWriteLocker and', (): void => {
    const identifier = { path: 'http://test.com/foo' };

    it('can read a resource.', async(): Promise<void> => {
      const testFn = jest.fn();
      await expect(locker.withReadLock(identifier, (): any => testFn())).resolves.toBeUndefined();
      expect(testFn).toHaveBeenCalledWith();
    });

    it('can write a resource.', async(): Promise<void> => {
      const testFn = jest.fn();
      await expect(locker.withWriteLock(identifier, (): any => testFn())).resolves.toBeUndefined();
      expect(testFn).toHaveBeenCalledWith();
    });

    it('can read a resource twice again after it was unlocked.', async(): Promise<void> => {
      const testFn = jest.fn();
      await expect(locker.withReadLock(identifier, (): any => testFn())).resolves.toBeUndefined();
      expect(testFn).toHaveBeenCalledTimes(1);
      await expect(locker.withReadLock(identifier, (): any => testFn())).resolves.toBeUndefined();
      expect(testFn).toHaveBeenCalledTimes(2);
    });

    it('can acquire different readLocks simultaneously.', async(): Promise<void> => {
      const testFn = jest.fn();
      const lock1 = locker.withReadLock({ path: 'path1' }, (): any => testFn());
      const lock2 = locker.withReadLock({ path: 'path2' }, (): any => testFn());
      const lock3 = locker.withReadLock({ path: 'path3' }, (): any => testFn());

      await expect(Promise.all([ lock1, lock2, lock3 ])).resolves.toBeDefined();
    });

    it('can acquire different writeLocks simultaneously.', async(): Promise<void> => {
      const testFn = jest.fn();
      const lock1 = locker.withWriteLock({ path: 'path1' }, (): any => testFn());
      const lock2 = locker.withWriteLock({ path: 'path2' }, (): any => testFn());
      const lock3 = locker.withWriteLock({ path: 'path3' }, (): any => testFn());

      await expect(Promise.all([ lock1, lock2, lock3 ])).resolves.toBeDefined();
    });

    it('can acquire the same readLock simultaneously.', async(): Promise<void> => {
      let res = '';
      let countdown = 3;
      const releaseSignal = new EventEmitter();
      releaseSignal.on('countdown', (): void => {
        countdown -= 1;
        // Start releasing locks after 3 inits of the promises below
        if (countdown === 0) {
          for (const num of [ 1, 0, 2 ]) {
            releaseSignal.emit(`release${num}`);
          }
        }
      });
      const promises = [ 0, 1, 2 ].map(async(num): Promise<any> =>
        locker.withReadLock(identifier, async(): Promise<void> => {
          res += `l${num}`;
          await new Promise<void>((resolve): any => {
            releaseSignal.on(`release${num}`, resolve);
            releaseSignal.emit('countdown');
          });
          res += `r${num}`;
        }));

      await Promise.all(promises);
      expect(res).toBe('l0l1l2r1r0r2');
    });

    it('cannot acquire the same writeLock simultaneously.', async(): Promise<void> => {
      let res = '';

      await expect(locker.withWriteLock(identifier, async(): Promise<void> => {
        res += 'l0';
        await expect(locker.withWriteLock(identifier, (): void => {
          res += 'l1';
          res += 'r1';
          // eslint-disable-next-line jest/require-to-throw-message
        })).rejects.toThrow();
        res += 'r0';
      })).resolves.toBeUndefined();

      await expect(locker.withWriteLock(identifier, async(): Promise<void> => {
        res += 'l2';
        res += 'r2';
      })).resolves.toBeUndefined();

      expect(res).toBe('l0r0l2r2');
    });
  });

  describe('defines custom Redis lua functions', (): void => {
    let redis: Redis & RedisReadWriteLock & RedisResourceLock;

    async function clearRedis(): Promise<void> {
      const keys = await redis.keys('*');
      if (keys && keys.length > 0) {
        await redis.del(keys);
      }
    }

    beforeAll(async(): Promise<void> => {
      redis = new Redis('127.0.0.1:6379') as Redis & RedisReadWriteLock & RedisResourceLock;

      // Register lua scripts
      for (const [ name, script ] of Object.entries(REDIS_LUA_SCRIPTS)) {
        redis.defineCommand(name, { numberOfKeys: 1, lua: script });
      }

      await clearRedis();
    });

    beforeEach(async(): Promise<void> => {
      await clearRedis();
    });

    afterAll(async(): Promise<void> => {
      await redis.quit();
    });

    it('#acquireReadLock.', async(): Promise<void> => {
      const key1 = 'key1';
      const writeKey1 = `${key1}.wlock`;
      const countKey1 = `${key1}.count`;
      // Test fails
      await redis.set(writeKey1, 'locked');
      await expect(redis.acquireReadLock(key1)).resolves.toBe(0);

      // Test succeeds
      await redis.del(writeKey1);
      await expect(redis.acquireReadLock(key1)).resolves.toBe(1);
      await expect(redis.get(countKey1)).resolves.toBe('1');
      await expect(redis.acquireReadLock(key1)).resolves.toBe(1);
      await expect(redis.get(countKey1)).resolves.toBe('2');
      await expect(redis.acquireReadLock(key1)).resolves.toBe(1);
      await expect(redis.get(countKey1)).resolves.toBe('3');
    });

    it('#acquireWriteLock.', async(): Promise<void> => {
      const key1 = 'key1';
      const writeKey1 = `${key1}.wlock`;
      const countKey1 = `${key1}.count`;

      // Test fails because count > 0
      await expect(redis.incr(countKey1)).resolves.toBe(1);
      await expect(redis.acquireWriteLock(key1)).resolves.toBe(0);

      // Test fails because write lock is present
      await clearRedis();
      await redis.set(writeKey1, 'locked');
      await expect(redis.acquireWriteLock(key1)).resolves.toBe(0);

      // Test succeeds
      await clearRedis();
      await expect(redis.acquireWriteLock(key1)).resolves.toBe('OK');

      // Test fails again
      await expect(redis.acquireWriteLock(key1)).resolves.toBe(0);
    });

    it('#releaseReadLock.', async(): Promise<void> => {
      const key1 = 'key1';
      const countKey1 = `${key1}.count`;

      // Test succeeds
      await expect(redis.acquireReadLock(key1)).resolves.toBe(1);
      await expect(redis.acquireReadLock(key1)).resolves.toBe(1);
      await expect(redis.acquireReadLock(key1)).resolves.toBe(1);
      await expect(redis.get(countKey1)).resolves.toBe('3');

      await expect(redis.releaseReadLock(key1)).resolves.toBe(1);
      await expect(redis.releaseReadLock(key1)).resolves.toBe(1);
      await expect(redis.releaseReadLock(key1)).resolves.toBe(1);
      await expect(redis.get(countKey1)).resolves.toBe('0');

      // Test fails
      await expect(redis.releaseReadLock(key1)).rejects
        .toThrow(ReplyError);
      await expect(redis.releaseReadLock(key1)).rejects
        .toThrow('Error trying to release readlock when read count was 0.');
    });

    it('#releaseWriteLock.', async(): Promise<void> => {
      const key1 = 'key1';
      const writeKey1 = `${key1}.wlock`;

      // Test fails
      await expect(redis.releaseWriteLock(key1)).rejects
        .toThrow(ReplyError);
      await expect(redis.releaseWriteLock(key1)).rejects
        .toThrow('Error trying to release writelock that did not exist.');

      // Test succeeds
      await redis.acquireWriteLock(key1);
      await expect(redis.exists(writeKey1)).resolves.toBe(1);
      await expect(redis.get(writeKey1)).resolves.toBe('locked');
      await expect(redis.releaseWriteLock(key1)).resolves.toBe(1);
      await expect(redis.exists(writeKey1)).resolves.toBe(0);
    });

    it('#acquireLock.', async(): Promise<void> => {
      const key1 = 'key1';
      const lockKey1 = `${key1}.lock`;
      // Test succeeds
      await expect(redis.acquireLock(key1)).resolves.toBe('OK');
      await expect(redis.exists(lockKey1)).resolves.toBe(1);
      await expect(redis.get(lockKey1)).resolves.toBe('locked');

      // Test fails
      await expect(redis.acquireLock(key1)).resolves.toBe(0);
      await expect(redis.exists(lockKey1)).resolves.toBe(1);
      await expect(redis.get(lockKey1)).resolves.toBe('locked');

      // Test succeeds again
      await redis.releaseLock(key1);
      await expect(redis.exists(lockKey1)).resolves.toBe(0);
      await expect(redis.acquireLock(key1)).resolves.toBe('OK');
    });

    it('#releaseLock.', async(): Promise<void> => {
      const key1 = 'key1';
      const lockKey1 = `${key1}.lock`;

      // Test fails
      await expect(redis.releaseLock(key1)).rejects
        .toThrow(ReplyError);
      await expect(redis.releaseLock(key1)).rejects
        .toThrow('Error trying to release lock that did not exist.');

      // Test succeeds
      await redis.acquireLock(key1);
      await expect(redis.exists(lockKey1)).resolves.toBe(1);
      await expect(redis.get(lockKey1)).resolves.toBe('locked');
      await expect(redis.releaseLock(key1)).resolves.toBe(1);
      await expect(redis.exists(lockKey1)).resolves.toBe(0);
    });
  });
});

import { Readable } from 'node:stream';
import arrayifyStream from 'arrayify-stream';
import { BasicETagHandler, SingleRootIdentifierStrategy } from '../../src';
import { BasicRequestParser } from '../../src/http/input/BasicRequestParser';
import { RawBodyParser } from '../../src/http/input/body/RawBodyParser';
import { BasicConditionsParser } from '../../src/http/input/conditions/BasicConditionsParser';
import { OriginalUrlExtractor } from '../../src/http/input/identifier/OriginalUrlExtractor';
import { ContentTypeParser } from '../../src/http/input/metadata/ContentTypeParser';
import { AcceptPreferenceParser } from '../../src/http/input/preferences/AcceptPreferenceParser';
import { RepresentationMetadata } from '../../src/http/representation/RepresentationMetadata';
import type { HttpRequest } from '../../src/server/HttpRequest';
import { guardedStreamFrom } from '../../src/util/StreamUtil';

describe('A BasicRequestParser with simple input parsers', (): void => {
  const identifierStrategy = new SingleRootIdentifierStrategy('http://test.com/');
  const targetExtractor = new OriginalUrlExtractor({ identifierStrategy });
  const preferenceParser = new AcceptPreferenceParser();
  const metadataParser = new ContentTypeParser();
  const conditionsParser = new BasicConditionsParser(new BasicETagHandler());
  const bodyParser = new RawBodyParser();
  const requestParser = new BasicRequestParser(
    { targetExtractor, preferenceParser, metadataParser, conditionsParser, bodyParser },
  );

  it('can parse an incoming request.', async(): Promise<void> => {
    const request = guardedStreamFrom([ '<http://test.com/s> <http://test.com/p> <http://test.com/o>.' ]) as HttpRequest;
    request.method = 'POST';
    request.url = '/';
    request.headers = {
      accept: 'text/turtle; q=0.8',
      'accept-language': 'en-gb, en;q=0.5',
      'content-type': 'text/turtle',
      'if-unmodified-since': 'Wed, 21 Oct 2015 07:28:00 UTC',
      'if-none-match': '12345',
      'transfer-encoding': 'chunked',
      host: 'test.com',
    };

    const result = await requestParser.handle(request);
    expect(result).toEqual({
      method: 'POST',
      target: { path: 'http://test.com/' },
      preferences: {
        type: { 'text/turtle': 0.8 },
        language: { 'en-gb': 1, en: 0.5 },
      },
      conditions: expect.objectContaining({
        unmodifiedSince: new Date('2015-10-21T07:28:00.000Z'),
        notMatchesETag: [ '12345' ],
      }),
      body: {
        data: expect.any(Readable),
        binary: true,
        metadata: expect.any(RepresentationMetadata),
      },
    });
    expect(result.body?.metadata.contentType).toBe('text/turtle');

    await expect(arrayifyStream(result.body.data)).resolves.toEqual(
      [ '<http://test.com/s> <http://test.com/p> <http://test.com/o>.' ],
    );
  });
});

import fetch from 'cross-fetch';
import type { App, DataAccessorBasedStore, Initializable, ResourceLocker } from '../../src';
import { BasicRepresentation, readableToString } from '../../src';
import { describeIf, getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, getTestFolder, instantiateFromConfig, removeFolder } from './Config';

const port = getPort('ResourceLockCleanup');
const baseUrl = `http://localhost:${port}/`;
const rootFilePath = getTestFolder(`resource-lock-cleanup`);
const resourceIdentifier = { path: `${baseUrl}container1/test.txt` };

const configs: [string, any][] = [
  [
    'file-based',
    {
      config: 'server-file.json',
      init: async(initializable: Initializable): Promise<void> => initializable.initialize(),
      teardown: async(): Promise<void> => removeFolder(rootFilePath),
    },
  ],
  [
    'redis-based',
    {
      config: 'server-redis-lock.json',
      init: jest.fn(),
      teardown: jest.fn(),
    },
  ],
];

/* eslint-disable jest/require-top-level-describe, jest/consistent-test-it */
describeIf('docker').each(configs)('A server using %s locking', (id, { config, init, teardown }):
void => {
  let app: App;
  let store: DataAccessorBasedStore;
  let locker: ResourceLocker;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getTestConfigPath(config),
      ],
      variables,
    ) as Record<string, any>;
    ({ app, store, locker } = instances);
    // Create the test resource
    await store.setRepresentation(resourceIdentifier, new BasicRepresentation('abc', 'text/plain'));

    // Perform additional initialization, if configured
    await init(locker);
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('should not be affected by dangling locks.', async(): Promise<void> => {
    // Simulate lock existing before server startup, by creating a (write) lock directly
    await locker.acquire({ path: `${resourceIdentifier.path}.write` });
    // Start the server
    await app.start();

    // Updating the resource should succeed (if the server clears dangling locks on startup).
    const updatedContent = 'def';
    const result = await fetch(resourceIdentifier.path, {
      method: 'PUT',
      headers: {
        'content-type': 'text/plain',
      },
      body: updatedContent,
    });
    expect(result.status).toBe(205);
    // Check if the resource was updated:
    const representation = await store.getRepresentation(resourceIdentifier);
    const data = await readableToString(representation.data);
    expect(data).toEqual(updatedContent);
  });
});

import { fetch } from 'cross-fetch';
import type { App } from '../../src/init/App';
import { joinUrl } from '../../src/util/PathUtil';
import { register } from '../util/AccountUtil';
import type { User } from '../util/AccountUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, instantiateFromConfig } from './Config';

const port = getPort('RestrictedIdentity');
const baseUrl = `http://localhost:${port}/`;

// Undo the global access token verifier mock
jest.unmock('@solid/access-token-verifier');

// Prevent panva/node-openid-client from emitting DraftWarning
jest.spyOn(process, 'emitWarning').mockImplementation();

describe('A server with restricted IDP access', (): void => {
  let app: App;
  const user: User = {
    podName: 'alice',
    email: 'alice@test.email',
    password: 'password',
  };
  const webId = joinUrl(baseUrl, 'alice/profile/card#me');
  let controls: any;

  beforeAll(async(): Promise<void> => {
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath('restricted-idp.json'),
      getDefaultVariables(port, baseUrl),
    ) as Record<string, any>;
    ({ app } = instances);
    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await app.stop();
  });

  it('has ACL resources in the relevant containers.', async(): Promise<void> => {
    let res = await fetch(joinUrl(baseUrl, '.well-known/.acl'));
    expect(res.status).toBe(200);

    res = await fetch(joinUrl(baseUrl, '.account/.acl'));
    expect(res.status).toBe(200);
  });

  it('can create a pod.', async(): Promise<void> => {
    const result = await register(baseUrl, user);
    ({ controls } = result);
    expect(result.webId).toBe(webId);
  });

  it('can restrict account creation.', async(): Promise<void> => {
    // Only allow new WebID to register
    const restrictedAcl = `@prefix acl: <http://www.w3.org/ns/auth/acl#>.
@prefix foaf: <http://xmlns.com/foaf/0.1/>.

<#authorization>
    a               acl:Authorization;
    acl:agent       <${webId}>;
    acl:mode        acl:Read, acl:Write, acl:Control;
    acl:accessTo    <./>.`;

    let res = await fetch(`${controls.account.create}.acl`, {
      method: 'PUT',
      headers: { 'content-type': 'text/turtle' },
      body: restrictedAcl,
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(`${controls.account.create}.acl`);

    // Registration is now disabled
    res = await fetch(controls.account.create);
    expect(res.status).toBe(401);

    res = await fetch(controls.account.create, { method: 'POST' });
    expect(res.status).toBe(401);
  });

  it('can still create accounts with the correct credentials.', async(): Promise<void> => {
    // Account creation still works for the WebID
    let res = await fetch(controls.account.create, {
      headers: { authorization: `WebID ${webId}` },
    });
    expect(res.status).toBe(200);

    res = await fetch(controls.account.create, {
      method: 'POST',
      headers: { authorization: `WebID ${webId}` },
    });
    expect(res.status).toBe(200);
  });
});

import fetch from 'cross-fetch';
import { ensureFile, writeJson } from 'fs-extra';
import type { App } from '../../src/init/App';
import { joinFilePath, joinUrl } from '../../src/util/PathUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, getTestFolder, instantiateFromConfig, removeFolder } from './Config';

const port = getPort('SeedingPods');
const baseUrl = `http://localhost:${port}/`;

const rootFilePath = getTestFolder('seeding-pods');

describe('A server with seeded pods', (): void => {
  const indexUrl = joinUrl(baseUrl, '.account/');
  let app: App;

  beforeAll(async(): Promise<void> => {
    // Create the seed file
    const seed = [
      {
        email: 'test1@example.com',
        password: 'password1',
        pods: [
          { name: 'pod1' },
          { name: 'pod2' },
        ],
      },
      {
        email: 'test2@example.com',
        password: 'password2',
        pods: [
          { name: 'pod3' },
          // This will fail
          { name: 'pod2' },
        ],
      },
      {
        // This will all fail
        email: 'test1@example.com',
        password: 'password3',
        pods: [
          { name: 'pod4' },
        ],
      },
    ];
    const path = joinFilePath(rootFilePath, 'seed.json');
    await ensureFile(path);
    await writeJson(path, seed);

    // Start server with the seed config
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      getTestConfigPath('server-memory.json'),
      {
        ...getDefaultVariables(port, baseUrl),
        'urn:solid-server:default:variable:seedConfig': path,
      },
    ) as Record<string, any>;
    ({ app } = instances);
    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await removeFolder(rootFilePath);
    await app.stop();
  });

  it('can seed accounts and pods.', async(): Promise<void> => {
    // Get the controls
    const res = await fetch(indexUrl);
    expect(res.status).toBe(200);
    const { controls } = await res.json();

    // Verify that the pods exists
    await expect(fetch(joinUrl(baseUrl, 'pod1/'))).resolves.toEqual(expect.objectContaining({ status: 200 }));
    await expect(fetch(joinUrl(baseUrl, 'pod2/'))).resolves.toEqual(expect.objectContaining({ status: 200 }));
    await expect(fetch(joinUrl(baseUrl, 'pod3/'))).resolves.toEqual(expect.objectContaining({ status: 200 }));
    await expect(fetch(joinUrl(baseUrl, 'pod4/'))).resolves.toEqual(expect.objectContaining({ status: 404 }));

    // Verify that we can log in with the accounts
    await expect(fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email: 'test1@example.com', password: 'password1' }),
    })).resolves.toEqual(expect.objectContaining({ status: 200 }));
    await expect(fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email: 'test2@example.com', password: 'password2' }),
    })).resolves.toEqual(expect.objectContaining({ status: 200 }));
    await expect(fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email: 'test1@example.com', password: 'password3' }),
    })).resolves.toEqual(expect.objectContaining({ status: 403 }));
  });
});

import fetch from 'cross-fetch';
import type { App } from '../../src/init/App';
import { AppRunner } from '../../src/init/AppRunner';
import { resolveModulePath } from '../../src/util/PathUtil';
import { LDP } from '../../src/util/Vocabularies';
import { getPort } from '../util/Util';
import { getDefaultVariables } from './Config';

const port = getPort('ServerFetch');
const baseUrl = `http://localhost:${port}/`;

// Some tests with real Requests/Responses until the mocking library has been removed from the tests
describe('A Solid server', (): void => {
  const document = `${baseUrl}document`;
  const container = `${baseUrl}container/`;
  let app: App;

  beforeAll(async(): Promise<void> => {
    // Using AppRunner here so it is also tested in an integration test
    app = await new AppRunner().create({
      loaderProperties: {
        mainModulePath: resolveModulePath(''),
        logLevel: 'error',
        typeChecking: false,
      },
      config: resolveModulePath('config/default.json'),
      variableBindings: getDefaultVariables(port, baseUrl),
    });
    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await app.stop();
  });

  it('can PUT to containers.', async(): Promise<void> => {
    const res = await fetch(container, {
      method: 'PUT',
      headers: {
        'content-type': 'text/turtle',
      },
      body: '<a:b> <a:b> <a:b>.',
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(container);
  });

  it('can PUT to documents.', async(): Promise<void> => {
    const res = await fetch(document, {
      method: 'PUT',
      headers: {
        'content-type': 'text/turtle',
      },
      body: '<a:b> <a:b> <a:b>.',
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(document);
  });

  it('can do a successful HEAD request to a container.', async(): Promise<void> => {
    const res = await fetch(container, { method: 'HEAD' });
    expect(res.status).toBe(200);
  });

  it('can do a successful HEAD request to a container without accept headers.', async(): Promise<void> => {
    const res = await fetch(container, { method: 'HEAD', headers: { accept: '' }});
    expect(res.status).toBe(200);
  });

  it('can do a successful HEAD request to a document.', async(): Promise<void> => {
    const res = await fetch(document, { method: 'HEAD' });
    expect(res.status).toBe(200);
  });

  it('can do a successful HEAD request to a document without accept headers.', async(): Promise<void> => {
    const res = await fetch(document, { method: 'HEAD', headers: { accept: '' }});
    expect(res.status).toBe(200);
  });

  it('can do a successful GET request to a container.', async(): Promise<void> => {
    const res = await fetch(container);
    expect(res.status).toBe(200);
  });

  it('can do a successful GET request to a container without accept headers.', async(): Promise<void> => {
    const res = await fetch(container, { headers: { accept: '' }});
    expect(res.status).toBe(200);
  });

  it('can do a successful GET request to a document.', async(): Promise<void> => {
    const res = await fetch(document);
    expect(res.status).toBe(200);
  });

  it('can do a successful GET request to a document without accept headers.', async(): Promise<void> => {
    const res = await fetch(document, { headers: { accept: '' }});
    expect(res.status).toBe(200);
  });

  it('can handle PUT errors.', async(): Promise<void> => {
    // There was a specific case where the following request caused the connection to close instead of error
    const res = await fetch(baseUrl, {
      method: 'PUT',
      headers: {
        'content-type': 'text/plain',
      },
      body: '"test"',
    });
    expect(res.status).toBe(409);
    // This container already exists and it can not be edited
    // See https://github.com/solid/community-server/issues/1027#issuecomment-1023371546
  });

  it('can POST to create a container.', async(): Promise<void> => {
    const res = await fetch(container, {
      method: 'POST',
      headers: {
        'content-type': 'text/turtle',
        slug: 'containerPOST/',
        link: `<${LDP.Container}>; rel="type"`,
      },
      body: '<a:b> <a:b> <a:b>.',
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(`${container}containerPOST/`);
  });

  it('can POST to create a document.', async(): Promise<void> => {
    const res = await fetch(container, {
      method: 'POST',
      headers: {
        'content-type': 'text/turtle',
        slug: 'documentPOST',
      },
      body: '<a:b> <a:b> <a:b>.',
    });
    expect(res.status).toBe(201);
    expect(res.headers.get('location')).toBe(`${container}documentPOST`);
  });

  it('can DELETE containers.', async(): Promise<void> => {
    const res = await fetch(`${container}containerPOST/`, { method: 'DELETE' });
    expect(res.status).toBe(205);
  });

  it('can DELETE documents.', async(): Promise<void> => {
    const res = await fetch(`${container}documentPOST`, { method: 'DELETE' });
    expect(res.status).toBe(205);
  });

  it('can PATCH documents.', async(): Promise<void> => {
    await fetch(document, {
      method: 'PUT',
      headers: {
        'content-type': 'text/turtle',
      },
      body: '<a:b> <a:b> <a:b>.',
    });
    const res = await fetch(document, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/sparql-update',
      },
      body: 'INSERT DATA { <b:b> <b:b> <b:b>. }',
    });
    expect(res.status).toBe(205);
  });

  it('can not PATCH containers.', async(): Promise<void> => {
    await fetch(container, {
      method: 'PUT',
      headers: {
        'content-type': 'text/turtle',
      },
    });
    const res = await fetch(container, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/sparql-update',
      },
      body: 'INSERT DATA { <b:b> <b:b> <b:b>. }',
    });
    expect(res.status).toBe(409);
  });

  it('can PATCH metadata resources.', async(): Promise<void> => {
    const res = await fetch(`${document}.meta`, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/sparql-update',
      },
      body: 'INSERT DATA { <b:b> <b:b> <b:b>. }',
    });
    expect(res.status).toBe(205);
  });
});

