const stores: [string, any][] = [
  [ 'in-memory storage', {
    configs: [ 'storage/backend/memory.json', 'util/resource-locker/memory.json' ],
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    configs: [ 'storage/backend/file.json', 'util/resource-locker/file.json' ],
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

async function readChunk(reader: ReadableStreamDefaultReader): Promise<Store> {
  const decoder = new TextDecoder();
  const parser = new Parser();
  const { value } = await reader.read();
  const notification = decoder.decode(value);
  return new Store(parser.parse(notification));
}

function endpoint(topic: string): string {
  return joinUrl(baseUrl, pathPrefix, encodeURIComponent(topic));
}

describe.each(stores)('A server supporting StreamingHTTPChannel2023 using %s', (name, { configs, teardown }): void => {
  let app: App;
  let store: ResourceStore;
  const webId = 'http://example.com/card/#me';
  const topic = joinUrl(baseUrl, '/foo');
  const receiveFrom = endpoint(topic);

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        ...configs.map(getPresetConfigPath),
        getTestConfigPath('streaming-http-notifications.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app, store } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('advertises streaming http endpoint in Link header.', async(): Promise<void> => {
    await store.setRepresentation({ path: topic }, new BasicRepresentation('new', 'text/plain'));
    const response = await fetch(topic);
    expect(response.status).toBe(200);
    const linkHeader = response.headers.get('link');
    const match = /<([^>]+)>; rel="http:\/\/www\.w3\.org\/ns\/solid\/terms#updatesViaStreamingHttp2023"/u
      .exec(linkHeader!);
    expect(match![1]).toEqual(receiveFrom);
  });

  it('only allows GET on receiveFrom endpoint.', async(): Promise<void> => {
    const methods = [ 'HEAD', 'PUT', 'POST' ];
    for (const method of methods) {
      const response = await fetch(receiveFrom, {
        method,
      });
      expect(response.status).toBe(405);
    }

    // For some reason it differs
    const del = await fetch(receiveFrom, {
      method: 'DELETE',
    });
    expect(del.status).toBe(404);
  });

  it('emits initial Update if topic exists.', async(): Promise<void> => {
    await store.setRepresentation({ path: topic }, new BasicRepresentation('new', 'text/plain'));
    const streamingResponse = await fetch(receiveFrom);
    const reader = streamingResponse.body!.getReader();

    try {
      const quads = await readChunk(reader);
      expect(quads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Update ]);
      expect(quads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);
    } finally {
      reader.releaseLock();
      await streamingResponse.body!.cancel();
    }
  });

  it('emits initial Delete if topic does not exist.', async(): Promise<void> => {
    try {
      await store.deleteResource({ path: topic });
    } catch {}
    const streamingResponse = await fetch(receiveFrom);
    const reader = streamingResponse.body!.getReader();

    try {
      const quads = await readChunk(reader);
      expect(quads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Delete ]);
      expect(quads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);
    } finally {
      reader.releaseLock();
      await streamingResponse.body!.cancel();
    }
  });

  it('does not emit initial notification when other receivers connect.', async(): Promise<void> => {
    await store.setRepresentation({ path: topic }, new BasicRepresentation('new', 'text/plain'));
    const streamingResponse = await fetch(receiveFrom);
    const reader = streamingResponse.body!.getReader();

    const otherResponse = await fetch(receiveFrom);
    const otherReader = otherResponse.body!.getReader();

    try {
      // Expected initial notification
      const updateQuads = await readChunk(reader);
      expect(updateQuads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Update ]);
      expect(updateQuads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);

      // Expected initial notification on other receiver
      const otherQuads = await readChunk(otherReader);
      expect(otherQuads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Update ]);
      expect(otherQuads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);

      // Delete resource
      const response = await fetch(topic, {
        method: 'DELETE',
      });
      expect(response.status).toBe(205);

      // If it was caused by the other receiver connecting, it would have been Update as well
      const deleteQuads = await readChunk(reader);
      expect(deleteQuads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Delete ]);
      expect(deleteQuads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);
    } finally {
      reader.releaseLock();
      await streamingResponse.body!.cancel();
      otherReader.releaseLock();
      await otherResponse.body!.cancel();
    }
  });

  it('emits Create events.', async(): Promise<void> => {
    try {
      await store.deleteResource({ path: topic });
    } catch {}
    const streamingResponse = await fetch(receiveFrom);
    const reader = streamingResponse.body!.getReader();

    try {
      // Ignore initial notification
      await readChunk(reader);

      // Create resource
      const response = await fetch(topic, {
        method: 'PUT',
        headers: { 'content-type': 'text/plain' },
        body: 'abc',
      });
      expect(response.status).toBe(201);

      const quads = await readChunk(reader);
      expect(quads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Create ]);
      expect(quads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);
    } finally {
      reader.releaseLock();
      await streamingResponse.body!.cancel();
    }
  });

  it('emits Update events.', async(): Promise<void> => {
    await store.setRepresentation({ path: topic }, new BasicRepresentation('new', 'text/plain'));
    const streamingResponse = await fetch(receiveFrom);
    const reader = streamingResponse.body!.getReader();

    try {
      // Ignore initial notification
      await readChunk(reader);

      // Update resource
      const response = await fetch(topic, {
        method: 'PUT',
        headers: { 'content-type': 'text/plain' },
        body: 'abc',
      });
      expect(response.status).toBe(205);

      const quads = await readChunk(reader);
      expect(quads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Update ]);
      expect(quads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);
    } finally {
      reader.releaseLock();
      await streamingResponse.body!.cancel();
    }
  });

  it('emits Delete events.', async(): Promise<void> => {
    await store.setRepresentation({ path: topic }, new BasicRepresentation('new', 'text/plain'));
    const streamingResponse = await fetch(receiveFrom);
    const reader = streamingResponse.body!.getReader();

    try {
      // Ignore initial notification
      await readChunk(reader);

      // Delete resource
      const response = await fetch(topic, {
        method: 'DELETE',
      });
      expect(response.status).toBe(205);

      const quads = await readChunk(reader);
      expect(quads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Delete ]);
      expect(quads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(topic) ]);
    } finally {
      reader.releaseLock();
      await streamingResponse.body!.cancel();
    }
  });

  it('prevents connecting to channels of restricted topics.', async(): Promise<void> => {
    const restricted = joinUrl(baseUrl, '/restricted');
    const restrictedReceiveFrom = endpoint(restricted);
    await store.setRepresentation({ path: restricted }, new BasicRepresentation('new', 'text/plain'));

    // Only allow our WebID to read
    const restrictedAcl = `
      @prefix acl: <http://www.w3.org/ns/auth/acl#>.
      @prefix foaf: <http://xmlns.com/foaf/0.1/>.

      <#authorization>
          a               acl:Authorization;
          acl:agent       <${webId}>;
          acl:mode        acl:Read, acl:Write;
          acl:accessTo    <./restricted>.`;

    await store.setRepresentation({ path: `${restricted}.acl` }, new BasicRepresentation(restrictedAcl, 'text/turtle'));

    // Unauthenticated fetch fails
    const unauthenticatedResponse = await fetch(restrictedReceiveFrom);
    try {
      expect(unauthenticatedResponse.status).toBe(401);
    } finally {
      await unauthenticatedResponse.body?.cancel();
    }

    // Authenticated fetch succeeds
    const authenticatedResponse = await fetch(restrictedReceiveFrom, {
      headers: {
        authorization: `WebID ${webId}`,
      },
    });
    try {
      expect(authenticatedResponse.status).toBe(200);
    } finally {
      await authenticatedResponse.body!.cancel();
    }
  });

  it('emits container notifications if contents get added or removed.', async(): Promise<void> => {
    const resource = joinUrl(baseUrl, '/resource');
    const baseReceiveFrom = endpoint(joinUrl(baseUrl, '/'));

    // Connecting to the base URL, which is the parent container
    const streamingResponse = await fetch(baseReceiveFrom);
    const reader = streamingResponse.body!.getReader();

    try {
      // Ignore initial notification
      await readChunk(reader);

      // Create contained resource
      const createResponse = await fetch(resource, {
        method: 'PUT',
        headers: { 'content-type': 'text/plain' },
        body: 'abc',
      });
      expect(createResponse.status).toBe(201);

      // Will receive the Add notification
      const addQuads = await readChunk(reader);

      expect(addQuads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Add ]);
      expect(addQuads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(resource) ]);
      expect(addQuads.getObjects(null, AS.terms.target, null)).toEqual([ namedNode(baseUrl) ]);

      // Remove contained resource
      const removeResponse = await fetch(resource, {
        method: 'DELETE',
      });
      expect(removeResponse.status).toBe(205);

      // Will receive the Remove notification
      const removeQuads = await readChunk(reader);
      expect(removeQuads.getObjects(null, RDF.terms.type, null)).toEqual([ AS.terms.Remove ]);
      expect(removeQuads.getObjects(null, AS.terms.object, null)).toEqual([ namedNode(resource) ]);
      expect(removeQuads.getObjects(null, AS.terms.target, null)).toEqual([ namedNode(baseUrl) ]);
    } finally {
      reader.releaseLock();
      await streamingResponse.body!.cancel();
    }
  });
});

import fetch from 'cross-fetch';
import type { App } from '../../src/init/App';
import { register } from '../util/AccountUtil';
import type { User } from '../util/AccountUtil';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';

const port = getPort('Subdomains');
const baseUrl = `http://localhost:${port}/`;

const rootFilePath = getTestFolder('subdomains');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    storeConfig: 'storage/backend/memory.json',
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    storeConfig: 'storage/backend/file.json',
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

// Simulating subdomains using the forwarded header so no DNS changes are required
describe.each(stores)('A subdomain server with %s', (name, { storeConfig, teardown }): void => {
  let app: App;
  const user: User = {
    email: 'alice@example.com',
    password: 'password',
    webId: 'http://example.com/#alice',
    podName: 'alice',
  };
  const podHost = `alice.localhost:${port}`;
  const podUrl = `http://${podHost}/`;
  let authorization: string;
  let controls: any;

  beforeAll(async(): Promise<void> => {
    const variables: Record<string, any> = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getPresetConfigPath(storeConfig),
        getTestConfigPath('server-subdomains-unsafe.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  describe('handling resources', (): void => {
    it('can read the root container.', async(): Promise<void> => {
      const res = await fetch(baseUrl);
      expect(res.status).toBe(200);
    });

    it('can write resources.', async(): Promise<void> => {
      let res = await fetch(`${baseUrl}alice`, {
        method: 'PUT',
        headers: {
          authorization: `WebID ${user.webId}`,
          'content-type': 'text/plain',
        },
        body: 'this is new data!',
      });
      expect(res.status).toBe(201);
      expect(res.headers.get('location')).toBe(`${baseUrl}alice`);

      res = await fetch(`${baseUrl}alice`);
      expect(res.status).toBe(200);
      await expect(res.text()).resolves.toBe('this is new data!');
    });
  });

  describe('handling pods', (): void => {
    it('creates pods in a subdomain.', async(): Promise<void> => {
      const result = await register(baseUrl, user);
      ({ controls, authorization } = result);
      expect(result.pod).toBe(podUrl);
    });

    it('can fetch the created pod in a subdomain.', async(): Promise<void> => {
      const res = await fetch(baseUrl, { headers: { forwarded: `host=${podHost}` }});
      expect(res.status).toBe(200);
    });

    it('should not be able to read the acl file.', async(): Promise<void> => {
      const res = await fetch(`${baseUrl}.acl`, { headers: { forwarded: `host=${podHost}` }});
      expect(res.status).toBe(401);
    });

    it('should be able to read acl file with the correct credentials.', async(): Promise<void> => {
      const res = await fetch(`${baseUrl}.acl`, {
        headers: {
          forwarded: `host=${podHost}`,
          authorization: `WebID ${user.webId}`,
        },
      });
      expect(res.status).toBe(200);
    });

    it('should be able to write to the pod now as the owner.', async(): Promise<void> => {
      let res = await fetch(`${baseUrl}alice`, {
        headers: {
          forwarded: `host=${podHost}`,
          authorization: `WebID ${user.webId}`,
        },
      });
      expect(res.status).toBe(404);

      res = await fetch(`${baseUrl}alice`, {
        method: 'PUT',
        headers: {
          forwarded: `host=${podHost}`,
          authorization: `WebID ${user.webId}`,
          'content-type': 'text/plain',
        },
        body: 'this is new data!',
      });
      expect(res.status).toBe(201);
      expect(res.headers.get('location')).toBe(`${podUrl}alice`);

      res = await fetch(`${baseUrl}alice`, {
        headers: {
          forwarded: `host=${podHost}`,
          authorization: `WebID ${user.webId}`,
        },
      });
      expect(res.status).toBe(200);
      await expect(res.text()).resolves.toBe('this is new data!');
    });

    it('should not be able to create a pod with the same name.', async(): Promise<void> => {
      const res = await fetch(controls.account.pod, {
        method: 'POST',
        headers: { authorization, 'content-type': 'application/json' },
        body: JSON.stringify({ name: user.podName }),
      });
      expect(res.status).toBe(400);
      await expect(res.text()).resolves.toContain(`There already is a resource at ${podUrl}`);
    });
  });
});

import { createDpopHeader, generateDpopKeyPair } from '@inrupt/solid-client-authn-core';
import fetch from 'cross-fetch';
import { copy, readdir } from 'fs-extra';
import type { App } from '../../src/init/App';
import { APPLICATION_X_WWW_FORM_URLENCODED } from '../../src/util/ContentTypes';
import { joinFilePath, joinUrl, resolveAssetPath } from '../../src/util/PathUtil';
import { getPort } from '../util/Util';
import { getDefaultVariables, getTestConfigPath, getTestFolder, instantiateFromConfig, removeFolder } from './Config';
import { IdentityTestState } from './IdentityTestState';

// This port needs to remain fixed as the assets used are generated with this port in mind
const port = getPort('V6Migration');
const baseUrl = `http://localhost:${port}/`;
const rootFilePath = getTestFolder('v6-migration');
const assetPath = resolveAssetPath('@css:test/assets/migration/v6/');

// Prevent panva/node-openid-client from emitting DraftWarning
jest.spyOn(process, 'emitWarning').mockImplementation();

describe('A server migrating from v6', (): void => {
  let app: App;

  beforeAll(async(): Promise<void> => {
    await removeFolder(rootFilePath);
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
      // Skip the confirmation prompt
      'urn:solid-server:default:variable:confirmMigration': true,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        getTestConfigPath('file-pod.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app } = instances);

    // Move the v6 internal data to the server
    await copy(assetPath, rootFilePath);
  });

  afterAll(async(): Promise<void> => {
    // Await removeFolder(rootFilePath);
    await app.stop();
  });

  it('can start the server to migrate the data.', async(): Promise<void> => {
    // This is going to trigger the migration step
    await expect(app.start()).resolves.toBeUndefined();

    // If migration was successful, there should be no files left in these folders
    const accountDir = await readdir(joinFilePath(rootFilePath, '.internal/accounts/'));
    expect(accountDir).toEqual(expect.arrayContaining([ 'data', 'index', 'credentials' ]));
    const credentialsDir = await readdir(joinFilePath(rootFilePath, '.internal/accounts/credentials/'));
    expect(credentialsDir).toEqual([]);
    const forgotDir = await readdir(joinFilePath(rootFilePath, '.internal/forgot-password/'));
    expect(forgotDir).toEqual([]);

    // Setup resources should have been migrated
    const setupDir = await readdir(joinFilePath(rootFilePath, '.internal/setup/'));
    expect(setupDir).toEqual([
      // Invalid JSON file was not deleted, only error was logged. Just in case its data needs to be saved.
      'aW52YWxpZFJlc291cmNl$.json',
      'current-base-url$.json',
      'current-server-version$.json',
      'setupCompleted-2.0$.json',
      'v6-migration$.json',
    ]);
  });

  it('still allows existing accounts to log in.', async(): Promise<void> => {
    const indexUrl = joinUrl(baseUrl, '.account/');
    let res = await fetch(indexUrl);
    expect(res.status).toBe(200);
    const { controls } = await res.json();

    res = await fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email: 'test@example.com', password: 'password' }),
    });
    expect(res.status).toBe(200);

    res = await fetch(controls.password.login, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email: 'test2@example.com', password: 'password2' }),
    });
    expect(res.status).toBe(200);
  });

  it('still gives control access to pod owners.', async(): Promise<void> => {
    // Init
    const state = new IdentityTestState(baseUrl, 'http://mockedredirect/', baseUrl);
    let url = await state.initSession();
    expect(url.startsWith(baseUrl)).toBeTruthy();
    url = await state.handleRedirect(url);

    // Log in
    let res = await state.fetchIdp(url);
    expect(res.status).toBe(200);
    const { controls } = await res.json();
    res = await state.fetchIdp(
      controls.password.login,
      'POST',
      JSON.stringify({ email: 'test@example.com', password: 'password' }),
    );
    await state.handleLocationRedirect(res);

    res = await state.fetchIdp(controls.oidc.webId);
    expect(res.status).toBe(200);

    // Pick WebID
    const webId = joinUrl(baseUrl, 'test/profile/card#me');
    res = await state.fetchIdp(controls.oidc.webId, 'POST', { webId, remember: true });
    await state.handleLocationRedirect(res);

    // Consent
    res = await state.fetchIdp(controls.oidc.consent, 'POST');

    // Redirect back to the client and verify login success
    await state.handleIncomingRedirect(res, webId);

    // GET the root ACL (which is initialized as an empty file with the given comment)
    url = joinUrl(baseUrl, 'test/.acl');
    res = await state.session.fetch(url);
    expect(res.status).toBe(200);
    await expect(res.text()).resolves.toBe('# Test comment for integration test\n');

    // Log out of session again
    await state.session.logout();
  });

  it('still supports the existing client credentials.', async(): Promise<void> => {
    // These are the values stored in the original assets
    const id = 'token_fd13b73d-2527-4280-82af-278e5b8fe607';
    const secret = 'a809d7ce5daf0e9acd457c91d712ff05038e4a87192e27191c837602bd4b' +
      '370c633282864c133650b0e9a35b59018b064157532642f628affb2f79e81999e898';
    const tokenUrl = joinUrl(baseUrl, '.oidc/token');
    const dpopHeader = await createDpopHeader(tokenUrl, 'POST', await generateDpopKeyPair());
    const authString = `${encodeURIComponent(id)}:${encodeURIComponent(secret)}`;
    const res = await fetch(tokenUrl, {
      method: 'POST',
      headers: {
        authorization: `Basic ${Buffer.from(authString).toString('base64')}`,
        'content-type': APPLICATION_X_WWW_FORM_URLENCODED,
        dpop: dpopHeader,
      },
      body: 'grant_type=client_credentials&scope=webid',
    });
    expect(res.status).toBe(200);
    const { access_token: accessToken } = await res.json();
    expect(typeof accessToken).toBe('string');
  });
});

import { createServer } from 'node:http';
import type { IncomingMessage, Server, ServerResponse } from 'node:http';
import { fetch } from 'cross-fetch';
import { createRemoteJWKSet, jwtVerify } from 'jose';
import type { NamedNode } from 'n3';
import { DataFactory, Parser, Store } from 'n3';
import type { App } from '../../src/init/App';
import { matchesAuthorizationScheme } from '../../src/util/HeaderUtil';
import { joinUrl, trimTrailingSlashes } from '../../src/util/PathUtil';
import { readJsonStream } from '../../src/util/StreamUtil';
import { NOTIFY } from '../../src/util/Vocabularies';
import { expectNotification, subscribe } from '../util/NotificationUtil';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';
import quad = DataFactory.quad;

const port = getPort('WebhookChannel2023');
const baseUrl = `http://localhost:${port}/`;
const clientPort = getPort('WebhookChannel2023-client');
const target = `http://localhost:${clientPort}/`;
const webId = 'http://example.com/card/#me';
const notificationType = NOTIFY.WebhookChannel2023;

const rootFilePath = getTestFolder('WebhookChannel2023');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    configs: [ 'storage/backend/memory.json', 'util/resource-locker/memory.json' ],
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    configs: [ 'storage/backend/file.json', 'util/resource-locker/file.json' ],
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

describe.each(stores)('A server supporting WebhookChannel2023 using %s', (name, { configs, teardown }): void => {
  let app: App;
  const topic = joinUrl(baseUrl, '/foo');
  let storageDescriptionUrl: string;
  let subscriptionUrl: string;
  let clientServer: Server;
  let serverWebId: string;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        ...configs.map(getPresetConfigPath),
        getTestConfigPath('webhook-notifications.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app } = instances);

    await app.start();

    // Start client server
    clientServer = createServer();
    clientServer.listen(clientPort);
  });

  afterAll(async(): Promise<void> => {
    clientServer.close();
    await teardown();
    await app.stop();
  });

  it('links to the storage description.', async(): Promise<void> => {
    const response = await fetch(baseUrl);
    expect(response.status).toBe(200);
    const linkHeader = response.headers.get('link');
    expect(linkHeader).not.toBeNull();
    const match = /<([^>]+)>; rel="http:\/\/www\.w3\.org\/ns\/solid\/terms#storageDescription"/u.exec(linkHeader!);
    expect(match).not.toBeNull();
    storageDescriptionUrl = match![1];
  });

  it('exposes metadata on how to subscribe in the storage description.', async(): Promise<void> => {
    const response = await fetch(storageDescriptionUrl, { headers: { accept: 'text/turtle' }});
    expect(response.status).toBe(200);
    const quads = new Store(new Parser().parse(await response.text()));

    // Find the notification channel for websockets
    const subscriptions = quads.getObjects(null, NOTIFY.terms.subscription, null);
    const webhookSubscriptions = subscriptions.filter((channel): boolean => quads.has(
      quad(channel as NamedNode, NOTIFY.terms.channelType, NOTIFY.terms.WebhookChannel2023),
    ));
    expect(webhookSubscriptions).toHaveLength(1);
    subscriptionUrl = webhookSubscriptions[0].value;
  });

  it('supports subscribing.', async(): Promise<void> => {
    const { sender } =
      await subscribe(notificationType, webId, subscriptionUrl, topic, { [NOTIFY.sendTo]: target }) as any;
    serverWebId = sender;
  });

  it('emits Created events.', async(): Promise<void> => {
    const clientPromise = new Promise<{ request: IncomingMessage; response: ServerResponse }>((resolve): void => {
      clientServer.on('request', (request, response): void => {
        resolve({ request, response });
      });
    });

    let res = await fetch(topic, {
      method: 'PUT',
      headers: { 'content-type': 'text/plain' },
      body: 'abc',
    });
    expect(res.status).toBe(201);

    const { request, response } = await clientPromise;
    expect(request.headers['content-type']).toBe('application/ld+json');
    const notification = await readJsonStream(request);

    expectNotification(notification, topic, 'Create');

    // Find the JWKS of the server
    res = await fetch(joinUrl(baseUrl, '.well-known/openid-configuration'));
    expect(res.status).toBe(200);
    expect(res.headers.get('content-type')).toContain('application/json');
    const resJson = await res.json();
    expect(typeof resJson.jwks_uri).toBe('string');
    const jwks = createRemoteJWKSet(new URL(resJson.jwks_uri));

    // Check validity of DPoP headers
    // Note that this is not a comprehensive validation of the headers,
    // only some of the basics are checked.
    const { authorization, dpop } = request.headers;
    expect(matchesAuthorizationScheme('DPoP', authorization)).toBe(true);
    const encodedDpopToken = authorization!.slice('dpop '.length);
    // These will throw if they can not be decoded with the JWKS from the server
    const decodedDpopToken = await jwtVerify(encodedDpopToken, jwks, { issuer: trimTrailingSlashes(baseUrl) });
    expect(decodedDpopToken.payload).toMatchObject({
      webid: serverWebId,
    });
    const decodedDpopProof = await jwtVerify(dpop as string, jwks);
    expect(decodedDpopProof.payload).toMatchObject({
      htu: target,
      htm: 'POST',
    });

    // Close the connection so the server can shut down
    response.end();
  });

  it('sends a notification if a state value was sent along.', async(): Promise<void> => {
    const clientPromise = new Promise<{ request: IncomingMessage; response: ServerResponse }>((resolve): void => {
      clientServer.on('request', (request, response): void => {
        resolve({ request, response });
      });
    });

    await subscribe(notificationType, webId, subscriptionUrl, topic, { [NOTIFY.sendTo]: target, state: 'abc' });

    // Will resolve even though the resource did not change since subscribing
    const { request, response } = await clientPromise;
    expect(request.headers['content-type']).toBe('application/ld+json');
    const notification = await readJsonStream(request);

    expectNotification(notification, topic, 'Update');

    // Close the connection so the server can shut down
    response.end();
  });

  it('can remove notification channels.', async(): Promise<void> => {
    const { id } = await subscribe(notificationType, webId, subscriptionUrl, topic, { [NOTIFY.sendTo]: target }) as any;

    const response = await fetch(id, { method: 'DELETE' });
    expect(response.status).toBe(205);

    // Expired WebSockets only get removed every hour so not feasible to test in integration test
  });
});

import { fetch } from 'cross-fetch';
import type { NamedNode } from 'n3';
import { DataFactory, Parser, Store } from 'n3';
import { WebSocket } from 'ws';
import { BasicRepresentation } from '../../src/http/representation/BasicRepresentation';
import type { App } from '../../src/init/App';
import type { ResourceStore } from '../../src/storage/ResourceStore';
import { joinUrl } from '../../src/util/PathUtil';
import { NOTIFY, RDF } from '../../src/util/Vocabularies';
import { expectNotification, subscribe } from '../util/NotificationUtil';
import { getPort } from '../util/Util';
import {
  getDefaultVariables,
  getPresetConfigPath,
  getTestConfigPath,
  getTestFolder,
  instantiateFromConfig,
  removeFolder,
} from './Config';
import quad = DataFactory.quad;
import namedNode = DataFactory.namedNode;

const port = getPort('WebSocketChannel2023');
const baseUrl = `http://localhost:${port}/`;
const notificationType = NOTIFY.WebSocketChannel2023;

const rootFilePath = getTestFolder('WebSocketChannel2023');
const stores: [string, any][] = [
  [ 'in-memory storage', {
    configs: [ 'storage/backend/memory.json', 'util/resource-locker/memory.json' ],
    teardown: jest.fn(),
  }],
  [ 'on-disk storage', {
    configs: [ 'storage/backend/file.json', 'util/resource-locker/file.json' ],
    teardown: async(): Promise<void> => removeFolder(rootFilePath),
  }],
];

describe.each(stores)('A server supporting WebSocketChannel2023 using %s', (name, { configs, teardown }): void => {
  let app: App;
  let store: ResourceStore;
  const webId = 'http://example.com/card/#me';
  const topic = joinUrl(baseUrl, '/foo');
  let storageDescriptionUrl: string;
  let subscriptionUrl: string;
  let webSocketUrl: string;

  beforeAll(async(): Promise<void> => {
    const variables = {
      ...getDefaultVariables(port, baseUrl),
      'urn:solid-server:default:variable:rootFilePath': rootFilePath,
    };

    // Create and start the server
    const instances = await instantiateFromConfig(
      'urn:solid-server:test:Instances',
      [
        ...configs.map(getPresetConfigPath),
        getTestConfigPath('websocket-notifications.json'),
      ],
      variables,
    ) as Record<string, any>;
    ({ app, store } = instances);

    await app.start();
  });

  afterAll(async(): Promise<void> => {
    await teardown();
    await app.stop();
  });

  it('links to the storage description.', async(): Promise<void> => {
    const response = await fetch(baseUrl);
    expect(response.status).toBe(200);
    const linkHeader = response.headers.get('link');
    expect(linkHeader).not.toBeNull();
    const match = /<([^>]+)>; rel="http:\/\/www\.w3\.org\/ns\/solid\/terms#storageDescription"/u.exec(linkHeader!);
    expect(match).not.toBeNull();
    storageDescriptionUrl = match![1];
  });

  it('exposes metadata on how to subscribe in the storage description.', async(): Promise<void> => {
    const response = await fetch(storageDescriptionUrl, { headers: { accept: 'text/turtle' }});
    expect(response.status).toBe(200);
    const quads = new Store(new Parser().parse(await response.text()));

    // Find the notification channel for websockets
    const subscriptions = quads.getObjects(null, NOTIFY.terms.subscription, null);
    const websocketSubscriptions = subscriptions.filter((channel): boolean => quads.has(
      quad(channel as NamedNode, NOTIFY.terms.channelType, NOTIFY.terms.WebSocketChannel2023),
    ));
    expect(websocketSubscriptions).toHaveLength(1);
    subscriptionUrl = websocketSubscriptions[0].value;
  });

  it('supports subscribing.', async(): Promise<void> => {
    const response = await subscribe(notificationType, webId, subscriptionUrl, topic);
    webSocketUrl = (response as any).receiveFrom;
  });

  it('emits Created events.', async(): Promise<void> => {
    const socket = new WebSocket(webSocketUrl);

    const notificationPromise = new Promise<Buffer>((resolve): any => socket.on('message', resolve));
    await new Promise<void>((resolve): any => socket.on('open', resolve));

    const response = await fetch(topic, {
      method: 'PUT',
      headers: { 'content-type': 'text/plain' },
      body: 'abc',
    });
    expect(response.status).toBe(201);

    const notification = JSON.parse((await notificationPromise).toString());
    socket.close();

    expectNotification(notification, topic, 'Create');
  });

  it('emits Update events.', async(): Promise<void> => {
    const socket = new WebSocket(webSocketUrl);
    const notificationPromise = new Promise<Buffer>((resolve): any => socket.on('message', resolve));
    await new Promise<void>((resolve): any => socket.on('open', resolve));

    const response = await fetch(topic, {
      method: 'PUT',
      headers: { 'content-type': 'text/plain' },
      body: 'def',
    });
    expect(response.status).toBe(205);

    const notification = JSON.parse((await notificationPromise).toString());
    socket.close();

    expectNotification(notification, topic, 'Update');
  });

  it('emits Delete events.', async(): Promise<void> => {
    const socket = new WebSocket(webSocketUrl);
    const notificationPromise = new Promise<Buffer>((resolve): any => socket.on('message', resolve));
    await new Promise<void>((resolve): any => socket.on('open', resolve));

    const response = await fetch(topic, { method: 'DELETE' });
    expect(response.status).toBe(205);

    const notification = JSON.parse((await notificationPromise).toString());
    socket.close();

    expectNotification(notification, topic, 'Delete');
  });

  it('prevents subscribing to restricted resources.', async(): Promise<void> => {
    const restricted = joinUrl(baseUrl, '/restricted');

    // Only allow our WebID to read
    const restrictedAcl = `@prefix acl: <http://www.w3.org/ns/auth/acl#>.
@prefix foaf: <http://xmlns.com/foaf/0.1/>.

<#authorization>
    a               acl:Authorization;
    acl:agent       <${webId}>;
    acl:mode        acl:Read;
    acl:accessTo    <./restricted>.`;
    await store.setRepresentation({ path: `${restricted}.acl` }, new BasicRepresentation(restrictedAcl, 'text/turtle'));

    const channel = {
      '@context': [ 'https://www.w3.org/ns/solid/notification/v1' ],
      type: notificationType,
      topic: restricted,
    };

    // Unauthenticated fetch fails
    let response = await fetch(subscriptionUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/ld+json' },
      body: JSON.stringify(channel),
    });
    expect(response.status).toBe(401);

    // (debug) Authenticated fetch succeeds
    response = await fetch(subscriptionUrl, {
      method: 'POST',
      headers: {
        authorization: `WebID ${webId}`,
        'content-type': 'application/ld+json',
      },
      body: JSON.stringify(channel),
    });
    expect(response.status).toBe(200);
  });

  it('sends a notification if a state value was sent along.', async(): Promise<void> => {
    const response = await fetch(topic, {
      method: 'PUT',
      headers: { 'content-type': 'text/plain' },
      body: 'abc',
    });
    expect(response.status).toBe(201);

    const { receiveFrom } = await subscribe(notificationType, webId, subscriptionUrl, topic, { state: 'abc' }) as any;

    const socket = new WebSocket(receiveFrom);
    const notificationPromise = new Promise<Buffer>((resolve): any => socket.on('message', resolve));
    await new Promise<void>((resolve): any => socket.on('open', resolve));

    // Will receive a notification even though the resource did not change after the socket was open
    const notification = JSON.parse((await notificationPromise).toString());
    socket.close();

    expectNotification(notification, topic, 'Update');
  });

  it('removes expired channels.', async(): Promise<void> => {
    const { receiveFrom } =
      await subscribe(notificationType, webId, subscriptionUrl, topic, { endAt: '1988-03-09T14:48:00.000Z' }) as any;

    const socket = new WebSocket(receiveFrom);
    const messagePromise = new Promise<Buffer>((resolve): any => socket.on('message', resolve));
    await new Promise<void>((resolve): any => socket.on('close', resolve));

    const message = (await messagePromise).toString();
    expect(message).toContain('There was an error opening this WebSocket');
  });

  it('emits container notifications if contents get added or removed.', async(): Promise<void> => {
    const resource = joinUrl(baseUrl, '/resource');
    // Subscribing to the base URL, which is the parent container
    const { receiveFrom } = await subscribe(notificationType, webId, subscriptionUrl, baseUrl) as any;

    const socket = new WebSocket(receiveFrom);
    let notificationPromise = new Promise<Buffer>((resolve): any => socket.on('message', resolve));
    await new Promise<void>((resolve): any => socket.on('open', resolve));

    let response = await fetch(resource, {
      method: 'PUT',
      headers: { 'content-type': 'text/plain' },
      body: 'abc',
    });
    expect(response.status).toBe(201);

    // Will receive the Add notification
    let notification = JSON.parse((await notificationPromise).toString());

    // Slightly differs from the other notifications due to the combination of object and target
    expect(notification).toEqual({
      '@context': [
        'https://www.w3.org/ns/activitystreams',
        'https://www.w3.org/ns/solid/notification/v1',
      ],
      id: expect.stringContaining(baseUrl),
      type: 'Add',
      object: resource,
      target: baseUrl,
      published: expect.anything(),
      state: expect.anything(),
    });

    // Reset the notifications promise
    notificationPromise = new Promise<Buffer>((resolve): any => socket.on('message', resolve));

    response = await fetch(resource, {
      method: 'DELETE',
    });
    expect(response.status).toBe(205);

    // Will receive the Remove notification
    notification = JSON.parse((await notificationPromise).toString());

    expect(notification).toEqual({
      '@context': [
        'https://www.w3.org/ns/activitystreams',
        'https://www.w3.org/ns/solid/notification/v1',
      ],
      id: expect.stringContaining(baseUrl),
      type: 'Remove',
      object: resource,
      target: baseUrl,
      published: expect.anything(),
      state: expect.anything(),
    });

    socket.close();
  });

  it('can use other RDF formats and content negotiation when creating a channel.', async(): Promise<void> => {
    const turtleChannel = `
      _:id <${RDF.type}> <${notificationType}> ;
           <http://www.w3.org/ns/solid/notifications#topic> <${topic}>.
    `;

    const response = await fetch(subscriptionUrl, {
      method: 'POST',
      headers: {
        authorization: `WebID ${webId}`,
        'content-type': 'text/turtle',
        accept: 'text/turtle',
      },
      body: turtleChannel,
    });
    expect(response.status).toBe(200);
    expect(response.headers.get('content-type')).toBe('text/turtle');

    const parser = new Parser({ baseIRI: subscriptionUrl });
    const quads = new Store(parser.parse(await response.text()));

    expect(quads.getObjects(null, RDF.terms.type, null)).toEqual([ NOTIFY.terms.WebSocketChannel2023 ]);
    expect(quads.getObjects(null, NOTIFY.terms.topic, null)).toEqual([ namedNode(topic) ]);
    expect(quads.countQuads(null, NOTIFY.terms.receiveFrom, null, null)).toBe(1);
  });

  it('can remove notification channels.', async(): Promise<void> => {
    const { id } = await subscribe(notificationType, webId, subscriptionUrl, topic) as any;

    const response = await fetch(id, { method: 'DELETE' });
    expect(response.status).toBe(205);

    // Expired WebSockets only get removed every hour so not feasible to test in integration test
  });
});

{
  "extends": "../tsconfig.json",
  "compilerOptions": {
    "module": "es2022",
    "moduleResolution": "node"
  },
  "include": [
    "."
