import { EventEmitter } from 'node:events';
import { PassThrough } from 'node:stream';
import type { MockResponse } from 'node-mocks-http';
import { createResponse } from 'node-mocks-http';
import { BasicResponseWriter } from '../../../../src/http/output/BasicResponseWriter';
import type { MetadataWriter } from '../../../../src/http/output/metadata/MetadataWriter';
import type { ResponseDescription } from '../../../../src/http/output/response/ResponseDescription';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { INTERNAL_QUADS } from '../../../../src/util/ContentTypes';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';
import { guardedStreamFrom } from '../../../../src/util/StreamUtil';
import { StaticAsyncHandler } from '../../../util/StaticAsyncHandler';

describe('A BasicResponseWriter', (): void => {
  let metadataWriter: MetadataWriter;
  let writer: BasicResponseWriter;
  let response: MockResponse<any>;
  let result: ResponseDescription;

  beforeEach(async(): Promise<void> => {
    metadataWriter = new StaticAsyncHandler(true, undefined);
    writer = new BasicResponseWriter(metadataWriter);
    response = createResponse({ eventEmitter: EventEmitter });
    result = { statusCode: 201 };
  });

  it('requires the input to be a binary ResponseDescription.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata(INTERNAL_QUADS);
    await expect(writer.canHandle({ response, result: { statusCode: 201, metadata }}))
      .rejects.toThrow(NotImplementedHttpError);
    metadata.contentType = 'text/turtle';
    await expect(writer.canHandle({ response, result: { statusCode: 201, metadata }}))
      .resolves.toBeUndefined();
    await expect(writer.canHandle({ response, result: { statusCode: 201 }}))
      .resolves.toBeUndefined();
  });

  it('responds with the status code of the ResponseDescription.', async(): Promise<void> => {
    await writer.handle({ response, result });
    expect(response._isEndCalled()).toBeTruthy();
    expect(response._getStatusCode()).toBe(201);
  });

  it('responds with a body if the description has a body.', async(): Promise<void> => {
    const data = guardedStreamFrom([ '<http://test.com/s> <http://test.com/p> <http://test.com/o>.' ]);
    result = { statusCode: 201, data };

    const end = new Promise<void>((resolve): void => {
      response.on('end', (): void => {
        expect(response._isEndCalled()).toBeTruthy();
        expect(response._getStatusCode()).toBe(201);
        expect(response._getData()).toBe('<http://test.com/s> <http://test.com/p> <http://test.com/o>.');
        resolve();
      });
    });

    await writer.handle({ response, result });
    await end;
  });

  it('serializes metadata if there is metadata.', async(): Promise<void> => {
    result = { statusCode: 201, metadata: new RepresentationMetadata() };
    jest.spyOn(metadataWriter, 'handle').mockImplementation();
    await writer.handle({ response, result });
    expect(metadataWriter.handle).toHaveBeenCalledTimes(1);
    expect(metadataWriter.handle).toHaveBeenLastCalledWith({ response, metadata: result.metadata });
    expect(response._isEndCalled()).toBeTruthy();
    expect(response._getStatusCode()).toBe(201);
  });

  it('can handle the data stream erroring.', async(): Promise<void> => {
    const data = guardedStreamFrom([]);
    data.read = (): any => {
      data.emit('error', new Error('bad data!'));
      return null;
    };
    result = { statusCode: 201, data };

    response = new PassThrough();
    // eslint-disable-next-line jest/prefer-spy-on
    response.writeHead = jest.fn();

    const end = new Promise<void>((resolve): void => {
      response.on('error', (error: Error): void => {
        expect(error).toEqual(new Error('bad data!'));
        resolve();
      });
    });

    await expect(writer.handle({ response, result })).resolves.toBeUndefined();
    await end;
  });
});

import 'jest-rdf';
import arrayifyStream from 'arrayify-stream';
import { DataFactory } from 'n3';
import type { PreferenceParser } from '../../../../../src/http/input/preferences/PreferenceParser';
import { ConvertingErrorHandler } from '../../../../../src/http/output/error/ConvertingErrorHandler';
import { BasicRepresentation } from '../../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../../src/http/representation/Representation';
import type { RepresentationPreferences } from '../../../../../src/http/representation/RepresentationPreferences';
import type { HttpRequest } from '../../../../../src/server/HttpRequest';
import type {
  RepresentationConverter,
  RepresentationConverterArgs,
} from '../../../../../src/storage/conversion/RepresentationConverter';
import type { HttpError } from '../../../../../src/util/errors/HttpError';
import { NotFoundHttpError } from '../../../../../src/util/errors/NotFoundHttpError';
import { HTTP, XSD } from '../../../../../src/util/Vocabularies';
import literal = DataFactory.literal;

const preferences: RepresentationPreferences = { type: { 'text/turtle': 1 }};

async function expectValidArgs(args: RepresentationConverterArgs, stack?: string, cause?: Error): Promise<void> {
  expect(args.preferences).toBe(preferences);
  expect(args.representation.metadata.get(HTTP.terms.statusCodeNumber))
    .toEqualRdfTerm(literal(404, XSD.terms.integer));
  expect(args.representation.metadata.contentType).toBe('internal/error');

  // Error contents
  const errorArray = await arrayifyStream(args.representation.data);
  expect(errorArray).toHaveLength(1);
  const resultError = errorArray[0];
  expect(resultError).toMatchObject({ name: 'NotFoundHttpError', message: 'not here' });
  expect(resultError.stack).toBe(stack);
  expect(resultError.cause).toBe(cause);
}

describe('A ConvertingErrorHandler', (): void => {
  // The error object can get modified by the handler
  let error: HttpError;
  const cause = new Error('cause');
  let stack: string | undefined;
  const request = {} as HttpRequest;
  let converter: jest.Mocked<RepresentationConverter>;
  let preferenceParser: jest.Mocked<PreferenceParser>;
  let handler: ConvertingErrorHandler;

  beforeEach(async(): Promise<void> => {
    error = new NotFoundHttpError('not here', { cause });
    ({ stack } = error);
    converter = {
      canHandle: jest.fn(),
      handle: jest.fn(async(): Promise<Representation> =>
        new BasicRepresentation('serialization', 'text/turtle', true)),
      handleSafe: jest.fn(async(): Promise<Representation> =>
        new BasicRepresentation('serialization', 'text/turtle', true)),
    } satisfies Partial<RepresentationConverter> as any;

    preferenceParser = {
      canHandle: jest.fn(),
      handle: jest.fn().mockResolvedValue(preferences),
    } as any;

    handler = new ConvertingErrorHandler(converter, preferenceParser, true);
  });

  it('rejects input not supported by the converter.', async(): Promise<void> => {
    converter.canHandle.mockRejectedValueOnce(new Error('rejected'));
    await expect(handler.canHandle({ error, request })).rejects.toThrow('rejected');
    expect(converter.canHandle).toHaveBeenCalledTimes(1);
    const args = converter.canHandle.mock.calls[0][0];
    expect(args.preferences).toBe(preferences);
    expect(args.representation.metadata.contentType).toBe('internal/error');
  });

  it('rejects input not supported by the preference parser.', async(): Promise<void> => {
    preferenceParser.canHandle.mockRejectedValueOnce(new Error('rejected'));
    await expect(handler.canHandle({ error, request })).rejects.toThrow('rejected');
    expect(preferenceParser.canHandle).toHaveBeenCalledTimes(1);
    expect(preferenceParser.canHandle).toHaveBeenLastCalledWith({ request });
    expect(converter.canHandle).toHaveBeenCalledTimes(0);
  });

  it('accepts input supported by the converter.', async(): Promise<void> => {
    await expect(handler.canHandle({ error, request })).resolves.toBeUndefined();
    expect(converter.canHandle).toHaveBeenCalledTimes(1);
    const args = converter.canHandle.mock.calls[0][0];
    expect(args.preferences).toBe(preferences);
    expect(args.representation.metadata.contentType).toBe('internal/error');
  });

  it('returns the converted error response.', async(): Promise<void> => {
    const prom = handler.handle({ error, request });
    await expect(prom).resolves.toMatchObject({ statusCode: 404 });
    expect((await prom).metadata?.contentType).toBe('text/turtle');
    expect(converter.handle).toHaveBeenCalledTimes(1);
    const args = converter.handle.mock.calls[0][0];
    await expectValidArgs(args, stack, cause);
  });

  it('uses the handleSafe function of the converter during its own handleSafe call.', async(): Promise<void> => {
    const prom = handler.handleSafe({ error, request });
    await expect(prom).resolves.toMatchObject({ statusCode: 404 });
    expect((await prom).metadata?.contentType).toBe('text/turtle');
    expect(converter.handleSafe).toHaveBeenCalledTimes(1);
    const args = converter.handleSafe.mock.calls[0][0];
    await expectValidArgs(args, stack, cause);
  });

  it('hides the stack trace and cause if the option is disabled.', async(): Promise<void> => {
    handler = new ConvertingErrorHandler(converter, preferenceParser);
    const prom = handler.handle({ error, request });
    await expect(prom).resolves.toMatchObject({ statusCode: 404 });
    expect((await prom).metadata?.contentType).toBe('text/turtle');
    expect(converter.handle).toHaveBeenCalledTimes(1);
    const args = converter.handle.mock.calls[0][0];
    await expectValidArgs(args);
  });
});

import { EmptyErrorHandler } from '../../../../../src/http/output/error/EmptyErrorHandler';
import type { HttpRequest } from '../../../../../src/server/HttpRequest';
import { BadRequestHttpError } from '../../../../../src/util/errors/BadRequestHttpError';
import { NotImplementedHttpError } from '../../../../../src/util/errors/NotImplementedHttpError';
import { NotModifiedHttpError } from '../../../../../src/util/errors/NotModifiedHttpError';
import { SOLID_ERROR } from '../../../../../src/util/Vocabularies';

describe('An EmptyErrorHandler', (): void => {
  const request: HttpRequest = {} as any;

  it('can only handle 304 errors by default.', async(): Promise<void> => {
    const handler = new EmptyErrorHandler();
    await expect(handler.canHandle({ error: new NotModifiedHttpError(), request })).resolves.toBeUndefined();
    await expect(handler.canHandle({ error: new BadRequestHttpError(), request }))
      .rejects.toThrow(NotImplementedHttpError);
  });

  it('can support other error types.', async(): Promise<void> => {
    const handler = new EmptyErrorHandler([ 400 ]);
    await expect(handler.canHandle({ error: new BadRequestHttpError(), request })).resolves.toBeUndefined();
    await expect(handler.canHandle({ error: new NotModifiedHttpError(), request }))
      .rejects.toThrow(NotImplementedHttpError);
  });

  it('can support all error types.', async(): Promise<void> => {
    const handler = new EmptyErrorHandler([], true);
    await expect(handler.canHandle({ error: new BadRequestHttpError(), request })).resolves.toBeUndefined();
    await expect(handler.canHandle({ error: new NotModifiedHttpError(), request })).resolves.toBeUndefined();
  });

  it('can support specific error instances.', async(): Promise<void> => {
    const handler = new EmptyErrorHandler();
    const error = new BadRequestHttpError();
    await expect(handler.canHandle({ error, request })).rejects.toThrow(NotImplementedHttpError);
    error.metadata.add(SOLID_ERROR.terms.emptyBody, 'true');
    await expect(handler.canHandle({ error: new NotModifiedHttpError(), request })).resolves.toBeUndefined();
  });

  it('returns a ResponseDescription with an empty body.', async(): Promise<void> => {
    const handler = new EmptyErrorHandler();
    const error = new NotModifiedHttpError();
    const response = await handler.handle({ error, request });
    expect(response.statusCode).toBe(error.statusCode);
    expect(response.data).toBeUndefined();
    expect(response.metadata).toBe(error.metadata);
  });
});

import { RedirectingErrorHandler } from '../../../../../src/http/output/error/RedirectingErrorHandler';
import type { HttpRequest } from '../../../../../src/server/HttpRequest';
import { BadRequestHttpError } from '../../../../../src/util/errors/BadRequestHttpError';
import { FoundHttpError } from '../../../../../src/util/errors/FoundHttpError';
import { NotImplementedHttpError } from '../../../../../src/util/errors/NotImplementedHttpError';
import { SOLID_HTTP } from '../../../../../src/util/Vocabularies';

describe('A RedirectingErrorHandler', (): void => {
  const request = {} as HttpRequest;
  const handler = new RedirectingErrorHandler();

  it('only accepts redirect errors.', async(): Promise<void> => {
    const unsupportedError = new BadRequestHttpError();
    await expect(handler.canHandle({ error: unsupportedError, request })).rejects.toThrow(NotImplementedHttpError);

    const supportedError = new FoundHttpError('http://test.com/foo/bar');
    await expect(handler.canHandle({ error: supportedError, request })).resolves.toBeUndefined();
  });

  it('creates redirect responses.', async(): Promise<void> => {
    const error = new FoundHttpError('http://test.com/foo/bar');
    const result = await handler.handle({ error, request });
    expect(result.statusCode).toBe(error.statusCode);
    expect(result.metadata?.get(SOLID_HTTP.terms.location)?.value).toBe(error.location);
  });
});

import 'jest-rdf';
import { DataFactory } from 'n3';
import type { ErrorHandler } from '../../../../../src/http/output/error/ErrorHandler';
import { SafeErrorHandler } from '../../../../../src/http/output/error/SafeErrorHandler';
import { BasicRepresentation } from '../../../../../src/http/representation/BasicRepresentation';
import { NotFoundHttpError } from '../../../../../src/util/errors/NotFoundHttpError';
import { readableToString } from '../../../../../src/util/StreamUtil';
import { HTTP, XSD } from '../../../../../src/util/Vocabularies';
import literal = DataFactory.literal;

describe('A SafeErrorHandler', (): void => {
  let error: Error;
  let stack: string | undefined;
  let errorHandler: jest.Mocked<ErrorHandler>;
  let handler: SafeErrorHandler;

  beforeEach(async(): Promise<void> => {
    error = new NotFoundHttpError('not here');
    ({ stack } = error);

    errorHandler = {
      handleSafe: jest.fn().mockResolvedValue(new BasicRepresentation('<html>fancy error</html>', 'text/html')),
    } as any;

    handler = new SafeErrorHandler(errorHandler, true);
  });

  it('can handle everything.', async(): Promise<void> => {
    await expect(handler.canHandle({} as any)).resolves.toBeUndefined();
  });

  it('sends the request to the stored error handler.', async(): Promise<void> => {
    const prom = handler.handle({ error } as any);
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.metadata?.contentType).toBe('text/html');
    await expect(readableToString(result.data!)).resolves.toBe('<html>fancy error</html>');
  });

  describe('where the wrapped error handler fails', (): void => {
    beforeEach(async(): Promise<void> => {
      errorHandler.handleSafe.mockRejectedValue(new Error('handler failed'));
    });

    it('creates a text representation of the error.', async(): Promise<void> => {
      const prom = handler.handle({ error } as any);
      await expect(prom).resolves.toBeDefined();
      const result = await prom;
      expect(result.statusCode).toBe(404);
      expect(result.metadata?.get(HTTP.terms.statusCodeNumber)).toEqualRdfTerm(literal(404, XSD.terms.integer));
      expect(result.metadata?.contentType).toBe('text/plain');
      await expect(readableToString(result.data!)).resolves.toBe(`${stack}\n`);
    });

    it('concatenates name and message if there is no stack.', async(): Promise<void> => {
      delete error.stack;
      const prom = handler.handle({ error } as any);
      await expect(prom).resolves.toBeDefined();
      const result = await prom;
      expect(result.statusCode).toBe(404);
      expect(result.metadata?.get(HTTP.terms.statusCodeNumber)).toEqualRdfTerm(literal(404, XSD.terms.integer));
      expect(result.metadata?.contentType).toBe('text/plain');
      await expect(readableToString(result.data!)).resolves.toBe(`NotFoundHttpError: not here\n`);
    });

    it('hides the stack trace if the option is disabled.', async(): Promise<void> => {
      handler = new SafeErrorHandler(errorHandler);
      const prom = handler.handle({ error } as any);
      await expect(prom).resolves.toBeDefined();
      const result = await prom;
      expect(result.statusCode).toBe(404);
      expect(result.metadata?.get(HTTP.terms.statusCodeNumber)).toEqualRdfTerm(literal(404, XSD.terms.integer));
      expect(result.metadata?.contentType).toBe('text/plain');
      await expect(readableToString(result.data!)).resolves.toBe(`NotFoundHttpError: not here\n`);
    });
  });
});

import type { TargetExtractor } from '../../../../../src/http/input/identifier/TargetExtractor';
import type { ErrorHandler, ErrorHandlerArgs } from '../../../../../src/http/output/error/ErrorHandler';
import { TargetExtractorErrorHandler } from '../../../../../src/http/output/error/TargetExtractorErrorHandler';
import type { ResourceIdentifier } from '../../../../../src/http/representation/ResourceIdentifier';
import { NotFoundHttpError } from '../../../../../src/util/errors/NotFoundHttpError';
import { SOLID_ERROR } from '../../../../../src/util/Vocabularies';

describe('A TargetExtractorErrorHandler', (): void => {
  const identifier: ResourceIdentifier = { path: 'http://example.com/foo' };
  let input: ErrorHandlerArgs;
  let source: jest.Mocked<ErrorHandler>;
  let targetExtractor: jest.Mocked<TargetExtractor>;
  let handler: TargetExtractorErrorHandler;

  beforeEach(async(): Promise<void> => {
    input = {
      request: 'request' as any,
      error: new NotFoundHttpError(),
    };

    source = {
      canHandle: jest.fn(),
      handle: jest.fn().mockResolvedValue('response'),
    } satisfies Partial<ErrorHandler> as any;

    targetExtractor = {
      handleSafe: jest.fn().mockResolvedValue(identifier),
    } satisfies Partial<TargetExtractor> as any;

    handler = new TargetExtractorErrorHandler(source, targetExtractor);
  });

  it('can handle input its source can handle.', async(): Promise<void> => {
    await expect(handler.canHandle(input)).resolves.toBeUndefined();
    expect(source.canHandle).toHaveBeenLastCalledWith(input);

    const error = new Error('bad data');
    source.canHandle.mockRejectedValueOnce(error);
    await expect(handler.canHandle(input)).rejects.toThrow(error);
  });

  it('adds the identifier as metadata.', async(): Promise<void> => {
    await expect(handler.handle(input)).resolves.toBe('response');
    expect(input.error.metadata.get(SOLID_ERROR.terms.target)?.value).toEqual(identifier.path);
    expect(targetExtractor.handleSafe).toHaveBeenLastCalledWith(input);
  });

  it('still calls the source handler if the identifier could not be added.', async(): Promise<void> => {
    targetExtractor.handleSafe.mockRejectedValueOnce(new Error('bad data'));
    await expect(handler.handle(input)).resolves.toBe('response');
    expect(input.error.metadata.get(SOLID_ERROR.terms.target)).toBeUndefined();
    expect(targetExtractor.handleSafe).toHaveBeenLastCalledWith(input);
  });
});

import { createResponse } from 'node-mocks-http';
import { AllowAcceptHeaderWriter } from '../../../../../src/http/output/metadata/AllowAcceptHeaderWriter';
import type { MetadataRecord } from '../../../../../src/http/representation/RepresentationMetadata';
import { RepresentationMetadata } from '../../../../../src/http/representation/RepresentationMetadata';
import type { HttpResponse } from '../../../../../src/server/HttpResponse';
import { MethodNotAllowedHttpError } from '../../../../../src/util/errors/MethodNotAllowedHttpError';
import { NotFoundHttpError } from '../../../../../src/util/errors/NotFoundHttpError';
import { UnsupportedMediaTypeHttpError } from '../../../../../src/util/errors/UnsupportedMediaTypeHttpError';
import { LDP, PIM, RDF, SOLID_ERROR, SOLID_META } from '../../../../../src/util/Vocabularies';

describe('An AllowAcceptHeaderWriter', (): void => {
  const document = new RepresentationMetadata(
    { path: 'http://example.com/foo/bar' },
    { [RDF.type]: LDP.terms.Resource },
  );
  const descriptionResource = new RepresentationMetadata(
    { path: 'http://example.com/foo/bar.meta' },
    { [RDF.type]: [ LDP.terms.Resource, SOLID_META.terms.DescriptionResource ]},
  );
  const emptyContainer = new RepresentationMetadata(
    { path: 'http://example.com/foo/' },
    { [RDF.type]: [ LDP.terms.Resource, LDP.terms.Container ]},
  );
  const fullContainer = new RepresentationMetadata(
    { path: 'http://example.com/foo/' },
    {
      [RDF.type]: [ LDP.terms.Resource, LDP.terms.Container ],
      [LDP.contains]: [ document.identifier ],
      // Typescript doesn't find the correct constructor without the cast
    } as MetadataRecord,
  );
  const storageContainer = new RepresentationMetadata(
    { path: 'http://example.com/foo/' },
    { [RDF.type]: [ LDP.terms.Resource, LDP.terms.Container, PIM.terms.Storage ]},
  );
  const error404 = new RepresentationMetadata({ [SOLID_ERROR.errorResponse]: NotFoundHttpError.uri });
  const error404Container = new RepresentationMetadata({
    [SOLID_ERROR.errorResponse]: NotFoundHttpError.uri,
    [SOLID_ERROR.target]: 'http://example.com/foo/',
  });
  const error404Document = new RepresentationMetadata({
    [SOLID_ERROR.errorResponse]: NotFoundHttpError.uri,
    [SOLID_ERROR.target]: 'http://example.com/foo/bar',
  });
  const error405 = new RepresentationMetadata(
    { [SOLID_ERROR.errorResponse]: MethodNotAllowedHttpError.uri, [SOLID_ERROR.disallowedMethod]: 'PUT' },
  );
  const error415 = new RepresentationMetadata({ [SOLID_ERROR.errorResponse]: UnsupportedMediaTypeHttpError.uri });
  let response: HttpResponse;
  let writer: AllowAcceptHeaderWriter;

  beforeEach(async(): Promise<void> => {
    response = createResponse() as HttpResponse;

    writer = new AllowAcceptHeaderWriter(
      [ 'OPTIONS', 'GET', 'HEAD', 'PUT', 'POST', 'PATCH', 'DELETE' ],
      { patch: [ 'text/n3', 'application/sparql-update' ], post: [ '*/*' ], put: [ '*/*' ]},
    );
  });

  it('returns all methods except POST for a document.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: document })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'OPTIONS', 'GET', 'HEAD', 'PUT', 'PATCH', 'DELETE' ]));
    expect(headers['accept-patch']).toBe('text/n3, application/sparql-update');
    expect(headers['accept-put']).toBe('*/*');
    expect(headers['accept-post']).toBeUndefined();
  });

  it('returns all methods except POST, PUT, and DELETE for a description resource.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: descriptionResource })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'OPTIONS', 'GET', 'HEAD', 'PATCH' ]));
    expect(headers['accept-patch']).toBe('text/n3, application/sparql-update');
    expect(headers['accept-put']).toBeUndefined();
    expect(headers['accept-post']).toBeUndefined();
  });

  it('returns all methods except PUT/PATCH for an empty container.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: emptyContainer })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'OPTIONS', 'GET', 'HEAD', 'POST', 'DELETE' ]));
    expect(headers['accept-patch']).toBeUndefined();
    expect(headers['accept-put']).toBeUndefined();
    expect(headers['accept-post']).toBe('*/*');
  });

  it('returns all methods except PUT/PATCH/DELETE for a non-empty container.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: fullContainer })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'OPTIONS', 'GET', 'HEAD', 'POST' ]));
    expect(headers['accept-patch']).toBeUndefined();
    expect(headers['accept-put']).toBeUndefined();
    expect(headers['accept-post']).toBe('*/*');
  });

  it('returns all methods except PUT/PATCH/DELETE for a storage container.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: storageContainer })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'OPTIONS', 'GET', 'HEAD', 'POST' ]));
    expect(headers['accept-patch']).toBeUndefined();
    expect(headers['accept-put']).toBeUndefined();
    expect(headers['accept-post']).toBe('*/*');
  });

  it('returns PATCH and PUT if the target does not exist.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: error404 })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'PUT', 'PATCH' ]));
    expect(headers['accept-patch']).toBe('text/n3, application/sparql-update');
    expect(headers['accept-put']).toBe('*/*');
    expect(headers['accept-post']).toBeUndefined();
  });

  it('returns PUT if the target does not exist and is a document.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: error404Document })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'PUT', 'PATCH' ]));
    expect(headers['accept-patch']).toBe('text/n3, application/sparql-update');
    expect(headers['accept-put']).toBe('*/*');
    expect(headers['accept-post']).toBeUndefined();
  });

  it('returns PUT if the target does not exist and is a container.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: error404Container })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'PUT' ]));
    expect(headers['accept-patch']).toBeUndefined();
    expect(headers['accept-put']).toBe('*/*');
    expect(headers['accept-post']).toBeUndefined();
  });

  it('removes methods that are not allowed by a 405 error.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: error405 })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(typeof headers.allow).toBe('string');
    expect(new Set(headers.allow!.split(', ')))
      .toEqual(new Set([ 'OPTIONS', 'GET', 'HEAD', 'POST', 'PATCH', 'DELETE' ]));
    expect(headers['accept-patch']).toBe('text/n3, application/sparql-update');
    expect(headers['accept-put']).toBeUndefined();
    expect(headers['accept-post']).toBe('*/*');
  });

  it('only returns Accept- headers in case of a 415.', async(): Promise<void> => {
    await expect(writer.handleSafe({ response, metadata: error415 })).resolves.toBeUndefined();
    const headers = response.getHeaders();
    expect(headers.allow).toBeUndefined();
    expect(headers['accept-patch']).toBe('text/n3, application/sparql-update');
    expect(headers['accept-put']).toBe('*/*');
    expect(headers['accept-post']).toBe('*/*');
  });
});

import { createResponse } from 'node-mocks-http';
import { AuxiliaryLinkMetadataWriter } from '../../../../../src/http/output/metadata/AuxiliaryLinkMetadataWriter';
import { RepresentationMetadata } from '../../../../../src/http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../../../../src/http/representation/ResourceIdentifier';
import type { HttpResponse } from '../../../../../src/server/HttpResponse';
import { LDP, RDF, SOLID_ERROR } from '../../../../../src/util/Vocabularies';
import { SimpleSuffixStrategy } from '../../../../util/SimpleSuffixStrategy';

describe('A LinkRelMetadataWriter', (): void => {
  const auxiliaryStrategy = new SimpleSuffixStrategy('.dummy');
  const metadataStrategy = new SimpleSuffixStrategy('.meta');
  const writer = new AuxiliaryLinkMetadataWriter(auxiliaryStrategy, metadataStrategy, 'test');
  let identifier: ResourceIdentifier;

  beforeEach((): void => {
    identifier = { path: 'http://example.org/' };
  });

  it('adds the correct link headers.', async(): Promise<void> => {
    const response = createResponse() as HttpResponse;
    const metadata = new RepresentationMetadata(identifier);
    metadata.add(RDF.terms.type, LDP.terms.Resource);

    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();
    expect(response.getHeaders()).toEqual({ link:
      `<${identifier.path}.meta>; rel="test"` });
  });

  it('does not add link headers for auxiliary resources.', async(): Promise<void> => {
    const response = createResponse() as HttpResponse;
    identifier.path += '.dummy';
    const metadata = new RepresentationMetadata(identifier);
    metadata.add(RDF.terms.type, LDP.terms.Resource);

    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();
    expect(response.getHeaders()).toEqual({});
  });

  it('adds link headers for errors.', async(): Promise<void> => {
    const response = createResponse() as HttpResponse;
    const metadata = new RepresentationMetadata();
    metadata.add(SOLID_ERROR.terms.target, identifier.path);
    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();
    expect(response.getHeaders()).toEqual({ link:
        `<${identifier.path}.meta>; rel="test"` });
  });

  it('does not add link headers for errors without a target.', async(): Promise<void> => {
    const response = createResponse() as HttpResponse;
    const metadata = new RepresentationMetadata();
    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();
    expect(response.getHeaders()).toEqual({});
  });
});

import { createResponse } from 'node-mocks-http';
import { ConstantMetadataWriter } from '../../../../../src/http/output/metadata/ConstantMetadataWriter';
import type { HttpResponse } from '../../../../../src/server/HttpResponse';

describe('A ConstantMetadataWriter', (): void => {
  const writer = new ConstantMetadataWriter({ 'custom-Header': 'X', other: 'Y' });

  it('adds new headers.', async(): Promise<void> => {
    const response = createResponse() as HttpResponse;

    await expect(writer.handle({ response })).resolves.toBeUndefined();

    expect(response.getHeaders()).toEqual({ 'custom-header': 'X', other: 'Y' });
  });

  it('extends existing headers.', async(): Promise<void> => {
    const response = createResponse() as HttpResponse;
    response.setHeader('Other', 'A');

    await expect(writer.handle({ response })).resolves.toBeUndefined();

    expect(response.getHeaders()).toEqual({ 'custom-header': 'X', other: [ 'A', 'Y' ]});
  });
});

import { createResponse } from 'node-mocks-http';
import { ContentTypeMetadataWriter } from '../../../../../src/http/output/metadata/ContentTypeMetadataWriter';
import { RepresentationMetadata } from '../../../../../src/http/representation/RepresentationMetadata';
import type { HttpResponse } from '../../../../../src/server/HttpResponse';
import { ContentType } from '../../../../../src/util/Header';

describe('A ContentTypeMetadataWriter', (): void => {
  const writer = new ContentTypeMetadataWriter();
  let response: HttpResponse;

  beforeEach(async(): Promise<void> => {
    response = createResponse() as HttpResponse;
  });

  it('adds no header if there is no relevant metadata.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata();
    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();
    expect(response.getHeaders()).toEqual({});
  });

  it('adds a Content-Type header with parameters if present.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata(new ContentType('text/plain', { charset: 'utf-8' }));
    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();

    expect(response.getHeaders()).toEqual({
      'content-type': 'text/plain; charset=utf-8',
    });
  });

  it('adds a Content-Type header without parameters.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata('text/plain');
    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();

    expect(response.getHeaders()).toEqual({
      'content-type': 'text/plain',
    });
  });
});

import { DataFactory } from 'n3';
import { createResponse } from 'node-mocks-http';
import { CookieMetadataWriter } from '../../../../../src/http/output/metadata/CookieMetadataWriter';
import { RepresentationMetadata } from '../../../../../src/http/representation/RepresentationMetadata';
import type { HttpResponse } from '../../../../../src/server/HttpResponse';
import namedNode = DataFactory.namedNode;
import literal = DataFactory.literal;

describe('A CookieMetadataWriter', (): void => {
  const writer = new CookieMetadataWriter({
    'http://example.com/pred1': { name: 'custom1' },
    'http://example.com/pred2': { name: 'custom2', expirationUri: 'http://example.com/pred2expiration' },
  });
  let metadata: RepresentationMetadata;
  let response: HttpResponse;

  beforeEach(async(): Promise<void> => {
    metadata = new RepresentationMetadata();
    response = createResponse() as HttpResponse;
  });

  it('adds no headers if there is no relevant metadata.', async(): Promise<void> => {
    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();
    expect(response.getHeaders()).toEqual({});
  });

  it('adds the relevant set-cookie headers.', async(): Promise<void> => {
    const date = new Date('2015-10-21T07:28:00.000Z');
    metadata.add(namedNode('http://example.com/pred1'), literal('my-value'));
    metadata.add(namedNode('http://example.com/pred2'), literal('other-value'));
    metadata.add(namedNode('http://example.com/pred2expiration'), literal(date.toISOString()));
    metadata.add(namedNode('http://example.com/unknown'), literal('unknown-value'));
    await expect(writer.handle({ response, metadata })).resolves.toBeUndefined();
    expect(response.getHeader('set-cookie')).toEqual([
      'custom1=my-value; Path=/; SameSite=Lax',
      'custom2=other-value; Path=/; Expires=Wed, 21 Oct 2015 07:28:00 GMT; SameSite=Lax',
    ]);
  });
});

