import 'jest-rdf';
import { Readable } from 'node:stream';
import arrayifyStream from 'arrayify-stream';
import { DataFactory } from 'n3';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { INTERNAL_QUADS } from '../../../../src/util/ContentTypes';
import { guardedStreamFrom } from '../../../../src/util/StreamUtil';
import { CONTENT_TYPE } from '../../../../src/util/Vocabularies';

const { namedNode } = DataFactory;

describe('BasicRepresentation', (): void => {
  it('creates a representation with (data, metadata, binary).', (): void => {
    const data = guardedStreamFrom([ '' ]);
    const metadata = new RepresentationMetadata();
    const representation = new BasicRepresentation(data, metadata, true);
    expect(representation.data).toBe(data);
    expect(representation.metadata).toBe(metadata);
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (data, metadata).', (): void => {
    const data = guardedStreamFrom([ '' ]);
    let metadata = new RepresentationMetadata();
    let representation = new BasicRepresentation(data, metadata);
    expect(representation.data).toBe(data);
    expect(representation.metadata).toBe(metadata);
    expect(representation.binary).toBe(true);

    metadata = new RepresentationMetadata(INTERNAL_QUADS);
    representation = new BasicRepresentation(data, metadata);
    expect(representation.data).toBe(data);
    expect(representation.metadata).toBe(metadata);
    expect(representation.binary).toBe(false);
  });

  it('creates a representation with (unguarded data, metadata).', (): void => {
    const data = Readable.from([ '' ]);
    const metadata = new RepresentationMetadata();
    const representation = new BasicRepresentation(data, metadata);
    expect(representation.data).toBe(data);
    expect(representation.metadata).toBe(metadata);
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (array data, metadata).', async(): Promise<void> => {
    const data = [ 'my', 'data' ];
    const metadata = new RepresentationMetadata();
    const representation = new BasicRepresentation(data, metadata);
    await expect(arrayifyStream(representation.data)).resolves.toEqual(data);
    expect(representation.metadata).toBe(metadata);
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (string data, metadata).', async(): Promise<void> => {
    const data = 'my data';
    const metadata = new RepresentationMetadata();
    const representation = new BasicRepresentation(data, metadata);
    await expect(arrayifyStream(representation.data)).resolves.toEqual([ data ]);
    expect(representation.metadata).toBe(metadata);
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (data, metadata record).', (): void => {
    const data = guardedStreamFrom([ '' ]);
    const representation = new BasicRepresentation(data, { [CONTENT_TYPE]: 'text/custom' });
    expect(representation.data).toBe(data);
    expect(representation.metadata.contentType).toBe('text/custom');
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (data, content type).', (): void => {
    const data = guardedStreamFrom([ '' ]);
    const representation = new BasicRepresentation(data, 'text/custom');
    expect(representation.data).toBe(data);
    expect(representation.metadata.contentType).toBe('text/custom');
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (data, identifier, metadata record).', (): void => {
    const identifier = { path: 'http://example.org/#' };
    const data = guardedStreamFrom([ '' ]);
    const representation = new BasicRepresentation(data, identifier, { [CONTENT_TYPE]: 'text/custom' });
    expect(representation.data).toBe(data);
    expect(representation.metadata.identifier).toEqualRdfTerm(namedNode(identifier.path));
    expect(representation.metadata.contentType).toBe('text/custom');
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (data, identifier, content type).', (): void => {
    const identifier = { path: 'http://example.org/#' };
    const data = guardedStreamFrom([ '' ]);
    const representation = new BasicRepresentation(data, identifier, 'text/custom');
    expect(representation.data).toBe(data);
    expect(representation.metadata.identifier).toEqualRdfTerm(namedNode(identifier.path));
    expect(representation.metadata.contentType).toBe('text/custom');
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (data, identifier term, metadata record).', (): void => {
    const identifier = namedNode('http://example.org/#');
    const data = guardedStreamFrom([ '' ]);
    const representation = new BasicRepresentation(data, identifier, { [CONTENT_TYPE]: 'text/custom' });
    expect(representation.data).toBe(data);
    expect(representation.metadata.identifier).toBe(identifier);
    expect(representation.metadata.contentType).toBe('text/custom');
    expect(representation.binary).toBe(true);
  });

  it('creates a representation with (data, identifier term, content type).', (): void => {
    const identifier = namedNode('http://example.org/#');
    const data = guardedStreamFrom([ '' ]);
    const representation = new BasicRepresentation(data, identifier, 'text/custom');
    expect(representation.data).toBe(data);
    expect(representation.metadata.identifier).toBe(identifier);
    expect(representation.metadata.contentType).toBe('text/custom');
    expect(representation.binary).toBe(true);
  });
});

import 'jest-rdf';
import type { BlankNode } from 'n3';
import { DataFactory } from 'n3';
import type { NamedNode, Quad } from '@rdfjs/types';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { ContentType } from '../../../../src/util/Header';
import { CONTENT_TYPE_TERM, RDFS, SOLID_META } from '../../../../src/util/Vocabularies';

const { defaultGraph, literal, namedNode, quad } = DataFactory;

// Helper functions to filter quads
function getQuads(quads: Quad[], subject?: string, predicate?: string, object?: string, graph?: string): Quad[] {
  return quads.filter((qq): boolean =>
    (!subject || qq.subject.value === subject) &&
    (!predicate || qq.predicate.value === predicate) &&
    (!object || qq.object.value === object) &&
    (!graph || qq.graph.value === graph));
}

function removeQuads(quads: Quad[], subject?: string, predicate?: string, object?: string, graph?: string): Quad[] {
  const filtered = getQuads(quads, subject, predicate, object, graph);
  return quads.filter((qq): boolean => !filtered.includes(qq));
}

describe('A RepresentationMetadata', (): void => {
  let metadata: RepresentationMetadata;
  const identifier = namedNode('http://example.com/id');
  const graphNode = namedNode('http://graph');
  const inputQuads = [
    quad(identifier, namedNode('has'), literal('data')),
    quad(identifier, namedNode('has'), literal('moreData')),
    quad(identifier, namedNode('hasOne'), literal('otherData')),
    quad(identifier, namedNode('has'), literal('data'), graphNode),
    quad(namedNode('otherNode'), namedNode('linksTo'), identifier),
    quad(namedNode('otherNode'), namedNode('has'), literal('otherData')),
    quad(namedNode('otherNode'), namedNode('graphData'), literal('otherData'), graphNode),
  ];

  describe('constructor', (): void => {
    it('creates a blank node if no identifier was given.', async(): Promise<void> => {
      metadata = new RepresentationMetadata();
      expect(metadata.identifier.termType).toBe('BlankNode');
      expect(metadata.quads()).toHaveLength(0);
    });

    it('stores the given identifier if given.', async(): Promise<void> => {
      metadata = new RepresentationMetadata(namedNode('identifier'));
      expect(metadata.identifier).toEqualRdfTerm(namedNode('identifier'));
    });

    it('converts identifiers to named nodes.', async(): Promise<void> => {
      metadata = new RepresentationMetadata({ path: 'identifier' });
      expect(metadata.identifier).toEqualRdfTerm(namedNode('identifier'));
    });

    it('converts string to content type.', async(): Promise<void> => {
      metadata = new RepresentationMetadata('text/turtle');
      expect(metadata.contentType).toBe('text/turtle');

      metadata = new RepresentationMetadata({ path: 'identifier' }, 'text/turtle');
      expect(metadata.contentType).toBe('text/turtle');

      metadata = new RepresentationMetadata(new RepresentationMetadata(), 'text/turtle');
      expect(metadata.contentType).toBe('text/turtle');
    });

    it('stores the content-length correctly.', async(): Promise<void> => {
      metadata = new RepresentationMetadata();
      metadata.contentLength = 50;
      expect(metadata.contentLength).toBe(50);

      metadata = new RepresentationMetadata();
      metadata.contentLength = undefined;
      expect(metadata.contentLength).toBeUndefined();
    });

    it('copies an other metadata object.', async(): Promise<void> => {
      const other = new RepresentationMetadata({ path: 'otherId' }, { 'test:pred': 'objVal' });
      metadata = new RepresentationMetadata(other);
      expect(metadata.identifier).toEqualRdfTerm(namedNode('otherId'));
      expect(metadata.quads()).toBeRdfIsomorphic([
        quad(namedNode('otherId'), namedNode('test:pred'), literal('objVal')),
      ]);
    });

    it('takes overrides for specific predicates.', async(): Promise<void> => {
      metadata = new RepresentationMetadata({ predVal: 'objVal' });
      expect(metadata.get(namedNode('predVal'))).toEqualRdfTerm(literal('objVal'));

      metadata = new RepresentationMetadata({ predVal: literal('objVal') });
      expect(metadata.get(namedNode('predVal'))).toEqualRdfTerm(literal('objVal'));

      metadata = new RepresentationMetadata({ predVal: [ 'objVal1', literal('objVal2') ], predVal2: 'objVal3' });
      expect(metadata.getAll(namedNode('predVal'))).toEqualRdfTermArray([ literal('objVal1'), literal('objVal2') ]);
      expect(metadata.get(namedNode('predVal2'))).toEqualRdfTerm(literal('objVal3'));
    });

    it('can combine overrides with an identifier.', async(): Promise<void> => {
      metadata = new RepresentationMetadata(identifier, { predVal: 'objVal' });
      expect(metadata.quads()).toBeRdfIsomorphic([
        quad(identifier, namedNode('predVal'), literal('objVal')),
      ]);
    });

    it('can combine overrides with other metadata.', async(): Promise<void> => {
      const other = new RepresentationMetadata({ path: 'otherId' }, { 'test:pred': 'objVal' });
      metadata = new RepresentationMetadata(other, { 'test:pred': 'objVal2' });
      expect(metadata.quads()).toBeRdfIsomorphic([
        quad(namedNode('otherId'), namedNode('test:pred'), literal('objVal2')),
      ]);
    });
  });

  describe('instantiated', (): void => {
    beforeEach(async(): Promise<void> => {
      metadata = new RepresentationMetadata(identifier).addQuads(inputQuads);
    });

    it('can get all quads.', async(): Promise<void> => {
      expect(metadata.quads()).toBeRdfIsomorphic(inputQuads);
    });

    it('can query quads.', async(): Promise<void> => {
      expect(metadata.quads(null, namedNode('has'))).toHaveLength(getQuads(inputQuads, undefined, 'has').length);
      expect(metadata.quads(null, null, literal('otherData')))
        .toHaveLength(getQuads(inputQuads, undefined, undefined, 'otherData').length);
    });

    it('can change the stored identifier.', async(): Promise<void> => {
      const newIdentifier = namedNode('newNode');
      metadata.identifier = newIdentifier;
      const newQuads = inputQuads.map((triple): Quad => {
        if (triple.subject.equals(identifier)) {
          return quad(newIdentifier, triple.predicate, triple.object, triple.graph);
        }
        if (triple.object.equals(identifier)) {
          return quad(triple.subject, triple.predicate, newIdentifier, triple.graph);
        }
        return triple;
      });
      expect(metadata.identifier).toEqualRdfTerm(newIdentifier);
      expect(metadata.quads()).toBeRdfIsomorphic(newQuads);
    });

    it('can copy metadata.', async(): Promise<void> => {
      const other = new RepresentationMetadata(identifier, { 'test:pred': 'objVal' });
      metadata.setMetadata(other);

      expect(metadata.identifier).toEqual(other.identifier);
      expect(metadata.quads()).toBeRdfIsomorphic([
        ...inputQuads,
        quad(identifier, namedNode('test:pred'), literal('objVal')),
      ]);
    });

    it('updates its identifier when copying metadata.', async(): Promise<void> => {
      const other = new RepresentationMetadata({ path: 'otherId' }, { 'test:pred': 'objVal' });
      metadata.setMetadata(other);

      // `setMetadata` should have the same result as the following
      const expectedMetadata = new RepresentationMetadata(identifier).addQuads(inputQuads);
      expectedMetadata.identifier = namedNode('otherId');
      expectedMetadata.add(namedNode('test:pred'), 'objVal');

      expect(metadata.identifier).toEqual(other.identifier);
      expect(metadata.quads()).toBeRdfIsomorphic(expectedMetadata.quads());
    });

    it('can add a quad.', async(): Promise<void> => {
      const newQuad = quad(namedNode('random'), namedNode('new'), literal('triple'));
      metadata.addQuad('random', namedNode('new'), 'triple');
      expect(metadata.quads()).toBeRdfIsomorphic([ ...inputQuads, newQuad ]);
    });

    it('can add a quad with a graph.', async(): Promise<void> => {
      const newQuad = quad(namedNode('random'), namedNode('new'), literal('triple'), namedNode('graph'));
      metadata.addQuad('random', namedNode('new'), 'triple', 'graph');
      expect(metadata.quads()).toBeRdfIsomorphic([ ...inputQuads, newQuad ]);
    });

    it('can add quads.', async(): Promise<void> => {
      const newQuads: Quad[] = [
        quad(namedNode('random'), namedNode('new'), namedNode('triple')),
      ];
      metadata.addQuads(newQuads);
      expect(metadata.quads()).toBeRdfIsomorphic([ ...newQuads, ...inputQuads ]);
    });

    it('can remove a quad.', async(): Promise<void> => {
      const old = inputQuads[0];
      metadata.removeQuad(old.subject as any, old.predicate as any, old.object as any, old.graph as any);
      expect(metadata.quads()).toBeRdfIsomorphic(inputQuads.slice(1));
    });

    it('removes all matching triples if graph is undefined.', async(): Promise<void> => {
      metadata.removeQuad(identifier, namedNode('has'), 'data');
      expect(metadata.quads()).toHaveLength(inputQuads.length - 2);
      expect(metadata.quads()).toBeRdfIsomorphic(removeQuads(inputQuads, identifier.value, 'has', 'data'));
    });

    it('can remove quads.', async(): Promise<void> => {
      metadata.removeQuads([ inputQuads[0] ]);
      expect(metadata.quads()).toBeRdfIsomorphic(inputQuads.slice(1));
    });

    it('can add a single value for a predicate.', async(): Promise<void> => {
      const newQuad = quad(identifier, namedNode('new'), namedNode('triple'));
      metadata.add(newQuad.predicate as NamedNode, newQuad.object as NamedNode);
      expect(metadata.quads()).toBeRdfIsomorphic([ newQuad, ...inputQuads ]);
    });

    it('can add single values as string.', async(): Promise<void> => {
      const newQuad = quad(identifier, namedNode('new'), literal('triple'));
      metadata.add(newQuad.predicate as NamedNode, newQuad.object.value);
      expect(metadata.quads()).toBeRdfIsomorphic([ newQuad, ...inputQuads ]);
    });

    it('can add multiple values for a predicate.', async(): Promise<void> => {
      const newQuads = [
        quad(identifier, namedNode('new'), namedNode('triple')),
        quad(identifier, namedNode('new'), namedNode('triple2')),
      ];
      metadata.add(namedNode('new'), [ namedNode('triple'), namedNode('triple2') ]);
      expect(metadata.quads()).toBeRdfIsomorphic([ ...newQuads, ...inputQuads ]);
    });

    it('can remove a single value for a predicate.', async(): Promise<void> => {
      metadata.remove(namedNode('has'), literal('data'));
      expect(metadata.quads()).toBeRdfIsomorphic(removeQuads(inputQuads, identifier.value, 'has', 'data'));
    });

    it('can remove single values as string.', async(): Promise<void> => {
      metadata.remove(namedNode('has'), 'data');
      expect(metadata.quads()).toBeRdfIsomorphic(removeQuads(inputQuads, identifier.value, 'has', 'data'));
    });

    it('can remove multiple values for a predicate.', async(): Promise<void> => {
      metadata.remove(namedNode('has'), [ literal('data'), 'moreData' ]);
      let expected = removeQuads(inputQuads, identifier.value, 'has', 'data');
      expected = removeQuads(expected, identifier.value, 'has', 'moreData');
      expect(metadata.quads()).toBeRdfIsomorphic(expected);
    });

    it('can remove all values for a predicate.', async(): Promise<void> => {
      const pred = namedNode('has');
      metadata.removeAll(pred);
      expect(metadata.quads()).toBeRdfIsomorphic(removeQuads(inputQuads, identifier.value, 'has'));
    });

    it('can remove all values for a predicate in a specific graph.', async(): Promise<void> => {
      const pred = namedNode('has');
      metadata.removeAll(pred, graphNode);
      expect(metadata.quads()).toBeRdfIsomorphic(
        removeQuads(inputQuads, identifier.value, 'has', undefined, graphNode.value),
      );
    });

    it('can check the existence of a triple.', async(): Promise<void> => {
      expect(metadata.has(namedNode('has'), literal('data'))).toBe(true);
      expect(metadata.has(namedNode('has'))).toBe(true);
      expect(metadata.has(undefined, literal('data'))).toBe(true);
      expect(metadata.has(namedNode('has'), literal('wrongData'))).toBe(false);
    });

    it('can get all values for a predicate.', async(): Promise<void> => {
      expect(metadata.getAll(namedNode('has'))).toEqualRdfTermArray(
        [ literal('data'), literal('moreData'), literal('data') ],
      );
    });

    it('can get all values for a predicate in a graph.', async(): Promise<void> => {
      expect(metadata.getAll(namedNode('has'), defaultGraph())).toEqualRdfTermArray(
        [ literal('data'), literal('moreData') ],
      );
    });

    it('can get the single value for a predicate.', async(): Promise<void> => {
      expect(metadata.get(namedNode('hasOne'))).toEqualRdfTerm(literal('otherData'));
    });

    it('returns undefined if getting an undefined predicate.', async(): Promise<void> => {
      expect(metadata.get(namedNode('doesntExist'))).toBeUndefined();
    });

    it('errors if there are multiple values when getting a value.', async(): Promise<void> => {
      expect((): any => metadata.get(namedNode('has'))).toThrow(Error);
    });

    it('can set the value of a predicate.', async(): Promise<void> => {
      metadata.set(namedNode('has'), literal('singleValue'));
      expect(metadata.get(namedNode('has'))).toEqualRdfTerm(literal('singleValue'));
    });

    it('can set multiple values of a predicate.', async(): Promise<void> => {
      metadata.set(namedNode('has'), [ literal('value1'), literal('value2') ]);
      expect(metadata.getAll(namedNode('has'))).toEqualRdfTermArray([ literal('value1'), literal('value2') ]);
    });

    it('has a shorthand for content-type.', async(): Promise<void> => {
      expect(metadata.contentType).toBeUndefined();
      metadata.contentType = 'a/b';
      expect(metadata.get(CONTENT_TYPE_TERM)).toEqualRdfTerm(literal('a/b'));
      expect(metadata.contentType).toBe('a/b');
      metadata.contentType = undefined;
      expect(metadata.contentType).toBeUndefined();
    });

    it('errors if a shorthand has multiple values.', async(): Promise<void> => {
      metadata.add(CONTENT_TYPE_TERM, 'a/b');
      metadata.add(CONTENT_TYPE_TERM, 'c/d');
      expect((): any => metadata.contentType).toThrow('Multiple results for http://www.w3.org/ns/ma-ont#format');
    });

    it('has a shorthand for Content-Type as string.', async(): Promise<void> => {
      expect(metadata.contentType).toBeUndefined();
      expect(metadata.contentTypeObject).toBeUndefined();
      metadata.contentType = 'text/plain';
      expect(metadata.contentTypeObject).toEqual({ value: 'text/plain', parameters: {}});
    });

    it('errors trying to set a Content-Type with parameters using a string.', async(): Promise<void> => {
      expect((): void => {
        metadata.contentType = 'text/plain; charset=utf-8; test=value1';
      }).toThrow(Error);
    });

    it('has a shorthand for Content-Type as object.', async(): Promise<void> => {
      expect(metadata.contentType).toBeUndefined();
      expect(metadata.contentTypeObject).toBeUndefined();
      metadata.contentTypeObject = new ContentType(
        'text/plain',
        {
          charset: 'utf-8',
          test: 'value1',
        },
      );
      expect(metadata.contentTypeObject).toEqual({
        value: 'text/plain',
        parameters: {
          charset: 'utf-8',
          test: 'value1',
        },
      });
      expect(metadata.contentType).toBe('text/plain');
    });

    it('can properly clear the Content-Type parameters explicitly.', async(): Promise<void> => {
      expect(metadata.contentType).toBeUndefined();
      expect(metadata.contentTypeObject).toBeUndefined();
      metadata.contentTypeObject = new ContentType('text/plain', {
        charset: 'utf-8',
        test: 'value1',
      });
      metadata.contentType = undefined;
      expect(metadata.contentType).toBeUndefined();
      expect(metadata.contentTypeObject).toBeUndefined();
      expect(metadata.quads(null, SOLID_META.terms.contentTypeParameter, null, null)).toHaveLength(0);
      expect(metadata.quads(null, SOLID_META.terms.value, null, null)).toHaveLength(0);
      expect(metadata.quads(null, RDFS.terms.label, null, null)).toHaveLength(0);
    });

    it('can properly clear the Content-Type parameters implicitly.', async(): Promise<void> => {
      expect(metadata.contentType).toBeUndefined();
      expect(metadata.contentTypeObject).toBeUndefined();
      metadata.contentTypeObject = new ContentType('text/plain', {
        charset: 'utf-8',
        test: 'value1',
      });
      metadata.contentType = 'text/turtle';
      expect(metadata.contentType).toBe('text/turtle');
      expect(metadata.contentTypeObject).toEqual({
        value: 'text/turtle',
        parameters: {},
      });
      expect(metadata.quads(null, SOLID_META.terms.contentTypeParameter, null, null)).toHaveLength(0);
      expect(metadata.quads(null, SOLID_META.terms.value, null, null)).toHaveLength(0);
      expect(metadata.quads(null, RDFS.terms.label, null, null)).toHaveLength(0);
    });

    it('can return invalid parameters when too many quads are present.', async(): Promise<void> => {
      expect(metadata.contentType).toBeUndefined();
      expect(metadata.contentTypeObject).toBeUndefined();
      metadata.contentTypeObject = new ContentType('text/plain', {
        charset: 'utf-8',
        test: 'value1',
      });
      const param = metadata.quads(null, SOLID_META.terms.value)[0].subject;
      metadata.addQuad(param as BlankNode, SOLID_META.terms.value, 'anomaly');
      expect(metadata.contentTypeObject?.parameters).toMatchObject({ invalid: '' });
    });
  });
});

import { EventEmitter } from 'node:events';
import type { WebSocket } from 'ws';
import { RepresentationMetadata } from '../../../src/http/representation/RepresentationMetadata';
import { UnsecureWebSocketsProtocol } from '../../../src/http/UnsecureWebSocketsProtocol';
import type { HttpRequest } from '../../../src/server/HttpRequest';
import { BaseActivityEmitter } from '../../../src/server/notifications/ActivityEmitter';
import type { Guarded } from '../../../src/util/GuardedStream';
import { AS } from '../../../src/util/Vocabularies';

jest.mock('ws', (): any => ({
  WebSocketServer: jest.fn().mockImplementation((): any => ({
    handleUpgrade(upgradeRequest: any, socket: any, head: any, callback: any): void {
      callback(socket, upgradeRequest);
    },
  })),
}));

class DummySocket extends EventEmitter {
  public readonly messages = new Array<string>();
  public readonly close = jest.fn();

  public send(message: string): void {
    this.messages.push(message);
  }
}

describe('An UnsecureWebSocketsProtocol', (): void => {
  let webSocket: WebSocket & DummySocket;
  const metadata = new RepresentationMetadata();
  const source = new BaseActivityEmitter();
  const baseUrl = 'http://example.com/';
  let protocol: UnsecureWebSocketsProtocol;

  it('can only handle requests targeting the base URl.', async(): Promise<void> => {
    protocol = new UnsecureWebSocketsProtocol(source, baseUrl);
    webSocket = new DummySocket() as any;
    await expect(protocol.canHandle({ webSocket, upgradeRequest: { url: '/' } as any })).resolves.toBeUndefined();
    await expect(protocol.canHandle({ webSocket, upgradeRequest: { url: '/foo' } as any }))
      .rejects.toThrow('Only WebSocket requests to / are supported.');
  });

  describe('after registering a socket', (): void => {
    beforeAll(async(): Promise<void> => {
      webSocket = new DummySocket() as any;
      protocol = new UnsecureWebSocketsProtocol(source, baseUrl);

      const upgradeRequest = {
        headers: {
          host: 'mypod.example',
          'sec-websocket-protocol': 'solid-0.1, other/1.0.0',
        },
        socket: {
          encrypted: true,
        },
      } as any as Guarded<HttpRequest>;
      await protocol.handle({ webSocket, upgradeRequest });
    });

    it('sends a protocol message.', (): void => {
      expect(webSocket.messages).toHaveLength(1);
      expect(webSocket.messages.shift()).toBe('protocol solid-0.1');
    });

    it('warns when receiving an unexpected message.', (): void => {
      webSocket.emit('message', 'unexpected');
      expect(webSocket.messages).toHaveLength(1);
      expect(webSocket.messages.shift()).toBe('warning Unrecognized message format: unexpected');
    });

    it('warns when receiving an unexpected message type.', (): void => {
      webSocket.emit('message', 'unknown 1 2 3');
      expect(webSocket.messages).toHaveLength(1);
      expect(webSocket.messages.shift()).toBe('warning Unrecognized message type: unknown');
    });

    describe('before subscribing to resources', (): void => {
      it('does not emit pub messages.', (): void => {
        source.emit('changed', { path: 'https://mypod.example/foo/bar' }, AS.terms.Update, metadata);
        expect(webSocket.messages).toHaveLength(0);
      });
    });

    describe('after subscribing to a resource', (): void => {
      beforeAll((): void => {
        webSocket.emit('message', 'sub https://mypod.example/foo/bar');
      });

      it('sends an ack message.', (): void => {
        expect(webSocket.messages).toHaveLength(1);
        expect(webSocket.messages.shift()).toBe('ack https://mypod.example/foo/bar');
      });

      it('emits pub messages for that resource.', (): void => {
        source.emit('changed', { path: 'https://mypod.example/foo/bar' }, AS.terms.Update, metadata);
        expect(webSocket.messages).toHaveLength(1);
        expect(webSocket.messages.shift()).toBe('pub https://mypod.example/foo/bar');
      });
    });

    describe('after subscribing to a resource via a relative URL', (): void => {
      beforeAll((): void => {
        webSocket.emit('message', 'sub /relative/foo');
      });

      it('sends an ack message.', (): void => {
        expect(webSocket.messages).toHaveLength(1);
        expect(webSocket.messages.shift()).toBe('ack https://mypod.example/relative/foo');
      });

      it('emits pub messages for that resource.', (): void => {
        source.emit('changed', { path: 'https://mypod.example/relative/foo' }, AS.terms.Update, metadata);
        expect(webSocket.messages).toHaveLength(1);
        expect(webSocket.messages.shift()).toBe('pub https://mypod.example/relative/foo');
      });
    });

    describe('after subscribing to a resource with the wrong host name', (): void => {
      beforeAll((): void => {
        webSocket.emit('message', 'sub https://wrong.example/host/foo');
      });

      it('send an error message.', (): void => {
        expect(webSocket.messages).toHaveLength(1);
        expect(webSocket.messages.shift())
          .toBe('error Mismatched host: expected mypod.example but got wrong.example');
      });
    });

    describe('after subscribing to a resource with the wrong protocol', (): void => {
      beforeAll((): void => {
        webSocket.emit('message', 'sub http://mypod.example/protocol/foo');
      });

      it('send an error message.', (): void => {
        expect(webSocket.messages).toHaveLength(1);
        expect(webSocket.messages.shift())
          .toBe('error Mismatched protocol: expected https: but got http:');
      });
    });
  });

  describe('handling other situations', (): void => {
    beforeEach(async(): Promise<void> => {
      webSocket = new DummySocket() as any;
      protocol = new UnsecureWebSocketsProtocol(source, baseUrl);
    });

    it('unsubscribes when a socket closes.', async(): Promise<void> => {
      await protocol.handle({ webSocket, upgradeRequest: { headers: {}, socket: {}} as any });
      expect(webSocket.listenerCount('message')).toBe(1);
      webSocket.emit('close');
      expect(webSocket.listenerCount('message')).toBe(0);
      expect(webSocket.listenerCount('close')).toBe(0);
      expect(webSocket.listenerCount('error')).toBe(0);
    });

    it('unsubscribes when a socket errors.', async(): Promise<void> => {
      await protocol.handle({ webSocket, upgradeRequest: { headers: {}, socket: {}} as any });
      expect(webSocket.listenerCount('message')).toBe(1);
      webSocket.emit('error');
      expect(webSocket.listenerCount('message')).toBe(0);
      expect(webSocket.listenerCount('close')).toBe(0);
      expect(webSocket.listenerCount('error')).toBe(0);
    });

    it('emits a warning when no Sec-WebSocket-Protocol is supplied.', async(): Promise<void> => {
      await protocol.handle({ webSocket, upgradeRequest: { headers: {}, socket: {}} as any });
      expect(webSocket.messages).toHaveLength(2);
      expect(webSocket.messages.pop())
        .toBe('warning Missing Sec-WebSocket-Protocol header, expected value \'solid-0.1\'');
      expect(webSocket.close).toHaveBeenCalledTimes(0);
    });

    it('emits an error and closes the connection with the wrong Sec-WebSocket-Protocol.', async(): Promise<void> => {
      const upgradeRequest = {
        headers: {
          'sec-websocket-protocol': 'solid/1.0.0, other',
        },
        socket: {},
      } as any as HttpRequest;
      await protocol.handle({ webSocket, upgradeRequest });
      expect(webSocket.messages).toHaveLength(2);
      expect(webSocket.messages.pop()).toBe('error Client does not support protocol solid-0.1');
      expect(webSocket.close).toHaveBeenCalledTimes(1);
      expect(webSocket.listenerCount('message')).toBe(0);
      expect(webSocket.listenerCount('close')).toBe(0);
      expect(webSocket.listenerCount('error')).toBe(0);
    });

    it('respects the Forwarded header.', async(): Promise<void> => {
      const upgradeRequest = {
        headers: {
          forwarded: 'proto=https;host=other.example',
          'sec-websocket-protocol': 'solid-0.1',
        },
        socket: {},
      } as any as HttpRequest;
      await protocol.handle({ webSocket, upgradeRequest });
      webSocket.emit('message', 'sub https://other.example/protocol/foo');
      expect(webSocket.messages).toHaveLength(2);
      expect(webSocket.messages.pop()).toBe('ack https://other.example/protocol/foo');
    });

    it('respects the X-Forwarded-* headers if Forwarded header is not present.', async(): Promise<void> => {
      const upgradeRequest = {
        headers: {
          'x-forwarded-host': 'other.example',
          'x-forwarded-proto': 'https',
          'sec-websocket-protocol': 'solid-0.1',
        },
        socket: {},
      } as any as HttpRequest;
      await protocol.handle({ webSocket, upgradeRequest });
      webSocket.emit('message', 'sub https://other.example/protocol/foo');
      expect(webSocket.messages).toHaveLength(2);
      expect(webSocket.messages.pop()).toBe('ack https://other.example/protocol/foo');
    });
  });
});

import { AccountInitializer } from '../../../src/identity/AccountInitializer';
import type { AccountStore } from '../../../src/identity/interaction/account/util/AccountStore';
import type { PasswordStore } from '../../../src/identity/interaction/password/util/PasswordStore';
import type { PodCreator } from '../../../src/identity/interaction/pod/util/PodCreator';

describe('An AccountInitializer', (): void => {
  const email = 'email@example.com';
  const password = 'password!';
  let accountStore: jest.Mocked<AccountStore>;
  let passwordStore: jest.Mocked<PasswordStore>;
  let podCreator: jest.Mocked<PodCreator>;
  let initializer: AccountInitializer;

  beforeEach(async(): Promise<void> => {
    accountStore = {
      create: jest.fn().mockResolvedValue('account-id'),
    } satisfies Partial<AccountStore> as any;

    passwordStore = {
      create: jest.fn().mockResolvedValue('password-id'),
      confirmVerification: jest.fn(),
    } satisfies Partial<PasswordStore> as any;

    podCreator = {
      handleSafe: jest.fn(),
    } satisfies Partial<PodCreator> as any;

    initializer = new AccountInitializer({
      accountStore,
      passwordStore,
      podCreator,
      email,
      password,
    });
  });

  it('creates the account/login/pod.', async(): Promise<void> => {
    await expect(initializer.handle()).resolves.toBeUndefined();
    expect(accountStore.create).toHaveBeenCalledTimes(1);
    expect(passwordStore.create).toHaveBeenCalledTimes(1);
    expect(passwordStore.create).toHaveBeenLastCalledWith(email, 'account-id', password);
    expect(passwordStore.confirmVerification).toHaveBeenCalledTimes(1);
    expect(podCreator.handleSafe).toHaveBeenCalledTimes(1);
    expect(podCreator.handleSafe).toHaveBeenLastCalledWith({ accountId: 'account-id' });
  });

  it('can create a pod with a name.', async(): Promise<void> => {
    initializer = new AccountInitializer({
      accountStore,
      passwordStore,
      podCreator,
      email,
      password,
      name: 'name',
    });
    await expect(initializer.handle()).resolves.toBeUndefined();
    expect(accountStore.create).toHaveBeenCalledTimes(1);
    expect(passwordStore.create).toHaveBeenCalledTimes(1);
    expect(passwordStore.create).toHaveBeenLastCalledWith(email, 'account-id', password);
    expect(passwordStore.confirmVerification).toHaveBeenCalledTimes(1);
    expect(podCreator.handleSafe).toHaveBeenCalledTimes(1);
    expect(podCreator.handleSafe).toHaveBeenLastCalledWith({ accountId: 'account-id', name: 'name' });
  });
});

import { interactionPolicy } from 'oidc-provider';
import type { KoaContextWithOIDC } from 'oidc-provider';
import { AccountPromptFactory } from '../../../../src/identity/configuration/AccountPromptFactory';
import type { CookieStore } from '../../../../src/identity/interaction/account/util/CookieStore';
import type { WebIdStore } from '../../../../src/identity/interaction/webid/util/WebIdStore';
import DefaultPolicy = interactionPolicy.DefaultPolicy;
import Prompt = interactionPolicy.Prompt;

describe('An AccountPromptFactory', (): void => {
  let ctx: KoaContextWithOIDC;
  let policy: jest.Mocked<DefaultPolicy>;
  const webId = 'http://example.com/card#me';
  const accountId = 'id';
  const name = 'name';
  let webIdStore: jest.Mocked<WebIdStore>;
  let cookieStore: jest.Mocked<CookieStore>;
  let factory: AccountPromptFactory;

  beforeEach(async(): Promise<void> => {
    policy = [] as any;
    // eslint-disable-next-line jest/prefer-spy-on
    policy.add = jest.fn();
    // eslint-disable-next-line jest/prefer-spy-on
    policy.get = jest.fn().mockReturnValue(new Prompt({ name: 'login' }));

    ctx = {
      cookies: {
        get: jest.fn().mockResolvedValue(undefined),
      },
      oidc: {
        internalAccountId: webId,
        session: {
          accountId: webId,
        },
      },
    } as any;

    webIdStore = {
      isLinked: jest.fn().mockResolvedValue(true),
    } satisfies Partial<WebIdStore> as any;

    cookieStore = {
      get: jest.fn().mockResolvedValue(accountId),
    } satisfies Partial<CookieStore> as any;

    factory = new AccountPromptFactory(webIdStore, cookieStore, name);
  });

  describe('account prompt', (): void => {
    it('generates a prompt that checks for the presence of the account cookie.', async(): Promise<void> => {
      await expect(factory.handle(policy)).resolves.toBeUndefined();
      expect(policy.add).toHaveBeenCalledTimes(1);
      expect(policy.add).toHaveBeenLastCalledWith(expect.any(Prompt), 0);
      const prompt = policy.add.mock.calls[0][0];
      // The first check is added automatically because the prompt is requestable
      expect(prompt.checks).toHaveLength(2);
      const check = prompt.checks[1];
      await expect(check.check(ctx)).resolves.toBe(false);
    });

    it('returns true if there is no cookie.', async(): Promise<void> => {
      jest.spyOn(ctx.cookies, 'get').mockImplementation();
      await expect(factory.handle(policy)).resolves.toBeUndefined();
      const prompt = policy.add.mock.calls[0][0];
      const check = prompt.checks[1];
      await expect(check.check(ctx)).resolves.toBe(true);
    });

    it('returns true if there is no matching account.', async(): Promise<void> => {
      cookieStore.get.mockResolvedValueOnce(undefined);
      jest.spyOn(ctx.cookies, 'get').mockImplementation();
      await expect(factory.handle(policy)).resolves.toBeUndefined();
      const prompt = policy.add.mock.calls[0][0];
      const check = prompt.checks[1];
      await expect(check.check(ctx)).resolves.toBe(true);
    });
  });

  describe('WebID verification check', (): void => {
    it('generates a check that checks if the active account owns the chosen WebID.', async(): Promise<void> => {
      await expect(factory.handle(policy)).resolves.toBeUndefined();
      expect(policy.get).toHaveBeenCalledTimes(1);
      expect(policy.get).toHaveBeenLastCalledWith('login');
      const prompt = policy.get.mock.results[0].value;
      const check = prompt.checks[0];
      await expect(check.check(ctx)).resolves.toBe(false);
    });

    it('triggers if the account does not own the WebID.', async(): Promise<void> => {
      webIdStore.isLinked.mockResolvedValueOnce(false);
      await expect(factory.handle(policy)).resolves.toBeUndefined();
      const prompt = policy.get.mock.results[0].value;
      const check = prompt.checks[0];
      await expect(check.check(ctx)).resolves.toBe(true);
    });

    it('does not trigger if there is no session with an accountId.', async(): Promise<void> => {
      delete (ctx.oidc as any).session;
      await expect(factory.handle(policy)).resolves.toBeUndefined();
      const prompt = policy.get.mock.results[0].value;
      const check = prompt.checks[0];
      await expect(check.check(ctx)).resolves.toBe(false);
    });

    it('does not trigger if there is no internal account ID in the context.', async(): Promise<void> => {
      delete (ctx.oidc as any).internalAccountId;
      await expect(factory.handle(policy)).resolves.toBeUndefined();
      const prompt = policy.get.mock.results[0].value;
      const check = prompt.checks[0];
      await expect(check.check(ctx)).resolves.toBe(false);
    });

    it('errors if the login prompt could not be found.', async(): Promise<void> => {
      policy.get.mockReturnValue(undefined);
      await expect(factory.handle(policy)).rejects.toThrow('Missing default login policy');
    });
  });
});

import { generateKeyPair, importJWK, jwtVerify, SignJWT } from 'jose';
import * as jose from 'jose';
import { CachedJwkGenerator } from '../../../../src/identity/configuration/CachedJwkGenerator';
import type { AlgJwk } from '../../../../src/identity/configuration/JwkGenerator';
import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import type { JWKS } from '../../../../templates/types/oidc-provider';

describe('A CachedJwkGenerator', (): void => {
  const alg = 'ES256';
  const storageKey = 'jwks';
  let storageMap: Map<string, AlgJwk>;
  let storage: jest.Mocked<KeyValueStorage<string, JWKS>>;
  let generator: CachedJwkGenerator;

  beforeEach(async(): Promise<void> => {
    storageMap = new Map();
    storage = {
      get: jest.fn(async(key: string): Promise<AlgJwk | undefined> => storageMap.get(key)),
      set: jest.fn(async(key: string, value: AlgJwk): Promise<any> => storageMap.set(key, value)),
    } as any;

    generator = new CachedJwkGenerator(alg, storageKey, storage);
  });

  it('generates a matching key set.', async(): Promise<void> => {
    const privateKey = await generator.getPrivateKey();
    expect(privateKey.alg).toBe(alg);

    const publicKey = await generator.getPublicKey();
    expect(publicKey.alg).toBe(alg);

    const privateObject = await importJWK(privateKey);
    const publicObject = await importJWK(publicKey);

    const signed = await new SignJWT({ data: 'signed data' }).setProtectedHeader({ alg }).sign(privateObject);
    await expect(jwtVerify(signed, publicObject)).resolves.toMatchObject({
      payload: {
        data: 'signed data',
      },
    });

    const otherKey = (await generateKeyPair(alg)).publicKey;
    await expect(jwtVerify(signed, otherKey)).rejects.toThrow('signature verification failed');
  });

  it('caches the private key in memory.', async(): Promise<void> => {
    const spy = jest.spyOn(jose, 'generateKeyPair');
    const privateKey = await generator.getPrivateKey();
    // 1 call from checking the storage
    expect(storage.get).toHaveBeenCalledTimes(1);
    expect(spy).toHaveBeenCalledTimes(1);

    const privateKey2 = await generator.getPrivateKey();
    expect(privateKey).toBe(privateKey2);
    expect(spy).toHaveBeenCalledTimes(1);
    expect(storage.get).toHaveBeenCalledTimes(1);
    spy.mockRestore();
  });

  it('caches the public key in memory.', async(): Promise<void> => {
    const spy = jest.spyOn(jose, 'generateKeyPair');
    const publicKey = await generator.getPublicKey();
    // 1 call from checking the storage
    expect(storage.get).toHaveBeenCalledTimes(1);
    expect(spy).toHaveBeenCalledTimes(1);

    const publicKey2 = await generator.getPublicKey();
    expect(publicKey).toBe(publicKey2);
    expect(spy).toHaveBeenCalledTimes(1);
    expect(storage.get).toHaveBeenCalledTimes(1);
    spy.mockRestore();
  });

  it('caches the key in storage in case of server restart.', async(): Promise<void> => {
    const spy = jest.spyOn(jose, 'generateKeyPair');
    const privateKey = await generator.getPrivateKey();
    // 1 call from checking the storage
    expect(storage.get).toHaveBeenCalledTimes(1);
    expect(spy).toHaveBeenCalledTimes(1);

    const generator2 = new CachedJwkGenerator(alg, storageKey, storage);

    const privateKey2 = await generator2.getPrivateKey();
    expect(privateKey).toBe(privateKey2);
    expect(spy).toHaveBeenCalledTimes(1);
    expect(storage.get).toHaveBeenCalledTimes(2);
    spy.mockRestore();
  });
});

import { Readable } from 'node:stream';
import { exportJWK, generateKeyPair } from 'jose';
import type { ErrorHandler } from '../../../../src/http/output/error/ErrorHandler';
import type { ResponseWriter } from '../../../../src/http/output/ResponseWriter';
import { IdentityProviderFactory } from '../../../../src/identity/configuration/IdentityProviderFactory';
import type { JwkGenerator } from '../../../../src/identity/configuration/JwkGenerator';
import type { PromptFactory } from '../../../../src/identity/configuration/PromptFactory';
import type {
  ClientCredentialsStore,
} from '../../../../src/identity/interaction/client-credentials/util/ClientCredentialsStore';
import type { Interaction } from '../../../../src/identity/interaction/InteractionHandler';
import type { InteractionRoute } from '../../../../src/identity/interaction/routing/InteractionRoute';
import type { AdapterFactory } from '../../../../src/identity/storage/AdapterFactory';
import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import { extractErrorTerms } from '../../../../src/util/errors/HttpErrorUtil';
import { OAuthHttpError } from '../../../../src/util/errors/OAuthHttpError';
import type { Configuration, errors, KoaContextWithOIDC } from '../../../../templates/types/oidc-provider';

jest.mock('oidc-provider', (): any => {
  const fn = jest.fn((issuer: string, config: Configuration): any => ({ issuer, config, use: jest.fn() }));
  // The base export is the Provider class, but we also need some of the deeper exports like interactionPolicy
  (fn as any).interactionPolicy = jest.requireActual('oidc-provider').interactionPolicy;
  return fn;
});

const routes = {
  authorization: '/foo/oidc/auth',
  backchannel_authentication: '/foo/oidc/backchannel',
  code_verification: '/foo/oidc/device',
  device_authorization: '/foo/oidc/device/auth',
  end_session: '/foo/oidc/session/end',
  introspection: '/foo/oidc/token/introspection',
  jwks: '/foo/oidc/jwks',
  pushed_authorization_request: '/foo/oidc/request',
  registration: '/foo/oidc/reg',
  revocation: '/foo/oidc/token/revocation',
  token: '/foo/oidc/token',
  userinfo: '/foo/oidc/me',
};

describe('An IdentityProviderFactory', (): void => {
  let jestWorkerId: string | undefined;
  let nodeEnv: string | undefined;
  let baseConfig: Configuration;
  const baseUrl = 'http://example.com/foo/';
  const oidcPath = '/oidc';
  const webId = 'http://alice.example.com/card#me';
  let oidcInteraction: Interaction;
  let interactionRoute: InteractionRoute;
  let ctx: KoaContextWithOIDC;
  let promptFactory: jest.Mocked<PromptFactory>;
  let adapterFactory: jest.Mocked<AdapterFactory>;
  let storage: jest.Mocked<KeyValueStorage<string, any>>;
  let jwkGenerator: jest.Mocked<JwkGenerator>;
  let clientCredentialsStore: jest.Mocked<ClientCredentialsStore>;
  let errorHandler: jest.Mocked<ErrorHandler>;
  let responseWriter: jest.Mocked<ResponseWriter>;
  let factory: IdentityProviderFactory;

  beforeAll(async(): Promise<void> => {
    // We need to fool the IDP factory into thinking we are not in a test run,
    // otherwise we can't mock the oidc-provider library,
    // as the `importOidcProvider` utility function always calls `jest.requireActual`.
    jestWorkerId = process.env.JEST_WORKER_ID;
    nodeEnv = process.env.NODE_ENV;
    delete process.env.JEST_WORKER_ID;
    delete process.env.NODE_ENV;
  });

  beforeEach(async(): Promise<void> => {
    // Disabling devInteractions to prevent warnings when testing the path
    // where we use the actual library instead of a mock.
    baseConfig = { claims: { webid: [ 'webid', 'client_webid' ]}, features: { devInteractions: { enabled: false }}};

    oidcInteraction = { prompt: { name: 'account' }} as any;

    interactionRoute = {
      getPath: jest.fn().mockReturnValue('http://example.com/interaction/'),
    } as any;

    ctx = {
      method: 'GET',
      req: Readable.from('data'),
      res: {},
      request: {
        href: 'http://example.com/idp/',
        query: {
          client_id: 'CLIENT_ID',
          redirect_uri: 'REDIRECT_URI',
        },
      },
      accepts: jest.fn().mockReturnValue('type'),
    } as any;

    promptFactory = {
      handleSafe: jest.fn(),
    } satisfies Partial<PromptFactory> as any;

    adapterFactory = {
      createStorageAdapter: jest.fn().mockReturnValue('adapter!'),
    };

    const map = new Map();
    storage = {
      get: jest.fn((id: string): any => map.get(id)),
      set: jest.fn((id: string, value: any): any => map.set(id, value)),
    } satisfies Partial<KeyValueStorage<string, any>> as any;

    const { privateKey, publicKey } = await generateKeyPair('ES256');
    jwkGenerator = {
      alg: 'ES256',
      getPrivateKey: jest.fn().mockResolvedValue({ ...await exportJWK(privateKey), alg: 'ES256' }),
      getPublicKey: jest.fn().mockResolvedValue({ ...await exportJWK(publicKey), alg: 'ES256' }),
    };

    clientCredentialsStore = {
      findByLabel: jest.fn(),
    } satisfies Partial<ClientCredentialsStore> as any;

    errorHandler = {
      handleSafe: jest.fn().mockResolvedValue({ statusCode: 500 }),
    } satisfies Partial<ErrorHandler> as any;

    responseWriter = { handleSafe: jest.fn() } satisfies Partial<ResponseWriter> as any;

    factory = new IdentityProviderFactory(baseConfig, {
      promptFactory,
      adapterFactory,
      baseUrl,
      oidcPath,
      interactionRoute,
      storage,
      jwkGenerator,
      clientCredentialsStore,
      showStackTrace: true,
      errorHandler,
      responseWriter,
    });
  });

  afterAll(async(): Promise<void> => {
    process.env.JEST_WORKER_ID = jestWorkerId;
    process.env.NODE_ENV = nodeEnv;
  });

  it('creates a correct configuration.', async(): Promise<void> => {
    // This is the output of our mock function
    const provider = await factory.getProvider() as any;
    expect(provider.proxy).toBe(true);
    const { issuer, config } = provider as { issuer: string; config: Configuration };
    expect(issuer).toBe(baseUrl);

    // Copies the base config
    expect(config.claims).toEqual(baseConfig.claims);

    (config.adapter as (name: string) => any)('test!');
    expect(adapterFactory.createStorageAdapter).toHaveBeenCalledTimes(1);
    expect(adapterFactory.createStorageAdapter).toHaveBeenLastCalledWith('test!');

    expect(config.cookies?.keys).toEqual([ expect.any(String) ]);
    expect(config.jwks).toEqual({ keys: [ expect.objectContaining({ alg: 'ES256' }) ]});
    expect(config.routes).toEqual(routes);
    expect(config.pkce?.methods).toEqual([ 'S256' ]);
    expect((config.pkce!.required as any)()).toBe(true);
    expect(config.clientDefaults?.id_token_signed_response_alg).toBe('ES256');

    await expect((config.interactions?.url as any)(ctx, oidcInteraction)).resolves.toBe(interactionRoute.getPath());

    let findResult = await config.findAccount?.({ oidc: { client: { clientId: 'clientId' }}} as any, webId);
    expect(findResult?.accountId).toBe(webId);
    await expect((findResult?.claims as any)()).resolves.toEqual({ sub: webId, webid: webId, azp: 'clientId' });
    findResult = await config.findAccount?.({ oidc: {}} as any, webId);
    await expect((findResult?.claims as any)()).resolves.toEqual({ sub: webId, webid: webId });

    await expect((config.extraTokenClaims as any)({}, {}))
      .rejects.toThrow('Missing client ID from client credentials.');
    const client = { clientId: 'my_id', kind: 'ClientCredentials' };
    await expect((config.extraTokenClaims as any)({}, { client }))
      .rejects.toThrow(`Unknown client credentials token my_id`);
    clientCredentialsStore.findByLabel.mockResolvedValueOnce({ id: 'id', label: 'label', accountId: 'id', webId: 'http://example.com/foo', secret: 'my-secret' });
    await expect((config.extraTokenClaims as any)({}, { client }))
      .resolves.toEqual({ webid: 'http://example.com/foo' });
    await expect((config.extraTokenClaims as any)({}, { kind: 'AccessToken', accountId: webId, clientId: 'clientId' }))
      .resolves.toEqual({ webid: webId });

    expect(config.features?.resourceIndicators?.enabled).toBe(true);
    expect((config.features?.resourceIndicators?.defaultResource as any)()).toBe('http://example.com/');
    expect((config.features?.resourceIndicators?.getResourceServerInfo as any)()).toEqual({
      scope: '',
      audience: 'solid',
      accessTokenFormat: 'jwt',
      jwt: { sign: { alg: 'ES256' }},
    });

    // Test the renderError function
    const error = new Error('error!');
    await expect((config.renderError as any)(ctx, {}, error)).resolves.toBeUndefined();
    expect(errorHandler.handleSafe).toHaveBeenCalledTimes(1);
    expect(errorHandler.handleSafe)
      .toHaveBeenLastCalledWith({ error, request: ctx.req });
    expect(responseWriter.handleSafe).toHaveBeenCalledTimes(1);
    expect(responseWriter.handleSafe).toHaveBeenLastCalledWith({ response: ctx.res, result: { statusCode: 500 }});

    // Test that the Prompt was added
    expect(promptFactory.handleSafe).toHaveBeenCalledTimes(1);
  });

  it('copies a field from the input config if values need to be added to it.', async(): Promise<void> => {
    baseConfig.cookies = {
      long: { signed: true },
    };
    factory = new IdentityProviderFactory(baseConfig, {
      promptFactory,
      adapterFactory,
      baseUrl,
      oidcPath,
      interactionRoute,
      storage,
      jwkGenerator,
      clientCredentialsStore,
      showStackTrace: true,
      errorHandler,
      responseWriter,
    });
    const { config } = await factory.getProvider() as unknown as { issuer: string; config: Configuration };
    expect(config.cookies?.long?.signed).toBe(true);
  });

  it('caches the provider.', async(): Promise<void> => {
    const result1 = await factory.getProvider() as unknown as { issuer: string; config: Configuration };
    const result2 = await factory.getProvider() as unknown as { issuer: string; config: Configuration };
    expect(result1).toBe(result2);
  });

  it('uses cached keys in case they already exist.', async(): Promise<void> => {
    const result1 = await factory.getProvider() as unknown as { issuer: string; config: Configuration };
    // Create a new factory that is not cached yet
    const factory2 = new IdentityProviderFactory(baseConfig, {
      promptFactory,
      adapterFactory,
      baseUrl,
      oidcPath,
      interactionRoute,
      storage,
      jwkGenerator,
      clientCredentialsStore,
      showStackTrace: true,
      errorHandler,
      responseWriter,
    });
    const result2 = await factory2.getProvider() as unknown as { issuer: string; config: Configuration };
    expect(result1.config.cookies).toEqual(result2.config.cookies);
    expect(storage.get).toHaveBeenCalledTimes(2);
    expect(storage.set).toHaveBeenCalledTimes(1);
    expect(storage.set).toHaveBeenCalledWith('cookie-secret', result1.config.cookies?.keys);
  });

  it('updates errors if there is more information.', async(): Promise<void> => {
    const provider = await factory.getProvider() as any;
    const { config } = provider as { config: Configuration };

    const error = new Error('bad data') as errors.OIDCProviderError;
    error.error_description = 'more info';
    error.error_detail = 'more details';

    const oAuthError = new OAuthHttpError(error, error.name, 500, 'bad data - more info - more details');

    await expect((config.renderError as any)(ctx, {}, error)).resolves.toBeUndefined();
    expect(errorHandler.handleSafe).toHaveBeenCalledTimes(1);
    expect(errorHandler.handleSafe)
      .toHaveBeenLastCalledWith({ error: oAuthError, request: ctx.req });
    expect(responseWriter.handleSafe).toHaveBeenCalledTimes(1);
    expect(responseWriter.handleSafe).toHaveBeenLastCalledWith({ response: ctx.res, result: { statusCode: 500 }});
    expect(oAuthError.message).toBe('bad data - more info - more details');
    expect(oAuthError.stack).toContain('Error: bad data - more info - more details');
  });

  it('throws a specific error for unknown clients.', async(): Promise<void> => {
    const provider = await factory.getProvider() as any;
    const { config } = provider as { config: Configuration };

    const error = new Error('invalid_client') as errors.OIDCProviderError;
    error.error_description = 'client is invalid';
    error.error_detail = 'client not found';

    await expect((config.renderError as any)(ctx, {}, error)).resolves.toBeUndefined();
    expect(errorHandler.handleSafe).toHaveBeenCalledTimes(1);
    expect(errorHandler.handleSafe)
      .toHaveBeenLastCalledWith({
        error: expect.objectContaining({
          statusCode: 400,
          name: 'BadRequestHttpError',
          message: 'Unknown client, you might need to clear the local storage on the client.',
          errorCode: 'E0003',
        }),
        request: ctx.req,
      });
    expect(extractErrorTerms(errorHandler.handleSafe.mock.calls[0][0].error.metadata)).toEqual({
      client_id: 'CLIENT_ID',
      redirect_uri: 'REDIRECT_URI',
    });
    expect(responseWriter.handleSafe).toHaveBeenCalledTimes(1);
    expect(responseWriter.handleSafe).toHaveBeenLastCalledWith({ response: ctx.res, result: { statusCode: 500 }});
  });

  it('adds middleware to make the OIDC provider think the request wants HTML.', async(): Promise<void> => {
    const provider = await factory.getProvider();
    expect(provider.use).toHaveBeenCalledTimes(1);
    const middleware = jest.mocked(provider.use).mock.calls[0][0];

    // eslint-disable-next-line jest/unbound-method
    const oldAccept = ctx.accepts;
    const next = jest.fn();
    await expect(middleware(ctx, next)).resolves.toBeUndefined();
    expect(next).toHaveBeenCalledTimes(1);

    expect(ctx.accepts('json', 'html')).toBe('html');
    expect(oldAccept).toHaveBeenCalledTimes(0);
  });

  it('does not modify the context accepts function in other cases.', async(): Promise<void> => {
    const provider = await factory.getProvider();
    expect(provider.use).toHaveBeenCalledTimes(1);
    const middleware = jest.mocked(provider.use).mock.calls[0][0];

    // eslint-disable-next-line jest/unbound-method
    const oldAccept = ctx.accepts;
    const next = jest.fn();
    await expect(middleware(ctx, next)).resolves.toBeUndefined();
    expect(next).toHaveBeenCalledTimes(1);

    expect(ctx.accepts('something')).toBe('type');
    expect(oldAccept).toHaveBeenCalledTimes(1);
    expect(oldAccept).toHaveBeenLastCalledWith('something');
  });

  it('avoids dynamic imports when testing with Jest.', async(): Promise<void> => {
    // Reset the env variable, so we can test the path where the dynamic import is not used
    process.env.JEST_WORKER_ID = jestWorkerId;
    const provider = await factory.getProvider() as any;
    // We don't define this in our mock
    expect(provider.app).toBeDefined();
  });
});

import type { Operation } from '../../../src/http/Operation';
import { BasicRepresentation } from '../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../src/http/representation/Representation';
import type { ProviderFactory } from '../../../src/identity/configuration/ProviderFactory';
import type { IdentityProviderHttpHandlerArgs } from '../../../src/identity/IdentityProviderHttpHandler';
import { IdentityProviderHttpHandler } from '../../../src/identity/IdentityProviderHttpHandler';
import type { CookieStore } from '../../../src/identity/interaction/account/util/CookieStore';
import type { Interaction, InteractionHandler } from '../../../src/identity/interaction/InteractionHandler';
import type { HttpRequest } from '../../../src/server/HttpRequest';
import type { HttpResponse } from '../../../src/server/HttpResponse';
import { SOLID_HTTP } from '../../../src/util/Vocabularies';
import type Provider from '../../../templates/types/oidc-provider';

describe('An IdentityProviderHttpHandler', (): void => {
  const cookie = 'cookie';
  const accountId = 'accountId';
  const request: HttpRequest = {} as any;
  const response: HttpResponse = {} as any;
  const oidcInteraction: Interaction = {} as any;
  let operation: Operation;
  let representation: Representation;
  let providerFactory: jest.Mocked<ProviderFactory>;
  let provider: jest.Mocked<Provider>;
  let cookieStore: jest.Mocked<CookieStore>;
  let handler: jest.Mocked<InteractionHandler>;
  let idpHandler: IdentityProviderHttpHandler;

  beforeEach(async(): Promise<void> => {
    operation = {
      method: 'GET',
      target: { path: 'http://test.com/idp' },
      preferences: { type: { 'text/html': 1 }},
      body: new BasicRepresentation(),
    };
    operation.body.metadata.set(SOLID_HTTP.terms.accountCookie, cookie);

    provider = {
      interactionDetails: jest.fn().mockReturnValue(oidcInteraction),
    } as any;

    providerFactory = {
      getProvider: jest.fn().mockResolvedValue(provider),
    };

    cookieStore = {
      generate: jest.fn(),
      get: jest.fn().mockResolvedValue(accountId),
      delete: jest.fn(),
      refresh: jest.fn(),
    };

    representation = new BasicRepresentation();
    handler = {
      handleSafe: jest.fn().mockResolvedValue(representation),
    } as any;

    const args: IdentityProviderHttpHandlerArgs = {
      providerFactory,
      cookieStore,
      handler,
    };
    idpHandler = new IdentityProviderHttpHandler(args);
  });

  it('returns the handler result as 200 response.', async(): Promise<void> => {
    const result = await idpHandler.handle({ operation, request, response });
    expect(result.statusCode).toBe(200);
    expect(result.data).toBe(representation.data);
    expect(result.metadata).toBe(representation.metadata);
    expect(provider.interactionDetails).toHaveBeenCalledTimes(1);
    expect(provider.interactionDetails).toHaveBeenLastCalledWith(request, response);
    expect(cookieStore.get).toHaveBeenCalledTimes(1);
    expect(cookieStore.get).toHaveBeenLastCalledWith(cookie);
    expect(handler.handleSafe).toHaveBeenCalledTimes(1);
    expect(handler.handleSafe).toHaveBeenLastCalledWith({ operation, oidcInteraction, accountId });
  });

  it('passes no interaction if the provider call failed.', async(): Promise<void> => {
    provider.interactionDetails.mockRejectedValueOnce(new Error('no interaction'));
    const result = await idpHandler.handle({ operation, request, response });
    expect(result.statusCode).toBe(200);
    expect(result.data).toBe(representation.data);
    expect(result.metadata).toBe(representation.metadata);
    expect(provider.interactionDetails).toHaveBeenCalledTimes(1);
    expect(provider.interactionDetails).toHaveBeenLastCalledWith(request, response);
    expect(cookieStore.get).toHaveBeenCalledTimes(1);
    expect(cookieStore.get).toHaveBeenLastCalledWith(cookie);
    expect(handler.handleSafe).toHaveBeenCalledTimes(1);
    expect(handler.handleSafe).toHaveBeenLastCalledWith({ operation, accountId });
  });

  it('passes no accountID if there is no cookie.', async(): Promise<void> => {
    operation.body.metadata.removeAll(SOLID_HTTP.terms.accountCookie);
    const result = await idpHandler.handle({ operation, request, response });
    expect(result.statusCode).toBe(200);
    expect(result.data).toBe(representation.data);
    expect(result.metadata).toBe(representation.metadata);
    expect(provider.interactionDetails).toHaveBeenCalledTimes(1);
    expect(provider.interactionDetails).toHaveBeenLastCalledWith(request, response);
    expect(cookieStore.get).toHaveBeenCalledTimes(0);
    expect(handler.handleSafe).toHaveBeenCalledTimes(1);
    expect(handler.handleSafe).toHaveBeenLastCalledWith({ operation, oidcInteraction });
  });
});

