import { boolean, number, object, string } from 'yup';
import { parseSchema, URL_SCHEMA, validateWithError } from '../../../../src/identity/interaction/YupUtil';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';

describe('YupUtil', (): void => {
  describe('#URL_SCHEMA', (): void => {
    it('validates URLs.', async(): Promise<void> => {
      await expect(URL_SCHEMA.isValid('https://example.com/foo')).resolves.toBe(true);
      await expect(URL_SCHEMA.isValid('http://localhost:3000/foo')).resolves.toBe(true);
      await expect(URL_SCHEMA.isValid('apple')).resolves.toBe(false);
      await expect(URL_SCHEMA.isValid('mail@example.com')).resolves.toBe(false);
      await expect(URL_SCHEMA.isValid('')).resolves.toBe(true);
      await expect(URL_SCHEMA.isValid(null)).resolves.toBe(false);
    });
  });

  describe('#parseSchema', (): void => {
    it('creates representations for yup schemas.', async(): Promise<void> => {
      const schema = object({
        optStr: string(),
        reqStr: string().required(),
        numb: number(),
        bool: boolean(),
        obj: object({
          key: string().required(),
          obj2: object({
            nested: number(),
          }),
        }).required(),
      });
      expect(parseSchema(schema)).toEqual({ fields: {
        optStr: { type: 'string', required: false },
        reqStr: { type: 'string', required: true },
        numb: { type: 'number', required: false },
        bool: { type: 'boolean', required: false },
        obj: {
          type: 'object',
          required: true,
          fields: {
            key: { type: 'string', required: true },
            obj2: {
              type: 'object',
              required: false,
              fields: {
                nested: { type: 'number', required: false },
              },
            },
          },
        },
      }});
    });
  });

  describe('#validateWithError', (): void => {
    it('throws a BadRequestHttpError if there is an error.', async(): Promise<void> => {
      const schema = object({});
      await expect(validateWithError(schema, { test: 'data' })).resolves.toEqual({ test: 'data' });
      await expect(validateWithError(schema, 'test')).rejects.toThrow(BadRequestHttpError);
    });
  });
});

import type { ProviderFactory } from '../../../src/identity/configuration/ProviderFactory';
import { OidcHttpHandler } from '../../../src/identity/OidcHttpHandler';
import type { HttpRequest } from '../../../src/server/HttpRequest';
import type { HttpResponse } from '../../../src/server/HttpResponse';
import type Provider from '../../../templates/types/oidc-provider';

describe('An OidcHttpHandler', (): void => {
  const request: HttpRequest = {
    url: '/.well-known/openid-configuration',
  } as any;
  const response: HttpResponse = {} as any;
  let provider: jest.Mocked<Provider>;
  let providerFactory: jest.Mocked<ProviderFactory>;
  let handler: OidcHttpHandler;

  beforeEach(async(): Promise<void> => {
    provider = {
      callback: jest.fn().mockReturnValue(jest.fn()),
      issuer: 'http://localhost:3000/',
    } as any;

    providerFactory = {
      getProvider: jest.fn().mockResolvedValue(provider),
    } as any;

    handler = new OidcHttpHandler(providerFactory);
  });

  it('sends all requests to the OIDC library.', async(): Promise<void> => {
    await expect(handler.handle({ request, response })).resolves.toBeUndefined();
    expect(provider.callback).toHaveBeenCalledTimes(1);
    expect(provider.callback.mock.results[0].value).toHaveBeenCalledTimes(1);
    expect(provider.callback.mock.results[0].value).toHaveBeenLastCalledWith(request, response);
  });

  it('rewrites the request when using base URL with root path.', async(): Promise<void> => {
    Object.assign(provider, { issuer: 'http://localhost:3000/path/' });
    request.url = '/path/.well-known/openid-configuration';
    await expect(handler.handle({ request, response })).resolves.toBeUndefined();
    expect(request.url).toBe('/.well-known/openid-configuration');
    expect(provider.callback).toHaveBeenCalledTimes(1);
    expect(provider.callback.mock.results[0].value).toHaveBeenCalledTimes(1);
    expect(provider.callback.mock.results[0].value).toHaveBeenLastCalledWith(request, response);
  });

  it('respects query parameters when rewriting requests.', async(): Promise<void> => {
    Object.assign(provider, { issuer: 'http://localhost:3000/path/' });
    request.url = '/path/.well-known/openid-configuration?param1=value1';
    await expect(handler.handle({ request, response })).resolves.toBeUndefined();
    expect(request.url).toBe('/.well-known/openid-configuration?param1=value1');
    expect(provider.callback).toHaveBeenCalledTimes(1);
    expect(provider.callback.mock.results[0].value).toHaveBeenCalledTimes(1);
    expect(provider.callback.mock.results[0].value).toHaveBeenLastCalledWith(request, response);
  });
});

import { NoCheckOwnershipValidator } from '../../../../src/identity/ownership/NoCheckOwnershipValidator';

describe('A NoCheckOwnershipValidator', (): void => {
  const validator = new NoCheckOwnershipValidator();

