import { Readable } from 'node:stream';
import { DataFactory } from 'n3';
import type { Quad } from 'n3';
import rdfDereferencer from 'rdf-dereference';
import { v4 } from 'uuid';
import { TokenOwnershipValidator } from '../../../../src/identity/ownership/TokenOwnershipValidator';
import type { ExpiringStorage } from '../../../../src/storage/keyvalue/ExpiringStorage';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { extractErrorTerms } from '../../../../src/util/errors/HttpErrorUtil';
import { SOLID } from '../../../../src/util/Vocabularies';

const { literal, namedNode, quad } = DataFactory;

jest.mock('uuid');
jest.mock('rdf-dereference', (): any => ({
  dereference: jest.fn(),
}));

function quadToString(qq: Quad): string {
  const subPred = `<${qq.subject.value}> <${qq.predicate.value}>`;
  if (qq.object.termType === 'Literal') {
    return `${subPred} "${qq.object.value}"`;
  }
  return `${subPred} <${qq.object.value}>`;
}

describe('A TokenOwnershipValidator', (): void => {
  const rdfDereferenceMock: jest.Mocked<typeof rdfDereferencer> = rdfDereferencer as any;
  const webId = 'http://alice.test.com/#me';
  const token = 'randomlyGeneratedToken';
  const tokenTriple = quad(namedNode(webId), SOLID.terms.oidcIssuerRegistrationToken, literal(token));
  const tokenString = `${quadToString(tokenTriple)}.`;
  let storage: ExpiringStorage<string, string>;
  let validator: TokenOwnershipValidator;

  function mockDereference(qq?: Quad): any {
    rdfDereferenceMock.dereference.mockImplementation((uri: string): any => ({
      uri,
      data: Readable.from(qq ? [ qq ] : []),
    }));
  }

  beforeEach(async(): Promise<void> => {
    const now = Date.now();
    jest.spyOn(Date, 'now').mockReturnValue(now);
    jest.mocked(v4).mockReturnValue(token);

    const map = new Map<string, any>();
    storage = {
      get: jest.fn().mockImplementation((key: string): any => map.get(key)),
      set: jest.fn().mockImplementation((key: string, value: any): any => map.set(key, value)),
      delete: jest.fn().mockImplementation((key: string): any => map.delete(key)),
    } as any;

    mockDereference();

    validator = new TokenOwnershipValidator(storage);
  });

  it('errors if no token is stored in the storage.', async(): Promise<void> => {
    // Even if the token is in the WebId, it will error since it's not in the storage
    mockDereference(tokenTriple);
    let error: unknown;
    try {
      await validator.handle({ webId });
    } catch (err: unknown) {
      error = err;
    }
    expect(error).toEqual(expect.objectContaining({ message: expect.stringContaining(tokenString) }));
    expect(BadRequestHttpError.isInstance(error)).toBe(true);
    expect(extractErrorTerms((error as BadRequestHttpError).metadata))
      .toEqual({ quad: tokenString });
    expect(rdfDereferenceMock.dereference).toHaveBeenCalledTimes(0);
  });

  it('errors if the expected triple is missing.', async(): Promise<void> => {
    // First call will add the token to the storage
    await expect(validator.handle({ webId })).rejects.toThrow(tokenString);
    expect(rdfDereferenceMock.dereference).toHaveBeenCalledTimes(0);
    // Second call will fetch the WebId
    await expect(validator.handle({ webId })).rejects.toThrow(tokenString);
    expect(rdfDereferenceMock.dereference).toHaveBeenCalledTimes(1);
  });

  it('resolves if the WebId contains the verification triple.', async(): Promise<void> => {
    mockDereference(tokenTriple);
    // First call will add the token to the storage
    await expect(validator.handle({ webId })).rejects.toThrow(tokenString);
    // Second call will succeed since it has the verification triple
    await expect(validator.handle({ webId })).resolves.toBeUndefined();
  });

  it('fails if the WebId contains the wrong verification triple.', async(): Promise<void> => {
    const wrongQuad = quad(namedNode(webId), SOLID.terms.oidcIssuerRegistrationToken, literal('wrongToken'));
    mockDereference(wrongQuad);
    // First call will add the token to the storage
    await expect(validator.handle({ webId })).rejects.toThrow(tokenString);
    // Second call will fail since it has the wrong verification triple
    await expect(validator.handle({ webId })).rejects.toThrow(tokenString);
  });
});

import fetch from 'cross-fetch';
import type { AdapterFactory } from '../../../../src/identity/storage/AdapterFactory';
import { ClientIdAdapterFactory } from '../../../../src/identity/storage/ClientIdAdapterFactory';
import { RdfToQuadConverter } from '../../../../src/storage/conversion/RdfToQuadConverter';
import type { Adapter } from '../../../../templates/types/oidc-provider';

jest.mock('cross-fetch');

describe('A ClientIdAdapterFactory', (): void => {
  const fetchMock: jest.Mock = fetch as any;
  const id = 'https://app.example.com/card#me';
  let json: any;
  let rdf: string;
  let source: jest.Mocked<Adapter>;
  let sourceFactory: AdapterFactory;
  let adapter: Adapter;
  const converter = new RdfToQuadConverter();
  let factory: ClientIdAdapterFactory;

  beforeEach(async(): Promise<void> => {
    json = {
      '@context': 'https://www.w3.org/ns/solid/oidc-context.jsonld',

      client_id: id,
      client_name: 'Solid Application Name',
      redirect_uris: [ 'http://example.com/' ],
      scope: 'openid profile offline_access',
      grant_types: [ 'refresh_token', 'authorization_code' ],
      response_types: [ 'code' ],
      default_max_age: 3600,
      require_auth_time: true,
    };
    rdf = `<${id}> <http://www.w3.org/ns/solid/oidc#redirect_uris> <http://example.com>.`;

    fetchMock.mockImplementation((url: string): any => ({ text: (): any => '', url, status: 200 }));

    source = {
      upsert: jest.fn(),
      find: jest.fn(),
      findByUserCode: jest.fn(),
      findByUid: jest.fn(),
      destroy: jest.fn(),
      revokeByGrantId: jest.fn(),
      consume: jest.fn(),
    };

    sourceFactory = {
      createStorageAdapter: jest.fn().mockReturnValue(source),
    };

    factory = new ClientIdAdapterFactory(sourceFactory, converter);
    adapter = factory.createStorageAdapter('Client');
  });

  it('returns the source payload if there is one.', async(): Promise<void> => {
    source.find.mockResolvedValueOnce('payload!' as any);
    await expect(adapter.find(id)).resolves.toBe('payload!');
  });

  it('returns undefined if this is not a Client Adapter and there is no source payload.', async(): Promise<void> => {
    adapter = factory.createStorageAdapter('NotClient');
    await expect(adapter.find(id)).resolves.toBeUndefined();
  });

  it('returns undefined if the client ID is not a URL.', async(): Promise<void> => {
    await expect(adapter.find('noUrl')).resolves.toBeUndefined();
  });

  it('errors if the client ID is unsecure.', async(): Promise<void> => {
    await expect(adapter.find('http://unsecure')).rejects
      .toThrow('SSL is required for client_id authentication unless working locally.');
  });

  it('errors if the client ID requests does not respond with 200.', async(): Promise<void> => {
    fetchMock.mockResolvedValueOnce({ url: id, status: 400, text: (): string => 'error' });
    await expect(adapter.find(id)).rejects.toThrow(`Unable to access data at ${id}: error`);
  });

  it('can handle a valid JSON-LD response.', async(): Promise<void> => {
    fetchMock.mockResolvedValueOnce({ url: id, status: 200, text: (): string => JSON.stringify(json) });
    await expect(adapter.find(id)).resolves.toEqual({
      ...json,
      token_endpoint_auth_method: 'none',
    });
  });

  it('can handle a context array.', async(): Promise<void> => {
    json['@context'] = [ json['@context'] ];
    fetchMock.mockResolvedValueOnce({ url: id, status: 200, text: (): string => JSON.stringify(json) });
    await expect(adapter.find(id)).resolves.toEqual({
      ...json,
      token_endpoint_auth_method: 'none',
    });
  });

  it('errors if there is a client_id mismatch.', async(): Promise<void> => {
    json.client_id = 'someone else';
    fetchMock.mockResolvedValueOnce({ url: id, status: 200, text: (): string => JSON.stringify(json) });
    await expect(adapter.find(id)).rejects
      .toThrow('The client registration `client_id` field must match the client ID');
  });

  it('can handle a valid RDF response.', async(): Promise<void> => {
    fetchMock.mockResolvedValueOnce(
      { url: id, status: 200, text: (): string => rdf, headers: { get: (): any => 'text/turtle' }},
    );
    await expect(adapter.find(id)).resolves.toEqual({
      client_id: id,
      redirect_uris: [ 'http://example.com' ],
      token_endpoint_auth_method: 'none',
    });
  });

  it('falls back to RDF parsing if no valid context was found.', async(): Promise<void> => {
    json = {
      '@id': 'https://app.example.com/card#me',
      'http://www.w3.org/ns/solid/oidc#redirect_uris': { '@id': 'http://example.com' },
      'http://randomField': { '@value': 'this will not be there since RDF parsing only takes preset fields' },
    };
    fetchMock.mockResolvedValueOnce(
      {
        url: id,
        status: 200,
        text: (): string => JSON.stringify(json),
        headers: { get: (): any => 'application/ld+json' },
      },
    );
    await expect(adapter.find(id)).resolves.toEqual({
      client_id: id,
      redirect_uris: [ 'http://example.com' ],
      token_endpoint_auth_method: 'none',
    });
  });

  it('errors if there is no content-type.', async(): Promise<void> => {
    fetchMock.mockResolvedValueOnce(
      { url: id, status: 200, text: (): string => rdf, headers: { get: jest.fn() }},
    );
    await expect(adapter.find(id)).rejects
      .toThrow(`Unable to access data at ${id}`);
  });
});

import type { ExpiringAdapter } from '../../../../src/identity/storage/ExpiringAdapterFactory';
import { ExpiringAdapterFactory } from '../../../../src/identity/storage/ExpiringAdapterFactory';
import type { ExpiringStorage } from '../../../../src/storage/keyvalue/ExpiringStorage';
import type { AdapterPayload } from '../../../../templates/types/oidc-provider';

// Use fixed dates
jest.useFakeTimers();

describe('An ExpiringAdapterFactory', (): void => {
  const name = 'nnaammee';
  const id = 'http://alice.test.com/card#me';
  const grantId = 'grant123456';
  let payload: AdapterPayload;
  let storage: ExpiringStorage<string, unknown>;
  let adapter: ExpiringAdapter;
  let factory: ExpiringAdapterFactory;
  const expiresIn = 333 * 1000;

  beforeEach(async(): Promise<void> => {
    payload = { data: 'data!' };

    const map = new Map<string, any>();
    storage = {
      get: jest.fn().mockImplementation((key: string): any => map.get(key)),
      set: jest.fn().mockImplementation((key: string, value: any): any => map.set(key, value)),
      delete: jest.fn().mockImplementation((key: string): any => map.delete(key)),
    } as any;

    factory = new ExpiringAdapterFactory(storage);
    adapter = factory.createStorageAdapter(name);
  });

  it('can find payload by id.', async(): Promise<void> => {
    await expect(adapter.upsert(id, payload, 333)).resolves.toBeUndefined();
    expect(storage.set).toHaveBeenCalledTimes(1);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), payload, expiresIn);
    await expect(adapter.find(id)).resolves.toBe(payload);
  });

  it('can store payloads without expiration time.', async(): Promise<void> => {
    await expect(adapter.upsert(id, payload)).resolves.toBeUndefined();
    expect(storage.set).toHaveBeenCalledTimes(1);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), payload, undefined);
  });

  it('can find payload by userCode.', async(): Promise<void> => {
    const userCode = 'userCode!';
    payload.userCode = userCode;
    await expect(adapter.upsert(id, payload, 333)).resolves.toBeUndefined();
    expect(storage.set).toHaveBeenCalledTimes(2);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), payload, expiresIn);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), id, expiresIn);
    await expect(adapter.findByUserCode(userCode)).resolves.toBe(payload);
  });

  it('can find payload by uid.', async(): Promise<void> => {
    const uid = 'uid!';
    payload.uid = uid;
    await expect(adapter.upsert(id, payload, 333)).resolves.toBeUndefined();
    expect(storage.set).toHaveBeenCalledTimes(2);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), payload, expiresIn);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), id, expiresIn);
    await expect(adapter.findByUid(uid)).resolves.toBe(payload);
  });

  it('can revoke by grantId.', async(): Promise<void> => {
    payload.grantId = grantId;
    await expect(adapter.upsert(id, payload, 333)).resolves.toBeUndefined();
    expect(storage.set).toHaveBeenCalledTimes(2);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), payload, expiresIn);
    expect(storage.set).toHaveBeenCalledWith(expect.anything(), [ expect.anything() ], expiresIn);
    await expect(adapter.find(id)).resolves.toBe(payload);
    await expect(adapter.revokeByGrantId(grantId)).resolves.toBeUndefined();
    expect(storage.delete).toHaveBeenCalledTimes(2);
    await expect(adapter.find(id)).resolves.toBeUndefined();
  });

  it('does not do anything if revokeByGrantId finds no matching grant.', async(): Promise<void> => {
    await expect(adapter.revokeByGrantId(grantId)).resolves.toBeUndefined();
    expect(storage.delete).toHaveBeenCalledTimes(0);
  });

  it('can store multiple ids for a single grant.', async(): Promise<void> => {
    payload.grantId = grantId;
    const id2 = 'id2!';
    const payload2 = { data: 'data2!', grantId };
    await expect(adapter.upsert(id, payload, 333)).resolves.toBeUndefined();
    await expect(adapter.upsert(id2, payload2, 333)).resolves.toBeUndefined();
    await expect(adapter.find(id)).resolves.toBe(payload);
    await expect(adapter.find(id2)).resolves.toBe(payload2);
    await expect(adapter.revokeByGrantId(grantId)).resolves.toBeUndefined();
    await expect(adapter.find(id)).resolves.toBeUndefined();
    await expect(adapter.find(id2)).resolves.toBeUndefined();
  });

  it('can destroy the payload.', async(): Promise<void> => {
    await expect(adapter.upsert(id, payload, 333)).resolves.toBeUndefined();
    await expect(adapter.find(id)).resolves.toBe(payload);
    await expect(adapter.destroy(id)).resolves.toBeUndefined();
    await expect(adapter.find(id)).resolves.toBeUndefined();
  });

  it('can consume the payload.', async(): Promise<void> => {
    // Caching since the object gets modified
    const cachedPayload = { ...payload };
    await expect(adapter.upsert(id, payload, 333)).resolves.toBeUndefined();
    await expect(adapter.find(id)).resolves.toEqual(cachedPayload);
    await expect(adapter.consume(id)).resolves.toBeUndefined();
    await expect(adapter.find(id)).resolves.toEqual({ ...cachedPayload, consumed: Math.floor(Date.now() / 1000) });
  });

  it('does not do anything if consume finds no payload.', async(): Promise<void> => {
    await expect(adapter.consume(id)).resolves.toBeUndefined();
    await expect(adapter.find(id)).resolves.toBeUndefined();
  });
});

import type { AdapterFactory } from '../../../../src/identity/storage/AdapterFactory';
import {
  PassthroughAdapter,
  PassthroughAdapterFactory,
} from '../../../../src/identity/storage/PassthroughAdapterFactory';
import type { Adapter } from '../../../../templates/types/oidc-provider';

describe('A PassthroughAdapterFactory', (): void => {
  let sourceFactory: jest.Mocked<AdapterFactory>;
  let factory: PassthroughAdapterFactory;

  beforeEach(async(): Promise<void> => {
    sourceFactory = {
      createStorageAdapter: jest.fn(),
    };

    factory = new PassthroughAdapterFactory(sourceFactory);
  });

  it('calls the source createStorageAdapter function.', async(): Promise<void> => {
    expect(factory.createStorageAdapter('Client')).toBeUndefined();
    expect(sourceFactory.createStorageAdapter).toHaveBeenCalledTimes(1);
    expect(sourceFactory.createStorageAdapter).toHaveBeenLastCalledWith('Client');
  });

  describe('A PassthroughAdapter', (): void => {
    let sourceAdapter: jest.Mocked<Adapter>;
    let adapter: PassthroughAdapter;

    beforeEach(async(): Promise<void> => {
      sourceAdapter = {
        upsert: jest.fn(),
        find: jest.fn(),
        findByUserCode: jest.fn(),
        findByUid: jest.fn(),
        consume: jest.fn(),
        destroy: jest.fn(),
        revokeByGrantId: jest.fn(),
      };

      adapter = new PassthroughAdapter('Name', sourceAdapter);
    });

    it('passes the call to the source for upsert.', async(): Promise<void> => {
      await expect(adapter.upsert('id', 'payload' as any, 5)).resolves.toBeUndefined();
      expect(sourceAdapter.upsert).toHaveBeenCalledTimes(1);
      expect(sourceAdapter.upsert).toHaveBeenLastCalledWith('id', 'payload' as any, 5);
    });

    it('passes the call to the source for find.', async(): Promise<void> => {
      await expect(adapter.find('id')).resolves.toBeUndefined();
      expect(sourceAdapter.find).toHaveBeenCalledTimes(1);
      expect(sourceAdapter.find).toHaveBeenLastCalledWith('id');
    });

    it('passes the call to the source for findByUserCode.', async(): Promise<void> => {
      await expect(adapter.findByUserCode('userCode')).resolves.toBeUndefined();
      expect(sourceAdapter.findByUserCode).toHaveBeenCalledTimes(1);
      expect(sourceAdapter.findByUserCode).toHaveBeenLastCalledWith('userCode');
    });

    it('passes the call to the source for findByUid.', async(): Promise<void> => {
      await expect(adapter.findByUid('uid')).resolves.toBeUndefined();
      expect(sourceAdapter.findByUid).toHaveBeenCalledTimes(1);
      expect(sourceAdapter.findByUid).toHaveBeenLastCalledWith('uid');
    });

    it('passes the call to the source for destroy.', async(): Promise<void> => {
      await expect(adapter.destroy('id')).resolves.toBeUndefined();
      expect(sourceAdapter.destroy).toHaveBeenCalledTimes(1);
      expect(sourceAdapter.destroy).toHaveBeenLastCalledWith('id');
    });

    it('passes the call to the source for revokeByGrantId.', async(): Promise<void> => {
      await expect(adapter.revokeByGrantId('grantId')).resolves.toBeUndefined();
      expect(sourceAdapter.revokeByGrantId).toHaveBeenCalledTimes(1);
      expect(sourceAdapter.revokeByGrantId).toHaveBeenLastCalledWith('grantId');
    });

    it('passes the call to the source for consume.', async(): Promise<void> => {
      await expect(adapter.consume('id')).resolves.toBeUndefined();
      expect(sourceAdapter.consume).toHaveBeenCalledTimes(1);
      expect(sourceAdapter.consume).toHaveBeenLastCalledWith('id');
    });
  });
});

import type { ClusterManager } from '../../../src';
import { App } from '../../../src/init/App';
import type { Finalizer } from '../../../src/init/final/Finalizer';
import type { Initializer } from '../../../src/init/Initializer';

describe('An App', (): void => {
  let initializer: Initializer;
  let finalizer: Finalizer;
  let clusterManager: ClusterManager;
  let app: App;

  beforeEach(async(): Promise<void> => {
    initializer = { handleSafe: jest.fn() } as any;
    finalizer = { handleSafe: jest.fn() } as any;
    clusterManager = {} as any;
    app = new App(initializer, finalizer, clusterManager);
  });

  it('can start with the initializer.', async(): Promise<void> => {
    await expect(app.start()).resolves.toBeUndefined();
    expect(initializer.handleSafe).toHaveBeenCalledTimes(1);
  });

  it('can stop with the finalizer.', async(): Promise<void> => {
    await expect(app.stop()).resolves.toBeUndefined();
    expect(finalizer.handleSafe).toHaveBeenCalledTimes(1);
  });

