import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { SingleContainerJsonStorage } from '../../../../src/init/migration/SingleContainerJsonStorage';
import type { ResourceStore } from '../../../../src/storage/ResourceStore';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';
import { isContainerIdentifier } from '../../../../src/util/PathUtil';
import { LDP } from '../../../../src/util/Vocabularies';

describe('A SingleContainerJsonStorage', (): void => {
  const baseUrl = 'http://example.com/';
  const container = '.internal/accounts/';
  let store: jest.Mocked<ResourceStore>;
  let storage: SingleContainerJsonStorage<any>;

  beforeEach(async(): Promise<void> => {
    store = {
      getRepresentation: jest.fn(async(id): Promise<Representation> => {
        if (isContainerIdentifier(id)) {
          const metadata = new RepresentationMetadata(id);
          metadata.add(LDP.terms.contains, 'http://example.com/.internal/accounts/foo');
          metadata.add(LDP.terms.contains, 'http://example.com/.internal/accounts/bad');
          metadata.add(LDP.terms.contains, 'http://example.com/.internal/accounts/bar/');
          metadata.add(LDP.terms.contains, 'http://example.com/.internal/accounts/baz');
          metadata.add(LDP.terms.contains, 'http://example.com/.internal/accounts/unknown');
          return new BasicRepresentation('', metadata);
        }
        if (id.path.endsWith('unknown')) {
          throw new NotFoundHttpError();
        }
        if (id.path.endsWith('bad')) {
          return new BasicRepresentation(`invalid JSON`, 'application/json');
        }
        return new BasicRepresentation(`{ "id": "${id.path}" }`, 'application/json');
      }),
    } satisfies Partial<ResourceStore> as any;

    storage = new SingleContainerJsonStorage(store, baseUrl, container);
  });

  it('only iterates over the valid documents in the base container.', async(): Promise<void> => {
    const entries = [];
    for await (const entry of storage.entries()) {
      entries.push(entry);
    }
    expect(entries).toEqual([
      [ 'foo', { id: 'http://example.com/.internal/accounts/foo' }],
      [ 'baz', { id: 'http://example.com/.internal/accounts/baz' }],
    ]);
    expect(store.getRepresentation).toHaveBeenCalledTimes(5);
    expect(store.getRepresentation).toHaveBeenNthCalledWith(
      1,
      { path: 'http://example.com/.internal/accounts/' },
      {},
    );
    expect(store.getRepresentation).toHaveBeenNthCalledWith(
      2,
      { path: 'http://example.com/.internal/accounts/foo' },
      { type: { 'application/json': 1 }},
    );
    expect(store.getRepresentation).toHaveBeenNthCalledWith(
      3,
      { path: 'http://example.com/.internal/accounts/bad' },
      { type: { 'application/json': 1 }},
    );
    expect(store.getRepresentation).toHaveBeenNthCalledWith(
      4,
      { path: 'http://example.com/.internal/accounts/baz' },
      { type: { 'application/json': 1 }},
    );
    expect(store.getRepresentation).toHaveBeenNthCalledWith(
      5,
      { path: 'http://example.com/.internal/accounts/unknown' },
      { type: { 'application/json': 1 }},
    );
  });

  it('does nothing if the container does not exist.', async(): Promise<void> => {
    store.getRepresentation.mockRejectedValueOnce(new NotFoundHttpError());
    const entries = [];
    for await (const entry of storage.entries()) {
      entries.push(entry);
    }
    expect(entries).toHaveLength(0);
  });
});

import type { AccountLoginStorage } from '../../../../src/identity/interaction/account/util/LoginStorage';
import { ACCOUNT_TYPE } from '../../../../src/identity/interaction/account/util/LoginStorage';
import {
  CLIENT_CREDENTIALS_STORAGE_TYPE,
} from '../../../../src/identity/interaction/client-credentials/util/BaseClientCredentialsStore';
import { PASSWORD_STORAGE_TYPE } from '../../../../src/identity/interaction/password/util/BasePasswordStore';
import { OWNER_STORAGE_TYPE, POD_STORAGE_TYPE } from '../../../../src/identity/interaction/pod/util/BasePodStore';
import { WEBID_STORAGE_TYPE } from '../../../../src/identity/interaction/webid/util/BaseWebIdStore';
import { V6MigrationInitializer } from '../../../../src/init/migration/V6MigrationInitializer';
import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';

type Account = {
  webId: string;
  email: string;
  password: string;
  verified: boolean;
};

type Settings = {
  useIdp: boolean;
  podBaseUrl?: string;
  clientCredentials?: string[];
};

type ClientCredentials = {
  webId: string;
  secret: string;
};

const questionMock = jest.fn().mockImplementation((input, callback): void => callback('y'));
const closeMock = jest.fn();
jest.mock('node:readline', (): any => ({
  createInterface: jest.fn().mockImplementation((): any => ({
    question: questionMock,
    close: closeMock,
  })),
}));

describe('A V6MigrationInitializer', (): void => {
  const webId = 'http://example.com/test/profile/card#me';
  const webId2 = 'http://example.com/test2/profile/card#me';
  let settings: Record<string, Settings>;
  let accounts: Record<string, Account>;
  let clientCredentials: Record<string, ClientCredentials>;
  const versionKey = 'version';
  let setupStorage: jest.Mocked<KeyValueStorage<string, string>>;
  let accountStorage: jest.Mocked<KeyValueStorage<string, Account | Settings>>;
  let clientCredentialsStorage: jest.Mocked<KeyValueStorage<string, ClientCredentials>>;
  let forgotPasswordStorage: jest.Mocked<KeyValueStorage<string, unknown>>;
  let newAccountStorage: jest.Mocked<AccountLoginStorage<any>>;
  let newSetupStorage: jest.Mocked<KeyValueStorage<string, string>>;
  let initializer: V6MigrationInitializer;

  beforeEach(async(): Promise<void> => {
    settings = {
      [webId]: { useIdp: true, podBaseUrl: 'http://example.com/test/', clientCredentials: [ 'token' ]},
      [webId2]: { useIdp: true, podBaseUrl: 'http://example.com/test2/' },
    };
    accounts = {
      account: { email: 'EMAIL@example.com', password: '123', webId, verified: true },
      account2: { email: 'email2@example.com', password: '1234', webId: webId2, verified: true },
    };
    clientCredentials = {
      token: { webId, secret: 'secret!' },
    };

    setupStorage = {
      get: jest.fn().mockResolvedValue('6.0.0'),
      delete: jest.fn(),
      entries: jest.fn(async function* (): AsyncGenerator<[string, string]> {
        yield [ 'version', '6.0.0' ];
      }),
    } satisfies Partial<KeyValueStorage<string, string>> as any;

    newSetupStorage = {
      set: jest.fn(),
    } satisfies Partial<KeyValueStorage<string, string>> as any;

    accountStorage = {
      get: jest.fn((id): any => settings[id] ?? accounts[id]),
      delete: jest.fn(),
      entries: jest.fn(async function* (): AsyncIterableIterator<[string, any]> {
        yield* Object.entries(accounts);
        yield* Object.entries(settings);
      }),
    } satisfies Partial<KeyValueStorage<string, any>> as any;

    clientCredentialsStorage = {
      delete: jest.fn(),
      entries: jest.fn(async function* (): AsyncIterableIterator<[string, any]> {
        yield* Object.entries(clientCredentials);
      }),
    } satisfies Partial<KeyValueStorage<string, any>> as any;

    forgotPasswordStorage = {
      delete: jest.fn(),
      entries: jest.fn(async function* (): AsyncIterableIterator<[string, any]> {
        yield [ 'forgot', {}];
      }),
    } satisfies Partial<KeyValueStorage<string, any>> as any;

    newAccountStorage = {
      create: jest.fn((type): any => ({ id: `${type}-id` })),
    } satisfies Partial<AccountLoginStorage<any>> as any;

    initializer = new V6MigrationInitializer({
      versionKey,
      setupStorage,
      accountStorage,
      clientCredentialsStorage,
      cleanupStorages: [ accountStorage, clientCredentialsStorage, forgotPasswordStorage ],
      newAccountStorage,
      newSetupStorage,
      skipConfirmation: true,
    });
  });

  it('migrates the data.', async(): Promise<void> => {
    await expect(initializer.handle()).resolves.toBeUndefined();

    expect(setupStorage.get).toHaveBeenCalledTimes(1);
    expect(setupStorage.get).toHaveBeenLastCalledWith(versionKey);

    expect(accountStorage.get).toHaveBeenCalledTimes(2);
    expect(accountStorage.get).toHaveBeenCalledWith(webId);
    expect(accountStorage.get).toHaveBeenCalledWith(webId2);
    expect(accountStorage.delete).toHaveBeenCalledTimes(4);
    expect(accountStorage.delete).toHaveBeenCalledWith(webId);
    expect(accountStorage.delete).toHaveBeenCalledWith(webId2);
    expect(accountStorage.delete).toHaveBeenCalledWith('account');
    expect(accountStorage.delete).toHaveBeenCalledWith('account2');

    expect(clientCredentialsStorage.delete).toHaveBeenCalledTimes(1);
    expect(clientCredentialsStorage.delete).toHaveBeenCalledWith('token');

    expect(forgotPasswordStorage.delete).toHaveBeenCalledTimes(1);
    expect(forgotPasswordStorage.delete).toHaveBeenCalledWith('forgot');

    expect(newAccountStorage.create).toHaveBeenCalledTimes(11);
    expect(newAccountStorage.create).toHaveBeenCalledWith(ACCOUNT_TYPE, {});
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      PASSWORD_STORAGE_TYPE,
      { email: 'email@example.com', password: '123', verified: true, accountId: 'account-id' },
    );
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      PASSWORD_STORAGE_TYPE,
      { email: 'email2@example.com', password: '1234', verified: true, accountId: 'account-id' },
    );
    expect(newAccountStorage.create).toHaveBeenCalledWith(WEBID_STORAGE_TYPE, { webId, accountId: 'account-id' });
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      WEBID_STORAGE_TYPE,
      { webId: webId2, accountId: 'account-id' },
    );
    expect(newAccountStorage.create).toHaveBeenCalledWith(POD_STORAGE_TYPE, { baseUrl: 'http://example.com/test/', accountId: 'account-id' });
    expect(newAccountStorage.create).toHaveBeenCalledWith(POD_STORAGE_TYPE, { baseUrl: 'http://example.com/test2/', accountId: 'account-id' });
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      OWNER_STORAGE_TYPE,
      { webId, podId: 'pod-id', visible: false },
    );
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      OWNER_STORAGE_TYPE,
      { webId: webId2, podId: 'pod-id', visible: false },
    );
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      CLIENT_CREDENTIALS_STORAGE_TYPE,
      { label: 'token', secret: 'secret!', webId, accountId: 'account-id' },
    );

    expect(newSetupStorage.set).toHaveBeenCalledTimes(1);
    expect(newSetupStorage.set).toHaveBeenLastCalledWith('version', '6.0.0');
    expect(setupStorage.delete).toHaveBeenCalledTimes(1);
    expect(setupStorage.delete).toHaveBeenLastCalledWith('version');
  });

  it('does nothing if the server has no stored version number.', async(): Promise<void> => {
    setupStorage.get.mockResolvedValueOnce(undefined);
    await expect(initializer.handle()).resolves.toBeUndefined();
    expect(accountStorage.get).toHaveBeenCalledTimes(0);
    expect(newAccountStorage.create).toHaveBeenCalledTimes(0);
  });

  it('does nothing if stored version is more than 6.', async(): Promise<void> => {
    setupStorage.get.mockResolvedValueOnce('7.0.0');
    await expect(initializer.handle()).resolves.toBeUndefined();
    expect(accountStorage.get).toHaveBeenCalledTimes(0);
    expect(newAccountStorage.create).toHaveBeenCalledTimes(0);
  });

  it('ignores accounts and credentials for which it cannot find the settings.', async(): Promise<void> => {
    delete settings[webId];
    await expect(initializer.handle()).resolves.toBeUndefined();

    expect(setupStorage.get).toHaveBeenCalledTimes(1);
    expect(setupStorage.get).toHaveBeenLastCalledWith(versionKey);

    expect(accountStorage.get).toHaveBeenCalledTimes(2);
    expect(accountStorage.get).toHaveBeenCalledWith(webId);
    expect(accountStorage.get).toHaveBeenCalledWith(webId2);
    expect(accountStorage.delete).toHaveBeenCalledTimes(3);
    expect(accountStorage.delete).toHaveBeenCalledWith(webId2);
    expect(accountStorage.delete).toHaveBeenCalledWith('account');
    expect(accountStorage.delete).toHaveBeenCalledWith('account2');

    expect(newAccountStorage.create).toHaveBeenCalledTimes(5);
    expect(newAccountStorage.create).toHaveBeenCalledWith(ACCOUNT_TYPE, {});
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      PASSWORD_STORAGE_TYPE,
      { email: 'email2@example.com', password: '1234', verified: true, accountId: 'account-id' },
    );
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      WEBID_STORAGE_TYPE,
      { webId: webId2, accountId: 'account-id' },
    );
    expect(newAccountStorage.create).toHaveBeenCalledWith(POD_STORAGE_TYPE, { baseUrl: 'http://example.com/test2/', accountId: 'account-id' });
    expect(newAccountStorage.create).toHaveBeenCalledWith(
      OWNER_STORAGE_TYPE,
      { webId: webId2, podId: 'pod-id', visible: false },
    );

    expect(newSetupStorage.set).toHaveBeenCalledTimes(1);
    expect(newSetupStorage.set).toHaveBeenLastCalledWith('version', '6.0.0');
    expect(setupStorage.delete).toHaveBeenCalledTimes(1);
    expect(setupStorage.delete).toHaveBeenLastCalledWith('version');
  });

  describe('with prompts enabled', (): void => {
    beforeEach(async(): Promise<void> => {
      jest.clearAllMocks();

      initializer = new V6MigrationInitializer({
        versionKey,
        setupStorage,
        accountStorage,
        clientCredentialsStorage,
        cleanupStorages: [ accountStorage, clientCredentialsStorage, forgotPasswordStorage ],
        newAccountStorage,
        newSetupStorage,
        skipConfirmation: false,
      });
    });

    it('shows a prompt before migrating the data.', async(): Promise<void> => {
      await expect(initializer.handle()).resolves.toBeUndefined();

      expect(questionMock).toHaveBeenCalledTimes(1);
      expect(questionMock.mock.invocationCallOrder[0])
        .toBeLessThan(newAccountStorage.create.mock.invocationCallOrder[0]);

      expect(newAccountStorage.create).toHaveBeenCalledTimes(11);
    });

    it('throws an error to stop the server if no positive answer is received.', async(): Promise<void> => {
      questionMock.mockImplementation((input, callback): void => callback('n'));
      await expect(initializer.handle()).rejects.toThrow('Stopping server as migration was cancelled.');
      expect(newAccountStorage.create).toHaveBeenCalledTimes(0);
    });
  });
});

import { ModuleVersionVerifier } from '../../../src/init/ModuleVersionVerifier';

describe('A ModuleVersionVerifier', (): void => {
  const storageKey = 'uniqueVersionKey';
  let storageMap: Map<string, string>;
  let initializer: ModuleVersionVerifier;

  beforeEach(async(): Promise<void> => {
    storageMap = new Map<string, string>();
    initializer = new ModuleVersionVerifier(storageKey, storageMap as any);
  });

  it('stores the latest version.', async(): Promise<void> => {
    await expect(initializer.handle()).resolves.toBeUndefined();
    expect(storageMap.get(storageKey)).toMatch(/^\d+\.\d+\.\d+(?:-.+)?/u);
  });
});

import { writeJson } from 'fs-extra';
import type { AccountStore } from '../../../src/identity/interaction/account/util/AccountStore';
import type { PasswordStore } from '../../../src/identity/interaction/password/util/PasswordStore';
import type { PodCreator } from '../../../src/identity/interaction/pod/util/PodCreator';
import { SeededAccountInitializer } from '../../../src/init/SeededAccountInitializer';
import { mockFileSystem } from '../../util/Util';

jest.mock('node:fs');
jest.mock('fs-extra');

describe('A SeededAccountInitializer', (): void => {
  const dummyConfig = [
    {
      email: 'hello@example.com',
      password: 'abc123',
      pods: [
        { name: 'pod1' },
        { name: 'pod2' },
        { name: 'pod3' },
      ],
    },
    {
      podName: 'example2',
      email: 'hello2@example.com',
      password: '123abc',
    },
  ];
  const configFilePath = './seeded-pod-config.json';
  let accountStore: jest.Mocked<AccountStore>;
  let passwordStore: jest.Mocked<PasswordStore>;
  let podCreator: jest.Mocked<PodCreator>;
  let initializer: SeededAccountInitializer;

  beforeEach(async(): Promise<void> => {
    let count = 0;
    accountStore = {
      create: jest.fn(async(): Promise<string> => {
        count += 1;
        return `account${count}`;
      }),
    } satisfies Partial<AccountStore> as any;

    let pwCount = 0;
    passwordStore = {
      create: jest.fn(async(): Promise<string> => {
        pwCount += 1;
        return `password${pwCount}`;
      }),
      confirmVerification: jest.fn(),
    } satisfies Partial<PasswordStore> as any;

    podCreator = {
      handleSafe: jest.fn(),
    } satisfies Partial<PodCreator> as any;

    mockFileSystem('/');
    await writeJson(configFilePath, dummyConfig);

    initializer = new SeededAccountInitializer({
      accountStore,
      passwordStore,
      podCreator,
      configFilePath,
    });
  });

  it('does not generate any accounts or pods if no config file is specified.', async(): Promise<void> => {
    await expect(new SeededAccountInitializer({ accountStore, passwordStore, podCreator }).handle())
      .resolves.toBeUndefined();
    expect(accountStore.create).toHaveBeenCalledTimes(0);
  });

  it('errors if the seed file is invalid.', async(): Promise<void> => {
    await writeJson(configFilePath, 'invalid config');
    await expect(initializer.handle()).rejects
      .toThrow('Invalid account seed file: this must be a `array` type, but the final value was: `"invalid config"`.');
  });

  it('generates an account with the specified settings.', async(): Promise<void> => {
    await expect(initializer.handleSafe()).resolves.toBeUndefined();
    expect(accountStore.create).toHaveBeenCalledTimes(2);
    expect(passwordStore.create).toHaveBeenCalledTimes(2);
    expect(passwordStore.create).toHaveBeenNthCalledWith(1, 'hello@example.com', 'account1', 'abc123');
    expect(passwordStore.create).toHaveBeenNthCalledWith(2, 'hello2@example.com', 'account2', '123abc');
    expect(passwordStore.confirmVerification).toHaveBeenCalledTimes(2);
    expect(passwordStore.confirmVerification).toHaveBeenNthCalledWith(1, 'password1');
    expect(passwordStore.confirmVerification).toHaveBeenNthCalledWith(2, 'password2');
    expect(podCreator.handleSafe).toHaveBeenCalledTimes(3);
    expect(podCreator.handleSafe).toHaveBeenNthCalledWith(1, { accountId: 'account1', name: 'pod1', settings: {}});
    expect(podCreator.handleSafe).toHaveBeenNthCalledWith(2, { accountId: 'account1', name: 'pod2', settings: {}});
    expect(podCreator.handleSafe).toHaveBeenNthCalledWith(3, { accountId: 'account1', name: 'pod3', settings: {}});
  });

  it('does not throw exceptions when one of the steps fails.', async(): Promise<void> => {
    accountStore.create.mockRejectedValueOnce(new Error('bad data'));
    await expect(initializer.handleSafe()).resolves.toBeUndefined();
    expect(accountStore.create).toHaveBeenCalledTimes(2);
    // Steps for first account will be skipped due to error
    expect(passwordStore.create).toHaveBeenCalledTimes(1);
    expect(podCreator.handleSafe).toHaveBeenCalledTimes(0);
  });
});

import type { Server } from 'node:http';
import { Server as HttpsServer } from 'node:https';
import { ServerInitializer } from '../../../src/init/ServerInitializer';
import type { Logger } from '../../../src/logging/Logger';
import { getLoggerFor } from '../../../src/logging/LogUtil';
import type { HttpServerFactory } from '../../../src/server/HttpServerFactory';

// Mock so we don't create an actual HTTPS server in the test below
jest.mock('node:https');
jest.mock('../../../src/logging/LogUtil');

describe('ServerInitializer', (): void => {
  let logger: jest.Mocked<Logger>;
  let server: Server;
  let serverFactory: jest.Mocked<HttpServerFactory>;
  let initializer: ServerInitializer;

  beforeEach(async(): Promise<void> => {
    logger = { info: jest.fn() } as any;
    (getLoggerFor as jest.MockedFn<() => Logger>).mockReturnValue(logger);

    server = {
      address: jest.fn().mockResolvedValue('address'),
      listen: jest.fn(),
      close: jest.fn((fn: () => void): void => fn()),
    } as any;
    serverFactory = {
      createServer: jest.fn().mockReturnValue(server),
    };
    initializer = new ServerInitializer(serverFactory, 3000);
  });

  it('starts an HTTP server.', async(): Promise<void> => {
    await initializer.handle();
    expect(serverFactory.createServer).toHaveBeenCalledTimes(1);
    expect(server.listen).toHaveBeenCalledTimes(1);
    expect(server.listen).toHaveBeenLastCalledWith(3000);
    expect(logger.info).toHaveBeenCalledTimes(1);
    expect(logger.info).toHaveBeenLastCalledWith(`Listening to server at http://localhost:3000/`);
  });

  it('correctly logs the protocol in case of an HTTPS server.', async(): Promise<void> => {
    server = new HttpsServer();
    serverFactory.createServer.mockResolvedValue(server);
    await initializer.handle();
    expect(serverFactory.createServer).toHaveBeenCalledTimes(1);
    expect(server.listen).toHaveBeenCalledTimes(1);
    expect(server.listen).toHaveBeenLastCalledWith(3000);
    expect(logger.info).toHaveBeenCalledTimes(1);
    expect(logger.info).toHaveBeenLastCalledWith(`Listening to server at https://localhost:3000/`);
  });

  it('listens to the specified Unix Domain Socket.', async(): Promise<void> => {
    initializer = new ServerInitializer(serverFactory, undefined, '/tmp/css.sock');
    await initializer.handle();
    expect(server.listen).toHaveBeenCalledWith('/tmp/css.sock');
  });

  it('throws when neither port or socket are set.', async(): Promise<void> => {
    expect((): void => {
      initializer = new ServerInitializer(serverFactory, undefined, undefined);
    }).toThrow('Either Port or Socket arguments must be set');
  });

  it('can stop the server.', async(): Promise<void> => {
    await initializer.handle();
    await expect(initializer.finalize()).resolves.toBeUndefined();
    expect(server.close).toHaveBeenCalledTimes(1);
  });

  it('only tries to stop the server if it was initialized.', async(): Promise<void> => {
    await expect(initializer.finalize()).resolves.toBeUndefined();
    expect(server.close).toHaveBeenCalledTimes(0);
  });
});

import { CombinedShorthandResolver } from '../../../../src/init/variables/CombinedShorthandResolver';
import type { ShorthandExtractor } from '../../../../src/init/variables/extractors/ShorthandExtractor';

describe('A CombinedShorthandResolver', (): void => {
  const values = { test: 'data' };
  const varPort = 'urn:solid-server:default:variable:port';
  const varLog = 'urn:solid-server:default:variable:loggingLevel';
  let resolverPort: jest.Mocked<ShorthandExtractor>;
  let resolverLog: jest.Mocked<ShorthandExtractor>;
  let resolver: CombinedShorthandResolver;

  beforeEach(async(): Promise<void> => {
    resolverPort = {
      handleSafe: jest.fn().mockResolvedValue(3000),
    } as any;

    resolverLog = {
      handleSafe: jest.fn().mockResolvedValue('info'),
    } as any;

    resolver = new CombinedShorthandResolver({
      [varPort]: resolverPort,
      [varLog]: resolverLog,
    });
