});

import { VariableSetter } from '../../../../../src/pods/generate/variables/VariableSetter';
import type { PodSettings } from '../../../../../src/pods/settings/PodSettings';

describe('A VariableSetter', (): void => {
  const variable = 'variable';
  const value = 'http://test.com/sparql';
  let settings: PodSettings;
  let handler: VariableSetter;

  beforeEach(async(): Promise<void> => {
    settings = {} as any;
  });

  it('does nothing if there already is a sparql endpoint value and override is false.', async(): Promise<void> => {
    handler = new VariableSetter(variable, value);
    settings[variable] = 'sparql-endpoint';
    await expect(handler.handle({ settings })).resolves.toBeUndefined();
    expect(settings[variable]).toBe('sparql-endpoint');
  });

  it('adds adds the value to the variable if there is none.', async(): Promise<void> => {
    handler = new VariableSetter(variable, value);
    await expect(handler.handle({ settings })).resolves.toBeUndefined();
    expect(settings[variable]).toBe(value);
  });

  it('always sets the value if override is true.', async(): Promise<void> => {
    handler = new VariableSetter(variable, value, true);
    settings[variable] = 'sparql-endpoint';
    await expect(handler.handle({ settings })).resolves.toBeUndefined();
    expect(settings[variable]).toBe(value);
  });
});

import type { Resource, ResourcesGenerator } from '../../../src/pods/generate/ResourcesGenerator';
import { GeneratedPodManager } from '../../../src/pods/GeneratedPodManager';
import type { PodSettings } from '../../../src/pods/settings/PodSettings';
import type { ResourceStore } from '../../../src/storage/ResourceStore';
import { ConflictHttpError } from '../../../src/util/errors/ConflictHttpError';

describe('A GeneratedPodManager', (): void => {
  const base = 'http://example.com/';
  let settings: PodSettings;
  let store: jest.Mocked<ResourceStore>;
  let generatorData: Resource[];
  let resGenerator: ResourcesGenerator;
  let manager: GeneratedPodManager;

  beforeEach(async(): Promise<void> => {
    settings = {
      name: 'first last',
      webId: 'http://secure/webId',
      base: { path: 'http://example.com/user/' },
    };
    store = {
      setRepresentation: jest.fn(),
      hasResource: jest.fn(),
    } as any;
    generatorData = [
      { identifier: { path: '/path/' }, representation: '/' as any },
      { identifier: { path: '/path/a/' }, representation: '/a/' as any },
      { identifier: { path: '/path/a/b' }, representation: '/a/b' as any },
    ];
    resGenerator = {
      generate: jest.fn(async function* (): any {
        yield* generatorData;
      }),
    };
    manager = new GeneratedPodManager(store, resGenerator);
  });

  it('throws an error if the generate identifier is not available.', async(): Promise<void> => {
    store.hasResource.mockResolvedValueOnce(true);
    const result = manager.createPod(settings, false);
    await expect(result).rejects.toThrow(`There already is a resource at ${base}user/`);
    await expect(result).rejects.toThrow(ConflictHttpError);
  });

  it('generates an identifier and writes containers before writing the resources in them.', async(): Promise<void> => {
    await expect(manager.createPod(settings, false)).resolves.toBeUndefined();

    expect(store.setRepresentation).toHaveBeenCalledTimes(3);
    expect(store.setRepresentation).toHaveBeenNthCalledWith(1, { path: '/path/' }, '/');
    expect(store.setRepresentation).toHaveBeenNthCalledWith(2, { path: '/path/a/' }, '/a/');
    expect(store.setRepresentation).toHaveBeenNthCalledWith(3, { path: '/path/a/b' }, '/a/b');
  });

  it('allows overwriting when enabled.', async(): Promise<void> => {
    store.hasResource.mockResolvedValueOnce(true);
    await expect(manager.createPod(settings, true)).resolves.toBeUndefined();

    expect(store.setRepresentation).toHaveBeenCalledTimes(3);
    expect(store.setRepresentation).toHaveBeenNthCalledWith(1, { path: '/path/' }, '/');
    expect(store.setRepresentation).toHaveBeenNthCalledWith(2, { path: '/path/a/' }, '/a/');
    expect(store.setRepresentation).toHaveBeenNthCalledWith(3, { path: '/path/a/b' }, '/a/b');
  });
});

import type { ResourceIdentifier } from '../../../src/http/representation/ResourceIdentifier';
import { GlobalQuotaStrategy } from '../../../src/storage/quota/GlobalQuotaStrategy';
import { UNIT_BYTES } from '../../../src/storage/size-reporter/Size';
import type { Size } from '../../../src/storage/size-reporter/Size';
import type { SizeReporter } from '../../../src/storage/size-reporter/SizeReporter';

describe('GlobalQuotaStrategy', (): void => {
  let strategy: GlobalQuotaStrategy;
  let mockSize: Size;
  let mockReporter: jest.Mocked<SizeReporter<any>>;
  let mockBase: string;

  beforeEach((): void => {
    mockSize = { amount: 2000, unit: UNIT_BYTES };
    mockBase = '';
    mockReporter = {
      getSize: jest.fn(async(identifier: ResourceIdentifier): Promise<Size> => ({
        unit: mockSize.unit,
        // This mock will return 1000 as size of the root and 50 for any other resource
        amount: identifier.path === mockBase ? 1000 : 50,
      })),
      getUnit: jest.fn().mockReturnValue(mockSize.unit),
      calculateChunkSize: jest.fn(async(chunk: any): Promise<number> => chunk.length),
      estimateSize: jest.fn().mockResolvedValue(5),
    };
    strategy = new GlobalQuotaStrategy(mockSize, mockReporter, mockBase);
  });

  describe('getAvailableSpace()', (): void => {
    it('should return the correct amount of available space left.', async(): Promise<void> => {
      const result = strategy.getAvailableSpace({ path: 'any/path' });
      await expect(result).resolves.toEqual(
        expect.objectContaining({ amount: mockSize.amount - 950 }),
      );
    });
  });
});

import { RepresentationMetadata } from '../../../src/http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../../src/http/representation/ResourceIdentifier';
import type { DataAccessor } from '../../../src/storage/accessors/DataAccessor';
import { PodQuotaStrategy } from '../../../src/storage/quota/PodQuotaStrategy';
import { UNIT_BYTES } from '../../../src/storage/size-reporter/Size';
import type { Size } from '../../../src/storage/size-reporter/Size';
import type { SizeReporter } from '../../../src/storage/size-reporter/SizeReporter';
import { NotFoundHttpError } from '../../../src/util/errors/NotFoundHttpError';
import type { IdentifierStrategy } from '../../../src/util/identifiers/IdentifierStrategy';
import { SingleRootIdentifierStrategy } from '../../../src/util/identifiers/SingleRootIdentifierStrategy';
import { PIM, RDF } from '../../../src/util/Vocabularies';
import { mockFileSystem } from '../../util/Util';

jest.mock('node:fs');

describe('PodQuotaStrategy', (): void => {
  let strategy: PodQuotaStrategy;
  let mockSize: Size;
  let mockReporter: jest.Mocked<SizeReporter<any>>;
  let identifierStrategy: IdentifierStrategy;
  let accessor: jest.Mocked<DataAccessor>;
  const base = 'http://localhost:3000/';
  const rootFilePath = 'folder';

  beforeEach((): void => {
    jest.restoreAllMocks();
    mockFileSystem(rootFilePath, new Date());
    mockSize = { amount: 2000, unit: UNIT_BYTES };
    identifierStrategy = new SingleRootIdentifierStrategy(base);
    mockReporter = {
      getSize: jest.fn().mockResolvedValue({ unit: mockSize.unit, amount: 50 }),
      getUnit: jest.fn().mockReturnValue(mockSize.unit),
      calculateChunkSize: jest.fn(async(chunk: any): Promise<number> => chunk.length),
      estimateSize: jest.fn().mockResolvedValue(5),
    };
    accessor = {
      // Assume that the pod is called "nested"
      getMetadata: jest.fn().mockImplementation(
        async(identifier: ResourceIdentifier): Promise<RepresentationMetadata> => {
          const res = new RepresentationMetadata();
          if (identifier.path === `${base}nested/`) {
            res.add(RDF.terms.type, PIM.Storage);
          }
          return res;
        },
      ),
    } as any;
    strategy = new PodQuotaStrategy(mockSize, mockReporter, identifierStrategy, accessor);
  });

  describe('getAvailableSpace()', (): void => {
    it('should return a Size containing MAX_SAFE_INTEGER when writing outside a pod.', async(): Promise<void> => {
      const result = strategy.getAvailableSpace({ path: `${base}file.txt` });
      await expect(result).resolves.toEqual(expect.objectContaining({ amount: Number.MAX_SAFE_INTEGER }));
    });

    it('should ignore the size of the existing resource when writing inside a pod.', async(): Promise<void> => {
      const result = strategy.getAvailableSpace({ path: `${base}nested/nested2/file.txt` });
      await expect(result).resolves.toEqual(expect.objectContaining({ amount: mockSize.amount }));
      expect(mockReporter.getSize).toHaveBeenCalledTimes(2);
    });

    it('should return a Size containing the available space when writing inside a pod.', async(): Promise<void> => {
      accessor.getMetadata.mockImplementationOnce((): any => {
        throw new NotFoundHttpError();
      });
      const result = strategy.getAvailableSpace({ path: `${base}nested/nested2/file.txt` });
      await expect(result).resolves.toEqual(expect.objectContaining({ amount: mockSize.amount }));
      expect(mockReporter.getSize).toHaveBeenCalledTimes(2);
    });

    it('should throw when looking for pim:Storage errors.', async(): Promise<void> => {
      accessor.getMetadata.mockImplementationOnce((): any => {
        throw new Error('error');
      });
      const result = strategy.getAvailableSpace({ path: `${base}nested/nested2/file.txt` });
      await expect(result).rejects.toThrow('error');
    });
  });
});

import { RepresentationMetadata } from '../../../src/http/representation/RepresentationMetadata';
import { QuotaStrategy } from '../../../src/storage/quota/QuotaStrategy';
import { UNIT_BYTES } from '../../../src/storage/size-reporter/Size';
import type { Size } from '../../../src/storage/size-reporter/Size';
import type { SizeReporter } from '../../../src/storage/size-reporter/SizeReporter';
import { guardedStreamFrom, pipeSafely } from '../../../src/util/StreamUtil';
import { mockFileSystem } from '../../util/Util';

jest.mock('node:fs');

class QuotaStrategyWrapper extends QuotaStrategy {
  public constructor(reporter: SizeReporter<any>, limit: Size) {
    super(reporter, limit);
  }

  public getAvailableSpace = async(): Promise<Size> => ({ unit: UNIT_BYTES, amount: 5 });
  protected getTotalSpaceUsed = async(): Promise<Size> => ({ unit: UNIT_BYTES, amount: 5 });
}

describe('A QuotaStrategy', (): void => {
  let strategy: QuotaStrategyWrapper;
  let mockSize: Size;
  let mockReporter: jest.Mocked<SizeReporter<any>>;
  const base = 'http://localhost:3000/';
  const rootFilePath = 'folder';

  beforeEach((): void => {
    jest.restoreAllMocks();
    mockFileSystem(rootFilePath, new Date());
    mockSize = { amount: 2000, unit: UNIT_BYTES };
    mockReporter = {
      getSize: jest.fn().mockResolvedValue({ unit: mockSize.unit, amount: 50 }),
      getUnit: jest.fn().mockReturnValue(mockSize.unit),
      calculateChunkSize: jest.fn(async(chunk: any): Promise<number> => chunk.length),
      estimateSize: jest.fn().mockResolvedValue(5),
    };
    strategy = new QuotaStrategyWrapper(mockReporter, mockSize);
  });

  describe('constructor()', (): void => {
    it('should set the passed parameters as properties.', async(): Promise<void> => {
      expect(strategy.limit).toEqual(mockSize);
      expect(strategy.reporter).toEqual(mockReporter);
    });
  });

  describe('estimateSize()', (): void => {
    it('should return a Size object containing the correct unit and amount.', async(): Promise<void> => {
      await expect(strategy.estimateSize(new RepresentationMetadata())).resolves.toEqual(
        // This '5' comes from the reporter mock a little up in this file
        expect.objectContaining({ unit: mockSize.unit, amount: 5 }),
      );
    });

    it('should return undefined when the reporter returns undefined.', async(): Promise<void> => {
      mockReporter.estimateSize.mockResolvedValueOnce(undefined);
      await expect(strategy.estimateSize(new RepresentationMetadata())).resolves.toBeUndefined();
    });
  });

  describe('createQuotaGuard()', (): void => {
    it('should return a passthrough that destroys the stream when quota is exceeded.', async(): Promise<void> => {
      jest.spyOn(strategy, 'getAvailableSpace').mockResolvedValue({ amount: 50, unit: mockSize.unit });
      const fiftyChars = 'A'.repeat(50);
      const stream = guardedStreamFrom(fiftyChars);
      const track = await strategy.createQuotaGuard({ path: `${base}nested/file2.txt` });
      const piped = pipeSafely(stream, track);

      for (let i = 0; i < 10; i++) {
        stream.push(fiftyChars);
      }

      expect(piped.destroyed).toBe(false);

      for (let i = 0; i < 10; i++) {
        stream.push(fiftyChars);
      }

      expect(piped.destroyed).toBe(false);

      stream.push(fiftyChars);

      const destroy = new Promise<void>((resolve): void => {
        piped.on('error', (): void => resolve());
      });
      await expect(destroy).resolves.toBeUndefined();
    });
  });
});

import type { BlankNode } from 'n3';
import type { CredentialsExtractor } from '../../../src/authentication/CredentialsExtractor';
import type { Authorizer } from '../../../src/authorization/Authorizer';
import type { PermissionReader } from '../../../src/authorization/PermissionReader';
import type { ModesExtractor } from '../../../src/authorization/permissions/ModesExtractor';
import type { AccessMap, PermissionMap } from '../../../src/authorization/permissions/Permissions';
import { AccessMode } from '../../../src/authorization/permissions/Permissions';
import type { Operation } from '../../../src/http/Operation';
import { BasicRepresentation } from '../../../src/http/representation/BasicRepresentation';
import { AuthorizingHttpHandler } from '../../../src/server/AuthorizingHttpHandler';
import type { HttpRequest } from '../../../src/server/HttpRequest';
import type { HttpResponse } from '../../../src/server/HttpResponse';
import type { OperationHttpHandler } from '../../../src/server/OperationHttpHandler';
import { ForbiddenHttpError } from '../../../src/util/errors/ForbiddenHttpError';
import { HttpError } from '../../../src/util/errors/HttpError';
import { IdentifierMap, IdentifierSetMultiMap } from '../../../src/util/map/IdentifierMap';
import { SOLID_META } from '../../../src/util/Vocabularies';

describe('An AuthorizingHttpHandler', (): void => {
  const credentials = {};
  const target = { path: 'http://example.com/foo' };
  const requestedModes: AccessMap = new IdentifierSetMultiMap<AccessMode>(
    [[ target, new Set([ AccessMode.read, AccessMode.write ]) ]],
  );
  const availablePermissions: PermissionMap = new IdentifierMap(
    [[ target, { read: true, write: true }]],
  );
  const request: HttpRequest = {} as any;
  const response: HttpResponse = {} as any;
  let operation: Operation;
  let credentialsExtractor: jest.Mocked<CredentialsExtractor>;
  let modesExtractor: jest.Mocked<ModesExtractor>;
  let permissionReader: jest.Mocked<PermissionReader>;
  let authorizer: jest.Mocked<Authorizer>;
  let source: jest.Mocked<OperationHttpHandler>;
  let handler: AuthorizingHttpHandler;

  beforeEach(async(): Promise<void> => {
    operation = {
      target,
      method: 'GET',
      preferences: {},
      body: new BasicRepresentation(),
    };

    credentialsExtractor = {
      handleSafe: jest.fn().mockResolvedValue(credentials),
    } as any;
    modesExtractor = {
      handleSafe: jest.fn().mockResolvedValue(requestedModes),
    } as any;
    permissionReader = {
      handleSafe: jest.fn().mockResolvedValue(availablePermissions),
    } as any;
    authorizer = {
      handleSafe: jest.fn(),
    } as any;
    source = {
      handleSafe: jest.fn(),
    } as any;

    handler = new AuthorizingHttpHandler(
      { credentialsExtractor, modesExtractor, permissionReader, authorizer, operationHandler: source },
    );
  });

  it('goes through all the steps and calls the source.', async(): Promise<void> => {
    await expect(handler.handle({ request, response, operation })).resolves.toBeUndefined();
    expect(credentialsExtractor.handleSafe).toHaveBeenCalledTimes(1);
    expect(credentialsExtractor.handleSafe).toHaveBeenLastCalledWith(request);
    expect(modesExtractor.handleSafe).toHaveBeenCalledTimes(1);
    expect(modesExtractor.handleSafe).toHaveBeenLastCalledWith(operation);
    expect(permissionReader.handleSafe).toHaveBeenCalledTimes(1);
    expect(permissionReader.handleSafe).toHaveBeenLastCalledWith({ credentials, requestedModes });
    expect(authorizer.handleSafe).toHaveBeenCalledTimes(1);
    expect(authorizer.handleSafe).toHaveBeenLastCalledWith({ credentials, requestedModes, availablePermissions });
    expect(source.handleSafe).toHaveBeenCalledTimes(1);
    expect(source.handleSafe).toHaveBeenLastCalledWith({ request, response, operation });
  });

  it('errors with added access modes if authorization fails.', async(): Promise<void> => {
    const error = new ForbiddenHttpError();
    authorizer.handleSafe.mockRejectedValueOnce(error);
    let handlerError: HttpError | undefined;
    try {
      await handler.handle({ request, response, operation });
    } catch (receivedError: unknown) {
      if (receivedError instanceof HttpError) {
        handlerError = receivedError;
      }
    }
    expect(handlerError).toBe(error);
    const [ bnode ] = handlerError?.metadata?.getAll(SOLID_META.terms.requestedAccess) ?? [];
    expect(bnode?.termType).toBe('BlankNode');
    const [ targetQuad ] = handlerError?.metadata?.quads(bnode as BlankNode, SOLID_META.terms.accessTarget) ?? [];
    expect(targetQuad.object.value).toBe(target.path);
    const modeQuads = handlerError?.metadata?.quads(bnode as BlankNode, SOLID_META.terms.accessMode) ?? [];
    const modes = modeQuads.map((quad): string => quad.object.value);
    expect(modes).toContain(AccessMode.read);
    expect(modes).toContain(AccessMode.write);
    expect(source.handleSafe).toHaveBeenCalledTimes(0);
  });
});

import type { RequestListener, Server } from 'node:http';
import request from 'supertest';
import type { BaseServerFactoryOptions } from '../../../src/server/BaseServerFactory';
import { BaseServerFactory } from '../../../src/server/BaseServerFactory';
import type { ServerConfigurator } from '../../../src/server/ServerConfigurator';
import { joinFilePath } from '../../../src/util/PathUtil';
import { getPort } from '../../util/Util';

const port = getPort('BaseServerFactory');

describe('A BaseServerFactory', (): void => {
  let server: Server;

  const options: [string, BaseServerFactoryOptions | undefined][] = [
    [ 'http', undefined ],
    [ 'https', {
      https: true,
      key: joinFilePath(__dirname, '../../assets/https/server.key'),
      cert: joinFilePath(__dirname, '../../assets/https/server.cert'),
    }],
  ];

  describe.each(options)('with %s', (protocol, httpOptions): void => {
    let rejectTls: string | undefined;
    let configurator: ServerConfigurator;
    let mockRequestHandler: jest.MockedFn<RequestListener>;

    beforeAll(async(): Promise<void> => {
      // Allow self-signed certificate
      rejectTls = process.env.NODE_TLS_REJECT_UNAUTHORIZED;
      process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';

      mockRequestHandler = jest.fn();

      configurator = {
        async handleSafe(serv: Server): Promise<void> {
          serv.on('request', mockRequestHandler);
        },
      } as any;

      const factory = new BaseServerFactory(configurator, httpOptions);
      server = await factory.createServer();

      server.listen(port);
    });

    beforeEach(async(): Promise<void> => {
      jest.clearAllMocks();
    });

    afterAll(async(): Promise<void> => {
      process.env.NODE_TLS_REJECT_UNAUTHORIZED = rejectTls;
      server.close();
    });

    it('emits a request event on requests.', async(): Promise<void> => {
      let resolveProm: (value: unknown) => void;
      const requestProm = new Promise((resolve): void => {
        resolveProm = resolve;
      });
      server.on('request', (req, res): void => {
        resolveProm(req);
        res.writeHead(200);
        res.end();
      });
      await request(server).get('/').set('Host', 'test.com').expect(200);

      await expect(requestProm).resolves.toEqual(expect.objectContaining({
        headers: expect.objectContaining({ host: 'test.com' }),
      }));

      expect(mockRequestHandler).toHaveBeenCalledTimes(1);
    });
  });
});

