import type { Quad } from '@rdfjs/types';
import { DataFactory } from 'n3';
import type { Operation } from '../../../../src/http/Operation';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../src/http/representation/Representation';
import type { StorageDescriber } from '../../../../src/server/description/StorageDescriber';
import { StorageDescriptionHandler } from '../../../../src/server/description/StorageDescriptionHandler';
import type { HttpRequest } from '../../../../src/server/HttpRequest';
import type { HttpResponse } from '../../../../src/server/HttpResponse';
import type { ResourceStore } from '../../../../src/storage/ResourceStore';
import { readableToQuads } from '../../../../src/util/StreamUtil';
import { PIM, RDF } from '../../../../src/util/Vocabularies';
import quad = DataFactory.quad;
import namedNode = DataFactory.namedNode;

describe('A StorageDescriptionHandler', (): void => {
  const path = '.well-known/solid';
  const request: HttpRequest = {} as any;
  const response: HttpResponse = {} as any;
  let operation: Operation;
  let representation: Representation;
  let store: jest.Mocked<ResourceStore>;
  let describer: jest.Mocked<StorageDescriber>;
  let handler: StorageDescriptionHandler;

  beforeEach(async(): Promise<void> => {
    operation = {
      method: 'GET',
      target: { path: `http://example.com/${path}` },
      body: new BasicRepresentation(),
      preferences: {},
    };

    representation = new BasicRepresentation();
    representation.metadata.add(RDF.terms.type, PIM.terms.Storage);

    store = {
      getRepresentation: jest.fn().mockResolvedValue(representation),
    } as any;

    describer = {
      canHandle: jest.fn(),
      handle: jest.fn(async(target): Promise<Quad[]> =>
        [ quad(namedNode(target.path), RDF.terms.type, PIM.terms.Storage) ]),
    } as any;

    handler = new StorageDescriptionHandler(store, path, describer);
  });

  it('only handles GET requests.', async(): Promise<void> => {
    operation.method = 'POST';
    await expect(handler.canHandle({ request, response, operation }))
      .rejects.toThrow('Only GET requests can target the storage description.');
    expect(store.getRepresentation).toHaveBeenCalledTimes(0);
  });

  it('requires the corresponding container to be a pim:Storage.', async(): Promise<void> => {
    representation.metadata.removeAll(RDF.terms.type);
    await expect(handler.canHandle({ request, response, operation }))
      .rejects.toThrow('Only supports descriptions of storage containers.');
    expect(store.getRepresentation).toHaveBeenCalledTimes(1);
    expect(store.getRepresentation).toHaveBeenLastCalledWith({ path: 'http://example.com/' }, {});
  });

  it('makes sure the describer can handle the input.', async(): Promise<void> => {
    describer.canHandle.mockRejectedValue(new Error('bad input'));
    await expect(handler.canHandle({ request, response, operation }))
      .rejects.toThrow('bad input');
  });

  it('can handle valid input.', async(): Promise<void> => {
    await expect(handler.canHandle({ request, response, operation }))
      .resolves.toBeUndefined();
    expect(store.getRepresentation).toHaveBeenCalledTimes(1);
    expect(store.getRepresentation).toHaveBeenLastCalledWith({ path: 'http://example.com/' }, {});
    expect(describer.canHandle).toHaveBeenCalledTimes(1);
    expect(describer.canHandle).toHaveBeenLastCalledWith(operation.target);
  });

  it('converts the quads from its describer into a response.', async(): Promise<void> => {
    const result = await handler.handle({ request, response, operation });
    expect(result.statusCode).toBe(200);
    expect(result.metadata?.contentType).toBe('internal/quads');
    expect(result.data).toBeDefined();
    const quads = await readableToQuads(result.data!);
    expect(quads.countQuads('http://example.com/', RDF.terms.type, PIM.terms.Storage, null)).toBe(1);
    expect(describer.handle).toHaveBeenCalledTimes(1);
    expect(describer.handle).toHaveBeenLastCalledWith({ path: 'http://example.com/' });
  });
});

import { EventEmitter } from 'node:events';
import type { IncomingMessage, Server, ServerResponse } from 'node:http';
import { Readable } from 'node:stream';
import type { Logger } from '../../../src/logging/Logger';
import { getLoggerFor } from '../../../src/logging/LogUtil';
import { HandlerServerConfigurator } from '../../../src/server/HandlerServerConfigurator';
import type { HttpHandler } from '../../../src/server/HttpHandler';
import { flushPromises } from '../../util/Util';

jest.mock('../../../src/logging/LogUtil', (): any => {
  const logger: Logger =
    { error: jest.fn(), info: jest.fn() } as any;
  return { getLoggerFor: (): Logger => logger };
});

describe('A HandlerServerConfigurator', (): void => {
  const logger: jest.Mocked<Logger> = getLoggerFor('mock') as any;
  let request: jest.Mocked<IncomingMessage>;
  let response: jest.Mocked<ServerResponse>;
  let server: Server;
  let handler: jest.Mocked<HttpHandler>;
  let listener: HandlerServerConfigurator;

  beforeEach(async(): Promise<void> => {
    // Clearing the logger mock
    jest.clearAllMocks();
    request = Readable.from('') as any;
    request.method = 'GET';
    request.url = '/';

    response = {
      headersSent: false,
      end: jest.fn(),
      setHeader: jest.fn(),
      writeHead: jest.fn(),
    } as any;
    response.end.mockImplementation((): any => {
      (response as any).headersSent = true;
    });
    response.writeHead.mockReturnValue(response);

    server = new EventEmitter() as any;

    handler = {
      handleSafe: jest.fn((): void => {
        (response as any).headersSent = true;
      }),
    } as any;

    listener = new HandlerServerConfigurator(handler);
    await listener.handle(server);
  });

  it('sends incoming requests to the handler.', async(): Promise<void> => {
    server.emit('request', request, response);
    await flushPromises();

    expect(handler.handleSafe).toHaveBeenCalledTimes(1);
    expect(handler.handleSafe).toHaveBeenLastCalledWith({ request, response });

    expect(response.setHeader).toHaveBeenCalledTimes(0);
    expect(response.writeHead).toHaveBeenCalledTimes(0);
    expect(response.end).toHaveBeenCalledTimes(0);
  });

  it('returns a 404 when the handler does not do anything.', async(): Promise<void> => {
    handler.handleSafe.mockImplementation(jest.fn());
    server.emit('request', request, response);
    await flushPromises();

    expect(response.setHeader).toHaveBeenCalledTimes(0);
    expect(response.writeHead).toHaveBeenCalledTimes(1);
    expect(response.writeHead).toHaveBeenLastCalledWith(404);
    expect(response.end).toHaveBeenCalledTimes(1);
    expect(response.end).toHaveBeenLastCalledWith();
  });

  it('writes an error to the HTTP response without the stack trace.', async(): Promise<void> => {
    handler.handleSafe.mockRejectedValueOnce(new Error('dummyError'));
    server.emit('request', request, response);
    await flushPromises();

    expect(response.setHeader).toHaveBeenCalledTimes(1);
    expect(response.setHeader).toHaveBeenLastCalledWith('Content-Type', 'text/plain; charset=utf-8');
    expect(response.writeHead).toHaveBeenCalledTimes(1);
    expect(response.writeHead).toHaveBeenLastCalledWith(500);
    expect(response.end).toHaveBeenCalledTimes(1);
    expect(response.end).toHaveBeenLastCalledWith('Error: dummyError\n');
  });

  it('does not write an error if the response had been started.', async(): Promise<void> => {
    (response as any).headersSent = true;
    handler.handleSafe.mockRejectedValueOnce(new Error('dummyError'));
    server.emit('request', request, response);
    await flushPromises();

    expect(response.setHeader).toHaveBeenCalledTimes(0);
    expect(response.writeHead).toHaveBeenCalledTimes(0);
    expect(response.end).toHaveBeenCalledTimes(1);
    expect(response.end).toHaveBeenLastCalledWith();
  });

  it('throws unknown errors if its handler throw non-Error objects.', async(): Promise<void> => {
    handler.handleSafe.mockRejectedValueOnce('apple');
    server.emit('request', request, response);
    await flushPromises();

    expect(response.setHeader).toHaveBeenCalledTimes(1);
    expect(response.setHeader).toHaveBeenLastCalledWith('Content-Type', 'text/plain; charset=utf-8');
    expect(response.writeHead).toHaveBeenCalledTimes(1);
    expect(response.writeHead).toHaveBeenLastCalledWith(500);
    expect(response.end).toHaveBeenCalledTimes(1);
    expect(response.end).toHaveBeenLastCalledWith('Unknown error: apple.\n');
  });

  it('can handle errors on the HttpResponse.', async(): Promise<void> => {
    handler.handleSafe.mockImplementationOnce(async(input): Promise<void> => {
      input.request.emit('error', new Error('bad request'));
    });
    server.emit('request', request, response);
    await flushPromises();

    expect(logger.error).toHaveBeenCalledTimes(1);
    expect(logger.error).toHaveBeenLastCalledWith('Request error: bad request');
  });

  it('prints the stack trace if that option is enabled.', async(): Promise<void> => {
    server.removeAllListeners();
    listener = new HandlerServerConfigurator(handler, true);
    await listener.handle(server);
    const error = new Error('dummyError');
    handler.handleSafe.mockRejectedValueOnce(error);
    server.emit('request', request, response);
    await flushPromises();

    expect(response.setHeader).toHaveBeenCalledTimes(1);
    expect(response.setHeader).toHaveBeenLastCalledWith('Content-Type', 'text/plain; charset=utf-8');
    expect(response.writeHead).toHaveBeenCalledTimes(1);
    expect(response.writeHead).toHaveBeenLastCalledWith(500);
    expect(response.end).toHaveBeenCalledTimes(1);
    expect(response.end).toHaveBeenLastCalledWith(`${error.stack}\n`);
  });
});

