  };
  const chunk = 'notification';
  const request: HttpRequest = {} as any;
  const response: HttpResponse = {} as any;
  let representation: BasicRepresentation;
  let route: AbsolutePathInteractionRoute;
  let streamMap: StreamingHttpMap;
  let operation: Operation;
  let generator: jest.Mocked<NotificationGenerator>;
  let serializer: jest.Mocked<NotificationSerializer>;
  let credentialsExtractor: jest.Mocked<CredentialsExtractor>;
  let permissionReader: jest.Mocked<PermissionReader>;
  let authorizer: jest.Mocked<Authorizer>;
  let handler: StreamingHttpRequestHandler;

  beforeEach(async(): Promise<void> => {
    operation = {
      method: 'GET',
      target: { path: `${path}${encodeURIComponent(topic.path)}` },
      body: new BasicRepresentation(),
      preferences: {},
    };
    representation = new BasicRepresentation(chunk, 'text/plain');

    route = new AbsolutePathInteractionRoute(path);

    streamMap = new StreamingHttpMap();

    generator = {
      canHandle: jest.fn(),
      handle: jest.fn().mockResolvedValue(notification),
    } as any;

    serializer = {
      handleSafe: jest.fn().mockResolvedValue(representation),
    } as any;

    credentialsExtractor = {
      handleSafe: jest.fn().mockResolvedValue({ public: {}}),
    } as any;

    permissionReader = {
      handleSafe: jest.fn().mockResolvedValue(new IdentifierMap([[ topic, AccessMode.read ]])),
    } as any;

    authorizer = {
      handleSafe: jest.fn(),
    } as any;

    handler = new StreamingHttpRequestHandler(
      streamMap,
      route,
      generator,
      serializer,
      credentialsExtractor,
      permissionReader,
      authorizer,
    );
  });

  it('stores streams.', async(): Promise<void> => {
    await handler.handle({ operation, request, response });
    expect([ ...streamMap.keys() ]).toHaveLength(1);
    expect(streamMap.has(channel.topic)).toBe(true);
  });

  it('removes closed streams.', async(): Promise<void> => {
    const description = await handler.handle({ operation, request, response });
    expect(streamMap.has(channel.topic)).toBe(true);
    description.data!.emit('close');
    expect(streamMap.has(channel.topic)).toBe(false);
  });

  it('removes erroring streams.', async(): Promise<void> => {
    const description = await handler.handle({ operation, request, response });
    expect(streamMap.has(channel.topic)).toBe(true);
    description.data!.emit('error');
    expect(streamMap.has(channel.topic)).toBe(false);
  });

  it('sets content type to turtle.', async(): Promise<void> => {
    const description = await handler.handle({ operation, request, response });
    expect(description.metadata?.contentType).toBe('text/turtle');
  });

  it('responds with the stream.', async(): Promise<void> => {
    const description = await handler.handle({ operation, request, response });
    expect(description.data).toBeDefined();
  });

  it('sends initial notification in a single chunk.', async(): Promise<void> => {
    const mockStream = {
      write: jest.fn(),
      on: jest.fn(),
    } as unknown as GuardedStream.Guarded<PassThrough>;
    jest.spyOn(GuardedStream, 'guardStream').mockReturnValueOnce(mockStream);
    const serializationStream = new PassThrough();
    // Use two chunks for the serialization stream
    serializationStream.write('foo');
    serializationStream.end('bar');
    serializer = {
      handleSafe: jest.fn().mockResolvedValue({
        data: serializationStream,
      }),
    } as any;
    handler = new StreamingHttpRequestHandler(
      streamMap,
      route,
      generator,
      serializer,
      credentialsExtractor,
      permissionReader,
      authorizer,
    );
    await handler.handle({ operation, request, response });
    expect(mockStream.write).toHaveBeenCalledTimes(1);
    expect(mockStream.write).toHaveBeenCalledWith('foobar');
  });

  it('logs an error if sending initial notification fails.', async(): Promise<void> => {
    serializer.handleSafe.mockRejectedValueOnce(new Error('failed'));
    await handler.handle({ operation, request, response });
    await flushPromises();
    expect(logger.error).toHaveBeenCalledTimes(1);
    expect(logger.error).toHaveBeenLastCalledWith(`Problem emitting initial notification: failed`);
  });

  it('errors on requests the Authorizer rejects.', async(): Promise<void> => {
    authorizer.handleSafe.mockRejectedValue(new Error('not allowed'));
    await expect(handler.handle({ operation, request, response })).rejects.toThrow('not allowed');
  });
});

import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import type { NotificationChannel } from '../../../../src/server/notifications/NotificationChannel';
import type { NotificationHandler } from '../../../../src/server/notifications/NotificationHandler';
import { TypedNotificationHandler } from '../../../../src/server/notifications/TypedNotificationHandler';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';

describe('A TypedNotificationHandler', (): void => {
  const topic: ResourceIdentifier = { path: 'http://example.com/foo' };
  const channel: NotificationChannel = {
    id: 'id',
    topic: topic.path,
    type: 'NotificationChannelType',
  };
  let source: jest.Mocked<NotificationHandler>;
  let handler: TypedNotificationHandler;

  beforeEach(async(): Promise<void> => {
    source = {
      canHandle: jest.fn(),
      handle: jest.fn(),
      handleSafe: jest.fn(),
    };

    handler = new TypedNotificationHandler(channel.type, source);
  });

  it('requires the input channel to have the correct type.', async(): Promise<void> => {
    await expect(handler.canHandle({ channel, topic })).resolves.toBeUndefined();

    const wrongChannel = {
      ...channel,
      type: 'somethingElse',
    };
    await expect(handler.canHandle({ channel: wrongChannel, topic })).rejects.toThrow(NotImplementedHttpError);
  });

  it('rejects input the source handler can not handle.', async(): Promise<void> => {
    source.canHandle.mockRejectedValue(new Error('bad input'));
    await expect(handler.canHandle({ channel, topic })).rejects.toThrow('bad input');
  });

  it('calls the source handle function.', async(): Promise<void> => {
    await expect(handler.handle({ channel, topic })).resolves.toBeUndefined();
    expect(source.handle).toHaveBeenCalledTimes(1);
    expect(source.handle).toHaveBeenLastCalledWith({ channel, topic });
  });
});

import { DataFactory, Store } from 'n3';
import {
  AbsolutePathInteractionRoute,
} from '../../../../../src/identity/interaction/routing/AbsolutePathInteractionRoute';
import {
  RelativePathInteractionRoute,
} from '../../../../../src/identity/interaction/routing/RelativePathInteractionRoute';
import type { Logger } from '../../../../../src/logging/Logger';
import { getLoggerFor } from '../../../../../src/logging/LogUtil';
import { CONTEXT_NOTIFICATION } from '../../../../../src/server/notifications/Notification';
import type { NotificationChannel } from '../../../../../src/server/notifications/NotificationChannel';
import type { StateHandler } from '../../../../../src/server/notifications/StateHandler';
import type {
  WebhookChannel2023,
} from '../../../../../src/server/notifications/WebhookChannel2023/WebhookChannel2023Type';
import {
  isWebhook2023Channel,
  WebhookChannel2023Type,
} from '../../../../../src/server/notifications/WebhookChannel2023/WebhookChannel2023Type';
import { NOTIFY, RDF } from '../../../../../src/util/Vocabularies';
import quad = DataFactory.quad;
import blankNode = DataFactory.blankNode;
import namedNode = DataFactory.namedNode;

jest.mock('../../../../../src/logging/LogUtil', (): any => {
  const logger: Logger =
    { error: jest.fn() } as any;
  return { getLoggerFor: (): Logger => logger };
});

jest.mock('uuid', (): any => ({ v4: (): string => '4c9b88c1-7502-4107-bb79-2a3a590c7aa3' }));

describe('A WebhookChannel2023Type', (): void => {
  const sendTo = 'http://example.org/somewhere-else';
  const topic = 'https://storage.example/resource';
  const subject = blankNode();
  let data: Store;
  let channel: WebhookChannel2023;
  const route = new AbsolutePathInteractionRoute('http://example.com/webhooks/');
  const webIdRoute = new RelativePathInteractionRoute(route, '/webid', false);
  let stateHandler: jest.Mocked<StateHandler>;
  let channelType: WebhookChannel2023Type;

  beforeEach(async(): Promise<void> => {
    data = new Store();
    data.addQuad(quad(subject, RDF.terms.type, NOTIFY.terms.WebhookChannel2023));
    data.addQuad(quad(subject, NOTIFY.terms.topic, namedNode(topic)));
    data.addQuad(quad(subject, NOTIFY.terms.sendTo, namedNode(sendTo)));

    const id = 'http://example.com/webhooks/4c9b88c1-7502-4107-bb79-2a3a590c7aa3';
    channel = {
      id,
      type: NOTIFY.WebhookChannel2023,
      topic: 'https://storage.example/resource',
      sendTo,
    };

    stateHandler = {
      handleSafe: jest.fn(),
    } as any;

    channelType = new WebhookChannel2023Type(route, webIdRoute, stateHandler);
  });

  it('exposes a utility function to verify if a channel is a webhook channel.', async(): Promise<void> => {
    expect(isWebhook2023Channel(channel)).toBe(true);

    (channel as NotificationChannel).type = 'something else';
    expect(isWebhook2023Channel(channel)).toBe(false);
  });

  it('correctly parses notification channel bodies.', async(): Promise<void> => {
    await expect(channelType.initChannel(data)).resolves.toEqual(channel);
  });

  it('adds the WebID when generating a JSON-LD representation of a channel.', async(): Promise<void> => {
    await expect(channelType.toJsonLd(channel)).resolves.toEqual({
      '@context': [
        CONTEXT_NOTIFICATION,
      ],
      id: channel.id,
      type: NOTIFY.WebhookChannel2023,
      sendTo,
      topic,
      sender: 'http://example.com/webhooks/webid',
    });
  });

  it('calls the state handler once the channel is completed.', async(): Promise<void> => {
    await channelType.completeChannel(channel);
    expect(stateHandler.handleSafe).toHaveBeenCalledTimes(1);
    expect(stateHandler.handleSafe).toHaveBeenLastCalledWith({ channel });
  });

  it('logs an error if something went wrong emitting the state notification.', async(): Promise<void> => {
    const logger = getLoggerFor('mock');
    stateHandler.handleSafe.mockRejectedValue(new Error('notification error'));

    await channelType.completeChannel(channel);
    expect(logger.error).toHaveBeenCalledTimes(1);
    expect(logger.error).toHaveBeenLastCalledWith('Error emitting state notification: notification error');
  });
});

import fetch from 'cross-fetch';
import { calculateJwkThumbprint, exportJWK, generateKeyPair, importJWK, jwtVerify } from 'jose';
import { BasicRepresentation } from '../../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../../src/http/representation/Representation';
import type { AlgJwk, JwkGenerator } from '../../../../../src/identity/configuration/JwkGenerator';
import {
  AbsolutePathInteractionRoute,
} from '../../../../../src/identity/interaction/routing/AbsolutePathInteractionRoute';
import type { Logger } from '../../../../../src/logging/Logger';
import { getLoggerFor } from '../../../../../src/logging/LogUtil';
import type { Notification } from '../../../../../src/server/notifications/Notification';
import type {
  WebhookChannel2023,
} from '../../../../../src/server/notifications/WebhookChannel2023/WebhookChannel2023Type';
import { WebhookEmitter } from '../../../../../src/server/notifications/WebhookChannel2023/WebhookEmitter';
import { NotImplementedHttpError } from '../../../../../src/util/errors/NotImplementedHttpError';
import { matchesAuthorizationScheme } from '../../../../../src/util/HeaderUtil';
import { trimTrailingSlashes } from '../../../../../src/util/PathUtil';
import { NOTIFY } from '../../../../../src/util/Vocabularies';

jest.mock('cross-fetch');

jest.mock('../../../../../src/logging/LogUtil', (): any => {
  const logger: Logger =
    { error: jest.fn(), debug: jest.fn() } as any;
  return { getLoggerFor: (): Logger => logger };
});

describe('A WebhookEmitter', (): void => {
  const fetchMock: jest.Mock = fetch as any;
  const baseUrl = 'http://example.com/';
  const serverWebId = 'http://example.com/.notifcations/webhooks/webid';
  const webIdRoute = new AbsolutePathInteractionRoute(serverWebId, false);
  const notification: Notification = {
    '@context': [
      'https://www.w3.org/ns/activitystreams',
      'https://www.w3.org/ns/solid/notification/v1',
    ],
    id: `urn:123:http://example.com/foo`,
    type: 'Update',
    object: 'http://example.com/foo',
    published: '123',
  };
  let representation: Representation;
  const channel: WebhookChannel2023 = {
    id: 'id',
    topic: 'http://example.com/foo',
    type: NOTIFY.WebhookChannel2023,
    sendTo: 'http://example.org/somewhere-else',
  };

  let privateJwk: AlgJwk;
  let publicJwk: AlgJwk;
  let jwkGenerator: jest.Mocked<JwkGenerator>;
  let emitter: WebhookEmitter;

  beforeEach(async(): Promise<void> => {
    fetchMock.mockResolvedValue({ status: 200 });

    representation = new BasicRepresentation(JSON.stringify(notification), 'application/ld+json');

    const { privateKey, publicKey } = await generateKeyPair('ES256');

    privateJwk = { ...await exportJWK(privateKey), alg: 'ES256' };
    publicJwk = { ...await exportJWK(publicKey), alg: 'ES256' };

    jwkGenerator = {
      alg: 'ES256',
      getPrivateKey: jest.fn().mockResolvedValue(privateJwk),
      getPublicKey: jest.fn().mockResolvedValue(publicJwk),
    };

    emitter = new WebhookEmitter(baseUrl, webIdRoute, jwkGenerator);
  });

  it('errors if the channel type is wrong.', async(): Promise<void> => {
    const badChannel = {
      ...channel,
      type: 'something else',
    };
    await expect(emitter.canHandle({ channel: badChannel, representation })).rejects.toThrow(NotImplementedHttpError);
  });

  it('sends out the necessary data and headers.', async(): Promise<void> => {
    const now = Date.now();
    jest.useFakeTimers();
    jest.setSystemTime(now);
    await expect(emitter.handle({ channel, representation })).resolves.toBeUndefined();

    expect(fetchMock).toHaveBeenCalledTimes(1);
    const call = fetchMock.mock.calls[0];
    expect(call[0]).toBe('http://example.org/somewhere-else');
    const { authorization, dpop, 'content-type': contentType } = call[1].headers;
    expect(contentType).toBe('application/ld+json');

    expect(matchesAuthorizationScheme('DPoP', authorization)).toBe(true);
    const encodedDpopToken = authorization.slice('DPoP '.length);

    const publicObject = await importJWK(publicJwk);

    // Check all the DPoP token fields
    const decodedDpopToken = await jwtVerify(encodedDpopToken, publicObject, { issuer: trimTrailingSlashes(baseUrl) });
    expect(decodedDpopToken.payload).toMatchObject({
      webid: serverWebId,
      azp: serverWebId,
      sub: serverWebId,
      cnf: { jkt: await calculateJwkThumbprint(publicJwk, 'sha256') },
      iat: now,
      exp: now + (20 * 60 * 1000),
      aud: [ serverWebId, 'solid' ],
      jti: expect.stringContaining('-'),
    });
    expect(decodedDpopToken.protectedHeader).toMatchObject({
      alg: 'ES256',
    });

    // CHeck the DPoP proof
    const decodedDpopProof = await jwtVerify(dpop, publicObject);
    expect(decodedDpopProof.payload).toMatchObject({
      htu: channel.sendTo,
      htm: 'POST',
      iat: now,
      jti: expect.stringContaining('-'),
    });
    expect(decodedDpopProof.protectedHeader).toMatchObject({
      alg: 'ES256',
      typ: 'dpop+jwt',
      jwk: publicJwk,
    });

    jest.useRealTimers();
  });

  it('logs an error if the fetch request receives an invalid status code.', async(): Promise<void> => {
    const logger = getLoggerFor('mock');

    fetchMock.mockResolvedValue({ status: 400, text: async(): Promise<string> => 'invalid request' });
    await expect(emitter.handle({ channel, representation })).resolves.toBeUndefined();

    expect(logger.error).toHaveBeenCalledTimes(1);
    expect(logger.error).toHaveBeenLastCalledWith(
      `There was an issue emitting a Webhook notification with target ${channel.sendTo}: invalid request`,
    );
  });
});

import { DataFactory, Parser } from 'n3';
import type { Operation } from '../../../../../src/http/Operation';
import { BasicRepresentation } from '../../../../../src/http/representation/BasicRepresentation';
import type { HttpRequest } from '../../../../../src/server/HttpRequest';
import type { HttpResponse } from '../../../../../src/server/HttpResponse';
import { WebhookWebId } from '../../../../../src/server/notifications/WebhookChannel2023/WebhookWebId';
import { readableToString } from '../../../../../src/util/StreamUtil';
import { SOLID } from '../../../../../src/util/Vocabularies';

const { namedNode, quad } = DataFactory;

describe('A WebhookWebId', (): void => {
  const request: HttpRequest = {} as any;
  const response: HttpResponse = {} as any;
  let operation: Operation;
  const baseUrl = 'http://example.com/';
  let webIdHandler: WebhookWebId;

  beforeEach(async(): Promise<void> => {
    operation = {
      method: 'GET',
      target: { path: 'http://example.com/.notifications/webhooks/webid' },
      preferences: {},
      body: new BasicRepresentation(),
    };

    webIdHandler = new WebhookWebId(baseUrl);
  });

  it('returns a solid:oidcIssuer triple.', async(): Promise<void> => {
    const turtle = await webIdHandler.handle({ operation, request, response });
    expect(turtle.statusCode).toBe(200);
    expect(turtle.metadata?.contentType).toBe('text/turtle');
    expect(turtle.data).toBeDefined();
    const quads = new Parser({ baseIRI: operation.target.path }).parse(await readableToString(turtle.data!));
    expect(quads).toHaveLength(1);
    expect(quads).toEqual([ quad(
      namedNode('http://example.com/.notifications/webhooks/webid'),
      SOLID.terms.oidcIssuer,
      namedNode('http://example.com'),
    ) ]);
  });

  it('errors if the base URL is invalid.', async(): Promise<void> => {
    expect((): any => new WebhookWebId('very invalid URL'))
      .toThrow('Invalid issuer URL: Unexpected "<very" on line 2.');
  });
});

import type { WebSocket } from 'ws';
import { BasicRepresentation } from '../../../../../src/http/representation/BasicRepresentation';
import type { NotificationChannel } from '../../../../../src/server/notifications/NotificationChannel';
import {
  WebSocket2023Emitter,
} from '../../../../../src/server/notifications/WebSocketChannel2023/WebSocket2023Emitter';
import type { SetMultiMap } from '../../../../../src/util/map/SetMultiMap';
import { WrappedSetMultiMap } from '../../../../../src/util/map/WrappedSetMultiMap';

describe('A WebSocket2023Emitter', (): void => {
  const channel: NotificationChannel = {
    id: 'id',
    topic: 'http://example.com/foo',
    type: 'type',
  };

  let webSocket: jest.Mocked<WebSocket>;
  let socketMap: SetMultiMap<string, WebSocket>;
  let emitter: WebSocket2023Emitter;

  beforeEach(async(): Promise<void> => {
    webSocket = {
      send: jest.fn(),
    } as any;

    socketMap = new WrappedSetMultiMap();

    emitter = new WebSocket2023Emitter(socketMap);
  });

  it('emits notifications to the stored WebSockets.', async(): Promise<void> => {
    socketMap.add(channel.id, webSocket);

    const representation = new BasicRepresentation('notification', 'text/plain');
    await expect(emitter.handle({ channel, representation })).resolves.toBeUndefined();
    expect(webSocket.send).toHaveBeenCalledTimes(1);
    expect(webSocket.send).toHaveBeenLastCalledWith('notification');
  });

  it('destroys the representation if there is no matching WebSocket.', async(): Promise<void> => {
    const representation = new BasicRepresentation('notification', 'text/plain');
    await expect(emitter.handle({ channel, representation })).resolves.toBeUndefined();
    expect(webSocket.send).toHaveBeenCalledTimes(0);
    expect(representation.data.destroyed).toBe(true);
  });

  it('can send to multiple matching WebSockets.', async(): Promise<void> => {
    const webSocket2: jest.Mocked<WebSocket> = {
      send: jest.fn(),
    } as any;

    socketMap.add(channel.id, webSocket);
    socketMap.add(channel.id, webSocket2);

    const representation = new BasicRepresentation('notification', 'text/plain');
    await expect(emitter.handle({ channel, representation })).resolves.toBeUndefined();
    expect(webSocket.send).toHaveBeenCalledTimes(1);
    expect(webSocket.send).toHaveBeenLastCalledWith('notification');
    expect(webSocket2.send).toHaveBeenCalledTimes(1);
    expect(webSocket2.send).toHaveBeenLastCalledWith('notification');
  });

  it('only sends to the matching WebSockets.', async(): Promise<void> => {
    const webSocket2: jest.Mocked<WebSocket> = {
      send: jest.fn(),
    } as any;
    const channel2: NotificationChannel = {
      ...channel,
      id: 'other',
    };

    socketMap.add(channel.id, webSocket);
    socketMap.add(channel2.id, webSocket2);

    const representation = new BasicRepresentation('notification', 'text/plain');
    await expect(emitter.handle({ channel, representation })).resolves.toBeUndefined();
    expect(webSocket.send).toHaveBeenCalledTimes(1);
    expect(webSocket.send).toHaveBeenLastCalledWith('notification');
    expect(webSocket2.send).toHaveBeenCalledTimes(0);
  });
});

