describe('A WebSocket2023Listener', (): void => {
  const channel: NotificationChannel = {
    id: 'id',
    topic: 'http://example.com/foo',
    type: 'type',
  };
  let webSocket: WebSocket;
  let upgradeRequest: HttpRequest;
  let storage: jest.Mocked<NotificationChannelStorage>;
  let handler: jest.Mocked<WebSocket2023Handler>;
  const baseUrl = 'http://example.com/';
  let listener: WebSocket2023Listener;

  beforeEach(async(): Promise<void> => {
    webSocket = {
      send: jest.fn(),
      close: jest.fn(),
    } as any;

    upgradeRequest = { url: `/foo/123456` } as any;

    storage = {
      get: jest.fn().mockResolvedValue(channel),
    } as any;

    handler = {
      handleSafe: jest.fn(),
    } as any;

    listener = new WebSocket2023Listener(storage, handler, baseUrl);
  });

  it('rejects requests with an unknown target.', async(): Promise<void> => {
    await expect(listener.canHandle({ upgradeRequest, webSocket })).resolves.toBeUndefined();
    storage.get.mockResolvedValue(undefined);
    await expect(listener.canHandle({ upgradeRequest, webSocket })).rejects.toThrow(NotImplementedHttpError);
  });

  it('calls the handler when receiving a valid request.', async(): Promise<void> => {
    await expect(listener.handle({ upgradeRequest, webSocket })).resolves.toBeUndefined();
    expect(webSocket.send).toHaveBeenCalledTimes(0);
    expect(webSocket.close).toHaveBeenCalledTimes(0);
    expect(handler.handleSafe).toHaveBeenCalledTimes(1);
    expect(handler.handleSafe).toHaveBeenLastCalledWith({ webSocket, channel });
  });
});

import { EventEmitter } from 'node:events';
import type { WebSocket } from 'ws';
import type { NotificationChannel } from '../../../../../src/server/notifications/NotificationChannel';
import type {
  NotificationChannelStorage,
} from '../../../../../src/server/notifications/NotificationChannelStorage';

import {
  WebSocket2023Storer,
} from '../../../../../src/server/notifications/WebSocketChannel2023/WebSocket2023Storer';
import type { SetMultiMap } from '../../../../../src/util/map/SetMultiMap';
import { WrappedSetMultiMap } from '../../../../../src/util/map/WrappedSetMultiMap';
import { flushPromises } from '../../../../util/Util';

/* eslint-disable jest/prefer-spy-on */
describe('A WebSocket2023Storer', (): void => {
  const channel: NotificationChannel = {
    id: 'id',
    topic: 'http://example.com/foo',
    type: 'type',
  };
  let webSocket: jest.Mocked<WebSocket>;
  let storage: jest.Mocked<NotificationChannelStorage>;
  let socketMap: SetMultiMap<string, WebSocket>;
  let storer: WebSocket2023Storer;

  beforeEach(async(): Promise<void> => {
    webSocket = new EventEmitter() as any;
    webSocket.send = jest.fn();
    webSocket.close = jest.fn();

    storage = {
      get: jest.fn(),
    } as any;

    socketMap = new WrappedSetMultiMap();

    storer = new WebSocket2023Storer(storage, socketMap);
  });

  it('stores WebSockets.', async(): Promise<void> => {
    await expect(storer.handle({ channel, webSocket })).resolves.toBeUndefined();
    expect([ ...socketMap.keys() ]).toHaveLength(1);
    expect(socketMap.has(channel.id)).toBe(true);
  });

  it('removes closed WebSockets.', async(): Promise<void> => {
    await expect(storer.handle({ channel, webSocket })).resolves.toBeUndefined();
    expect(socketMap.has(channel.id)).toBe(true);
    webSocket.emit('close');
    expect(socketMap.has(channel.id)).toBe(false);
  });

  it('removes erroring WebSockets.', async(): Promise<void> => {
    await expect(storer.handle({ channel, webSocket })).resolves.toBeUndefined();
    expect(socketMap.has(channel.id)).toBe(true);
    webSocket.emit('error');
    expect(socketMap.has(channel.id)).toBe(false);
  });

  it('removes expired WebSockets.', async(): Promise<void> => {
    jest.useFakeTimers();

    // Need to create class after fake timers have been enabled
    storer = new WebSocket2023Storer(storage, socketMap);

    const webSocket2: jest.Mocked<WebSocket> = new EventEmitter() as any;
    webSocket2.send = jest.fn();
    webSocket2.close = jest.fn();
    const webSocketOther: jest.Mocked<WebSocket> = new EventEmitter() as any;
    webSocketOther.send = jest.fn();
    webSocketOther.close = jest.fn();
    const channelOther: NotificationChannel = {
      ...channel,
      id: 'other',
    };
    await expect(storer.handle({ channel, webSocket })).resolves.toBeUndefined();
    await expect(storer.handle({ channel, webSocket: webSocket2 })).resolves.toBeUndefined();
    await expect(storer.handle({ channel: channelOther, webSocket: webSocketOther })).resolves.toBeUndefined();

    // `channel` expired, `channelOther` did not
    storage.get.mockImplementation((id): any => {
      if (id === channelOther.id) {
        return channelOther;
      }
    });

    jest.advanceTimersToNextTimer();

    await flushPromises();

    expect(webSocket.close).toHaveBeenCalledTimes(1);
    expect(webSocket2.close).toHaveBeenCalledTimes(1);
    expect(webSocketOther.close).toHaveBeenCalledTimes(0);

    jest.useRealTimers();
  });
});

import type { IncomingMessage } from 'node:http';
import {
  generateWebSocketUrl,
  parseWebSocketRequest,
} from '../../../../../src/server/notifications/WebSocketChannel2023/WebSocket2023Util';
import { BadRequestHttpError } from '../../../../../src/util/errors/BadRequestHttpError';

describe('WebSocket2023Util', (): void => {
  describe('#generateWebSocketUrl', (): void => {
    it('generates a WebSocket link.', async(): Promise<void> => {
      expect(generateWebSocketUrl('http://example.com/123456')).toBe('ws://example.com/123456');

      expect(generateWebSocketUrl('https://example.com/foo/bar/123456'))
        .toBe('wss://example.com/foo/bar/123456');
    });
  });

  describe('#parseWebSocketRequest', (): void => {
    it('parses the request.', async(): Promise<void> => {
      const request: IncomingMessage = { url: '/foo/bar/123%24456' } as any;
      expect(parseWebSocketRequest('http://example.com/', request)).toBe('http://example.com/foo/bar/123%24456');
    });

    it('throws an error if the url parameter is not defined.', async(): Promise<void> => {
      const request: IncomingMessage = {} as any;
      expect((): string => parseWebSocketRequest('http://example.com/', request)).toThrow(BadRequestHttpError);
    });

    it('can handle non-root base URLs.', async(): Promise<void> => {
      const request: IncomingMessage = { url: '/foo/bar/123%24456' } as any;
      expect(parseWebSocketRequest('http://example.com/foo/bar/', request)).toBe('http://example.com/foo/bar/123%24456');
    });
  });
});

import { DataFactory, Store } from 'n3';
import {
  AbsolutePathInteractionRoute,
} from '../../../../../src/identity/interaction/routing/AbsolutePathInteractionRoute';
import type { NotificationChannel } from '../../../../../src/server/notifications/NotificationChannel';
import {
  generateWebSocketUrl,
} from '../../../../../src/server/notifications/WebSocketChannel2023/WebSocket2023Util';
import type {
  WebSocketChannel2023,
} from '../../../../../src/server/notifications/WebSocketChannel2023/WebSocketChannel2023Type';
import {
  isWebSocket2023Channel,
  WebSocketChannel2023Type,
} from '../../../../../src/server/notifications/WebSocketChannel2023/WebSocketChannel2023Type';
import { NOTIFY, RDF } from '../../../../../src/util/Vocabularies';
import quad = DataFactory.quad;
import blankNode = DataFactory.blankNode;
import namedNode = DataFactory.namedNode;

jest.mock('uuid', (): any => ({ v4: (): string => '4c9b88c1-7502-4107-bb79-2a3a590c7aa3' }));

describe('A WebSocketChannel2023', (): void => {
  let data: Store;
  let channel: WebSocketChannel2023;
  const subject = blankNode();
  const topic = 'https://storage.example/resource';
  const route = new AbsolutePathInteractionRoute('http://example.com/foo');
  let channelType: WebSocketChannel2023Type;

  beforeEach(async(): Promise<void> => {
    data = new Store();
    data.addQuad(quad(subject, RDF.terms.type, NOTIFY.terms.WebSocketChannel2023));
    data.addQuad(quad(subject, NOTIFY.terms.topic, namedNode(topic)));

    const id = 'http://example.com/foo/4c9b88c1-7502-4107-bb79-2a3a590c7aa3';
    channel = {
      id,
      type: NOTIFY.WebSocketChannel2023,
      topic,
      receiveFrom: generateWebSocketUrl(id),
    };

    channelType = new WebSocketChannel2023Type(route);
  });

  it('exposes a utility function to verify if a channel is a websocket channel.', async(): Promise<void> => {
    expect(isWebSocket2023Channel(channel)).toBe(true);

    (channel as NotificationChannel).type = 'something else';
    expect(isWebSocket2023Channel(channel)).toBe(false);
  });

  it('correctly parses notification channel bodies.', async(): Promise<void> => {
    await expect(channelType.initChannel(data, {})).resolves.toEqual(channel);
  });
});

import type { RequestParser } from '../../../src/http/input/RequestParser';
import type { Operation } from '../../../src/http/Operation';
import type { ErrorHandler } from '../../../src/http/output/error/ErrorHandler';
import { ResponseDescription } from '../../../src/http/output/response/ResponseDescription';
import type { ResponseWriter } from '../../../src/http/output/ResponseWriter';
import { BasicRepresentation } from '../../../src/http/representation/BasicRepresentation';
import type { HttpRequest } from '../../../src/server/HttpRequest';
import type { HttpResponse } from '../../../src/server/HttpResponse';
import type { OperationHttpHandler } from '../../../src/server/OperationHttpHandler';
import { ParsingHttpHandler } from '../../../src/server/ParsingHttpHandler';
import { BadRequestHttpError } from '../../../src/util/errors/BadRequestHttpError';

describe('A ParsingHttpHandler', (): void => {
  const request: HttpRequest = {} as any;
  const response: HttpResponse = {} as any;
  const body = new BasicRepresentation();
  const operation: Operation = { method: 'GET', target: { path: 'http://test.com/foo' }, preferences: {}, body };
  const errorResponse = new ResponseDescription(400);
  let requestParser: jest.Mocked<RequestParser>;
  let errorHandler: jest.Mocked<ErrorHandler>;
  let responseWriter: jest.Mocked<ResponseWriter>;
  let source: jest.Mocked<OperationHttpHandler>;
  let handler: ParsingHttpHandler;

  beforeEach(async(): Promise<void> => {
    requestParser = { handleSafe: jest.fn().mockResolvedValue(operation) } as any;
    errorHandler = { handleSafe: jest.fn().mockResolvedValue(errorResponse) } as any;
    responseWriter = { handleSafe: jest.fn() } as any;

    source = {
      handleSafe: jest.fn(),
    } as any;

    handler = new ParsingHttpHandler(
      { requestParser, errorHandler, responseWriter, operationHandler: source },
    );
  });

  it('calls the source with the generated operation.', async(): Promise<void> => {
    await expect(handler.handle({ request, response })).resolves.toBeUndefined();
    expect(source.handleSafe).toHaveBeenCalledTimes(1);
    expect(source.handleSafe).toHaveBeenLastCalledWith({ operation, request, response });
    expect(errorHandler.handleSafe).toHaveBeenCalledTimes(0);
    expect(responseWriter.handleSafe).toHaveBeenCalledTimes(0);
  });

  it('calls the responseWriter if there is a response.', async(): Promise<void> => {
    const result = new ResponseDescription(200);
    source.handleSafe.mockResolvedValueOnce(result);
    await expect(handler.handle({ request, response })).resolves.toBeUndefined();
    expect(source.handleSafe).toHaveBeenCalledTimes(1);
    expect(source.handleSafe).toHaveBeenLastCalledWith({ operation, request, response });
    expect(errorHandler.handleSafe).toHaveBeenCalledTimes(0);
    expect(responseWriter.handleSafe).toHaveBeenCalledTimes(1);
    expect(responseWriter.handleSafe).toHaveBeenLastCalledWith({ response, result });
  });

  it('calls the error handler if something goes wrong.', async(): Promise<void> => {
    const error = new BadRequestHttpError('bad data');
    source.handleSafe.mockRejectedValueOnce(error);
    await expect(handler.handle({ request, response })).resolves.toBeUndefined();
    expect(errorHandler.handleSafe).toHaveBeenCalledTimes(1);
    expect(errorHandler.handleSafe).toHaveBeenLastCalledWith({ error, request });
    expect(responseWriter.handleSafe).toHaveBeenCalledTimes(1);
    expect(responseWriter.handleSafe).toHaveBeenLastCalledWith({ response, result: errorResponse });
  });

  it('creates an InternalServerError if th error was not an HttpError.', async(): Promise<void> => {
    const error = new Error('bad data');
    source.handleSafe.mockRejectedValueOnce(error);
    await expect(handler.handle({ request, response })).resolves.toBeUndefined();
    expect(errorHandler.handleSafe).toHaveBeenCalledTimes(1);
    expect(errorHandler.handleSafe).toHaveBeenLastCalledWith(expect.objectContaining({ request }));
    expect(errorHandler.handleSafe.mock.calls[0][0].error.cause).toBe(error);
    expect(responseWriter.handleSafe).toHaveBeenCalledTimes(1);
    expect(responseWriter.handleSafe).toHaveBeenLastCalledWith({ response, result: errorResponse });
  });
});

import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import type { BaseRouterHandlerArgs } from '../../../../src/server/util/BaseRouterHandler';
import { BaseRouterHandler } from '../../../../src/server/util/BaseRouterHandler';
import type { AsyncHandler } from '../../../../src/util/handlers/AsyncHandler';

class SimpleRouterHandler extends BaseRouterHandler<AsyncHandler<{ method: string; target: ResourceIdentifier }>> {
  public constructor(args: BaseRouterHandlerArgs<AsyncHandler<{ method: string; target: ResourceIdentifier }>>) {
    super(args);
  }

  public async canHandle(input: { method: string; target: ResourceIdentifier }): Promise<void> {
    await this.canHandleInput(input, input.method, input.target);
  }
}

describe('A BaseRouterHandler', (): void => {
  const baseUrl = 'http://example.com/';
  const method = 'GET';
  const target: ResourceIdentifier = { path: 'http://example.com/foo' };
  let handler: jest.Mocked<AsyncHandler<{ method: string; target: ResourceIdentifier }>>;
  let router: SimpleRouterHandler;

  beforeEach(async(): Promise<void> => {
    handler = {
      canHandle: jest.fn(),
      handle: jest.fn().mockResolvedValue('result'),
    } as any;

    router = new SimpleRouterHandler({
      baseUrl,
      handler,
      allowedPathNames: [ '^/foo$', '^/bar$' ],
      allowedMethods: [ 'GET', 'HEAD' ],
    });
  });

  it('requires the correct method.', async(): Promise<void> => {
    await expect(router.canHandle({ method: 'POST', target })).rejects.toThrow('POST is not allowed');
  });

  it('requires the path to match a given regex.', async(): Promise<void> => {
    await expect(router.canHandle({ method, target: { path: 'http://example.com/baz' }}))
      .rejects.toThrow('Cannot handle route /baz');
  });

  it('accepts valid input.', async(): Promise<void> => {
    await expect(router.canHandle({ method, target })).resolves.toBeUndefined();
  });

  it('requires the source handler to accept the input.', async(): Promise<void> => {
    handler.canHandle.mockRejectedValue(new Error('bad input'));
    await expect(router.canHandle({ method, target })).rejects.toThrow('bad input');
  });

  it('accepts all methods if no restrictions are defined.', async(): Promise<void> => {
    router = new SimpleRouterHandler({
      baseUrl,
      handler,
      allowedPathNames: [ '^/foo$', '^/bar$' ],
    });
    await expect(router.canHandle({ method: 'POST', target })).resolves.toBeUndefined();
  });

  it('accepts all paths if no restrictions are defined.', async(): Promise<void> => {
    router = new SimpleRouterHandler({
      handler,
      allowedMethods: [ 'GET', 'HEAD' ],
    });
    await expect(router.canHandle({ method, target: { path: 'http://example.com/baz' }})).resolves.toBeUndefined();
  });

  it('requires a baseUrl input if there is a path restriction.', async(): Promise<void> => {
    expect((): any => new SimpleRouterHandler({
      handler,
      allowedPathNames: [ '^/foo$', '^/bar$' ],
    })).toThrow('A value for allowedPathNames requires baseUrl to be defined.');
  });

  it('calls the source handler.', async(): Promise<void> => {
    await expect(router.handle({ method, target })).resolves.toBe('result');
    expect(handler.handle).toHaveBeenCalledTimes(1);
    expect(handler.handle).toHaveBeenLastCalledWith({ method, target });
  });
});

import type { Operation } from '../../../../src/http/Operation';
import { OkResponseDescription } from '../../../../src/http/output/response/OkResponseDescription';
import { ResponseDescription } from '../../../../src/http/output/response/ResponseDescription';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { HttpRequest } from '../../../../src/server/HttpRequest';
import type { HttpResponse } from '../../../../src/server/HttpResponse';
import type { OperationHttpHandler } from '../../../../src/server/OperationHttpHandler';
import { ConvertingOperationHttpHandler } from '../../../../src/server/util/ConvertingOperationHttpHandler';
import type {
  RepresentationConverter,
} from '../../../../src/storage/conversion/RepresentationConverter';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { guardedStreamFrom } from '../../../../src/util/StreamUtil';

describe('A ConvertingOperationHttpHandler', (): void => {
  const request: HttpRequest = {} as HttpRequest;
  const response: HttpResponse = {} as HttpResponse;
  let operation: Operation;
  const representation = new BasicRepresentation([], 'application/ld+json');
  let handlerResponse: ResponseDescription;
  const converted = new BasicRepresentation([], 'text/turtle');
  let converter: jest.Mocked<RepresentationConverter>;
  let operationHandler: jest.Mocked<OperationHttpHandler>;
  let handler: ConvertingOperationHttpHandler;

  beforeEach(async(): Promise<void> => {
    handlerResponse = new OkResponseDescription(representation.metadata, representation.data);

    operation = {
      method: 'GET',
      target: { path: 'http://example.com/foo' },
      body: new BasicRepresentation(),
      preferences: { type: { 'text/turtle': 1 }},
    };

    converter = {
      handleSafe: jest.fn().mockResolvedValue(converted),
    } as any;

    operationHandler = {
      canHandle: jest.fn(),
      handle: jest.fn().mockResolvedValue(handlerResponse),
    } as any;

    handler = new ConvertingOperationHttpHandler(converter, operationHandler);
  });

  it('can handle input if its handler can handle it.', async(): Promise<void> => {
    await expect(handler.canHandle({ request, response, operation })).resolves.toBeUndefined();

    operationHandler.canHandle.mockRejectedValueOnce(new Error('bad data'));
    await expect(handler.canHandle({ request, response, operation })).rejects.toThrow('bad data');
  });

  it('does not convert if there are no type preferences.', async(): Promise<void> => {
    delete operation.preferences.type;
    await expect(handler.handle({ request, response, operation })).resolves.toBe(handlerResponse);
    expect(converter.handleSafe).toHaveBeenCalledTimes(0);
  });

  it('does not convert if there is no output data.', async(): Promise<void> => {
    const emptyResponse = new ResponseDescription(200);
    operationHandler.handle.mockResolvedValueOnce(emptyResponse);
    await expect(handler.handle({ request, response, operation })).resolves.toBe(emptyResponse);
    expect(converter.handleSafe).toHaveBeenCalledTimes(0);
  });

  it('converts the response if requested.', async(): Promise<void> => {
    const result = await handler.handle({ request, response, operation });
    expect(result.data).toBe(converted.data);
    expect(result.metadata).toBe(converted.metadata);
    expect(result.statusCode).toBe(handlerResponse.statusCode);
    expect(converter.handleSafe).toHaveBeenCalledTimes(1);
    expect(converter.handleSafe).toHaveBeenLastCalledWith({
      identifier: operation.target,
      representation,
      preferences: operation.preferences,
    });
  });

  it('errors if there is data without metadata.', async(): Promise<void> => {
    operationHandler.handle.mockResolvedValueOnce(new ResponseDescription(200, undefined, guardedStreamFrom('')));
    await expect(handler.handle({ request, response, operation })).rejects.toThrow(InternalServerError);
  });
});

