import { BasicRepresentation } from '../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../src/http/representation/Representation';
import { BinarySliceResourceStore } from '../../../src/storage/BinarySliceResourceStore';
import type { ResourceStore } from '../../../src/storage/ResourceStore';
import { InternalServerError } from '../../../src/util/errors/InternalServerError';
import { RangeNotSatisfiedHttpError } from '../../../src/util/errors/RangeNotSatisfiedHttpError';
import { readableToString } from '../../../src/util/StreamUtil';
import { POSIX, SOLID_HTTP } from '../../../src/util/Vocabularies';

describe('A BinarySliceResourceStore', (): void => {
  const identifier = { path: 'path' };
  let representation: Representation;
  let source: jest.Mocked<ResourceStore>;
  let store: BinarySliceResourceStore;

  beforeEach(async(): Promise<void> => {
    representation = new BasicRepresentation('0123456789', 'text/plain');

    source = {
      getRepresentation: jest.fn().mockResolvedValue(representation),
    } satisfies Partial<ResourceStore> as any;

    store = new BinarySliceResourceStore(source, 5);
  });

  it('slices the data stream and stores the metadata.', async(): Promise<void> => {
    const result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: 1, end: 4 }]}});
    await expect(readableToString(result.data)).resolves.toBe('1234');
    expect(result.metadata.get(SOLID_HTTP.terms.unit)?.value).toBe('bytes');
    expect(result.metadata.get(SOLID_HTTP.terms.start)?.value).toBe('1');
    expect(result.metadata.get(SOLID_HTTP.terms.end)?.value).toBe('4');
  });

  it('uses the stream size when slicing if available.', async(): Promise<void> => {
    representation.metadata.set(POSIX.terms.size, '10');
    const result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: -4 }]}});
    await expect(readableToString(result.data)).resolves.toBe('6789');
    expect(result.metadata.get(SOLID_HTTP.terms.unit)?.value).toBe('bytes');
    expect(result.metadata.get(SOLID_HTTP.terms.start)?.value).toBe('-4');
  });

  it('limits response size to default slice size.', async(): Promise<void> => {
    representation.metadata.set(POSIX.terms.size, '10');
    const result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: 0 }]}});
    await expect(readableToString(result.data)).resolves.toBe('01234');
    expect(result.metadata.get(SOLID_HTTP.terms.unit)?.value).toBe('bytes');
    expect(result.metadata.get(SOLID_HTTP.terms.start)?.value).toBe('0');
    expect(result.metadata.get(SOLID_HTTP.terms.end)?.value).toBe('4');
  });

  it('does not go out of range when default slice size extends beyond the resource size.', async(): Promise<void> => {
    representation.metadata.set(POSIX.terms.size, '10');
    const result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: 8 }]}});
    await expect(readableToString(result.data)).resolves.toBe('89');
    expect(result.metadata.get(SOLID_HTTP.terms.unit)?.value).toBe('bytes');
    expect(result.metadata.get(SOLID_HTTP.terms.start)?.value).toBe('8');
    expect(result.metadata.get(SOLID_HTTP.terms.end)?.value).toBe('9');
  });

  it('does not add end metadata if there is none.', async(): Promise<void> => {
    const result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: 5 }]}});
    await expect(readableToString(result.data)).resolves.toBe('56789');
    expect(result.metadata.get(SOLID_HTTP.terms.unit)?.value).toBe('bytes');
    expect(result.metadata.get(SOLID_HTTP.terms.start)?.value).toBe('5');
    expect(result.metadata.get(SOLID_HTTP.terms.end)).toBeUndefined();
  });

  it('returns the original data if there is no valid range request.', async(): Promise<void> => {
    let result = await store.getRepresentation(identifier, {});
    await expect(readableToString(result.data)).resolves.toBe('0123456789');

    source.getRepresentation.mockResolvedValue(new BasicRepresentation('0123456789', 'text/plain'));
    result = await store.getRepresentation(identifier, { range: { unit: 'triples', parts: []}});
    await expect(readableToString(result.data)).resolves.toBe('0123456789');

    source.getRepresentation.mockResolvedValue(new BasicRepresentation('0123456789', 'text/plain'));
    result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: []}});
    await expect(readableToString(result.data)).resolves.toBe('0123456789');
  });

  it('returns the original data if there already is slice metadata.', async(): Promise<void> => {
    representation.metadata.set(SOLID_HTTP.terms.unit, 'triples');

    const result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: 5 }]}});
    await expect(readableToString(result.data)).resolves.toBe('0123456789');
  });

  it('only supports binary streams.', async(): Promise<void> => {
    representation.binary = false;
    await expect(store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: 5 }]}}))
      .rejects.toThrow(InternalServerError);
  });

  it('does not support multipart ranges.', async(): Promise<void> => {
    await expect(store.getRepresentation(
      identifier,
      { range: { unit: 'bytes', parts: [{ start: 5, end: 6 }, { start: 7, end: 8 }]}},
    )).rejects.toThrow(RangeNotSatisfiedHttpError);
  });

  it('closes the source stream if there was an error creating the SliceStream.', async(): Promise<void> => {
    jest.spyOn(representation.data, 'destroy').mockImplementation();
    await expect(store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: -5 }]}}))
      .rejects.toThrow(RangeNotSatisfiedHttpError);
    expect(representation.data.destroy).toHaveBeenCalledTimes(1);
  });

  it('returns all bytes when a defaultSliceSize is not provided.', async(): Promise<void> => {
    store = new BinarySliceResourceStore(source);
    const result = await store.getRepresentation(identifier, { range: { unit: 'bytes', parts: [{ start: 0 }]}});
    await expect(readableToString(result.data)).resolves.toBe('0123456789');
  });
});

import type { ResourceIdentifier } from '../../../src/http/representation/ResourceIdentifier';
import { CachedResourceSet } from '../../../src/storage/CachedResourceSet';
import type { ResourceSet } from '../../../src/storage/ResourceSet';

describe('A CachedResourceSet', (): void => {
  const identifier: ResourceIdentifier = { path: 'http://example.com/foo' };
  let source: jest.Mocked<ResourceSet>;
  let set: CachedResourceSet;

  beforeEach(async(): Promise<void> => {
    source = {
      hasResource: jest.fn().mockResolvedValue(true),
    };

    set = new CachedResourceSet(source);
  });

  it('calls the source.', async(): Promise<void> => {
    await expect(set.hasResource(identifier)).resolves.toBe(true);
    expect(source.hasResource).toHaveBeenCalledTimes(1);
    expect(source.hasResource).toHaveBeenLastCalledWith(identifier);
  });

  it('caches the result.', async(): Promise<void> => {
    await expect(set.hasResource(identifier)).resolves.toBe(true);
    await expect(set.hasResource(identifier)).resolves.toBe(true);
    expect(source.hasResource).toHaveBeenCalledTimes(1);
    expect(source.hasResource).toHaveBeenLastCalledWith(identifier);
  });

  it('caches on the identifier object itself.', async(): Promise<void> => {
    const copy = { ...identifier };
    await expect(set.hasResource(identifier)).resolves.toBe(true);
    await expect(set.hasResource(copy)).resolves.toBe(true);
    expect(source.hasResource).toHaveBeenCalledTimes(2);
    expect(source.hasResource).toHaveBeenNthCalledWith(1, identifier);
    expect(source.hasResource).toHaveBeenNthCalledWith(2, copy);
  });
});

import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { BasicConditions } from '../../../../src/storage/conditions/BasicConditions';
import type { ETagHandler } from '../../../../src/storage/conditions/ETagHandler';
import { DC } from '../../../../src/util/Vocabularies';

describe('A BasicConditions', (): void => {
  const now = new Date(2020, 10, 20);
  const tomorrow = new Date(2020, 10, 21);
  const yesterday = new Date(2020, 10, 19);
  const eTag = `"${now.getTime()}-text/turtle"`;
  let eTagHandler: jest.Mocked<ETagHandler>;
  let metadata: RepresentationMetadata;

  beforeEach(async(): Promise<void> => {
    eTagHandler = {
      getETag: jest.fn(),
      matchesETag: jest.fn().mockReturnValue(true),
      sameResourceState: jest.fn(),
    };

    metadata = new RepresentationMetadata({ [DC.modified]: now.toISOString() });
  });

  it('copies the input parameters.', async(): Promise<void> => {
    const eTags = [ '123456', 'abcdefg' ];
    const options = { matchesETag: eTags, notMatchesETag: eTags, modifiedSince: now, unmodifiedSince: now };
    expect(new BasicConditions(eTagHandler, options)).toMatchObject(options);
  });

  it('always returns false if notMatchesETag contains *.', async(): Promise<void> => {
    const conditions = new BasicConditions(eTagHandler, { notMatchesETag: [ '*' ]});
    expect(conditions.matchesMetadata(new RepresentationMetadata())).toBe(false);
  });

  it('requires matchesETag to match the provided ETag with the metadata.', async(): Promise<void> => {
    const conditions = new BasicConditions(eTagHandler, { matchesETag: [ eTag ]});
    expect(conditions.matchesMetadata(metadata)).toBe(true);
    expect(eTagHandler.matchesETag).toHaveBeenCalledTimes(1);
    expect(eTagHandler.matchesETag).toHaveBeenLastCalledWith(metadata, eTag, false);

    eTagHandler.matchesETag.mockReturnValue(false);
    expect(conditions.matchesMetadata(metadata)).toBe(false);
    expect(eTagHandler.matchesETag).toHaveBeenCalledTimes(2);
    expect(eTagHandler.matchesETag).toHaveBeenLastCalledWith(metadata, eTag, false);
  });

  it('calls the ETagHandler in strict mode if required.', async(): Promise<void> => {
    const conditions = new BasicConditions(eTagHandler, { matchesETag: [ eTag ]});
    expect(conditions.matchesMetadata(metadata, true)).toBe(true);
    expect(eTagHandler.matchesETag).toHaveBeenCalledTimes(1);
    expect(eTagHandler.matchesETag).toHaveBeenLastCalledWith(metadata, eTag, true);
  });

  it('supports all ETags if matchesETag contains *.', async(): Promise<void> => {
    eTagHandler.matchesETag.mockReturnValue(false);
    const conditions = new BasicConditions(eTagHandler, { matchesETag: [ '*' ]});
    expect(conditions.matchesMetadata(metadata, true)).toBe(true);
    expect(eTagHandler.matchesETag).toHaveBeenCalledTimes(0);
  });

  it('requires notMatchesETag to not match the provided ETag with the metadata.', async(): Promise<void> => {
    const conditions = new BasicConditions(eTagHandler, { notMatchesETag: [ eTag ]});
    expect(conditions.matchesMetadata(metadata)).toBe(false);
    expect(eTagHandler.matchesETag).toHaveBeenCalledTimes(1);
    expect(eTagHandler.matchesETag).toHaveBeenLastCalledWith(metadata, eTag, false);

    eTagHandler.matchesETag.mockReturnValue(false);
    expect(conditions.matchesMetadata(metadata)).toBe(true);
    expect(eTagHandler.matchesETag).toHaveBeenCalledTimes(2);
    expect(eTagHandler.matchesETag).toHaveBeenLastCalledWith(metadata, eTag, false);
  });

  it('requires lastModified to be after modifiedSince.', async(): Promise<void> => {
    const conditions = new BasicConditions(eTagHandler, { modifiedSince: now });
    metadata.set(DC.terms.modified, yesterday.toISOString());
    expect(conditions.matchesMetadata(metadata)).toBe(false);

    metadata.set(DC.terms.modified, now.toISOString());
    expect(conditions.matchesMetadata(metadata)).toBe(false);

    metadata.set(DC.terms.modified, tomorrow.toISOString());
    expect(conditions.matchesMetadata(metadata)).toBe(true);
  });

  it('requires lastModified to be before unmodifiedSince.', async(): Promise<void> => {
    const conditions = new BasicConditions(eTagHandler, { unmodifiedSince: now });
    metadata.set(DC.terms.modified, yesterday.toISOString());
    expect(conditions.matchesMetadata(metadata)).toBe(true);

    metadata.set(DC.terms.modified, now.toISOString());
    expect(conditions.matchesMetadata(metadata)).toBe(true);

    metadata.set(DC.terms.modified, tomorrow.toISOString());
    expect(conditions.matchesMetadata(metadata)).toBe(false);
  });

  it('checks if matchesETag contains * for resources that do not exist.', async(): Promise<void> => {
    expect(new BasicConditions(eTagHandler, { matchesETag: [ '*' ]}).matchesMetadata()).toBe(false);
    expect(new BasicConditions(eTagHandler, {}).matchesMetadata()).toBe(true);
  });
});

import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { BasicETagHandler } from '../../../../src/storage/conditions/BasicETagHandler';
import { DC } from '../../../../src/util/Vocabularies';

describe('A BasicETagHandler', (): void => {
  const now = new Date();
  const contentType = 'text/turtle';
  const eTag = `"${now.getTime()}-${contentType}"`;
  let metadata: RepresentationMetadata;
  const handler = new BasicETagHandler();

  beforeEach(async(): Promise<void> => {
    metadata = new RepresentationMetadata();
    metadata.add(DC.terms.modified, now.toISOString());
    metadata.contentType = 'text/turtle';
  });

  it('can generate ETags.', async(): Promise<void> => {
    expect(handler.getETag(metadata)).toBe(eTag);
  });

  it('does not generate an ETag if the last modified date is missing.', async(): Promise<void> => {
    metadata.removeAll(DC.terms.modified);
    expect(handler.getETag(metadata)).toBeUndefined();
  });

  it('does not generate an ETag if the content-type is missing.', async(): Promise<void> => {
    metadata.contentType = undefined;
    expect(handler.getETag(metadata)).toBeUndefined();
  });

  it('can validate an ETag against metadata.', async(): Promise<void> => {
    expect(handler.matchesETag(metadata, eTag, true)).toBe(true);
  });

  it('requires a last modified date when comparing metadata with an ETag.', async(): Promise<void> => {
    metadata.removeAll(DC.terms.modified);
    expect(handler.matchesETag(metadata, eTag, true)).toBe(false);
  });

  it('requires a content type when comparing metadata with an ETag.', async(): Promise<void> => {
    metadata.contentType = undefined;
    expect(handler.matchesETag(metadata, eTag, true)).toBe(false);
  });

  it('does not require a content type when comparing metadata with an ETag.', async(): Promise<void> => {
    metadata.contentType = undefined;
    expect(handler.matchesETag(metadata, eTag, false)).toBe(true);
  });

  it('can verify if 2 ETags reference the same resource state.', async(): Promise<void> => {
    expect(handler.sameResourceState(eTag, eTag)).toBe(true);
    expect(handler.sameResourceState(eTag, `"${now.getTime()}-text/plain"`)).toBe(true);
    expect(handler.sameResourceState(eTag, `"${now.getTime() + 1}-${contentType}"`)).toBe(false);
  });
});

import { BaseTypedRepresentationConverter } from '../../../../src/storage/conversion/BaseTypedRepresentationConverter';
import type { RepresentationConverterArgs } from '../../../../src/storage/conversion/RepresentationConverter';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';

class CustomTypedRepresentationConverter extends BaseTypedRepresentationConverter {
  public handle = jest.fn();
}

describe('A BaseTypedRepresentationConverter', (): void => {
  it('accepts strings.', async(): Promise<void> => {
    const converter = new CustomTypedRepresentationConverter('a/b', 'c/d');
    await expect(converter.getOutputTypes('a/b')).resolves.toEqual({
      'c/d': 1,
    });
  });

  it('accepts string arrays.', async(): Promise<void> => {
    const converter = new CustomTypedRepresentationConverter([ 'a/b', 'c/d' ], [ 'e/f', 'g/h' ]);
    const output = { 'e/f': 1, 'g/h': 1 };
    await expect(converter.getOutputTypes('a/b')).resolves.toEqual(output);
    await expect(converter.getOutputTypes('c/d')).resolves.toEqual(output);
  });

  it('accepts records.', async(): Promise<void> => {
    const converter = new CustomTypedRepresentationConverter({ 'a/b': 0.5 }, { 'c/d': 0.5 });
    await expect(converter.getOutputTypes('a/b')).resolves.toEqual({
      'c/d': 0.5 * 0.5,
    });
  });

  it('can not handle input without a Content-Type.', async(): Promise<void> => {
    const args: RepresentationConverterArgs = { representation: { metadata: {}}, preferences: {}} as any;
    const converter = new CustomTypedRepresentationConverter('*/*', 'b/b');
    await expect(converter.canHandle(args)).rejects.toThrow(NotImplementedHttpError);
  });

  it('can not handle a type that does not match the input types.', async(): Promise<void> => {
    const args: RepresentationConverterArgs =
      { representation: { metadata: { contentType: 'b/b' }}, preferences: {}} as any;
    const converter = new CustomTypedRepresentationConverter('a/a', 'b/b');
    await expect(converter.canHandle(args)).rejects.toThrow(NotImplementedHttpError);
  });

  it('can not handle preference that do not match the output types.', async(): Promise<void> => {
    const args: RepresentationConverterArgs =
      { representation: { metadata: { contentType: 'a/a' }}, preferences: { type: { 'c/c': 1 }}} as any;
    const converter = new CustomTypedRepresentationConverter('a/a', { 'c/*': 0, 'd/d': 1 });
    await expect(converter.canHandle(args)).rejects.toThrow(NotImplementedHttpError);
  });

  it('can handle input where the type and preferences match the converter.', async(): Promise<void> => {
    const args: RepresentationConverterArgs =
      { representation: { metadata: { contentType: 'a/a' }}, preferences: { type: { 'c/*': 1 }}} as any;
    const converter = new CustomTypedRepresentationConverter('a/a', { 'c/c': 1, 'd/d': 1 });
    await expect(converter.canHandle(args)).resolves.toBeUndefined();
  });
});

import type { Representation } from '../../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type {
  RepresentationPreferences,
  ValuePreferences,
} from '../../../../src/http/representation/RepresentationPreferences';
import { BaseTypedRepresentationConverter } from '../../../../src/storage/conversion/BaseTypedRepresentationConverter';
import { ChainedConverter } from '../../../../src/storage/conversion/ChainedConverter';
import { matchesMediaType } from '../../../../src/storage/conversion/ConversionUtil';
import type { RepresentationConverterArgs } from '../../../../src/storage/conversion/RepresentationConverter';
import { CONTENT_TYPE, POSIX } from '../../../../src/util/Vocabularies';

class DummyConverter extends BaseTypedRepresentationConverter {
  private readonly inTypes: ValuePreferences;
  private readonly outTypes: ValuePreferences;

  public constructor(inTypes: ValuePreferences, outTypes: ValuePreferences) {
    super(inTypes, outTypes);
    this.inTypes = inTypes;
    this.outTypes = outTypes;
  }

  public async handle(input: RepresentationConverterArgs): Promise<Representation> {
    // Make sure the input type is supported
    const inType = input.representation.metadata.contentType!;
    if (!Object.entries(this.inTypes).some(([ range, weight ]): boolean =>
      weight > 0 && matchesMediaType(range, inType))) {
      throw new Error(`Unsupported input: ${inType}`);
    }

    // Make sure we're sending preferences that are actually supported
    const outType = Object.keys(input.preferences.type!)[0];
    if (!Object.entries(this.outTypes).some(([ range, weight ]): boolean =>
      weight > 0 && matchesMediaType(range, outType))) {
      throw new Error(`Unsupported output: ${outType}`);
    }
    const metadata = new RepresentationMetadata(
      input.representation.metadata,
      { [CONTENT_TYPE]: outType },
    );
    return { ...input.representation, metadata };
  }
}

describe('A ChainedConverter', (): void => {
  let representation: Representation;
  let preferences: RepresentationPreferences;
  let args: RepresentationConverterArgs;

  beforeEach(async(): Promise<void> => {
    const metadata = new RepresentationMetadata('a/a');
    metadata.set(POSIX.terms.size, '500');
    representation = { metadata } as Representation;
    preferences = { type: { 'x/x': 1, 'x/*': 0.8 }};
    args = { representation, preferences, identifier: { path: 'path' }};
  });

  it('needs at least 1 converter.', async(): Promise<void> => {
    expect((): any => new ChainedConverter([])).toThrow('At least 1 converter is required.');
    expect(new ChainedConverter([ new DummyConverter({}, {}) ])).toBeInstanceOf(ChainedConverter);
  });

  it('errors if there are no content-type or preferences.', async(): Promise<void> => {
    args.representation.metadata.contentType = undefined;
    const converters = [ new DummyConverter({ 'a/a': 1 }, { 'x/x': 1 }) ];
    const converter = new ChainedConverter(converters);
    await expect(converter.canHandle(args)).rejects.toThrow('Missing Content-Type header.');
  });

  it('errors if no path can be found.', async(): Promise<void> => {
    const converters = [ new DummyConverter({ 'a/a': 1 }, { 'x/x': 1 }) ];
    const converter = new ChainedConverter(converters);

    args.representation.metadata.contentType = 'b/b';
    await expect(converter.handle(args)).rejects
      .toThrow('No conversion path could be made from b/b to x/x:1,x/*:0.8,internal/*:0.');
  });

  it('can handle situations where no conversion is required.', async(): Promise<void> => {
    const converters = [ new DummyConverter({ 'b/b': 1 }, { 'x/x': 1 }) ];
    args.representation.metadata.contentType = 'b/b';
    args.preferences.type = { 'b/*': 1, 'x/x': 0.5 };
    const converter = new ChainedConverter(converters);

    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('b/b');
    expect(result.metadata.get(POSIX.terms.size)?.value).toBe('500');
  });

  it('converts input matching the output preferences if a better output can be found.', async(): Promise<void> => {
    const converters = [ new DummyConverter({ 'b/b': 1 }, { 'x/x': 1 }) ];
    args.representation.metadata.contentType = 'b/b';
    args.preferences.type = { 'b/*': 0.5, 'x/x': 1 };
    const converter = new ChainedConverter(converters);

    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/x');
    expect(result.metadata.get(POSIX.terms.size)).toBeUndefined();
  });

  it('interprets no preferences as */*.', async(): Promise<void> => {
    const converters = [ new DummyConverter({ 'a/a': 1 }, { 'x/x': 1 }) ];
    const converter = new ChainedConverter(converters);
    args.representation.metadata.contentType = 'b/b';
    args.preferences.type = undefined;

    let result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('b/b');
    expect(result.metadata.get(POSIX.terms.size)?.value).toBe('500');

    args.preferences.type = {};
    result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('b/b');
    expect(result.metadata.get(POSIX.terms.size)?.value).toBe('500');
  });

  it('can find paths of length 1.', async(): Promise<void> => {
    const converters = [ new DummyConverter({ 'a/a': 1 }, { 'x/x': 1 }) ];
    const converter = new ChainedConverter(converters);

    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/x');
    expect(result.metadata.get(POSIX.terms.size)).toBeUndefined();
  });

  it('can find longer paths.', async(): Promise<void> => {
    // Path: a/a -> b/b -> c/c -> x/x
    const converters = [
      new DummyConverter({ 'b/b': 0.8, 'b/c': 1 }, { 'c/b': 0.9, 'c/c': 1 }),
      new DummyConverter({ 'a/a': 0.8, 'a/b': 1 }, { 'b/b': 0.9, 'b/a': 0.5 }),
      new DummyConverter({ 'd/d': 0.8, 'c/*': 1 }, { 'x/x': 0.9, 'x/a': 1 }),
    ];
    const converter = new ChainedConverter(converters);

    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/x');
    expect(result.metadata.get(POSIX.terms.size)).toBeUndefined();
  });

  it('will use the shortest path among the best found.', async(): Promise<void> => {
    // Valid paths: 0 -> 1 -> 2, 3 -> 2, 4 -> 2, 5 -> 2, *6 -> 2*
    const converters = [
      new DummyConverter({ 'a/a': 1 }, { 'b/b': 1 }),
      new DummyConverter({ 'b/b': 1 }, { 'c/c': 1 }),
      new DummyConverter({ 'c/c': 1 }, { 'x/x': 1 }),
      new DummyConverter({ '*/*': 0.5 }, { 'c/c': 1 }),
      new DummyConverter({ 'a/a': 0.8 }, { 'c/c': 1 }),
      new DummyConverter({ 'a/*': 1 }, { 'c/c': 0.5 }),
      new DummyConverter({ 'a/a': 1 }, { 'c/c': 1 }),
    ];
    const converter = new ChainedConverter(converters);

    // Only the best converters should have been called (6 and 2)
    for (const dummyConverter of converters) {
      jest.spyOn(dummyConverter, 'handle');
    }
    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/x');
    expect(result.metadata.get(POSIX.terms.size)).toBeUndefined();
    expect(converters[0].handle).toHaveBeenCalledTimes(0);
    expect(converters[1].handle).toHaveBeenCalledTimes(0);
    expect(converters[2].handle).toHaveBeenCalledTimes(1);
    expect(converters[3].handle).toHaveBeenCalledTimes(0);
    expect(converters[4].handle).toHaveBeenCalledTimes(0);
    expect(converters[5].handle).toHaveBeenCalledTimes(0);
    expect(converters[6].handle).toHaveBeenCalledTimes(1);
  });

  it('will use the intermediate content-types with the best weight.', async(): Promise<void> => {
    const converters = [
      new DummyConverter({ 'a/a': 1 }, { 'b/b': 0.8, 'c/c': 0.6 }),
      new DummyConverter({ 'b/b': 0.1, 'c/*': 0.9 }, { 'd/d': 1, 'e/e': 0.8 }),
      new DummyConverter({ 'd/*': 0.9, 'e/*': 0.1 }, { 'x/x': 1 }),
    ];
    const converter = new ChainedConverter(converters);

    const spy0 = jest.spyOn(converters[0], 'handle');
    const spy1 = jest.spyOn(converters[1], 'handle');
    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/x');
    let { metadata } = await spy0.mock.results[0].value;
    expect(metadata.contentType).toBe('c/c');
    ({ metadata } = await spy1.mock.results[0].value);
    expect(metadata.contentType).toBe('d/d');
  });

  it('will continue if an even better path can be found by adding a converter.', async(): Promise<void> => {
    // Path: a/a -> x/a -> x/x
    const converters = [
      new DummyConverter({ 'a/a': 1 }, { 'x/a': 0.9 }),
      new DummyConverter({ 'x/a': 1 }, { 'x/x': 1 }),
    ];
    const converter = new ChainedConverter(converters);

    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/x');
  });

  it('will continue if an even better path can be found through another path.', async(): Promise<void> => {
    // Path: a/a -> b/b -> x/x
    const converters = [
      new DummyConverter({ 'a/a': 1 }, { 'x/a': 0.5 }),
      new DummyConverter({ 'a/a': 1 }, { 'b/b': 1 }),
      new DummyConverter({ 'b/b': 1 }, { 'x/x': 0.6 }),
    ];
    const converter = new ChainedConverter(converters);

    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/x');
  });

  it('will stop if all future paths are worse.', async(): Promise<void> => {
    // Path: a/a -> x/a
    const converters = [
      new DummyConverter({ 'a/a': 1 }, { 'x/a': 1 }),
      new DummyConverter({ 'x/a': 1 }, { 'x/x': 0.1 }),
    ];
    const converter = new ChainedConverter(converters);

    const result = await converter.handle(args);
    expect(result.metadata.contentType).toBe('x/a');
  });

  it('calls handle when calling handleSafe.', async(): Promise<void> => {
    const converters = [ new DummyConverter({ 'a/a': 1 }, { 'x/x': 1 }) ];
    const converter = new ChainedConverter(converters);
    jest.spyOn(converter, 'handle');

    await converter.handleSafe(args);
    expect(converter.handle).toHaveBeenCalledTimes(1);
    expect(converter.handle).toHaveBeenLastCalledWith(args);
  });

  it('does not get stuck in infinite conversion loops.', async(): Promise<void> => {
    const converters = [
      new DummyConverter({ 'a/a': 1 }, { 'b/b': 1 }),
      new DummyConverter({ 'b/b': 1 }, { 'a/a': 1 }),
    ];
    const converter = new ChainedConverter(converters);

    await expect(converter.handle(args)).rejects
      .toThrow('No conversion path could be made from a/a to x/x:1,x/*:0.8,internal/*:0.');
  });
});

import fs from 'node:fs';
import fsExtra from 'fs-extra';
import arrayifyStream from 'arrayify-stream';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { ConstantConverterOptions } from '../../../../src/storage/conversion/ConstantConverter';
import { ConstantConverter } from '../../../../src/storage/conversion/ConstantConverter';
import { CONTENT_TYPE, POSIX } from '../../../../src/util/Vocabularies';

const createReadStream = jest.spyOn(fs, 'createReadStream').mockReturnValue('file contents' as any);
const stat = jest.spyOn(fsExtra, 'stat').mockReturnValue({ size: 100 } as any);

describe('A ConstantConverter', (): void => {
  const identifier = { path: 'identifier' };
  let options: ConstantConverterOptions;
  let converter: ConstantConverter;

  beforeEach(async(): Promise<void> => {
    jest.clearAllMocks();
    options = { container: true, document: true, minQuality: 1, enabledMediaRanges: [ '*/*' ], disabledMediaRanges: []};
    converter = new ConstantConverter('abc/def/index.html', 'text/html', options);
  });

  it('does not support requests without content type preferences.', async(): Promise<void> => {
    const preferences = {};
    const representation = {} as any;
    const args = { identifier, representation, preferences };

    await expect(converter.canHandle(args)).rejects.toThrow('No content type preferences specified');
  });

  it('does not support requests targeting documents if disabled in the options.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const representation = { metadata: new RepresentationMetadata() } as any;
    const args = { identifier, representation, preferences };

    converter = new ConstantConverter('abc/def/index.html', 'text/html', { document: false });

    await expect(converter.canHandle(args)).rejects.toThrow('Documents are not supported');
  });

  it('does not support requests targeting containers if disabled in the options.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const representation = { metadata: new RepresentationMetadata() } as any;
    const args = { identifier: { path: 'container/' }, representation, preferences };

    converter = new ConstantConverter('abc/def/index.html', 'text/html', { container: false });

    await expect(converter.canHandle(args)).rejects.toThrow('Containers are not supported');
  });

  it('does not support requests without matching content type preference.', async(): Promise<void> => {
    const preferences = { type: { 'text/turtle': 1 }};
    const representation = {} as any;
    const args = { identifier, representation, preferences };

    await expect(converter.canHandle(args)).rejects.toThrow('No preference for text/html');
  });

  it('does not support requests not reaching the minimum preference quality.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 0.9 }};
    const representation = {} as any;
    const args = { identifier, representation, preferences };

    await expect(converter.canHandle(args)).rejects.toThrow('Preference is lower than the specified minimum quality');
  });

  it('does not support representations that are already in the right format.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'text/html' });
    const representation = { metadata } as any;
    const args = { identifier, representation, preferences };

    await expect(converter.canHandle(args)).rejects.toThrow('Representation is already text/html');
  });

  it('does not support representations if their content-type is not enabled.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const representation = { metadata: new RepresentationMetadata({ [CONTENT_TYPE]: 'text/plain' }) } as any;
    const args = { identifier, representation, preferences };

    converter = new ConstantConverter('abc/def/index.html', 'text/html', { enabledMediaRanges: [ 'text/turtle' ]});

    await expect(converter.canHandle(args)).rejects.toThrow('text/plain is not one of the enabled media types.');
  });

  it('does not support representations if their content-type is disabled.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const representation = { metadata: new RepresentationMetadata({ [CONTENT_TYPE]: 'text/plain' }) } as any;
    const args = { identifier, representation, preferences };

    converter = new ConstantConverter('abc/def/index.html', 'text/html', { disabledMediaRanges: [ 'text/*' ]});

    await expect(converter.canHandle(args)).rejects.toThrow('text/plain is one of the disabled media types.');
  });

  it('supports representations with an unknown content type.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const metadata = new RepresentationMetadata();
    const representation = { metadata } as any;
    const args = { identifier, representation, preferences };

    await expect(converter.canHandle(args)).resolves.toBeUndefined();
  });

  it('replaces the representation of a supported request and replaces the size.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'text/turtle' });
    const representation = { metadata, data: { destroy: jest.fn() }} as any;
    const args = { identifier, representation, preferences };

    await expect(converter.canHandle(args)).resolves.toBeUndefined();
    const converted = await converter.handle(args);

    expect(representation.data.destroy).toHaveBeenCalledTimes(1);

    expect(createReadStream).toHaveBeenCalledTimes(1);
    expect(createReadStream).toHaveBeenCalledWith('abc/def/index.html', 'utf8');

    expect(converted.metadata.contentType).toBe('text/html');
    expect(converted.metadata.get(POSIX.terms.size)?.value).toBe('100');
    await expect(arrayifyStream(converted.data)).resolves.toEqual([ 'file contents' ]);
  });

  it('throws an internal error if the file cannot be accessed.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 1 }};
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'text/turtle' });
    const representation = { metadata, data: { destroy: jest.fn() }} as any;
    const args = { identifier, representation, preferences };

    await expect(converter.canHandle(args)).resolves.toBeUndefined();

    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    stat.mockImplementation(async(): Promise<never> => {
      throw new Error('file not found');
    });

    await expect(converter.handle(args)).rejects.toThrow('Unable to access file used for constant conversion.');
    expect(representation.data.destroy).toHaveBeenCalledTimes(1);
    expect(createReadStream).toHaveBeenCalledTimes(0);
  });

  it('defaults to the most permissive options.', async(): Promise<void> => {
    const preferences = { type: { 'text/html': 0.1 }};
    const metadata = new RepresentationMetadata();
    const representation = { metadata } as any;
    const args = { identifier, representation, preferences };

    converter = new ConstantConverter('abc/def/index.html', 'text/html');

    await expect(converter.canHandle(args)).resolves.toBeUndefined();

    args.identifier = { path: 'container/' };
    await expect(converter.canHandle(args)).resolves.toBeUndefined();
  });
});

import { DataFactory } from 'n3';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import { ContainerToTemplateConverter } from '../../../../src/storage/conversion/ContainerToTemplateConverter';
import { SingleRootIdentifierStrategy } from '../../../../src/util/identifiers/SingleRootIdentifierStrategy';
import { readableToString } from '../../../../src/util/StreamUtil';
import type { TemplateEngine } from '../../../../src/util/templates/TemplateEngine';
import { LDP, RDF } from '../../../../src/util/Vocabularies';

const { namedNode: nn, quad } = DataFactory;

describe('A ContainerToTemplateConverter', (): void => {
  const preferences = {};
  const identifierStrategy = new SingleRootIdentifierStrategy('http://test.com/');
  let templateEngine: jest.Mocked<TemplateEngine>;
  let converter: ContainerToTemplateConverter;

  beforeEach(async(): Promise<void> => {
    templateEngine = {
      handleSafe: jest.fn().mockResolvedValue('<html>'),
    } as any;
    converter = new ContainerToTemplateConverter(templateEngine, 'text/html', identifierStrategy);
  });

  it('supports containers.', async(): Promise<void> => {
    const container = { path: 'http://test.com/foo/bar/container/' };
    const representation = new BasicRepresentation([], 'internal/quads', false);
    await expect(converter.canHandle({ identifier: container, representation, preferences }))
      .resolves.toBeUndefined();
  });

  it('does not support documents.', async(): Promise<void> => {
    const document = { path: 'http://test.com/foo/bar/document' };
    const representation = new BasicRepresentation([], 'internal/quads', false);
    await expect(converter.canHandle({ identifier: document, representation, preferences }))
      .rejects.toThrow('Can only convert containers');
  });

  it('calls the template with the contained resources.', async(): Promise<void> => {
    const container = { path: 'http://test.com/foo/bar/my-container/' };
    const representation = new BasicRepresentation([
      quad(nn(container.path), RDF.terms.type, LDP.terms.BasicContainer),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}b`)),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}a`)),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}a`)),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}c%20c`)),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}d/`)),
      quad(nn(`${container.path}d/`), LDP.terms.contains, nn(`${container.path}d`)),
    ], 'internal/quads', false);
    const converted = await converter.handle({ identifier: container, representation, preferences });

    expect(converted.binary).toBe(true);
    expect(converted.metadata.contentType).toBe('text/html');
    await expect(readableToString(converted.data)).resolves.toBe('<html>');

    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(1);
    expect(templateEngine.handleSafe).toHaveBeenCalledWith({
      contents: {
        identifier: container.path,
        name: 'my-container',
        container: true,
        children: [
          {
            identifier: `${container.path}d/`,
            name: 'd',
            container: true,
          },
          {
            identifier: `${container.path}a`,
            name: 'a',
            container: false,
          },
          {
            identifier: `${container.path}b`,
            name: 'b',
            container: false,
          },
          {
            identifier: `${container.path}c%20c`,
            name: 'c c',
            container: false,
          },
        ],
        parents: [
          {
            identifier: 'http://test.com/',
            name: 'test.com',
            container: true,
          },
          {
            identifier: 'http://test.com/foo/',
            name: 'foo',
            container: true,
          },
          {
            identifier: 'http://test.com/foo/bar/',
            name: 'bar',
            container: true,
          },
        ],
      },
    });
  });

  it('converts the root container.', async(): Promise<void> => {
    const container = { path: 'http://test.com/' };
    const representation = new BasicRepresentation([
      quad(nn(container.path), RDF.terms.type, LDP.terms.BasicContainer),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}a`)),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}b`)),
      quad(nn(container.path), LDP.terms.contains, nn(`${container.path}c`)),
    ], 'internal/quads', false);
    await converter.handle({ identifier: container, representation, preferences });

    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(1);
    expect(templateEngine.handleSafe).toHaveBeenCalledWith({
      contents: {
        identifier: container.path,
        name: 'test.com',
        container: true,
        children: expect.objectContaining({ length: 3 }),
        parents: [],
      },
    });
  });

  it('converts an improperly named container.', async(): Promise<void> => {
    const container = { path: 'http//test.com/foo/bar' };
    const representation = new BasicRepresentation([], 'internal/quads', false);
    jest.spyOn(identifierStrategy, 'isRootContainer').mockReturnValueOnce(true);
    await converter.handle({ identifier: container, representation, preferences });

    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(1);
    expect(templateEngine.handleSafe).toHaveBeenCalledWith({
      contents: {
        identifier: container.path,
        name: container.path,
        container: true,
        children: [],
        parents: [],
      },
    });
  });
});

import 'jest-rdf';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { ContentTypeReplacer } from '../../../../src/storage/conversion/ContentTypeReplacer';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';
import { CONTENT_TYPE } from '../../../../src/util/Vocabularies';

const binary = true;
const data = { data: true };

describe('A ContentTypeReplacer', (): void => {
  const converter = new ContentTypeReplacer({
    'application/n-triples': [
      'text/turtle',
      'application/trig',
      'application/n-quads',
    ],
    'application/ld+json': 'application/json',
    'application/json': 'application/octet-stream',
    'application/octet-stream': 'internal/anything',
    'internal/anything': 'application/octet-stream',
    '*/*': 'application/octet-stream',
  });

  it('throws on an unsupported input type.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'text/plain' });
    const representation = { metadata };
    const preferences = { type: { 'application/json': 1 }};

    const result = converter.canHandle({ representation, preferences } as any);
    await expect(result).rejects.toThrow(NotImplementedHttpError);
    await expect(result).rejects.toThrow('Cannot convert from text/plain to application/json');
  });

  it('throws on an unsupported output type.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'application/n-triples' });
    const representation = { metadata };
    const preferences = { type: { 'application/json': 1 }};

    const result = converter.canHandle({ representation, preferences } as any);
    await expect(result).rejects.toThrow(NotImplementedHttpError);
    await expect(result).rejects.toThrow('Cannot convert from application/n-triples to application/json');
  });

  it('does not replace when no content type is given.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata();
    const representation = { binary, data, metadata };
    const preferences = { type: { 'application/json': 1 }};

    const result = converter.canHandle({ representation, preferences } as any);
    await expect(result).rejects.toThrow(NotImplementedHttpError);
    await expect(result).rejects.toThrow('Cannot convert from unknown to application/json');
  });

  it('replaces a supported content type when no preferences are given.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'application/n-triples' });
    const representation = { binary, data, metadata };
    const preferences = {};

    const result = await converter.handleSafe({ representation, preferences } as any);
    expect(result.binary).toBe(binary);
    expect(result.data).toBe(data);
    expect(result.metadata.contentType).toBe('text/turtle');
  });

  it('replaces a supported content type when preferences are given.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'application/n-triples' });
    const representation = { binary, data, metadata };
    const preferences = { type: { 'application/n-quads': 1 }};

    const result = await converter.handleSafe({ representation, preferences } as any);
    expect(result.binary).toBe(binary);
    expect(result.data).toBe(data);
    expect(result.metadata.contentType).toBe('application/n-quads');
  });

  it('replaces a supported wildcard type.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'text/plain' });
    const representation = { binary, data, metadata };
    const preferences = { type: { 'application/octet-stream': 1 }};

    const result = await converter.handleSafe({ representation, preferences } as any);
    expect(result.binary).toBe(binary);
    expect(result.data).toBe(data);
    expect(result.metadata.contentType).toBe('application/octet-stream');
  });

  it('picks the most preferred content type.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata({ [CONTENT_TYPE]: 'application/n-triples' });
    const representation = { binary, data, metadata };
    const preferences = { type: {
      'text/turtle': 0.5,
      'application/trig': 0.6,
      'application/n-quads': 0.4,
    }};

    const result = await converter.handleSafe({ representation, preferences } as any);
    expect(result.binary).toBe(binary);
    expect(result.data).toBe(data);
    expect(result.metadata.contentType).toBe('application/trig');
  });

  it('returns all matching output types.', async(): Promise<void> => {
    await expect(converter.getOutputTypes('application/n-triples')).resolves.toEqual({
      'text/turtle': 1,
      'application/trig': 1,
      'application/n-quads': 1,
      'application/octet-stream': 1,
      'internal/anything': 1,
    });
  });
});

import fetch, { Headers } from 'cross-fetch';
import * as fsExtra from 'fs-extra';
import type { ValuePreferences } from '../../../../src/http/representation/RepresentationPreferences';
import {
  cleanPreferences,
  ContextDocumentLoader,
  getBestPreference,
  getConversionTarget,
  getTypeWeight,
  getWeightedPreferences,
  isInternalContentType,
  matchesMediaPreferences,
  matchesMediaType,
  preferencesToString,
} from '../../../../src/storage/conversion/ConversionUtil';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';

jest.useFakeTimers();

// All of this is necessary to not break the cross-fetch imports that happen in `rdf-parse`
jest.mock('cross-fetch', (): any => {
  const mock = jest.fn();
  // Require the original module to not be mocked...
  const originalFetch = jest.requireActual('cross-fetch');
  return {
    __esModule: true,
    ...originalFetch,
    fetch: mock,
    default: mock,
  };
});

jest.mock('fs-extra', (): any => ({
  __esModule: true,
  ...jest.requireActual('fs-extra'),
}));

describe('ConversionUtil', (): void => {
  describe('ContextDocumentLoader', (): void => {
    const fetchMock: jest.Mock = fetch as any;
    const context1 = {
      '@context': {
        '@version': 1.1,
        test: 'http://example.com/context1#',
      },
    };
    const context2 = {
      '@context': {
        '@version': 1.1,
        test: 'http://example.com/context2#',
      },
    };
    const url = 'http://example.com/foo';

    function mockOnce(context: unknown): void {
      fetchMock.mockResolvedValueOnce({
        json: (): any => context,
        status: 200,
        ok: true,
        headers: new Headers({ 'content-type': 'application/ld+json' }),
      });
    }

    it('fetches the context URL.', async(): Promise<void> => {
      const loader = new ContextDocumentLoader({});

      mockOnce(context1);

      await expect(loader.load(url)).resolves.toEqual(context1);
    });

    it('returns the stored context if there is a match.', async(): Promise<void> => {
      const mock = jest.spyOn(fsExtra, 'readJsonSync');
      mock.mockReturnValueOnce(context2);

      const loader = new ContextDocumentLoader({ [url]: 'path' });

      mockOnce(context1);

      await expect(loader.load(url)).resolves.toEqual(context2);
    });

    it('caches fetched results for the given amount of time.', async(): Promise<void> => {
      const loader = new ContextDocumentLoader({}, 100);

      mockOnce(context1);
      mockOnce(context1);

      await expect(loader.load(url)).resolves.toEqual(context1);
      await expect(loader.load(url)).resolves.toEqual(context1);

      jest.advanceTimersByTime(100);

      await expect(loader.load(url)).resolves.toEqual(context1);

      expect(fetchMock).toHaveBeenCalledTimes(2);
    });
  });

  describe('#cleanPreferences', (): void => {
    it('supports all types for empty preferences.', async(): Promise<void> => {
      expect(cleanPreferences()).toEqual({ '*/*': 1, 'internal/*': 0 });
      expect(cleanPreferences({})).toEqual(expect.objectContaining({ '*/*': 1, 'internal/*': 0 }));
    });

    it('filters out internal types.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/a': 1 };
      expect(cleanPreferences(preferences)).toEqual({ 'a/a': 1, 'internal/*': 0 });
    });

    it('keeps internal types that are specifically requested.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/a': 1, 'internal/*': 0.5 };
      expect(cleanPreferences(preferences)).toEqual({ 'a/a': 1, 'internal/*': 0.5 });
    });
  });

  describe('#getTypeWeight', (): void => {
    it('returns the matching weight from the preferences.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/a': 0.8 };
      expect(getTypeWeight('a/a', preferences)).toBe(0.8);
    });

    it('returns the most specific weight.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/*': 0.5, '*/*': 0.8 };
      expect(getTypeWeight('a/a', preferences)).toBe(0.5);
    });

    it('returns 0 if no match is possible.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'b/*': 0.5, 'c/c': 0.8 };
      expect(getTypeWeight('a/a', preferences)).toBe(0);
    });

    it('errors on invalid types.', async(): Promise<void> => {
      expect((): any => getTypeWeight('unknown', {})).toThrow(InternalServerError);
      expect((): any => getTypeWeight('unknown', {})).toThrow('Unexpected media type: unknown.');
    });
  });

  describe('#getWeightedPreferences', (): void => {
    it('returns all weights in a sorted list.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'b/b': 1, 'c/c': 0.8 };
      const preferences: ValuePreferences = { 'a/*': 1, 'c/c': 0.8 };
      expect(getWeightedPreferences(types, preferences)).toEqual([
        { value: 'c/c', weight: 0.8 * 0.8 },
        { value: 'a/a', weight: 0.5 },
        { value: 'b/b', weight: 0 },
      ]);
    });
  });

  describe('#getBestPreference', (): void => {
    it('returns the best match.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'b/b': 1, 'c/c': 0.8 };
      const preferences: ValuePreferences = { 'a/*': 1, 'c/c': 0.8 };
      expect(getBestPreference(types, preferences)).toEqual({ value: 'c/c', weight: 0.8 * 0.8 });
    });

    it('returns undefined if there is no match.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'b/b': 1, 'c/c': 0.8 };
      const preferences: ValuePreferences = { 'd/*': 1, 'e/e': 0.8 };
      expect(getBestPreference(types, preferences)).toBeUndefined();
    });
  });

  describe('#getConversionTarget', (): void => {
    it('returns the best match.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'b/b': 1, 'c/c': 0.8 };
      const preferences: ValuePreferences = { 'a/*': 1, 'c/c': 0.8 };
      expect(getConversionTarget(types, preferences)).toBe('c/c');
    });

    it('matches anything if there are no preferences.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'b/b': 1, 'c/c': 0.8 };
      expect(getConversionTarget(types)).toBe('b/b');
    });

    it('returns undefined if there is no match.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'b/b': 1, 'c/c': 0.8 };
      const preferences: ValuePreferences = { 'd/*': 1, 'e/e': 0.8 };
      expect(getConversionTarget(types, preferences)).toBeUndefined();
    });

    it('does not match internal types if not in the preferences.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'internal/b': 1, 'c/c': 0.8 };
      expect(getConversionTarget(types)).toBe('c/c');
    });

    it('matches internal types if they are specifically requested.', async(): Promise<void> => {
      const types: ValuePreferences = { 'a/a': 0.5, 'internal/b': 1, 'c/c': 0.8 };
      const preferences: ValuePreferences = { 'a/*': 1, 'internal/b': 1, 'c/c': 0.8 };
      expect(getConversionTarget(types, preferences)).toBe('internal/b');
    });
  });

  describe('#matchesMediaPreferences', (): void => {
    it('returns false if there are no matches.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/x': 1, 'b/x': 0.5, 'c/x': 0 };
      expect(matchesMediaPreferences('c/x', preferences)).toBe(false);
    });

    it('returns true if there are matches.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/x': 1, 'b/x': 0.5, 'c/x': 0 };
      expect(matchesMediaPreferences('b/x', preferences)).toBe(true);
    });

    it('matches anything if there are no preferences.', async(): Promise<void> => {
      expect(matchesMediaPreferences('a/a')).toBe(true);
    });

    it('does not match internal types if not in the preferences.', async(): Promise<void> => {
      expect(matchesMediaPreferences('internal/b')).toBe(false);
    });

    it('matches internal types if they are specifically requested.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/*': 1, 'internal/b': 1, 'c/c': 0.8 };
      expect(matchesMediaPreferences('internal/b', preferences)).toBe(true);
    });
  });

  describe('#matchesMediaType', (): void => {
    it('matches all possible media types.', async(): Promise<void> => {
      expect(matchesMediaType('*/*', 'text/turtle')).toBeTruthy();
      expect(matchesMediaType('text/*', '*/*')).toBeTruthy();
      expect(matchesMediaType('text/*', 'text/turtle')).toBeTruthy();
      expect(matchesMediaType('text/plain', 'text/*')).toBeTruthy();
      expect(matchesMediaType('text/turtle', 'text/turtle')).toBeTruthy();

      expect(matchesMediaType('text/*', 'application/*')).toBeFalsy();
      expect(matchesMediaType('text/plain', 'application/*')).toBeFalsy();
      expect(matchesMediaType('text/plain', 'text/turtle')).toBeFalsy();
    });
  });

  describe('#isInternalContentType', (): void => {
    it('only returns true on internal types.', async(): Promise<void> => {
      expect(isInternalContentType('internal/quads')).toBeTruthy();

      expect(isInternalContentType()).toBeFalsy();
      expect(isInternalContentType('text/turtle')).toBeFalsy();
    });
  });

  describe('#preferencesToString', (): void => {
    it('returns a string serialization.', async(): Promise<void> => {
      const preferences: ValuePreferences = { 'a/*': 1, 'b/b': 0.8, 'c/c': 0 };
      expect(preferencesToString(preferences)).toBe('a/*:1,b/b:0.8,c/c:0');
    });
  });
});

import { DataFactory } from 'n3';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { RepresentationPreferences } from '../../../../src/http/representation/RepresentationPreferences';
import { DynamicJsonToTemplateConverter } from '../../../../src/storage/conversion/DynamicJsonToTemplateConverter';
import type { RepresentationConverterArgs } from '../../../../src/storage/conversion/RepresentationConverter';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';
import { readableToString } from '../../../../src/util/StreamUtil';
import type { TemplateEngine } from '../../../../src/util/templates/TemplateEngine';
import { CONTENT_TYPE_TERM, SOLID_META } from '../../../../src/util/Vocabularies';
import namedNode = DataFactory.namedNode;

describe('A DynamicJsonToTemplateConverter', (): void => {
  const templateFile = '/path/to/template.html.ejs';
  const identifier = { path: 'http://test.com/foo' };
  let representation: Representation;
  let preferences: RepresentationPreferences;
  let input: RepresentationConverterArgs;
  let templateEngine: jest.Mocked<TemplateEngine>;
  let converter: DynamicJsonToTemplateConverter;

  beforeEach(async(): Promise<void> => {
    representation = new BasicRepresentation('{ "json": true }', identifier, 'application/json');

    // Create dummy template metadata
    const templateNode = namedNode(templateFile);
    representation.metadata.add(SOLID_META.terms.template, templateNode);
    representation.metadata.addQuad(templateNode, CONTENT_TYPE_TERM, 'text/html');

    preferences = { type: { 'text/html': 1 }};

    input = { identifier, representation, preferences };

    templateEngine = {
      handleSafe: jest.fn().mockResolvedValue('<html>'),
    } as any;
    converter = new DynamicJsonToTemplateConverter(templateEngine);
  });

  it('can only handle JSON data.', async(): Promise<void> => {
    representation.metadata.contentType = 'text/plain';
    await expect(converter.canHandle(input)).rejects.toThrow('Only JSON data is supported');
  });

  it('can only handle preferences matching the templates found.', async(): Promise<void> => {
    input.preferences = { type: { 'text/plain': 1 }};
    await expect(converter.canHandle(input)).rejects.toThrow('No templates found matching text/plain, only text/html');
  });

  it('can handle JSON input with templates matching the preferences.', async(): Promise<void> => {
    await expect(converter.canHandle(input)).resolves.toBeUndefined();
  });

  it('rejects JSON input if no templates are defined.', async(): Promise<void> => {
    preferences.type = { 'application/json': 1 };
    representation.metadata = new RepresentationMetadata('application/json');
    await expect(converter.canHandle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('uses the input JSON as parameters for the matching template.', async(): Promise<void> => {
    const result = await converter.handle(input);
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/html');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(1);
    expect(templateEngine.handleSafe).toHaveBeenLastCalledWith({ contents: { json: true }, template: { templateFile }});
  });

  it('supports missing type preferences.', async(): Promise<void> => {
    input.preferences = {};
    const result = await converter.handle(input);
    await expect(readableToString(result.data)).resolves.toBe('<html>');
  });

  it('returns the input representation if JSON is preferred.', async(): Promise<void> => {
    input.preferences.type = { 'application/json': 1, 'text/html': 0.5 };
    await expect(converter.handle(input)).resolves.toBe(input.representation);
  });

  it('still converts if JSON is preferred but there is a JSON template.', async(): Promise<void> => {
    input.preferences.type = { 'application/json': 1 };
    const templateNode = namedNode(templateFile);
    representation.metadata.add(SOLID_META.terms.template, templateNode);
    representation.metadata.addQuad(templateNode, CONTENT_TYPE_TERM, 'application/json');
    const result = await converter.handle(input);
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(result.metadata.contentType).toBe('application/json');
  });
});

import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import { ErrorToJsonConverter } from '../../../../src/storage/conversion/ErrorToJsonConverter';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { errorTermsToMetadata } from '../../../../src/util/errors/HttpErrorUtil';
import type { OAuthErrorFields } from '../../../../src/util/errors/OAuthHttpError';
import { OAuthHttpError } from '../../../../src/util/errors/OAuthHttpError';
import { readJsonStream } from '../../../../src/util/StreamUtil';

describe('An ErrorToJsonConverter', (): void => {
  const identifier = { path: 'http://test.com/error' };
  const converter = new ErrorToJsonConverter();
  const preferences = {};

  it('supports going from errors to json.', async(): Promise<void> => {
    await expect(converter.getOutputTypes('internal/error')).resolves.toEqual({ 'application/json': 1 });
  });

  it('adds all HttpError fields.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text');
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('application/json');
    await expect(readJsonStream(result.data)).resolves.toEqual({
      name: 'BadRequestHttpError',
      message: 'error text',
      statusCode: 400,
      errorCode: 'H400',
      stack: error.stack,
      details: {},
    });
  });

  it('copies the HttpError details.', async(): Promise<void> => {
    const metadata = errorTermsToMetadata({ important: 'detail' });
    const error = new BadRequestHttpError('error text', { metadata });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('application/json');
    await expect(readJsonStream(result.data)).resolves.toEqual({
      name: 'BadRequestHttpError',
      message: 'error text',
      statusCode: 400,
      errorCode: 'H400',
      details: { important: 'detail' },
      stack: error.stack,
    });
  });

  it('adds OAuth fields if present.', async(): Promise<void> => {
    const out: OAuthErrorFields = {
      error: 'error',
      error_description: 'error_description',
      scope: 'scope',
      state: 'state',
    };
    const error = new OAuthHttpError(out, 'InvalidRequest', 400, 'error text');
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('application/json');
    await expect(readJsonStream(result.data)).resolves.toEqual({
      name: 'InvalidRequest',
      message: 'error text',
      statusCode: 400,
      errorCode: 'H400',
      stack: error.stack,
      error: 'error',
      error_description: 'error_description',
      scope: 'scope',
      state: 'state',
      details: {},
    });
  });

  it('only adds stack if it is defined.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text');
    delete error.stack;
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('application/json');
    await expect(readJsonStream(result.data)).resolves.toEqual({
      name: 'BadRequestHttpError',
      message: 'error text',
      statusCode: 400,
      errorCode: 'H400',
      details: {},
    });
  });

  it('can handle non-error causes.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text', { cause: 'not an error' });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('application/json');
    await expect(readJsonStream(result.data)).resolves.toEqual({
      name: 'BadRequestHttpError',
      message: 'error text',
      statusCode: 400,
      errorCode: 'H400',
      stack: error.stack,
      details: {},
      cause: 'not an error',
    });
  });

  it('ignores non-error causes that cannot be parsed.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text', { cause: (): number => 5 });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('application/json');
    await expect(readJsonStream(result.data)).resolves.toEqual({
      name: 'BadRequestHttpError',
      message: 'error text',
      statusCode: 400,
      errorCode: 'H400',
      stack: error.stack,
      details: {},
      cause: {},
    });
  });

  it('can handle non-HTTP errors as cause.', async(): Promise<void> => {
    const cause = new Error('error');
    const error = new BadRequestHttpError('error text', { cause });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('application/json');
    await expect(readJsonStream(result.data)).resolves.toEqual({
      name: 'BadRequestHttpError',
      message: 'error text',
      statusCode: 400,
      errorCode: 'H400',
      stack: error.stack,
      details: {},
      cause: {
        name: 'Error',
        message: 'error',
        stack: cause.stack,
      },
    });
  });
});

import 'jest-rdf';
import arrayifyStream from 'arrayify-stream';
import { DataFactory } from 'n3';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import { ErrorToQuadConverter } from '../../../../src/storage/conversion/ErrorToQuadConverter';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { DC, SOLID_ERROR } from '../../../../src/util/Vocabularies';

const { literal, namedNode, quad } = DataFactory;

describe('An ErrorToQuadConverter', (): void => {
  const identifier = { path: 'http://test.com/error' };
  const converter = new ErrorToQuadConverter();
  const preferences = {};

  it('supports going from errors to quads.', async(): Promise<void> => {
    await expect(converter.getOutputTypes('internal/error')).resolves.toEqual({ 'internal/quads': 1 });
  });

  it('adds triples for all error fields.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text');
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(false);
    expect(result.metadata.contentType).toBe('internal/quads');
    const quads = await arrayifyStream(result.data);
    expect(quads).toBeRdfIsomorphic([
      quad(namedNode(identifier.path), DC.terms.title, literal('BadRequestHttpError')),
      quad(namedNode(identifier.path), DC.terms.description, literal('error text')),
      quad(namedNode(identifier.path), SOLID_ERROR.terms.stack, literal(error.stack!)),
    ]);
  });

  it('only adds stack if it is defined.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text');
    delete error.stack;
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(false);
    expect(result.metadata.contentType).toBe('internal/quads');
    const quads = await arrayifyStream(result.data);
    expect(quads).toBeRdfIsomorphic([
      quad(namedNode(identifier.path), DC.terms.title, literal('BadRequestHttpError')),
      quad(namedNode(identifier.path), DC.terms.description, literal('error text')),
    ]);
  });
});

import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import { ErrorToTemplateConverter } from '../../../../src/storage/conversion/ErrorToTemplateConverter';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { errorTermsToMetadata } from '../../../../src/util/errors/HttpErrorUtil';
import { resolveModulePath } from '../../../../src/util/PathUtil';
import { readableToString } from '../../../../src/util/StreamUtil';
import type { TemplateEngine } from '../../../../src/util/templates/TemplateEngine';

describe('An ErrorToTemplateConverter', (): void => {
  const identifier = { path: 'http://test.com/error' };
  const mainTemplatePath = '/templates/main.html';
  const codeTemplatesPath = '/templates/codes';
  const extension = '.html';
  const contentType = 'text/html';
  const errorCode = 'E0001';
  const cause = new Error('cause');
  let templateEngine: jest.Mocked<TemplateEngine>;
  let converter: ErrorToTemplateConverter;
  const preferences = {};

  beforeEach(async(): Promise<void> => {
    templateEngine = {
      handleSafe: jest.fn().mockResolvedValue('<html>'),
    } as any;
    converter = new ErrorToTemplateConverter(
      templateEngine,
      { mainTemplatePath, codeTemplatesPath, extension, contentType },
    );
  });

  it('supports going from errors to the given content type.', async(): Promise<void> => {
    await expect(converter.getOutputTypes('internal/error')).resolves.toEqual({ 'text/html': 1 });
  });

  it('works with non-HTTP errors.', async(): Promise<void> => {
    const error = new Error('error text');
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();

    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/html');
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(1);
    expect(templateEngine.handleSafe).toHaveBeenLastCalledWith({
      contents: { name: 'Error', message: 'error text', stack: error.stack },
      template: { templateFile: mainTemplatePath },
    });
  });

  it('calls the template engine with all HTTP error fields.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text', { cause });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    templateEngine.handleSafe.mockRejectedValueOnce(new Error('error-specific template not found'));
    await expect(prom).resolves.toBeDefined();

    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/html');
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(2);
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(1, {
      contents: {},
      template: { templatePath: '/templates/codes', templateFile: 'H400.html' },
    });
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(2, {
      contents: { name: 'BadRequestHttpError', message: 'error text', stack: error.stack, cause: error.cause },
      template: { templateFile: mainTemplatePath },
    });
  });

  it('only adds stack if it is defined.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text');
    delete error.stack;
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    templateEngine.handleSafe.mockRejectedValueOnce(new Error('error-specific template not found'));
    await expect(prom).resolves.toBeDefined();

    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/html');
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(2);
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(1, {
      contents: {},
      template: { templatePath: '/templates/codes', templateFile: 'H400.html' },
    });
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(2, {
      contents: { name: 'BadRequestHttpError', message: 'error text' },
      template: { templateFile: mainTemplatePath },
    });
  });

  it('adds additional information if an error code description is found.', async(): Promise<void> => {
    const metadata = errorTermsToMetadata({ key: 'val' });
    const error = new BadRequestHttpError('error text', { errorCode, metadata });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/html');
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(2);
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(1, {
      contents: { key: 'val' },
      template: { templatePath: '/templates/codes', templateFile: 'E0001.html' },
    });
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(2, {
      contents: { name: 'BadRequestHttpError', message: 'error text', stack: error.stack, description: '<html>' },
      template: { templateFile: mainTemplatePath },
    });
  });

  it('sends an empty object for additional error code parameters if none are defined.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text', { errorCode });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();

    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/html');
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(2);
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(1, {
      contents: {},
      template: { templatePath: '/templates/codes', templateFile: 'E0001.html' },
    });
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(2, {
      contents: { name: 'BadRequestHttpError', message: 'error text', stack: error.stack, description: '<html>' },
      template: { templateFile: mainTemplatePath },
    });
  });

  it('converts errors with a code as usual if no corresponding template is found.', async(): Promise<void> => {
    const error = new BadRequestHttpError('error text', { errorCode: 'invalid' });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    templateEngine.handleSafe.mockRejectedValueOnce(new Error('error-specific template not found'));
    await expect(prom).resolves.toBeDefined();

    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/html');
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(2);
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(1, {
      contents: {},
      template: { templatePath: '/templates/codes', templateFile: 'invalid.html' },
    });
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(2, {
      contents: { name: 'BadRequestHttpError', message: 'error text', stack: error.stack },
      template: { templateFile: mainTemplatePath },
    });
  });

  it('has default template options.', async(): Promise<void> => {
    const metadata = errorTermsToMetadata({ key: 'val' });
    converter = new ErrorToTemplateConverter(templateEngine);
    const error = new BadRequestHttpError('error text', { errorCode, metadata });
    const representation = new BasicRepresentation([ error ], 'internal/error', false);
    const prom = converter.handle({ identifier, representation, preferences });
    await expect(prom).resolves.toBeDefined();
    const result = await prom;
    expect(result.binary).toBe(true);
    expect(result.metadata.contentType).toBe('text/markdown');
    await expect(readableToString(result.data)).resolves.toBe('<html>');
    expect(templateEngine.handleSafe).toHaveBeenCalledTimes(2);
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(1, {
      contents: { key: 'val' },
      template: { templatePath: resolveModulePath('templates/error/descriptions/'), templateFile: 'E0001.md.hbs' },
    });
    expect(templateEngine.handleSafe).toHaveBeenNthCalledWith(2, {
      contents: { name: 'BadRequestHttpError', message: 'error text', stack: error.stack, description: '<html>' },
      template: { templateFile: resolveModulePath('templates/error/main.md.hbs') },
    });
  });
});

