import { DataFactory } from 'n3';
import rdfSerializer from 'rdf-serialize';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { RepresentationPreferences } from '../../../../src/http/representation/RepresentationPreferences';
import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import { QuadToRdfConverter } from '../../../../src/storage/conversion/QuadToRdfConverter';
import { INTERNAL_QUADS } from '../../../../src/util/ContentTypes';
import { readableToString } from '../../../../src/util/StreamUtil';
import { DC, PREFERRED_PREFIX_TERM, SOLID_META } from '../../../../src/util/Vocabularies';

const { namedNode, triple, quad } = DataFactory;

describe('A QuadToRdfConverter', (): void => {
  const converter = new QuadToRdfConverter();
  const identifier: ResourceIdentifier = { path: 'http://example.org/foo/bar/' };
  let metadata: RepresentationMetadata;

  beforeEach((): void => {
    metadata = new RepresentationMetadata(identifier, INTERNAL_QUADS);
  });

  it('defaults to rdfSerializer preferences when given no output preferences.', async(): Promise<void> => {
    await expect(new QuadToRdfConverter().getOutputTypes(INTERNAL_QUADS))
      .resolves.toEqual(await rdfSerializer.getContentTypesPrioritized());
  });

  it('supports overriding output preferences.', async(): Promise<void> => {
    const outputPreferences = { 'text/turtle': 1 };
    await expect(new QuadToRdfConverter({ outputPreferences }).getOutputTypes(INTERNAL_QUADS))
      .resolves.toEqual(outputPreferences);
  });

  it('can handle quad to Turtle conversions.', async(): Promise<void> => {
    const representation = { metadata } as Representation;
    const preferences: RepresentationPreferences = { type: { 'text/turtle': 1 }};
    await expect(converter.canHandle({ identifier, representation, preferences })).resolves.toBeUndefined();
  });

  it('can handle quad to JSON-LD conversions.', async(): Promise<void> => {
    const representation = { metadata } as Representation;
    const preferences: RepresentationPreferences = { type: { 'application/ld+json': 1 }};
    await expect(converter.canHandle({ identifier, representation, preferences })).resolves.toBeUndefined();
  });

  it('converts quads to Turtle.', async(): Promise<void> => {
    const representation = new BasicRepresentation(
      [ triple(
        namedNode('http://test.com/s'),
        namedNode('http://test.com/p'),
        namedNode('http://test.com/o'),
      ) ],
      metadata,
    );
    const preferences: RepresentationPreferences = { type: { 'text/turtle': 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result).toMatchObject({
      binary: true,
      metadata: expect.any(RepresentationMetadata),
    });
    expect(result.metadata.contentType).toBe('text/turtle');
    await expect(readableToString(result.data)).resolves.toBe(
      `<http://test.com/s> <http://test.com/p> <http://test.com/o>.
`,
    );
  });

  it('converts quads with prefixes to Turtle.', async(): Promise<void> => {
    metadata.addQuad(DC.terms.namespace, PREFERRED_PREFIX_TERM, 'dc');
    metadata.addQuad('http://test.com/', PREFERRED_PREFIX_TERM, 'test');
    const representation = new BasicRepresentation([ triple(
      namedNode('http://test.com/s'),
      DC.terms.modified,
      namedNode('http://test.com/o'),
    ) ], metadata);
    const preferences: RepresentationPreferences = { type: { 'text/turtle': 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result.metadata.contentType).toBe('text/turtle');
    await expect(readableToString(result.data)).resolves.toBe(
      `@prefix dc: <http://purl.org/dc/terms/>.
@prefix test: <http://test.com/>.

test:s dc:modified test:o.
`,
    );
  });

  it('uses the base IRI when converting quads to Turtle.', async(): Promise<void> => {
    const representation = new BasicRepresentation([ triple(
      namedNode('http://example.org/foo/bar/'),
      namedNode('http://example.org/foo/bar/#abc'),
      namedNode('http://example.org/foo/bar/def/ghi'),
    ) ], metadata);
    const preferences: RepresentationPreferences = { type: { 'text/turtle': 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result.metadata.contentType).toBe('text/turtle');
    await expect(readableToString(result.data)).resolves.toBe(
      `<> <#abc> <def/ghi>.
`,
    );
  });

  it('converts quads to JSON-LD.', async(): Promise<void> => {
    metadata.contentType = INTERNAL_QUADS;
    const representation = new BasicRepresentation([ triple(
      namedNode('http://test.com/s'),
      namedNode('http://test.com/p'),
      namedNode('http://test.com/o'),
    ) ], metadata);
    const preferences: RepresentationPreferences = { type: { 'application/ld+json': 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result).toMatchObject({
      binary: true,
      metadata: expect.any(RepresentationMetadata),
    });
    expect(result.metadata.contentType).toBe('application/ld+json');
    await expect(readableToString(result.data)).resolves.toBe(
      `[
  {
    "@id": "http://test.com/s",
    "http://test.com/p": [
      {
        "@id": "http://test.com/o"
      }
    ]
  }
]
`,
    );
  });

  it('converts quads in the ResponseMetadata graph to the default graph.', async(): Promise<void> => {
    const representation = new BasicRepresentation([ quad(
      namedNode('http://test.com/s'),
      namedNode('http://test.com/p'),
      namedNode('http://test.com/o'),
      SOLID_META.terms.ResponseMetadata,
    ) ], metadata);
    const preferences: RepresentationPreferences = { type: { 'text/turtle': 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result).toMatchObject({
      binary: true,
      metadata: expect.any(RepresentationMetadata),
    });
    expect(result.metadata.contentType).toBe('text/turtle');
    await expect(readableToString(result.data)).resolves.toBe(
      `<http://test.com/s> <http://test.com/p> <http://test.com/o>.
`,
    );
  });
});

import 'jest-rdf';
import { Readable } from 'node:stream';
import arrayifyStream from 'arrayify-stream';
import fetch, { Headers } from 'cross-fetch';
import { DataFactory } from 'n3';
import rdfParser from 'rdf-parse';
import { PREFERRED_PREFIX_TERM, SOLID_META } from '../../../../src';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { RepresentationPreferences } from '../../../../src/http/representation/RepresentationPreferences';
import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import { RdfToQuadConverter } from '../../../../src/storage/conversion/RdfToQuadConverter';
import { INTERNAL_QUADS } from '../../../../src/util/ContentTypes';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';

const { namedNode, triple, literal, quad } = DataFactory;

// All of this is necessary to not break the cross-fetch imports that happen in `rdf-parse`
jest.mock('cross-fetch', (): any => {
  const mock = jest.fn();
  // Require the original module to not be mocked...
  const originalFetch = jest.requireActual('cross-fetch');
  return {
    __esModule: true,
    ...originalFetch,
    fetch: mock,
    default: mock,
  };
});

// Not mocking `fs` since this breaks the `rdf-parser` library
describe('A RdfToQuadConverter', (): void => {
  const fetchMock: jest.Mock = fetch as any;
  const converter = new RdfToQuadConverter();
  const identifier: ResourceIdentifier = { path: 'http://example.com/resource' };

  it('supports serializing as quads.', async(): Promise<void> => {
    const types = await rdfParser.getContentTypesPrioritized();
    // JSON is not supported
    delete types['application/json'];
    for (const [ type, priority ] of Object.entries(types)) {
      await expect(converter.getOutputTypes(type)).resolves.toEqual({ [INTERNAL_QUADS]: priority });
    }
  });

  it('may not handle application/json to quad conversion.', async(): Promise<void> => {
    await expect(converter.getOutputTypes('application/json')).resolves.toEqual({});
  });

  it('can handle turtle to quad conversions.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata('text/turtle');
    const representation = { metadata } as Representation;
    const preferences: RepresentationPreferences = { type: { [INTERNAL_QUADS]: 1 }};
    await expect(converter.canHandle({ identifier, representation, preferences })).resolves.toBeUndefined();
  });

  it('can handle JSON-LD to quad conversions.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata('application/ld+json');
    const representation = { metadata } as Representation;
    const preferences: RepresentationPreferences = { type: { [INTERNAL_QUADS]: 1 }};
    await expect(converter.canHandle({ identifier, representation, preferences })).resolves.toBeUndefined();
  });

  it('converts turtle to quads.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata('text/turtle');
    const representation = new BasicRepresentation(
      '<http://test.com/s> <http://test.com/p> <http://test.com/o>.',
      metadata,
    );
    const preferences: RepresentationPreferences = { type: { [INTERNAL_QUADS]: 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result).toEqual({
      binary: false,
      data: expect.any(Readable),
      metadata: expect.any(RepresentationMetadata),
    });
    expect(result.metadata.contentType).toEqual(INTERNAL_QUADS);
    await expect(arrayifyStream(result.data)).resolves.toEqualRdfQuadArray([ triple(
      namedNode('http://test.com/s'),
      namedNode('http://test.com/p'),
      namedNode('http://test.com/o'),
    ) ]);
  });

  it('emits on prefixes when converting turtle to quads.', async(): Promise<void> => {
    const id: ResourceIdentifier = { path: 'http://example.com/resource' };
    const metadata = new RepresentationMetadata('text/turtle');
    const representation = new BasicRepresentation(
      `@prefix foaf: <http://xmlns.com/foaf/0.1/> .

      <http://test.com/s> a foaf:Person.`,
      metadata,
    );
    const preferences: RepresentationPreferences = { type: { [INTERNAL_QUADS]: 1 }};
    const result = await converter.handle({ identifier: id, representation, preferences });
    expect(result).toEqual({
      binary: false,
      data: expect.any(Readable),
      metadata: expect.any(RepresentationMetadata),
    });
    expect(result.metadata.contentType).toEqual(INTERNAL_QUADS);
    await arrayifyStream(result.data);

    expect(result.metadata.quads(null, PREFERRED_PREFIX_TERM, null)).toBeRdfIsomorphic([
      quad(namedNode('http://xmlns.com/foaf/0.1/'), PREFERRED_PREFIX_TERM, literal('foaf'), SOLID_META.terms.ResponseMetadata),
    ]);
  });

  it('converts JSON-LD to quads.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata('application/ld+json');
    const representation = new BasicRepresentation(
      '{"@id": "http://test.com/s", "http://test.com/p": { "@id": "http://test.com/o" }}',
      metadata,
    );
    const preferences: RepresentationPreferences = { type: { [INTERNAL_QUADS]: 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result).toEqual({
      binary: false,
      data: expect.any(Readable),
      metadata: expect.any(RepresentationMetadata),
    });
    expect(result.metadata.contentType).toEqual(INTERNAL_QUADS);
    await expect(arrayifyStream(result.data)).resolves.toEqualRdfQuadArray([ triple(
      namedNode('http://test.com/s'),
      namedNode('http://test.com/p'),
      namedNode('http://test.com/o'),
    ) ]);
  });

  it('throws an BadRequestHttpError on invalid triple data.', async(): Promise<void> => {
    const metadata = new RepresentationMetadata('text/turtle');
    const representation = new BasicRepresentation(
      '<http://test.com/s> <http://test.com/p> <http://test.co',
      metadata,
    );
    const preferences: RepresentationPreferences = { type: { [INTERNAL_QUADS]: 1 }};
    const result = await converter.handle({ identifier, representation, preferences });
    expect(result).toEqual({
      binary: false,
      data: expect.any(Readable),
      metadata: expect.any(RepresentationMetadata),
    });
    expect(result.metadata.contentType).toEqual(INTERNAL_QUADS);
    await expect(arrayifyStream(result.data)).rejects.toThrow(BadRequestHttpError);
  });

  it('can use locally stored contexts.', async(): Promise<void> => {
    const fetchedContext = {
      '@context': {
        '@version': 1.1,
        test: 'http://example.com/context2#',
        testPredicate2: { '@id': 'test:predicate2' },
      },
    };
    // This depends on the fields needed by the `jsonld-context-parser` so could break if library changes
    fetchMock.mockResolvedValueOnce({
      json: (): any => fetchedContext,
      status: 200,
      ok: true,
      headers: new Headers({ 'content-type': 'application/ld+json' }),
    });

    const contextConverter = new RdfToQuadConverter(
      { 'http://example.com/context.jsonld': '@css:test/assets/contexts/test.jsonld' },
    );
    const jsonld = {
      '@context': [ 'http://example.com/context.jsonld', 'http://example.com/context2.jsonld' ],
      '@id': 'http://example.com/resource',
      testPredicate: 123,
      testPredicate2: 456,
    };
    const representation = new BasicRepresentation(JSON.stringify(jsonld), 'application/ld+json');
    const preferences: RepresentationPreferences = { type: { [INTERNAL_QUADS]: 1 }};
    const result = await contextConverter.handle({ identifier, representation, preferences });
    await expect(arrayifyStream(result.data)).resolves.toEqualRdfQuadArray([ triple(
      namedNode('http://example.com/resource'),
      namedNode('http://example.com/context#predicate'),
      literal(123),
    ), triple(
      namedNode('http://example.com/resource'),
      namedNode('http://example.com/context2#predicate2'),
      literal(456),
    ) ]);
  });
});

import 'jest-rdf';
import type { Readable } from 'node:stream';
import arrayifyStream from 'arrayify-stream';
import { DataFactory, Store } from 'n3';
import type { Conditions } from '../../../src';
import { CONTENT_TYPE_TERM, XSD } from '../../../src';
import type { AuxiliaryStrategy } from '../../../src/http/auxiliary/AuxiliaryStrategy';
import { BasicRepresentation } from '../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../src/http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../../src/http/representation/ResourceIdentifier';
import type { DataAccessor } from '../../../src/storage/accessors/DataAccessor';
import { DataAccessorBasedStore } from '../../../src/storage/DataAccessorBasedStore';
import { INTERNAL_QUADS } from '../../../src/util/ContentTypes';
import { BadRequestHttpError } from '../../../src/util/errors/BadRequestHttpError';
import { ConflictHttpError } from '../../../src/util/errors/ConflictHttpError';
import { ForbiddenHttpError } from '../../../src/util/errors/ForbiddenHttpError';
import { MethodNotAllowedHttpError } from '../../../src/util/errors/MethodNotAllowedHttpError';
import { NotFoundHttpError } from '../../../src/util/errors/NotFoundHttpError';
import { NotImplementedHttpError } from '../../../src/util/errors/NotImplementedHttpError';
import { PreconditionFailedHttpError } from '../../../src/util/errors/PreconditionFailedHttpError';
import type { Guarded } from '../../../src/util/GuardedStream';
import { ContentType } from '../../../src/util/Header';
import { SingleRootIdentifierStrategy } from '../../../src/util/identifiers/SingleRootIdentifierStrategy';
import { trimTrailingSlashes } from '../../../src/util/PathUtil';
import { guardedStreamFrom } from '../../../src/util/StreamUtil';
import { AS, CONTENT_TYPE, DC, LDP, PIM, RDF, SOLID_AS, SOLID_HTTP, SOLID_META } from '../../../src/util/Vocabularies';
import { SimpleSuffixStrategy } from '../../util/SimpleSuffixStrategy';

const { namedNode, quad, literal } = DataFactory;

const GENERATED_PREDICATE = namedNode('generated');

class SimpleDataAccessor implements DataAccessor {
  public readonly data: Record<string, Representation> = {};

  private checkExists(identifier: ResourceIdentifier): void {
    if (!this.data[identifier.path]) {
      throw new NotFoundHttpError();
    }
  }

  public async canHandle(representation: Representation): Promise<void> {
    if (!representation.binary) {
      throw new BadRequestHttpError();
    }
  }

  public async deleteResource(identifier: ResourceIdentifier): Promise<void> {
    this.checkExists(identifier);
    delete this.data[identifier.path];
  }

  public async getData(identifier: ResourceIdentifier): Promise<Guarded<Readable>> {
    this.checkExists(identifier);
    return this.data[identifier.path].data;
  }

  public async getMetadata(identifier: ResourceIdentifier): Promise<RepresentationMetadata> {
    this.checkExists(identifier);
    const metadata = new RepresentationMetadata(this.data[identifier.path].metadata);
    metadata.add(GENERATED_PREDICATE, 'data', SOLID_META.terms.ResponseMetadata);
    return metadata;
  }

  public async writeMetadata(identifier: ResourceIdentifier, metadata: RepresentationMetadata): Promise<void> {
    this.checkExists({ path: metadata.identifier.value });
    this.data[metadata.identifier.value].metadata = metadata;
  }

  public async* getChildren(identifier: ResourceIdentifier): AsyncIterableIterator<RepresentationMetadata> {
    // Find all keys that look like children of the container
    const children = Object.keys(this.data).filter((name): boolean =>
      name.startsWith(identifier.path) &&
      name.length > identifier.path.length &&
      !trimTrailingSlashes(name.slice(identifier.path.length)).includes('/'));
    yield* children.map((name): RepresentationMetadata => new RepresentationMetadata({ path: name }));
  }

  public async modifyResource(): Promise<void> {
    throw new Error('modify');
  }

  public async writeContainer(identifier: ResourceIdentifier, metadata?: RepresentationMetadata): Promise<void> {
    this.data[identifier.path] = { metadata } as Representation;
  }

  public async writeDocument(identifier: ResourceIdentifier, data: Readable, metadata?: RepresentationMetadata):
  Promise<void> {
    this.data[identifier.path] = { data, metadata } as Representation;
  }
}

describe('A DataAccessorBasedStore', (): void => {
  const now = new Date(2020, 5, 12);
  const later = new Date(2021, 6, 13);
  let mockDate: jest.SpyInstance;
  let store: DataAccessorBasedStore;
  let accessor: SimpleDataAccessor;
  const root = 'http://test.com/';
  const identifierStrategy = new SingleRootIdentifierStrategy(root);
  let auxiliaryStrategy: AuxiliaryStrategy;
  let containerMetadata: RepresentationMetadata;
  let representation: Representation;
  const failingConditions: Conditions = { matchesMetadata: (): boolean => false };
  const resourceData = 'text';
  const metadataStrategy = new SimpleSuffixStrategy('.meta');

  beforeEach(async(): Promise<void> => {
    mockDate = jest.spyOn(globalThis, 'Date').mockReturnValue(now as any);

    accessor = new SimpleDataAccessor();

    auxiliaryStrategy = new SimpleSuffixStrategy('.dummy');

    store = new DataAccessorBasedStore(accessor, identifierStrategy, auxiliaryStrategy, metadataStrategy);

    containerMetadata = new RepresentationMetadata(
      { [RDF.type]: [
        namedNode(LDP.Resource),
        namedNode(LDP.Container),
        namedNode(LDP.BasicContainer),
      ]},
    );
    const rootMetadata = new RepresentationMetadata(containerMetadata);
    rootMetadata.identifier = namedNode(root);
    accessor.data[root] = { metadata: rootMetadata } as Representation;

    representation = {
      binary: true,
      data: guardedStreamFrom([ resourceData ]),
      metadata: new RepresentationMetadata(
        { [CONTENT_TYPE]: 'text/plain', [RDF.type]: namedNode(LDP.Resource) },
      ),
      isEmpty: false,
    };
  });

  describe('getting a Representation', (): void => {
    it('will 404 if the identifier does not contain the root.', async(): Promise<void> => {
      await expect(store.getRepresentation({ path: 'verybadpath' })).rejects.toThrow(NotFoundHttpError);
    });

    it('will return the stored representation for resources.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      representation.metadata.identifier = namedNode(resourceID.path);
      accessor.data[resourceID.path] = representation;
      const result = await store.getRepresentation(resourceID);
      expect(result).toMatchObject({ binary: true });
      await expect(arrayifyStream(result.data)).resolves.toEqual([ resourceData ]);
      expect(result.metadata.contentType).toBe('text/plain');
      expect(result.metadata.get(namedNode('AUXILIARY'))?.value)
        .toBe(auxiliaryStrategy.getAuxiliaryIdentifier(resourceID).path);
    });

    it('will return a data stream that matches the metadata for containers.', async(): Promise<void> => {
      const resourceID = { path: `${root}container/` };
      containerMetadata.identifier = namedNode(resourceID.path);
      accessor.data[resourceID.path] = { metadata: containerMetadata } as Representation;
      const metaMirror = new RepresentationMetadata(containerMetadata);
      // Generated metadata will have its graph removed
      metaMirror.add(GENERATED_PREDICATE, 'data', SOLID_META.terms.ResponseMetadata);
      await auxiliaryStrategy.addMetadata(metaMirror);
      const result = await store.getRepresentation(resourceID);
      expect(result).toMatchObject({ binary: false });
      await expect(arrayifyStream(result.data)).resolves.toBeRdfIsomorphic(metaMirror.quads());
      expect(result.metadata.contentType).toEqual(INTERNAL_QUADS);
      expect(result.metadata.get(namedNode('AUXILIARY'))?.value)
        .toBe(auxiliaryStrategy.getAuxiliaryIdentifier(resourceID).path);
    });

    it('will remove containment triples referencing auxiliary resources.', async(): Promise<void> => {
      const resourceID = { path: `${root}container/` };
      containerMetadata.identifier = namedNode(resourceID.path);
      accessor.data[resourceID.path] = { metadata: containerMetadata } as Representation;
      accessor.data[`${resourceID.path}.dummy`] = representation;
      accessor.data[`${resourceID.path}resource`] = representation;
      accessor.data[`${resourceID.path}resource.dummy`] = representation;
      const result = await store.getRepresentation(resourceID);
      const contains = result.metadata.getAll(LDP.terms.contains);
      expect(contains).toHaveLength(1);
      expect(contains[0].value).toBe(`${resourceID.path}resource`);
    });

    it('will return the stored representation for metadata resources.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const metaResourceID = { path: `${root}resource.meta` };
      representation.metadata.identifier = namedNode(resourceID.path);

      accessor.data[resourceID.path] = representation;

      const result = await store.getRepresentation(metaResourceID);
      const quads = await arrayifyStream(result.data);
      expect(result).toMatchObject({ binary: false });
      expect(new Store(quads)).toBeRdfDatasetContaining(
        quad(namedNode(resourceID.path), CONTENT_TYPE_TERM, literal('text/plain')),
      );
      expect(result.metadata.contentType).toBe(INTERNAL_QUADS);
      expect(result.metadata.getAll(RDF.terms.type)).toEqualRdfTermArray([
        LDP.terms.Resource,
        SOLID_META.terms.DescriptionResource,
      ]);
    });

    it('will return the generated representation for container metadata resources.', async(): Promise<void> => {
      const metaResourceID = { path: `${root}.meta` };

      // Add resource to root
      const resourceID = { path: `${root}resource` };
      accessor.data[resourceID.path] = representation;

      const result = await store.getRepresentation(metaResourceID);
      const quads = await arrayifyStream(result.data);
      expect(new Store(quads)).toBeRdfDatasetContaining(
        quad(
          namedNode(root),
          namedNode(LDP.contains),
          namedNode(resourceID.path),
          SOLID_META.terms.ResponseMetadata,
        ),
      );
      expect(result.metadata.contentType).toBe(INTERNAL_QUADS);
    });
  });

  describe('adding a Resource', (): void => {
    it('will 404 if the identifier does not contain the root.', async(): Promise<void> => {
      await expect(store.addResource({ path: 'verybadpath' }, representation))
        .rejects.toThrow(NotFoundHttpError);
    });

    it('will 404 if the target does not exist.', async(): Promise<void> => {
      const resourceID = { path: `${root}container/` };
      await expect(store.addResource(resourceID, representation)).rejects.toThrow(NotFoundHttpError);
    });

    it('will error if it gets a non-404 error when reading the container.', async(): Promise<void> => {
      const resourceID = { path: `${root}container` };
      accessor.getMetadata = async(): Promise<any> => {
        throw new Error('randomError');
      };
      await expect(store.addResource(resourceID, representation)).rejects.toThrow('randomError');
    });

    it('does not allow adding resources to existing non-containers.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource/` };
      accessor.data[resourceID.path] = representation;
      const result = store.addResource(resourceID, representation);
      await expect(result).rejects.toThrow(MethodNotAllowedHttpError);
      await expect(result).rejects.toThrow('The given path is not a container.');
    });

    it('checks if the DataAccessor supports the data.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.binary = false;
      await expect(store.addResource(resourceID, representation)).rejects.toThrow(BadRequestHttpError);
      await expect(store.addResource(resourceID, representation)).rejects
        .toThrow('The given input is not supported by the server configuration.');
    });

    it('throws a 412 if the conditions are not matched.', async(): Promise<void> => {
      const resourceID = { path: root };
      await expect(store.addResource(resourceID, representation, failingConditions))
        .rejects.toThrow(PreconditionFailedHttpError);
    });

    it('ignores the content when trying to create a container when the data is not empty.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.add(RDF.terms.type, LDP.terms.Container);
      const result = await store.addResource(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);

      const generatedID = [ ...result.keys() ].find((id): boolean => id.path !== resourceID.path)!;
      expect(generatedID).toBeDefined();
      expect(generatedID.path).toMatch(new RegExp(`^${root}[^/]+/$`, 'u'));
    });

    it('can write resources.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      const result = await store.addResource(resourceID, representation);

      expect(result.size).toBe(2);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);

      const generatedID = [ ...result.keys() ].find((id): boolean => id.path !== resourceID.path)!;
      expect(generatedID).toBeDefined();
      expect(generatedID.path).toMatch(new RegExp(`^${root}[^/]+$`, 'u'));

      expect(accessor.data[generatedID.path]).toBeDefined();
      await expect(arrayifyStream(accessor.data[generatedID.path].data)).resolves.toEqual([ resourceData ]);
      expect(accessor.data[generatedID.path].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      expect(result.get(generatedID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);

      expect(result.get(resourceID)?.get(AS.terms.object)?.value).toEqual(generatedID.path);
    });

    it('can write containers.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.add(RDF.terms.type, LDP.terms.Container);
      const result = await store.addResource(resourceID, representation);

      expect(result.size).toBe(2);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);

      const generatedID = [ ...result.keys() ].find((id): boolean => id.path !== resourceID.path)!;
      expect(generatedID).toBeDefined();
      expect(generatedID.path).toMatch(new RegExp(`^${root}[^/]*/$`, 'u'));

      expect(accessor.data[generatedID.path]).toBeDefined();
      expect(accessor.data[generatedID.path].metadata.contentType).toBeUndefined();
      expect(result.get(generatedID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);

      const { metadata } = await store.getRepresentation(generatedID);
      expect(metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
    });

    it('creates a URI based on the incoming slug.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.add(SOLID_HTTP.terms.slug, 'newName');

      const result = await store.addResource(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get({ path: `${root}newName` })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
    });

    it('errors on a slug ending on / without Link rel:type Container header.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.add(SOLID_HTTP.terms.slug, 'noContainer/');
      representation.data = guardedStreamFrom([ `` ]);
      const result = store.addResource(resourceID, representation);

      await expect(result).rejects.toThrow(BadRequestHttpError);
      await expect(result).rejects
        .toThrow('Only slugs used to create containers can end with a `/`.');
    });

    it('adds a / at the end if the request metadata contains rdf:type ldp:Container.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.add(RDF.terms.type, LDP.terms.Container);
      representation.metadata.add(SOLID_HTTP.terms.slug, 'newContainer');
      representation.data = guardedStreamFrom([ `` ]);

      const result = await store.addResource(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get({ path: `${root}newContainer/` })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
    });

    it('generates a new URI if adding the slug would create an existing URI.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.add(SOLID_HTTP.terms.slug, 'newName');
      accessor.data[`${root}newName`] = representation;
      const result = await store.addResource(resourceID, representation);
      expect(result).not.toEqual(expect.objectContaining({
        [`${root}newName`]: expect.any(RepresentationMetadata),
      }));
      expect(result).not.toEqual(expect.objectContaining({
        [expect.any(String)]: expect.stringMatching(new RegExp(`^${root}[^/]+/$`, 'u')),
      }));
    });

    it('generates http://test.com/%26%26 when slug is &%26.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.add(SOLID_HTTP.terms.slug, '&%26');

      const result = await store.addResource(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get({ path: `${root}%26%26` })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
    });

    it('errors if the slug contains a slash.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      representation.data = guardedStreamFrom([ `` ]);
      representation.metadata.add(SOLID_HTTP.terms.slug, 'sla/sh/es');
      const result = store.addResource(resourceID, representation);
      await expect(result).rejects.toThrow(BadRequestHttpError);
      await expect(result).rejects.toThrow('Slugs should not contain slashes');
    });

    it('errors if the slug would cause an auxiliary resource URI to be generated.', async(): Promise<void> => {
      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.add(SOLID_HTTP.terms.slug, 'test.dummy');
      const result = store.addResource(resourceID, representation);
      await expect(result).rejects.toThrow(ForbiddenHttpError);
      await expect(result).rejects.toThrow('Slug bodies that would result in an auxiliary resource are forbidden');
    });
  });

  describe('setting a Representation', (): void => {
    it('will 404 if the identifier does not contain the root.', async(): Promise<void> => {
      await expect(store.setRepresentation({ path: 'verybadpath' }, representation))
        .rejects.toThrow(NotFoundHttpError);
    });

    it('checks if the DataAccessor supports the data.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      representation.binary = false;
      await expect(store.setRepresentation(resourceID, representation)).rejects.toThrow(BadRequestHttpError);
    });

    it('will error if the path has a different slash than the existing one.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      accessor.data[`${resourceID.path}/`] = representation;
      representation.metadata.identifier = namedNode(`${resourceID.path}/`);
      const prom = store.setRepresentation(resourceID, representation);
      await expect(prom).rejects.toThrow(`${resourceID.path} conflicts with existing path ${resourceID.path}/`);
      await expect(prom).rejects.toThrow(ConflictHttpError);
    });

    it('throws a 412 if the conditions are not matched.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      await store.setRepresentation(resourceID, representation);
      await expect(store.setRepresentation(resourceID, representation, failingConditions))
        .rejects.toThrow(PreconditionFailedHttpError);
    });

    // As discussed in #475, trimming the trailing slash of a root container in getNormalizedMetadata
    // can result in undefined behaviour since there is no parent container.
    it('will not trim the slash of root containers since there is no parent.', async(): Promise<void> => {
      delete accessor.data[root];

      const mock = jest.spyOn(accessor, 'getMetadata');

      const resourceID = { path: root };
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.contentType = 'text/turtle';
      representation.data = guardedStreamFrom([ `<${root}> a <coolContainer>.` ]);

      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(1);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      expect(mock).toHaveBeenCalledTimes(1);
      expect(mock).toHaveBeenLastCalledWith(resourceID);

      mock.mockRestore();
    });

    it('will error if path does not end in slash and does not match its resource type.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      representation.metadata.add(RDF.terms.type, LDP.terms.Container);
      await expect(store.setRepresentation(resourceID, representation)).rejects.toThrow(
        new BadRequestHttpError('Containers should have a `/` at the end of their path, resources should not.'),
      );
    });

    it('errors when trying to create an auxiliary resource with invalid data.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource.dummy` };
      jest.spyOn(auxiliaryStrategy, 'validate').mockRejectedValue(new Error('bad data!'));
      await expect(store.setRepresentation(resourceID, representation)).rejects.toThrow('bad data!');
    });

    it('can write resources.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get({ path: root })?.get(AS.terms.object)?.value).toEqual(resourceID.path);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      await expect(arrayifyStream(accessor.data[resourceID.path].data)).resolves.toEqual([ resourceData ]);
      expect(accessor.data[resourceID.path].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      expect(accessor.data[root].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      expect(accessor.data[root].metadata.get(GENERATED_PREDICATE)).toBeUndefined();
    });

    it('can write containers.', async(): Promise<void> => {
      const resourceID = { path: `${root}container/` };

      // Generate based on URI
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.contentType = 'text/turtle';
      representation.data = guardedStreamFrom([ `<${root}resource/> a <coolContainer>.` ]);
      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      expect(accessor.data[resourceID.path]).toBeTruthy();
      expect(accessor.data[resourceID.path].metadata.contentType).toBeUndefined();
      expect(accessor.data[resourceID.path].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      expect(accessor.data[root].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      expect(accessor.data[root].metadata.get(GENERATED_PREDICATE)).toBeUndefined();
    });

    it('can overwrite resources that do not update parent metadata.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      await expect(arrayifyStream(accessor.data[resourceID.path].data)).resolves.toEqual([ resourceData ]);
      expect(accessor.data[resourceID.path].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      expect(accessor.data[root].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());

      // Parent metadata does not get updated if the resource already exists
      representation = new BasicRepresentation('updatedText', 'text/plain');
      mockDate.mockReturnValue(later);
      const result2 = await store.setRepresentation(resourceID, representation);
      expect(result2.size).toBe(1);
      expect(result2.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Update);
      await expect(arrayifyStream(accessor.data[resourceID.path].data)).resolves.toEqual([ 'updatedText' ]);
      expect(accessor.data[resourceID.path].metadata.get(DC.terms.modified)?.value).toBe(later.toISOString());
      expect(accessor.data[root].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      mockDate.mockReturnValue(now);
    });

    it('does not write generated metadata.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      representation.metadata.add(namedNode('notGen'), 'value');
      representation.metadata.add(namedNode('gen'), 'value', SOLID_META.terms.ResponseMetadata);
      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      await expect(arrayifyStream(accessor.data[resourceID.path].data)).resolves.toEqual([ resourceData ]);
      expect(accessor.data[resourceID.path].metadata.get(namedNode('notGen'))?.value).toBe('value');
      expect(accessor.data[resourceID.path].metadata.get(namedNode('gen'))).toBeUndefined();
    });

    it('can write resources even if root does not exist.', async(): Promise<void> => {
      delete accessor.data[root];
      const resourceID = { path: `${root}resource` };
      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(2);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      await expect(arrayifyStream(accessor.data[resourceID.path].data)).resolves.toEqual([ resourceData ]);
    });

    it('creates recursive containers when needed.', async(): Promise<void> => {
      const resourceID = { path: `${root}a/b/resource` };
      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(4);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Add);
      expect(result.get({ path: `${root}a/` })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      expect(result.get({ path: `${root}a/b/` })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      expect(result.get({ path: `${root}a/b/resource` })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      await expect(arrayifyStream(accessor.data[resourceID.path].data)).resolves.toEqual([ resourceData ]);
      expect(accessor.data[`${root}a/`].metadata.getAll(RDF.terms.type).map((type): string => type.value))
        .toContain(LDP.Container);
      expect(accessor.data[`${root}a/b/`].metadata.getAll(RDF.terms.type).map((type): string => type.value))
        .toContain(LDP.Container);
    });

    it('errors when a recursive container overlaps with an existing resource.', async(): Promise<void> => {
      const resourceID = { path: `${root}a/b/resource` };
      accessor.data[`${root}a`] = representation;
      const prom = store.setRepresentation(resourceID, representation);
      await expect(prom).rejects.toThrow(`Creating container ${root}a/ conflicts with an existing resource.`);
      await expect(prom).rejects.toThrow(ForbiddenHttpError);
    });

    it('can write to root if it does not exist.', async(): Promise<void> => {
      delete accessor.data[root];
      const resourceID = { path: root };

      // Generate based on URI
      representation.metadata.removeAll(RDF.terms.type);
      representation.metadata.contentType = 'text/turtle';
      representation.data = guardedStreamFrom([]);
      const result = await store.setRepresentation(resourceID, representation);
      expect(result.size).toBe(1);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Create);
      expect(accessor.data[resourceID.path]).toBeTruthy();
      expect(Object.keys(accessor.data)).toHaveLength(1);
      expect(accessor.data[resourceID.path].metadata.contentType).toBeUndefined();
    });

    it('can write to a metadata resource.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const metaResourceID = { path: `${root}resource.meta` };

      accessor.data[resourceID.path] = representation;
      const metaRepresentation = new BasicRepresentation([ quad(
        namedNode(resourceID.path),
        namedNode(DC.description),
        literal('something'),
      ) ], resourceID);

      const result = await store.setRepresentation(metaResourceID, metaRepresentation);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Update);
      expect(accessor.data[resourceID.path].metadata.quads()).toBeRdfIsomorphic([
        quad(
          namedNode(resourceID.path),
          namedNode(DC.description),
          literal('something'),
        ),
        quad(
          namedNode(resourceID.path),
          DC.terms.modified,
          literal(now.toISOString(), XSD.terms.dateTime),
        ),
      ]);
    });

    it('can write to metadata resource when using Readable using an RDF serialization.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const metaResourceID = { path: `${root}resource.meta` };

      const quads = [ quad(
        namedNode(resourceID.path),
        namedNode(DC.description),
        literal('something'),
      ) ];
      accessor.data[resourceID.path] = representation;
      const metaRepresentation = new BasicRepresentation(guardedStreamFrom(quads), resourceID, INTERNAL_QUADS);

      const result = await store.setRepresentation(metaResourceID, metaRepresentation);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Update);
      expect(accessor.data[resourceID.path].metadata.quads()).toBeRdfIsomorphic([
        ...quads,
        quad(
          namedNode(resourceID.path),
          DC.terms.modified,
          literal(now.toISOString(), XSD.terms.dateTime),
        ),
      ]);
    });

    it('can not write metadata when the corresponding resource does not exist.', async(): Promise<void> => {
      const metaResourceID = { path: `${root}resource.meta` };
      await expect(store.setRepresentation(metaResourceID, representation)).rejects.toThrow(ConflictHttpError);
    });

    it('can not add metadata to a metadata resource.', async(): Promise<void> => {
      const metametaResourceID = { path: `${root}resource.meta.meta` };
      const resourceID = { path: `${root}resource` };

      accessor.data[resourceID.path] = representation;
      accessor.data[`${resourceID.path}.meta`] = representation;
      await expect(store.setRepresentation(metametaResourceID, representation)).rejects.toThrow(ConflictHttpError);
    });

    it('preserves the old metadata of a resource when preserve triple is present.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const representationWithMetadata: Representation = {
        binary: true,
        data: guardedStreamFrom([ resourceData ]),
        metadata: new RepresentationMetadata({
          [CONTENT_TYPE]: 'text/plain',
          [RDF.type]: [ namedNode(LDP.Resource), namedNode('http://example.org/Type') ],
        }),
        isEmpty: false,
      };
      await store.setRepresentation(resourceID, representationWithMetadata);

      const metaResourceID = metadataStrategy.getAuxiliaryIdentifier(resourceID);
      representation.metadata.add(
        SOLID_META.terms.preserve,
        namedNode(metaResourceID.path),
        SOLID_META.terms.ResponseMetadata,
      );

      await store.setRepresentation(resourceID, representation);
      expect(accessor.data[resourceID.path].metadata.quads(null, RDF.terms.type)).toHaveLength(2);
      expect(accessor.data[resourceID.path].metadata.quads(null, RDF.terms.type)).toBeRdfIsomorphic([
        quad(namedNode(resourceID.path), RDF.terms.type, LDP.terms.Resource),
        quad(namedNode(resourceID.path), RDF.terms.type, namedNode('http://example.org/Type')),
      ]);
    });

    it('preserves the old metadata of a resource even when the content-types have changed.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const representationWithMetadata: Representation = {
        binary: true,
        data: guardedStreamFrom([ '<a> <b> <c>' ]),
        metadata: new RepresentationMetadata({
          [CONTENT_TYPE]: 'text/turtle',
          [RDF.type]: [ namedNode(LDP.Resource), namedNode('http://example.org/Type') ],
        }),
        isEmpty: false,
      };
      await store.setRepresentation(resourceID, representationWithMetadata);
      expect(accessor.data[resourceID.path].metadata.contentType).toBe('text/turtle');

      const metaResourceID = metadataStrategy.getAuxiliaryIdentifier(resourceID);
      representation.metadata.add(
        SOLID_META.terms.preserve,
        namedNode(metaResourceID.path),
        SOLID_META.terms.ResponseMetadata,
      );
      representation.metadata.contentTypeObject = new ContentType('text/plain', { charset: 'UTF-8' });
      await store.setRepresentation(resourceID, representation);
      const { metadata } = accessor.data[resourceID.path];
      expect(metadata.quads(null, RDF.terms.type)).toHaveLength(2);
      expect(metadata.quads(null, RDF.terms.type)).toBeRdfIsomorphic([
        quad(namedNode(resourceID.path), RDF.terms.type, LDP.terms.Resource),
        quad(namedNode(resourceID.path), RDF.terms.type, namedNode('http://example.org/Type')),
      ]);
      expect(metadata.contentType).toBe('text/plain');
      expect(metadata.contentTypeObject?.parameters).toEqual({ charset: 'UTF-8' });
    });

    it('errors when trying to set a container representation when it already exists.', async(): Promise<void> => {
      const resourceID = { path: `${root}container/` };
      accessor.data[resourceID.path] = representation;

      await expect(store.setRepresentation(resourceID, representation)).rejects.toThrow(ConflictHttpError);
    });
  });

  describe('modifying a Representation', (): void => {
    it('throws a 412 if the conditions are not matched.', async(): Promise<void> => {
      const resourceID = { path: root };
      await expect(store.modifyResource(resourceID, representation, failingConditions))
        .rejects.toThrow(PreconditionFailedHttpError);
    });

    it('throws a 412 if the conditions are not matched on resources that do not exist.', async(): Promise<void> => {
      const resourceID = { path: `${root}notHere` };
      await expect(store.modifyResource(resourceID, representation, failingConditions))
        .rejects.toThrow(PreconditionFailedHttpError);
    });

    it('re-throws the error if something goes wrong accessing the metadata.', async(): Promise<void> => {
      jest.spyOn(accessor, 'getMetadata').mockImplementation(async(): Promise<any> => {
        throw new Error('error');
      });

      const resourceID = { path: root };
      await expect(store.modifyResource(resourceID, representation, failingConditions))
        .rejects.toThrow('error');
    });

    it('is not supported.', async(): Promise<void> => {
      const result = store.modifyResource({ path: root }, representation);
      await expect(result).rejects.toThrow(NotImplementedHttpError);
      await expect(result).rejects.toThrow('Patches are not supported by the default store.');
    });
  });

  describe('deleting a Resource', (): void => {
    it('will 404 if the identifier does not contain the root.', async(): Promise<void> => {
      await expect(store.deleteResource({ path: 'verybadpath' }))
        .rejects.toThrow(NotFoundHttpError);
    });

    it('will error when deleting a root storage container.', async(): Promise<void> => {
      representation.metadata.add(RDF.terms.type, PIM.terms.Storage);
      accessor.data[`${root}container/`] = representation;
      const result = store.deleteResource({ path: `${root}container/` });
      await expect(result).rejects.toThrow(MethodNotAllowedHttpError);
      await expect(result).rejects.toThrow('Cannot delete a root storage container.');
    });

    it('will error when deleting an auxiliary of a root storage container if not allowed.', async(): Promise<void> => {
      const storageMetadata = new RepresentationMetadata(representation.metadata);
      storageMetadata.add(RDF.terms.type, PIM.terms.Storage);
      accessor.data[`${root}container/`] = new BasicRepresentation(representation.data, storageMetadata);
      accessor.data[`${root}container/.dummy`] = representation;
      jest.spyOn(auxiliaryStrategy, 'isRequiredInRoot').mockReturnValue(true);
      const result = store.deleteResource({ path: `${root}container/.dummy` });
      await expect(result).rejects.toThrow(MethodNotAllowedHttpError);
      await expect(result).rejects.toThrow(
        'Cannot delete http://test.com/container/.dummy from a root storage container.',
      );
    });

    it('will error when deleting non-empty containers.', async(): Promise<void> => {
      accessor.data[`${root}container/`] = representation;
      accessor.data[`${root}container/otherThing`] = representation;
      const result = store.deleteResource({ path: `${root}container/` });
      await expect(result).rejects.toThrow(ConflictHttpError);
      await expect(result).rejects.toThrow('Can only delete empty containers.');
    });

    it('throws a 412 if the conditions are not matched.', async(): Promise<void> => {
      const resourceID = { path: root };
      await expect(store.deleteResource(resourceID, failingConditions))
        .rejects.toThrow(PreconditionFailedHttpError);
    });

    it('will delete resources.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      accessor.data[resourceID.path] = representation;
      const result = await store.deleteResource(resourceID);
      expect(result.size).toBe(2);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Remove);
      expect(result.get({ path: root })?.get(AS.terms.object)?.value).toEqual(resourceID.path);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Delete);
      expect(accessor.data[resourceID.path]).toBeUndefined();
      expect(accessor.data[root].metadata.get(DC.terms.modified)?.value).toBe(now.toISOString());
      expect(accessor.data[root].metadata.get(GENERATED_PREDICATE)).toBeUndefined();
    });

    it('will delete root non-storage containers.', async(): Promise<void> => {
      accessor.data[root] = new BasicRepresentation(representation.data, containerMetadata);
      const result = await store.deleteResource({ path: root });
      expect(result.size).toBe(1);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Delete);
      expect(accessor.data[root]).toBeUndefined();
    });

    it('will delete a root storage auxiliary resource of a non-root container.', async(): Promise<void> => {
      const resourceID = { path: `${root}container/` };
      const auxResourceID = { path: `${root}container/.dummy` };
      const storageMetadata = new RepresentationMetadata(representation.metadata);
      accessor.data[resourceID.path] = new BasicRepresentation(representation.data, storageMetadata);
      accessor.data[auxResourceID.path] = representation;
      jest.spyOn(auxiliaryStrategy, 'isRequiredInRoot').mockReturnValue(true);
      const result = await store.deleteResource(auxResourceID);
      expect(result.size).toBe(2);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Remove);
      expect(result.get(auxResourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Delete);
      expect(accessor.data[auxResourceID.path]).toBeUndefined();
    });

    it('will delete related auxiliary resources.', async(): Promise<void> => {
      const resourceID = { path: `${root}container/` };
      const auxResourceID = { path: `${root}container/.dummy` };
      accessor.data[resourceID.path] = representation;
      accessor.data[auxResourceID.path] = representation;

      const result = await store.deleteResource(resourceID);
      expect(result.size).toBe(3);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Remove);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Delete);
      expect(result.get(auxResourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Delete);
      expect(accessor.data[resourceID.path]).toBeUndefined();
      expect(accessor.data[auxResourceID.path]).toBeUndefined();
    });

    it('will still delete a resource if deleting auxiliary resources causes errors.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const auxResourceID = { path: `${root}resource.dummy` };
      accessor.data[resourceID.path] = representation;
      accessor.data[auxResourceID.path] = representation;
      const deleteFn = accessor.deleteResource.bind(accessor);
      jest.spyOn(accessor, 'deleteResource')
        .mockImplementation(async(identifier: ResourceIdentifier): Promise<void> => {
          if (auxiliaryStrategy.isAuxiliaryIdentifier(identifier)) {
            throw new Error('auxiliary error!');
          }
          await deleteFn.call(accessor, identifier);
        });
      const { logger } = store as any;
      jest.spyOn(logger, 'error').mockImplementation();
      const result = await store.deleteResource(resourceID);
      expect(result.size).toBe(2);
      expect(result.get({ path: root })?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Remove);
      expect(result.get(resourceID)?.get(SOLID_AS.terms.activity)).toEqual(AS.terms.Delete);
      expect(accessor.data[resourceID.path]).toBeUndefined();
      expect(accessor.data[auxResourceID.path]).toBeDefined();
      expect(logger.error).toHaveBeenCalledTimes(1);
      expect(logger.error).toHaveBeenLastCalledWith(
        'Error deleting auxiliary resource http://test.com/resource.dummy: auxiliary error!',
      );
    });

    it('rejects deleting a metadata resource.', async(): Promise<void> => {
      const metaResourceID = { path: `${root}resource.meta` };

      await expect(store.deleteResource(metaResourceID)).rejects.toThrow(ConflictHttpError);
    });
  });

  describe('resource Exists', (): void => {
    it('should return false when the resource does not exist.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      await expect(store.hasResource(resourceID)).resolves.toBeFalsy();
    });

    it('should return true when the resource exists.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      accessor.data[resourceID.path] = representation;
      await expect(store.hasResource(resourceID)).resolves.toBeTruthy();
    });

    it('should rethrow any unexpected errors from validateIdentifier.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      // eslint-disable-next-line jest/unbound-method
      const originalMetaData = accessor.getMetadata;
      jest.spyOn(accessor, 'getMetadata').mockImplementation(async(): Promise<any> => {
        throw new Error('error');
      });
      await expect(store.hasResource(resourceID)).rejects.toThrow('error');
      accessor.getMetadata = originalMetaData;
    });

    it('should return false when the metadata resource does not exist.', async(): Promise<void> => {
      const metaResourceID = { path: `${root}resource.meta` };
      await expect(store.hasResource(metaResourceID)).resolves.toBeFalsy();
    });

    it('should return true when the metadata resource exists.', async(): Promise<void> => {
      const resourceID = { path: `${root}resource` };
      const metaResourceID = { path: `${root}resource.meta` };

      accessor.data[resourceID.path] = representation;
      await expect(store.hasResource(metaResourceID)).resolves.toBeTruthy();
    });
  });
});

import { BasicRepresentation } from '../../../src/http/representation/BasicRepresentation';
import type { ResourceIdentifier } from '../../../src/http/representation/ResourceIdentifier';
import { IndexRepresentationStore } from '../../../src/storage/IndexRepresentationStore';
import type { ResourceStore } from '../../../src/storage/ResourceStore';
import { ConflictHttpError } from '../../../src/util/errors/ConflictHttpError';
import { NotFoundHttpError } from '../../../src/util/errors/NotFoundHttpError';
import { readableToString } from '../../../src/util/StreamUtil';

describe('An IndexRepresentationStore', (): void => {
  const baseUrl = 'http://test.com/';
  const emptyContainer = { path: `${baseUrl}/container/` };
  let source: jest.Mocked<ResourceStore>;
  let store: IndexRepresentationStore;

  beforeEach(async(): Promise<void> => {
    source = {
      getRepresentation: jest.fn((identifier: ResourceIdentifier): any => {
        if (identifier.path === `${baseUrl}index.html`) {
          return new BasicRepresentation('index data', identifier, 'text/html');
        }
        if (identifier.path.endsWith('/')) {
          return new BasicRepresentation('container data', identifier, 'text/turtle');
        }
        throw new NotFoundHttpError();
      }),
    } as any;

    store = new IndexRepresentationStore(source);
  });

  it('errors on invalid index names.', async(): Promise<void> => {
    expect((): any => new IndexRepresentationStore(source, '../secretContainer/secret.key'))
      .toThrow('Invalid index name');
  });

  it('retrieves the index resource if it is explicitly preferred.', async(): Promise<void> => {
    const preferences = { type: { 'text/turtle': 0.5, 'text/html': 0.8 }};
    const result = await store.getRepresentation({ path: baseUrl }, preferences);
    await expect(readableToString(result.data)).resolves.toBe('index data');
    expect(source.getRepresentation).toHaveBeenCalledTimes(2);
    expect(source.getRepresentation).toHaveBeenCalledWith({ path: `${baseUrl}index.html` }, preferences, undefined);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: baseUrl }, {}, undefined);

    // Use correct metadata
    expect(result.metadata.identifier.value).toBe(baseUrl);
    expect(result.metadata.contentType).toBe('text/html');
  });

  it('retrieves the index resource if there is a range preference.', async(): Promise<void> => {
    const preferences = { type: { 'text/*': 0.8, 'other/other': 0.7 }};
    const result = await store.getRepresentation({ path: baseUrl }, preferences);
    await expect(readableToString(result.data)).resolves.toBe('index data');
    expect(source.getRepresentation).toHaveBeenCalledTimes(2);
    expect(source.getRepresentation).toHaveBeenCalledWith({ path: `${baseUrl}index.html` }, preferences, undefined);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: baseUrl }, {}, undefined);

    // Use correct metadata
    expect(result.metadata.identifier.value).toBe(baseUrl);
    expect(result.metadata.contentType).toBe('text/html');
  });

  it('does not retrieve the index resource if there are no type preferences.', async(): Promise<void> => {
    const preferences = {};
    const result = await store.getRepresentation({ path: baseUrl }, preferences);
    await expect(readableToString(result.data)).resolves.toBe('container data');
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: baseUrl }, preferences, undefined);

    // Use correct metadata
    expect(result.metadata.identifier.value).toBe(baseUrl);
    expect(result.metadata.contentType).toBe('text/turtle');
  });

  it('does not retrieve the index resource on */*.', async(): Promise<void> => {
    const preferences = { type: { '*/*': 1 }};
    const result = await store.getRepresentation({ path: baseUrl }, preferences);
    await expect(readableToString(result.data)).resolves.toBe('container data');
  });

  it('errors if a non-404 error was thrown when accessing the index resource.', async(): Promise<void> => {
    const preferences = { type: { 'text/turtle': 0.5, 'text/html': 0.8 }};
    source.getRepresentation.mockRejectedValueOnce(new ConflictHttpError('conflict!'));
    await expect(store.getRepresentation({ path: baseUrl }, preferences)).rejects.toThrow('conflict!');
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
  });

  it('requests the usual data if there is no index resource.', async(): Promise<void> => {
    const preferences = { type: { 'text/turtle': 0.5, 'text/html': 0.8 }};
    source.getRepresentation.mockRejectedValueOnce(new NotFoundHttpError());
    const result = await store.getRepresentation(emptyContainer, preferences);
    await expect(readableToString(result.data)).resolves.toBe('container data');
    expect(source.getRepresentation).toHaveBeenCalledTimes(2);
    expect(source.getRepresentation).toHaveBeenCalledWith(
      { path: `${emptyContainer.path}index.html` },
      preferences,
      undefined,
    );
    expect(source.getRepresentation).toHaveBeenLastCalledWith(emptyContainer, preferences, undefined);
  });

  it('requests the usual data if the index media range is not the most preferred.', async(): Promise<void> => {
    const preferences = { type: { 'text/turtle': 0.8, 'text/html': 0.5 }};
    const result = await store.getRepresentation({ path: baseUrl }, preferences);
    await expect(readableToString(result.data)).resolves.toBe('container data');
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: baseUrl }, preferences, undefined);
  });

  it('returns the index resource if the media range is set to */*.', async(): Promise<void> => {
    store = new IndexRepresentationStore(source, 'base.html', '*/*');
    // Mocking because we also change the index name
    source.getRepresentation.mockResolvedValueOnce(new BasicRepresentation('index data', 'text/html'));

    const preferences = { type: { 'text/turtle': 0.8, 'text/html': 0.5 }};
    const result = await store.getRepresentation({ path: baseUrl }, preferences);
    await expect(readableToString(result.data)).resolves.toBe('index data');
    expect(source.getRepresentation).toHaveBeenCalledTimes(2);
    expect(source.getRepresentation).toHaveBeenCalledWith({ path: `${baseUrl}base.html` }, preferences, undefined);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: baseUrl }, {}, undefined);

    // Use correct metadata
    expect(result.metadata.identifier.value).toBe(baseUrl);
    expect(result.metadata.contentType).toBe('text/html');
  });

  it('returns the index resource if media range and Accept header are */*.', async(): Promise<void> => {
    store = new IndexRepresentationStore(source, 'base.html', '*/*');
    // Mocking because we also change the index name
    source.getRepresentation.mockResolvedValueOnce(new BasicRepresentation('index data', 'text/html'));

    const preferences = { type: { '*/*': 1 }};
    const result = await store.getRepresentation({ path: baseUrl }, preferences);
    await expect(readableToString(result.data)).resolves.toBe('index data');
    expect(source.getRepresentation).toHaveBeenCalledTimes(2);
    expect(source.getRepresentation).toHaveBeenCalledWith({ path: `${baseUrl}base.html` }, preferences, undefined);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: baseUrl }, {}, undefined);
  });
});

import { Base64EncodingStorage } from '../../../../src/storage/keyvalue/Base64EncodingStorage';
import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';

describe('A Base64EncodingStorage', (): void => {
  let map: Map<string, string>;
  let source: KeyValueStorage<string, string>;
  let storage: Base64EncodingStorage<string>;

  beforeEach(async(): Promise<void> => {
    map = new Map<string, string>();
    source = map as any;
    storage = new Base64EncodingStorage<string>(source);
  });

  it('encodes the keys.', async(): Promise<void> => {
    const key = 'key';
    // Base 64 encoding of 'key'
    const encodedKey = 'a2V5';
    const data = 'data';
    await storage.set(key, data);
    expect(map.size).toBe(1);
    expect(map.get(encodedKey)).toBe(data);
    await expect(storage.get(key)).resolves.toBe(data);
  });

  it('decodes the keys.', async(): Promise<void> => {
    // Base 64 encoding of 'key'
    const encodedKey = 'a2V5';
    const data = 'data';

    map.set(encodedKey, data);

    const results = [];
    for await (const entry of storage.entries()) {
      results.push(entry);
    }
    expect(results).toHaveLength(1);
    expect(results[0]).toEqual([ 'key', data ]);
  });

  it('correctly handles keys that have been encoded by the source storage.', async(): Promise<void> => {
    // Base 64 encoding of 'apple'
    const encodedKey = 'YXBwbGU=';
    const data = 'data';

    map.set(encodedKey, data);

    const results = [];
    for await (const entry of storage.entries()) {
      results.push(entry);
    }
    expect(results).toHaveLength(1);
    expect(results[0]).toEqual([ 'apple', data ]);
  });
});

import { ContainerPathStorage } from '../../../../src/storage/keyvalue/ContainerPathStorage';
import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';

describe('An ContainerPathStorage', (): void => {
  const relativePath = 'container/';
  let map: Map<string, string>;
  let source: KeyValueStorage<string, unknown>;
  let storage: ContainerPathStorage<unknown>;

  beforeEach(async(): Promise<void> => {
    map = new Map<string, string>();
    source = map as any;
    storage = new ContainerPathStorage(source, relativePath);
  });

  it('joins the input key with the relativePath to create a new key.', async(): Promise<void> => {
    const key = 'key';
    const generatedPath = `${relativePath}${key}`;
    const data = 'data';

    await expect(storage.set(key, data)).resolves.toBe(storage);
    expect(map.get(generatedPath)).toBe(data);

    await expect(storage.has(key)).resolves.toBe(true);
    await expect(storage.get(key)).resolves.toBe(data);
    await expect(storage.entries().next()).resolves.toEqual({ done: false, value: [ key, data ]});

    await expect(storage.delete(key)).resolves.toBe(true);
    expect([ ...map.keys() ]).toHaveLength(0);
  });

  it('only returns entries from the source storage matching the relative path.', async(): Promise<void> => {
    const generatedPath = `${relativePath}key`;
    const otherPath = `/otherContainer/key`;
    const data = 'data';

    map.set(generatedPath, data);
    map.set(otherPath, data);

    const results = [];
    for await (const entry of storage.entries()) {
      results.push(entry);
    }
    expect(results).toHaveLength(1);
    expect(results[0]).toEqual([ 'key', data ]);
  });
});

import { HashEncodingStorage } from '../../../../src/storage/keyvalue/HashEncodingStorage';
import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';

describe('A HashEncodingStorage', (): void => {
  let map: Map<string, string>;
  let source: KeyValueStorage<string, string>;
  let storage: HashEncodingStorage<string>;

  beforeEach(async(): Promise<void> => {
    map = new Map<string, string>();
    source = map as any;
    storage = new HashEncodingStorage<string>(source);
  });

  it('hashes the keys.', async(): Promise<void> => {
    const key = 'key';
    const hash = '2c70e12b7a0646f92279f427c7b38e7334d8e5389cff167a1dc30e73f826b683';
    const data = 'data';
    await storage.set(key, data);
    expect(map.size).toBe(1);
    expect(map.get(hash)).toBe(data);
    await expect(storage.get(key)).resolves.toBe(data);
  });

  it('errors when paths should be converted back to keys.', async(): Promise<void> => {
    await storage.set('key', 'data');
    await expect(storage.entries().next()).rejects.toThrow(NotImplementedHttpError);
  });
});

import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import { JsonFileStorage } from '../../../../src/storage/keyvalue/JsonFileStorage';
import type { ReadWriteLocker } from '../../../../src/util/locking/ReadWriteLocker';
import { mockFileSystem } from '../../../util/Util';

jest.mock('node:fs');
jest.mock('fs-extra');

describe('A JsonFileStorage', (): void => {
  const rootFilePath = 'files/';
  const jsonPath = 'storage.json';
  let cache: { data: any };
  let locker: ReadWriteLocker;
  let storage: JsonFileStorage;

  beforeEach(async(): Promise<void> => {
    cache = mockFileSystem(rootFilePath);
    locker = {
      withReadLock:
        jest.fn(async(identifier: ResourceIdentifier, whileLocked: () => any): Promise<any> => whileLocked()),
      withWriteLock:
        jest.fn(async(identifier: ResourceIdentifier, whileLocked: () => any): Promise<any> => whileLocked()),
    };
    storage = new JsonFileStorage(`${rootFilePath}${jsonPath}`, locker);
  });

  it('can read and write data.', async(): Promise<void> => {
    const key = 'apple';
    const value = { taste: 'sweet' };
    await expect(storage.get(key)).resolves.toBeUndefined();
    await expect(storage.has(key)).resolves.toBe(false);
    await expect(storage.delete(key)).resolves.toBe(false);
    await expect(storage.set(key, value)).resolves.toBe(storage);
    await expect(storage.get(key)).resolves.toEqual(value);
    await expect(storage.has(key)).resolves.toBe(true);
    expect(JSON.parse(cache.data[jsonPath])).toEqual({ apple: value });

    const key2 = 'lemon';
    const value2 = { taste: 'sour' };
    await expect(storage.set(key2, value2)).resolves.toBe(storage);
    await expect(storage.get(key2)).resolves.toEqual(value2);
    await expect(storage.has(key2)).resolves.toBe(true);
    expect(JSON.parse(cache.data[jsonPath])).toEqual({ apple: value, lemon: value2 });

    const json = JSON.parse(cache.data[jsonPath]);
    for await (const entry of storage.entries()) {
      expect(json[entry[0]]).toEqual(entry[1]);
    }

    await expect(storage.delete(key)).resolves.toBe(true);
    expect(JSON.parse(cache.data[jsonPath])).toEqual({ lemon: value2 });
  });

  it('throws an error if something goes wrong reading the JSON.', async(): Promise<void> => {
    cache.data[jsonPath] = '} very invalid {';
    await expect(storage.get('anything')).rejects.toThrow(Error);
  });
});

import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Representation } from '../../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import { JsonResourceStorage } from '../../../../src/storage/keyvalue/JsonResourceStorage';
import type { ResourceStore } from '../../../../src/storage/ResourceStore';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';
import { isContainerIdentifier, joinUrl } from '../../../../src/util/PathUtil';
import { readableToString } from '../../../../src/util/StreamUtil';
import { LDP } from '../../../../src/util/Vocabularies';

describe('A JsonResourceStorage', (): void => {
  const baseUrl = 'http://test.com/';
  const container = '/data/';
  const path1 = 'foo';
  const path2 = 'bar';
  const subPath = 'container/document';
  const containerIdentifier = 'http://test.com/data/';
  const subContainerIdentifier = 'http://test.com/data/container/';
  let data: Map<string, string>;

  let store: jest.Mocked<ResourceStore>;
  let storage: JsonResourceStorage<unknown>;

  beforeEach(async(): Promise<void> => {
    data = new Map<string, string>();
    store = {
      hasResource: jest.fn(async(id: ResourceIdentifier): Promise<boolean> => data.has(id.path)),
      getRepresentation: jest.fn(async(id: ResourceIdentifier): Promise<Representation> => {
        if (!data.has(id.path)) {
          throw new NotFoundHttpError();
        }
        // Simulate container metadata
        if (isContainerIdentifier(id)) {
          const keys = [ ...data.keys() ].filter((key): boolean => key.startsWith(id.path) &&
            /^[^/]+\/?$/u.test(key.slice(id.path.length)));
          const metadata = new RepresentationMetadata({ [LDP.contains]: keys });
          return new BasicRepresentation('', metadata);
        }
        return new BasicRepresentation(data.get(id.path)!, id);
      }),
      setRepresentation: jest.fn(async(id: ResourceIdentifier, representation: Representation): Promise<void> => {
        data.set(id.path, await readableToString(representation.data));
      }),
      deleteResource: jest.fn(async(identifier: ResourceIdentifier): Promise<void> => {
        if (!data.has(identifier.path)) {
          throw new NotFoundHttpError();
        }
        data.delete(identifier.path);
      }),
    } as any;

    storage = new JsonResourceStorage(store, baseUrl, container);
  });

  it('returns undefined if there is no matching data.', async(): Promise<void> => {
    await expect(storage.get(path1)).resolves.toBeUndefined();
  });

  it('returns data if it was set beforehand.', async(): Promise<void> => {
    await expect(storage.set(path1, 'apple')).resolves.toBe(storage);
    await expect(storage.get(path1)).resolves.toBe('apple');
  });

  it('can check if data is present.', async(): Promise<void> => {
    await expect(storage.has(path1)).resolves.toBe(false);
    await expect(storage.set(path1, 'apple')).resolves.toBe(storage);
    await expect(storage.has(path1)).resolves.toBe(true);
  });

  it('can delete data.', async(): Promise<void> => {
    await expect(storage.has(path1)).resolves.toBe(false);
    await expect(storage.delete(path1)).resolves.toBe(false);
    await expect(storage.has(path1)).resolves.toBe(false);
    await expect(storage.set(path1, 'apple')).resolves.toBe(storage);
    await expect(storage.has(path1)).resolves.toBe(true);
    await expect(storage.delete(path1)).resolves.toBe(true);
    await expect(storage.has(path1)).resolves.toBe(false);
  });

  it('can handle multiple paths.', async(): Promise<void> => {
    await expect(storage.set(path1, 'apple')).resolves.toBe(storage);
    await expect(storage.has(path1)).resolves.toBe(true);
    await expect(storage.has(path2)).resolves.toBe(false);
    await expect(storage.set(path2, 'pear')).resolves.toBe(storage);
    await expect(storage.get(path1)).resolves.toBe('apple');
  });

  it('re-throws errors thrown by the store.', async(): Promise<void> => {
    store.getRepresentation.mockRejectedValue(new Error('bad GET'));
    await expect(storage.get(path1)).rejects.toThrow('bad GET');
    await expect(storage.entries().next()).rejects.toThrow('bad GET');

    store.deleteResource.mockRejectedValueOnce(new Error('bad DELETE'));
    await expect(storage.delete(path1)).rejects.toThrow('bad DELETE');
  });

  it('returns no entries if no data was added.', async(): Promise<void> => {
    const entries = [];
    for await (const entry of storage.entries()) {
      entries.push(entry);
    }
    expect(entries).toHaveLength(0);
  });

  it('recursively accesses containers to find entries.', async(): Promise<void> => {
    await expect(storage.set(path1, 'path1')).resolves.toBe(storage);
    await expect(storage.set(path2, 'path2')).resolves.toBe(storage);
    await expect(storage.set(subPath, 'subDocument')).resolves.toBe(storage);

    // Need to manually insert the containers as they don't get created by the dummy store above
    data.set(containerIdentifier, '');
    data.set(subContainerIdentifier, '');

    // Manually setting invalid data which will be ignored
    data.set(joinUrl(containerIdentifier, 'badData'), 'invalid JSON');

    const entries = [];
    for await (const entry of storage.entries()) {
      entries.push(entry);
    }
    expect(entries).toEqual([
      [ path1, 'path1' ],
      [ path2, 'path2' ],
      [ subPath, 'subDocument' ],
    ]);
  });
});

import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import { MaxKeyLengthStorage } from '../../../../src/storage/keyvalue/MaxKeyLengthStorage';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';

describe('A MaxKeyLengthStorage', (): void => {
  const key = 'key';
  const longKey = 'thisisaverylongkeythatismorecharactersthansupportedbythestoragewhichallowsus' +
    'tocheckifthehashtriggeractuallyoccursinthecasesthatarenecessarybutnotintheothercasesasthatwouldcauseissues';
  const hash = '10a298fdb8f50bf0ddef6aac982c54f5613c357f897ab954daee498c60c6cad2';
  const hashedKey = `$hash$${hash}`;
  const payload = 'data';
  let source: jest.Mocked<KeyValueStorage<string, any>>;
  let storage: MaxKeyLengthStorage<string>;

  beforeEach(async(): Promise<void> => {
    const entries = [
      [ key, { key, payload }],
      [ hashedKey, { key: longKey, payload }],
    ];

    source = {
      has: jest.fn().mockResolvedValue(false),
      get: jest.fn(),
      set: jest.fn(),
      delete: jest.fn().mockResolvedValue(false),
      entries: jest.fn(async function* (): AsyncIterableIterator<any> {
        yield* entries;
      }),
    };

    storage = new MaxKeyLengthStorage(source);
  });

  it('checks the source for existence.', async(): Promise<void> => {
    await expect(storage.has(key)).resolves.toBe(false);
    expect(source.has).toHaveBeenCalledTimes(1);
    expect(source.has).toHaveBeenLastCalledWith(key);
    await expect(storage.has(longKey)).resolves.toBe(false);
    expect(source.has).toHaveBeenCalledTimes(2);
    expect(source.has).toHaveBeenLastCalledWith(hashedKey);
  });

  it('checks the source for data.', async(): Promise<void> => {
    await expect(storage.get(key)).resolves.toBeUndefined();
    expect(source.get).toHaveBeenCalledTimes(1);
    expect(source.get).toHaveBeenLastCalledWith(key);
    await expect(storage.get(longKey)).resolves.toBeUndefined();
    expect(source.get).toHaveBeenCalledTimes(2);
    expect(source.get).toHaveBeenLastCalledWith(hashedKey);
  });

  it('wraps data before writing it to the source.', async(): Promise<void> => {
    await expect(storage.set(key, payload)).resolves.toBe(storage);
    expect(source.set).toHaveBeenCalledTimes(1);
    expect(source.set).toHaveBeenLastCalledWith(key, { key, payload });
    await expect(storage.set(longKey, payload)).resolves.toBe(storage);
    expect(source.set).toHaveBeenCalledTimes(2);
    expect(source.set).toHaveBeenLastCalledWith(hashedKey, { key: longKey, payload });
  });

  it('calls the source to delete entries.', async(): Promise<void> => {
    await expect(storage.delete(key)).resolves.toBe(false);
    expect(source.delete).toHaveBeenCalledTimes(1);
    expect(source.delete).toHaveBeenLastCalledWith(key);
    await expect(storage.delete(longKey)).resolves.toBe(false);
    expect(source.delete).toHaveBeenCalledTimes(2);
    expect(source.delete).toHaveBeenLastCalledWith(hashedKey);
  });

  it('returns the correct entries.', async(): Promise<void> => {
    const entries = [];
    for await (const entry of storage.entries()) {
      entries.push(entry);
    }
    expect(entries).toEqual([
      [ key, payload ],
      [ longKey, payload ],
    ]);
  });

  it('errors trying to write with a key that has the hash prefix.', async(): Promise<void> => {
    await expect(storage.set(`$hash$key`, payload)).rejects.toThrow(NotImplementedHttpError);
  });
});

import { MemoryMapStorage } from '../../../../src/storage/keyvalue/MemoryMapStorage';

describe('A MemoryMapStorage', (): void => {
  const identifier1 = 'http://test.com/foo';
  const identifier2 = 'http://test.com/bar';
  let storage: MemoryMapStorage<string>;

  beforeEach(async(): Promise<void> => {
    storage = new MemoryMapStorage<string>();
  });

  it('returns undefined if there is no matching data.', async(): Promise<void> => {
    await expect(storage.get(identifier1)).resolves.toBeUndefined();
  });

  it('returns data if it was set beforehand.', async(): Promise<void> => {
    await expect(storage.set(identifier1, 'apple')).resolves.toBe(storage);
    await expect(storage.get(identifier1)).resolves.toBe('apple');
    await expect(storage.entries().next()).resolves.toEqual({ done: false, value: [ identifier1, 'apple' ]});
  });

  it('can check if data is present.', async(): Promise<void> => {
    await expect(storage.has(identifier1)).resolves.toBe(false);
    await expect(storage.set(identifier1, 'apple')).resolves.toBe(storage);
    await expect(storage.has(identifier1)).resolves.toBe(true);
  });

  it('can delete data.', async(): Promise<void> => {
    await expect(storage.has(identifier1)).resolves.toBe(false);
    await expect(storage.delete(identifier1)).resolves.toBe(false);
    await expect(storage.has(identifier1)).resolves.toBe(false);
    await expect(storage.set(identifier1, 'apple')).resolves.toBe(storage);
    await expect(storage.has(identifier1)).resolves.toBe(true);
    await expect(storage.delete(identifier1)).resolves.toBe(true);
    await expect(storage.has(identifier1)).resolves.toBe(false);
  });

  it('can handle multiple identifiers.', async(): Promise<void> => {
    await expect(storage.set(identifier1, 'apple')).resolves.toBe(storage);
    await expect(storage.has(identifier1)).resolves.toBe(true);
    await expect(storage.has(identifier2)).resolves.toBe(false);
    await expect(storage.set(identifier2, 'pear')).resolves.toBe(storage);
    await expect(storage.get(identifier1)).resolves.toBe('apple');
  });
});

import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import { PassthroughKeyValueStorage } from '../../../../src/storage/keyvalue/PassthroughKeyValueStorage';

class DummyStorage extends PassthroughKeyValueStorage<string> {
  public constructor(source: KeyValueStorage<string, string>) {
    super(source);
  }

  protected toNewKey(key: string): string {
    return `dummy-${key}`;
  }

  protected toOriginalKey(key: string): string {
    return key.slice('dummy-'.length);
  }
}

describe('A PassthroughKeyValueStorage', (): void => {
  let source: jest.Mocked<KeyValueStorage<string, string>>;
  let storage: DummyStorage;

  beforeEach(async(): Promise<void> => {
    source = {
      has: jest.fn(),
      get: jest.fn(),
      set: jest.fn(),
      delete: jest.fn(),
      entries: jest.fn(),
    };

    storage = new DummyStorage(source);
  });

  it('calls the source storage with the updated key.', async(): Promise<void> => {
    await storage.has('key');
    expect(source.has).toHaveBeenCalledTimes(1);
    expect(source.has).toHaveBeenLastCalledWith('dummy-key');

    await storage.get('key');
    expect(source.get).toHaveBeenCalledTimes(1);
    expect(source.get).toHaveBeenLastCalledWith('dummy-key');

    await storage.set('key', 'data');
    expect(source.set).toHaveBeenCalledTimes(1);
    expect(source.set).toHaveBeenLastCalledWith('dummy-key', 'data');

    await storage.delete('key');
    expect(source.delete).toHaveBeenCalledTimes(1);
    expect(source.delete).toHaveBeenLastCalledWith('dummy-key');

    // Set up data to test entries call
    const map = new Map<string, string>([[ 'dummy-key', 'value' ], [ 'dummy-key2', 'value2' ]]);
    source.entries.mockReturnValue(map.entries() as unknown as AsyncIterableIterator<[string, string]>);
    const results = [];
    for await (const entry of storage.entries()) {
      results.push(entry);
    }
    expect(results).toHaveLength(2);
    expect(results[0]).toEqual([ 'key', 'value' ]);
    expect(results[1]).toEqual([ 'key2', 'value2' ]);
  });
});

import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import type { Expires } from '../../../../src/storage/keyvalue/WrappedExpiringStorage';
import { WrappedExpiringStorage } from '../../../../src/storage/keyvalue/WrappedExpiringStorage';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import clearAllTimers = jest.clearAllTimers;

type Internal = Expires<string>;

function createExpires(payload: string, expires?: Date): Internal {
  return { payload, expires: expires?.toISOString() };
}

jest.useFakeTimers();

describe('A WrappedExpiringStorage', (): void => {
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  let source: jest.Mocked<KeyValueStorage<string, Internal>>;
  let storage: WrappedExpiringStorage<string, string>;

  beforeEach(async(): Promise<void> => {
    source = {
      get: jest.fn(),
      has: jest.fn(),
      set: jest.fn(),
      delete: jest.fn(),
      entries: jest.fn(),
    };
    storage = new WrappedExpiringStorage(source);
  });

  afterEach(async(): Promise<void> => {
    clearAllTimers();
  });

  it('does not return data if there is no result.', async(): Promise<void> => {
    await expect(storage.get('key')).resolves.toBeUndefined();
    expect(source.get).toHaveBeenCalledTimes(1);
    expect(source.get).toHaveBeenLastCalledWith('key');
  });

  it('returns data if it has not expired.', async(): Promise<void> => {
    source.get.mockResolvedValueOnce(createExpires('data!', tomorrow));
    await expect(storage.get('key')).resolves.toBe('data!');
  });

  it('deletes expired data when trying to get it.', async(): Promise<void> => {
    source.get.mockResolvedValueOnce(createExpires('data!', yesterday));
    await expect(storage.get('key')).resolves.toBeUndefined();
    expect(source.delete).toHaveBeenCalledTimes(1);
    expect(source.delete).toHaveBeenLastCalledWith('key');
  });

  it('returns false on `has` checks if there is no data.', async(): Promise<void> => {
    await expect(storage.has('key')).resolves.toBe(false);
    expect(source.get).toHaveBeenCalledTimes(1);
    expect(source.get).toHaveBeenLastCalledWith('key');
  });

  it('true on `has` checks if there is non-expired data.', async(): Promise<void> => {
    source.get.mockResolvedValueOnce(createExpires('data!', tomorrow));
    await expect(storage.has('key')).resolves.toBe(true);
  });

  it('deletes expired data when checking if it exists.', async(): Promise<void> => {
    source.get.mockResolvedValueOnce(createExpires('data!', yesterday));
    await expect(storage.has('key')).resolves.toBe(false);
    expect(source.delete).toHaveBeenCalledTimes(1);
    expect(source.delete).toHaveBeenLastCalledWith('key');
  });

  it('converts the expiry date to a string when storing data.', async(): Promise<void> => {
    await storage.set('key', 'data!', tomorrow);
    expect(source.set).toHaveBeenCalledTimes(1);
    expect(source.set).toHaveBeenLastCalledWith('key', createExpires('data!', tomorrow));
  });

  it('can store data with an expiration duration.', async(): Promise<void> => {
    await storage.set('key', 'data!', tomorrow.getTime() - Date.now());
    expect(source.set).toHaveBeenCalledTimes(1);
    expect(source.set).toHaveBeenLastCalledWith('key', createExpires('data!', tomorrow));
  });

  it('can store data without expiry date.', async(): Promise<void> => {
    await storage.set('key', 'data!');
    expect(source.set).toHaveBeenCalledTimes(1);
    expect(source.set).toHaveBeenLastCalledWith('key', createExpires('data!'));
  });

  it('errors when trying to store expired data.', async(): Promise<void> => {
    await expect(storage.set('key', 'data!', yesterday)).rejects.toThrow(InternalServerError);
  });

  it('directly calls delete on the source when deleting.', async(): Promise<void> => {
    await expect(storage.delete('key')).resolves.toBeUndefined();
    expect(source.delete).toHaveBeenCalledTimes(1);
    expect(source.delete).toHaveBeenLastCalledWith('key');
  });

  it('only iterates over non-expired entries.', async(): Promise<void> => {
    const data = [
      [ 'key1', createExpires('data1', tomorrow) ],
      [ 'key2', createExpires('data2', yesterday) ],
      [ 'key3', createExpires('data3') ],
    ];
    source.entries.mockImplementationOnce(function* (): any {
      yield* data;
    });
    const it = storage.entries();
    await expect(it.next()).resolves.toEqual(
      expect.objectContaining({ value: [ 'key1', 'data1' ]}),
    );
    await expect(it.next()).resolves.toEqual(
      expect.objectContaining({ value: [ 'key3', 'data3' ]}),
    );
  });

  it('removes expired entries after a given time.', async(): Promise<void> => {
    // Disable interval function and simply check it was called with the correct parameters
    // Otherwise it gets quite difficult to verify the async interval function gets executed
    const mockInterval = jest.spyOn(globalThis, 'setInterval');

    // We only need to call the timer.unref() once when the object is created
    const mockTimer = { unref: jest.fn() };
    const mockFn = jest.fn().mockReturnValueOnce(mockTimer);
    mockInterval.mockImplementationOnce(mockFn);

    // Timeout of 1 minute
    storage = new WrappedExpiringStorage(source, 1);
    const data = [
      [ 'key1', createExpires('data1', tomorrow) ],
      [ 'key2', createExpires('data2', yesterday) ],
      [ 'key3', createExpires('data3') ],
    ];
    source.entries.mockImplementationOnce(function* (): any {
      yield* data;
    });

    // Make sure interval is created correctly
    expect(mockInterval.mock.calls).toHaveLength(1);
    expect(mockInterval.mock.calls[0]).toHaveLength(2);
    expect(mockInterval.mock.calls[0][1]).toBe(60 * 1000);

    // Await the function that should have been executed by the interval
    await (mockInterval.mock.calls[0][0] as () => Promise<void>)();

    // Make sure timer.unref() is called on initialization
    expect(mockTimer.unref).toHaveBeenCalledTimes(1);
    // Make sure setSafeInterval has been called once as well
    expect(mockFn).toHaveBeenCalledTimes(1);
    expect(source.delete).toHaveBeenCalledTimes(1);
    expect(source.delete).toHaveBeenLastCalledWith('key2');
    mockInterval.mockRestore();
  });
});

import { INDEX_ID_KEY } from '../../../../src/storage/keyvalue/IndexedStorage';
import type { TypeObject } from '../../../../src/storage/keyvalue/IndexedStorage';
import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import { WrappedIndexedStorage } from '../../../../src/storage/keyvalue/WrappedIndexedStorage';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';

const dummyDescription = {
  root: { required: 'number', optional: 'string?', notIndexed: 'number' },
  child: { parent: 'id:root', name: 'string', notIndexed: 'number' },
  grandchild: { parent: 'id:child', bool: 'boolean', notIndexed: 'number' },
  otherChild: { parent: 'id:root', name: 'string', notIndexed: 'number' },
} as const;

describe('A WrappedIndexedStorage', (): void => {
  let valueMap: Map<string, any>;
  let valueStorage: jest.Mocked<KeyValueStorage<string, any>>;
  let indexMap: Map<string, string[]>;
  let indexStorage: jest.Mocked<KeyValueStorage<string, string[]>>;
  let storage: WrappedIndexedStorage<typeof dummyDescription>;

  beforeEach(async(): Promise<void> => {
    valueMap = new Map();
    valueStorage = {
      has: jest.fn(async(key): Promise<boolean> => valueMap.has(key)),
      get: jest.fn(async(key): Promise<unknown> => valueMap.get(key)),
      set: jest.fn(async(key, value): Promise<any> => valueMap.set(key, value)),
      delete: jest.fn(async(key): Promise<boolean> => valueMap.delete(key)),
      entries: jest.fn(async function* (): AsyncIterableIterator<[string, unknown]> {
        yield* valueMap.entries();
      }),
    };

    indexMap = new Map();
    indexStorage = {
      has: jest.fn(async(key): Promise<boolean> => indexMap.has(key)),
      get: jest.fn(async(key): Promise<string[] | undefined> => indexMap.get(key)),
      set: jest.fn(async(key, value): Promise<any> => indexMap.set(key, value)),
      delete: jest.fn(async(key): Promise<boolean> => indexMap.delete(key)),
      entries: jest.fn(async function* (): AsyncIterableIterator<[string, string[]]> {
        yield* indexMap.entries();
      }),
    };

    storage = new WrappedIndexedStorage<typeof dummyDescription>(valueStorage, indexStorage);
  });

  describe('that is empty', (): void => {
    it('can define and initialize data.', async(): Promise<void> => {
      await expect(storage.defineType('root', dummyDescription.root)).resolves.toBeUndefined();
      await expect(storage.defineType('child', dummyDescription.child)).resolves.toBeUndefined();
      await expect(storage.defineType('grandchild', dummyDescription.grandchild)).resolves.toBeUndefined();
      await expect(storage.defineType('otherChild', dummyDescription.otherChild)).resolves.toBeUndefined();
    });

    it('errors when defining types with multiple references.', async(): Promise<void> => {
      await expect(storage.defineType('root', { ref1: 'id:Type1', ref2: 'id:Type2' } as any))
        .rejects.toThrow(InternalServerError);
    });

    it('errors when defining types with array references.', async(): Promise<void> => {
      await expect(storage.defineType('root', { ref: 'id:Type1[]' } as any)).rejects.toThrow(InternalServerError);
    });

    it('errors when defining types with optional references.', async(): Promise<void> => {
      await expect(storage.defineType('root', { ref: 'id:Type1?' } as any)).rejects.toThrow(InternalServerError);
    });

    it('errors trying to create an index on an undefined type.', async(): Promise<void> => {
      await expect(storage.createIndex('root', 'required')).rejects.toThrow(InternalServerError);
    });

    it('errors trying to access data before its type was defined.', async(): Promise<void> => {
      await expect(storage.has('root', '???')).rejects.toThrow(InternalServerError);
    });

    it('errors if type definitions are added after validation.', async(): Promise<void> => {
      await expect(storage.defineType('root', dummyDescription.root)).resolves.toBeUndefined();
      // Trigger data validation
      await storage.has('root', '???');
      await expect(storage.defineType('root', dummyDescription.root)).rejects.toThrow(InternalServerError);
    });

    it('errors if the type definitions are cyclical.', async(): Promise<void> => {
      await expect(storage.defineType('root', { ...dummyDescription.root, invalidReference: 'id:grandchild' } as any))
        .resolves.toBeUndefined();
      await expect(storage.defineType('child', dummyDescription.child)).resolves.toBeUndefined();
      await expect(storage.defineType('grandchild', dummyDescription.grandchild)).resolves.toBeUndefined();

      // Trigger data validation
      await expect(storage.has('root', '???')).rejects.toThrow(InternalServerError);
    });

    it('errors if there are multiple root types.', async(): Promise<void> => {
      await expect(storage.defineType('root', dummyDescription.root)).resolves.toBeUndefined();
      await expect(storage.defineType('child', dummyDescription.root as any)).resolves.toBeUndefined();

      // Trigger data validation
      await expect(storage.has('root', '???')).rejects.toThrow(InternalServerError);
    });
  });

  describe('with data definitions', (): void => {
    beforeEach(async(): Promise<void> => {
      await storage.defineType('root', dummyDescription.root);
      await storage.defineType('child', dummyDescription.child);
      await storage.defineType('grandchild', dummyDescription.grandchild);
      await storage.defineType('otherChild', dummyDescription.otherChild);
    });

    it('can create new entries.', async(): Promise<void> => {
      const parent = await storage.create('root', { required: 5, notIndexed: 0 });
      expect(parent).toEqual({ id: expect.any(String), required: 5, notIndexed: 0 });
      const child = await storage.create('child', { name: 'child', parent: parent.id, notIndexed: 1 });
      expect(child).toEqual({ id: expect.any(String), name: 'child', parent: parent.id, notIndexed: 1 });
      const grandchild = await storage.create('grandchild', { bool: true, parent: child.id, notIndexed: 2 });
      expect(grandchild).toEqual({ id: expect.any(String), bool: true, parent: child.id, notIndexed: 2 });
      const otherChild = await storage.create('otherChild', { name: 'otherChild', parent: parent.id, notIndexed: 3 });
      expect(otherChild).toEqual({ id: expect.any(String), name: 'otherChild', parent: parent.id, notIndexed: 3 });
    });

    it('errors when creating new entries with unknown references.', async(): Promise<void> => {
      await expect(storage.create('child', { name: 'child', parent: '???', notIndexed: 1 }))
        .rejects.toThrow(NotFoundHttpError);
    });

    it('can create indexes.', async(): Promise<void> => {
      await expect(storage.createIndex('root', 'required')).resolves.toBeUndefined();
      await expect(storage.createIndex('root', 'optional')).resolves.toBeUndefined();
      await expect(storage.createIndex('child', 'name')).resolves.toBeUndefined();
      await expect(storage.createIndex('grandchild', 'bool')).resolves.toBeUndefined();
      await expect(storage.createIndex('otherChild', 'name')).resolves.toBeUndefined();

      // This one does nothing
      await expect(storage.createIndex('grandchild', 'parent')).resolves.toBeUndefined();
    });
  });

  describe('with initialized data', (): void => {
    let root: TypeObject<typeof dummyDescription.root>;
    let root2: TypeObject<typeof dummyDescription.root>;
    let child: TypeObject<typeof dummyDescription.child>;
    let child2: TypeObject<typeof dummyDescription.child>;
    let child3: TypeObject<typeof dummyDescription.child>;
    let grandchild: TypeObject<typeof dummyDescription.grandchild>;
    let grandchild2: TypeObject<typeof dummyDescription.grandchild>;
    let grandchild3: TypeObject<typeof dummyDescription.grandchild>;
    let otherChild: TypeObject<typeof dummyDescription.otherChild>;

    beforeEach(async(): Promise<void> => {
      await storage.defineType('root', dummyDescription.root);
      await storage.defineType('child', dummyDescription.child);
      await storage.defineType('grandchild', dummyDescription.grandchild);
      await storage.defineType('otherChild', dummyDescription.otherChild);

      await storage.createIndex('root', 'required');
      await storage.createIndex('root', 'optional');
      await storage.createIndex('child', 'name');
      await storage.createIndex('grandchild', 'bool');
      await storage.createIndex('otherChild', 'name');

      root = await storage.create('root', { required: 5, notIndexed: 0 });
      child = await storage.create('child', { name: 'child', parent: root.id, notIndexed: 1 });
      grandchild = await storage.create('grandchild', { bool: true, parent: child.id, notIndexed: 2 });
      otherChild = await storage.create('otherChild', { name: 'otherChild', parent: root.id, notIndexed: 3 });

      // Extra resources for query tests
      root2 = await storage.create('root', { required: 5, optional: 'defined', notIndexed: 1 });
      child2 = await storage.create('child', { name: 'child2', parent: root.id, notIndexed: 1 });
      child3 = await storage.create('child', { name: 'child', parent: root2.id, notIndexed: 1 });
      grandchild2 = await storage.create('grandchild', { bool: false, parent: child.id, notIndexed: 2 });
      grandchild3 = await storage.create('grandchild', { bool: true, parent: child2.id, notIndexed: 2 });
    });

    it('can verify existence.', async(): Promise<void> => {
      await expect(storage.has('root', root.id)).resolves.toBe(true);
      await expect(storage.has('child', child.id)).resolves.toBe(true);
      await expect(storage.has('grandchild', grandchild.id)).resolves.toBe(true);
      await expect(storage.has('otherChild', otherChild.id)).resolves.toBe(true);

      await expect(storage.has('root', '???')).resolves.toBe(false);
      await expect(storage.has('child', '???')).resolves.toBe(false);
    });

    it('can return data.', async(): Promise<void> => {
      await expect(storage.get('root', root.id)).resolves.toEqual(root);
      await expect(storage.get('child', child.id)).resolves.toEqual(child);
      await expect(storage.get('grandchild', grandchild.id)).resolves.toEqual(grandchild);
      await expect(storage.get('otherChild', otherChild.id)).resolves.toEqual(otherChild);
    });

    it('returns undefined if there is no match.', async(): Promise<void> => {
      await expect(storage.get('root', child.id)).resolves.toBeUndefined();
      await expect(storage.get('child', root.id)).resolves.toBeUndefined();
      await expect(storage.get('grandchild', otherChild.id)).resolves.toBeUndefined();
      await expect(storage.get('otherChild', grandchild.id)).resolves.toBeUndefined();
    });

    it('can update entries.', async(): Promise<void> => {
      await expect(storage.set('root', { [INDEX_ID_KEY]: root.id, required: -10, notIndexed: -1 }))
        .resolves.toBeUndefined();
      await expect(storage.get('root', root.id))
        .resolves.toEqual({ [INDEX_ID_KEY]: root.id, required: -10, notIndexed: -1 });

      await expect(storage.set('child', { ...child, name: 'newChild', notIndexed: -2 })).resolves.toBeUndefined();
      await expect(storage.get('child', child.id)).resolves.toEqual({ ...child, name: 'newChild', notIndexed: -2 });

      await expect(storage.set('grandchild', { ...grandchild, bool: false, notIndexed: -3 })).resolves.toBeUndefined();
      await expect(storage.get('grandchild', grandchild.id))
        .resolves.toEqual({ ...grandchild, bool: false, notIndexed: -3 });

      await expect(storage.set('otherChild', { ...otherChild, name: 'newOtherChild', notIndexed: -4 }))
        .resolves.toBeUndefined();
      await expect(storage.get('otherChild', otherChild.id))
        .resolves.toEqual({ ...otherChild, name: 'newOtherChild', notIndexed: -4 });
    });

    it('errors when trying to update unknown entries.', async(): Promise<void> => {
      await expect(storage.set('root', { [INDEX_ID_KEY]: '???', required: -10, notIndexed: -1 }))
        .rejects.toThrow(NotFoundHttpError);
      await expect(storage.set('child', { ...child, [INDEX_ID_KEY]: '???' }))
        .rejects.toThrow(NotFoundHttpError);
    });

    it('errors when trying to update references.', async(): Promise<void> => {
      await expect(storage.set('child', { ...child, parent: 'somewhereElse' }))
        .rejects.toThrow(NotImplementedHttpError);
    });

    it('can update specific fields.', async(): Promise<void> => {
      await expect(storage.setField('root', root.id, 'notIndexed', -1))
        .resolves.toBeUndefined();
      await expect(storage.get('root', root.id))
        .resolves.toEqual({ ...root, notIndexed: -1 });

      await expect(storage.setField('child', child.id, 'notIndexed', -2))
        .resolves.toBeUndefined();
      await expect(storage.get('child', child.id))
        .resolves.toEqual({ ...child, notIndexed: -2 });

      await expect(storage.setField('grandchild', grandchild.id, 'notIndexed', -2))
        .resolves.toBeUndefined();
      await expect(storage.get('grandchild', grandchild.id))
        .resolves.toEqual({ ...grandchild, notIndexed: -2 });

      await expect(storage.setField('otherChild', otherChild.id, 'notIndexed', -3))
        .resolves.toBeUndefined();
      await expect(storage.get('otherChild', otherChild.id))
        .resolves.toEqual({ ...otherChild, notIndexed: -3 });
    });

    it('errors when trying to update a field in unknown entries.', async(): Promise<void> => {
      await expect(storage.setField('root', '???', 'notIndexed', -1))
        .rejects.toThrow(NotFoundHttpError);
      await expect(storage.setField('child', '???', 'notIndexed', -1))
        .rejects.toThrow(NotFoundHttpError);
    });

    it('errors when trying to update a reference field.', async(): Promise<void> => {
      await expect(storage.setField('child', child.id, 'parent', 'somewhereElse'))
        .rejects.toThrow(NotImplementedHttpError);
    });

    it('can remove resource.', async(): Promise<void> => {
      await expect(storage.delete('otherChild', otherChild.id)).resolves.toBeUndefined();
      await expect(storage.get('otherChild', otherChild.id)).resolves.toBeUndefined();
      await expect(storage.delete('grandchild', grandchild.id)).resolves.toBeUndefined();
      await expect(storage.get('grandchild', grandchild.id)).resolves.toBeUndefined();
      await expect(storage.delete('child', child.id)).resolves.toBeUndefined();
      await expect(storage.get('child', child.id)).resolves.toBeUndefined();
      await expect(storage.delete('root', root.id)).resolves.toBeUndefined();
      await expect(storage.get('root', root.id)).resolves.toBeUndefined();
    });

    it('does nothing when removing a resource that does not exist.', async(): Promise<void> => {
      await expect(storage.delete('otherChild', otherChild.id)).resolves.toBeUndefined();
      await expect(storage.delete('otherChild', otherChild.id)).resolves.toBeUndefined();

      await expect(storage.delete('root', root.id)).resolves.toBeUndefined();
      await expect(storage.delete('root', root.id)).resolves.toBeUndefined();
    });

    it('removes all dependent resources when deleting.', async(): Promise<void> => {
      await expect(storage.delete('child', child.id)).resolves.toBeUndefined();
      await expect(storage.get('grandchild', grandchild.id)).resolves.toBeUndefined();
      await expect(storage.get('otherChild', otherChild.id)).resolves.toEqual(otherChild);

      await expect(storage.delete('root', root.id)).resolves.toBeUndefined();
      await expect(storage.get('otherChild', otherChild.id)).resolves.toBeUndefined();
    });

    it('can find objects using queries.', async(): Promise<void> => {
      await expect(storage.find('root', { required: 5 })).resolves.toEqual([ root, root2 ]);
      await expect(storage.find('root', { required: 5, notIndexed: 0 })).resolves.toEqual([ root ]);
      await expect(storage.find('root', { optional: 'defined' })).resolves.toEqual([ root2 ]);
      await expect(storage.find('root', { required: 5, optional: undefined })).resolves.toEqual([ root ]);

      await expect(storage.find('child', { parent: root[INDEX_ID_KEY] })).resolves.toEqual([ child, child2 ]);
      await expect(storage.find('child', { parent: root[INDEX_ID_KEY], name: 'child' })).resolves.toEqual([ child ]);
      await expect(storage.find('child', { parent: root[INDEX_ID_KEY], name: 'child2' })).resolves.toEqual([ child2 ]);
      await expect(storage.find('child', { name: 'child' })).resolves.toEqual([ child, child3 ]);
      await expect(storage.find('child', { parent: { [INDEX_ID_KEY]: root[INDEX_ID_KEY] }, name: 'child0' }))
        .resolves.toEqual([]);

      await expect(storage.find('grandchild', { parent: child[INDEX_ID_KEY] }))
        .resolves.toEqual([ grandchild, grandchild2 ]);
      await expect(storage.find('grandchild', { parent: child2[INDEX_ID_KEY] }))
        .resolves.toEqual([ grandchild3 ]);
      await expect(storage.find('grandchild', { bool: true }))
        .resolves.toEqual([ grandchild, grandchild3 ]);
    });

    it('can perform nested queries.', async(): Promise<void> => {
      await expect(storage.find('grandchild', { parent: { name: 'child' }}))
        .resolves.toEqual([ grandchild, grandchild2 ]);
      await expect(storage.find('grandchild', { bool: true, parent: { notIndexed: 1 }}))
        .resolves.toEqual([ grandchild, grandchild3 ]);
      await expect(storage.find('grandchild', { bool: true, parent: { parent: { required: 5 }}}))
        .resolves.toEqual([ grandchild, grandchild3 ]);
    });

    it('can also find just the IDs of the results.', async(): Promise<void> => {
      await expect(storage.findIds('root', { required: 5 }))
        .resolves.toEqual([ root[INDEX_ID_KEY], root2[INDEX_ID_KEY] ]);
      await expect(storage.findIds('child', { name: 'child' }))
        .resolves.toEqual([ child[INDEX_ID_KEY], child3[INDEX_ID_KEY] ]);
    });

    it('requires at least one index when finding results.', async(): Promise<void> => {
      await expect(storage.findIds('root', { notIndexed: 0 })).rejects.toThrow(InternalServerError);
      await expect(storage.findIds('root', { optional: undefined })).rejects.toThrow(InternalServerError);
      await expect(storage.findIds('child', { notIndexed: 0 })).rejects.toThrow(InternalServerError);
      await expect(storage.findIds('grandchild', { notIndexed: 0 })).rejects.toThrow(InternalServerError);
      await expect(storage.findIds('otherChild', { notIndexed: 0 })).rejects.toThrow(InternalServerError);
    });

    it('can iterate over all entries of a type.', async(): Promise<void> => {
      const roots: unknown[] = [];
      for await (const entry of storage.entries('root')) {
        roots.push(entry);
      }
      expect(roots).toEqual([ root, root2 ]);

      const children: unknown[] = [];
      for await (const entry of storage.entries('child')) {
        children.push(entry);
      }
      expect(children).toEqual([ child, child2, child3 ]);
    });

    it('errors if there is index corruption.', async(): Promise<void> => {
      // Corrupt the index. Will break if we change how index keys get generated.
      indexMap.set(`child/${child.id}`, [ root2.id ]);
      await expect(storage.create('grandchild', { bool: false, notIndexed: 5, parent: child.id }))
        .rejects.toThrow(InternalServerError);
    });

    it('ignores index corruption when deleting keys.', async(): Promise<void> => {
      // Corrupt the index. Will break if we change how index keys get generated.
      indexMap.delete(`child/name/${child.name}`);
      await expect(storage.delete('child', child.id)).resolves.toBeUndefined();
    });

    it('can handle missing virtual keys.', async(): Promise<void> => {
      // Remove child -> grandchild virtual key
      delete valueMap.get(root.id)['**child**'][child2.id]['**grandchild**'];
      await expect(storage.delete('child', child2.id)).resolves.toBeUndefined();

      // Remove root -> child virtual key
      delete valueMap.get(root.id)['**child**'];
      await expect(storage.create('grandchild', { bool: false, parent: child.id, notIndexed: 1 }))
        .rejects.toThrow('Could not find child ');
      await storage.find('child', { parent: root.id });
      const newChild = await storage.create('child', { name: 'name', parent: root.id, notIndexed: 1 });
      await expect(storage.delete('child', child.id))
        .rejects.toThrow('Could not find child ');
      await expect(storage.has('child', child.id)).resolves.toBe(false);
      await expect(storage.get('child', child.id)).resolves.toBeUndefined();
      await expect(storage.setField('child', child.id, 'name', 'name'))
        .rejects.toThrow('Could not find child ');
      const entries: string[] = [];
      for await (const entry of storage.entries('child')) {
        entries.push(entry.id);
      }
      expect(entries).toHaveLength(2);
      expect(entries).toContain(newChild.id);
      expect(entries).toContain(child3.id);
    });
  });
});

import { EventEmitter } from 'node:events';
import type { AuxiliaryIdentifierStrategy } from '../../../src/http/auxiliary/AuxiliaryIdentifierStrategy';
import type { Patch } from '../../../src/http/representation/Patch';
import type { Representation } from '../../../src/http/representation/Representation';
import type { ResourceIdentifier } from '../../../src/http/representation/ResourceIdentifier';
import { LockingResourceStore } from '../../../src/storage/LockingResourceStore';
import type { ResourceStore } from '../../../src/storage/ResourceStore';
import type { ExpiringReadWriteLocker } from '../../../src/util/locking/ExpiringReadWriteLocker';
import type { ReadWriteLocker } from '../../../src/util/locking/ReadWriteLocker';
import type { PromiseOrValue } from '../../../src/util/PromiseUtil';
import { guardedStreamFrom } from '../../../src/util/StreamUtil';
import { flushPromises } from '../../util/Util';

function emptyFn(): void {
  // Empty
}

describe('A LockingResourceStore', (): void => {
  const auxiliaryId = { path: 'http://test.com/foo.dummy' };
  const subjectId = { path: 'http://test.com/foo' };
  const data = { data: 'data!' } as any;
  let store: LockingResourceStore;
  let locker: jest.Mocked<ExpiringReadWriteLocker>;
  let source: ResourceStore;
  let auxiliaryStrategy: AuxiliaryIdentifierStrategy;
  let order: string[];
  let timeoutTrigger: EventEmitter;

  beforeEach(async(): Promise<void> => {
    order = [];
    function addOrder<T>(name: string, input?: T): T | undefined {
      order.push(name);
      return input;
    }

    const readable = guardedStreamFrom([ 1, 2, 3 ]);
    const destroy = readable.destroy.bind(readable);
    jest.spyOn(readable, 'destroy').mockImplementation((error): any => destroy.call(readable, error));
    source = {
      getRepresentation: jest.fn((): any => addOrder('getRepresentation', { data: readable } as Representation)),
      addResource: jest.fn((): any => addOrder('addResource')),
      setRepresentation: jest.fn((): any => addOrder('setRepresentation')),
      deleteResource: jest.fn((): any => addOrder('deleteResource')),
      modifyResource: jest.fn((): any => addOrder('modifyResource')),
      hasResource: jest.fn((): any => addOrder('hasResource')),
    };

    timeoutTrigger = new EventEmitter();

    locker = {
      withReadLock: jest.fn(async <T>(
        id: ResourceIdentifier,
        whileLocked: (maintainLock: () => void) => PromiseOrValue<T>,
      ): Promise<T> => {
        order.push('lock read');
        try {
          // Allows simulating a timeout event
          const timeout = new Promise<never>((resolve, reject): any => timeoutTrigger.on('timeout', (): void => {
            order.push('timeout');
            reject(new Error('timeout'));
          }));
          return await Promise.race([ Promise.resolve(whileLocked(emptyFn)), timeout ]);
        } finally {
          order.push('unlock read');
        }
      }) satisfies ReadWriteLocker['withReadLock'] as any,
      withWriteLock: jest.fn(async <T>(
        identifier: ResourceIdentifier,
        whileLocked: (maintainLock: () => void) => PromiseOrValue<T>,
      ): Promise<T> => {
        order.push('lock write');
        try {
          return await whileLocked(emptyFn);
        } finally {
          order.push('unlock write');
        }
      }) satisfies ReadWriteLocker['withWriteLock'] as any,
    };

    auxiliaryStrategy = {
      isAuxiliaryIdentifier: jest.fn((id: ResourceIdentifier): any => id.path.endsWith('.dummy')),
      getSubjectIdentifier: jest.fn((id: ResourceIdentifier): any => ({ path: id.path.slice(0, -6) })),
    } as any;

    store = new LockingResourceStore(source, locker, auxiliaryStrategy);
  });

  function registerEventOrder(eventSource: EventEmitter, event: string): void {
    eventSource.on(event, (): void => {
      order.push(event);
    });
  }

  it('acquires a lock on the container when adding a representation.', async(): Promise<void> => {
    await store.addResource(subjectId, data);
    expect(locker.withWriteLock).toHaveBeenCalledTimes(1);
    expect(locker.withWriteLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.addResource).toHaveBeenCalledTimes(1);
    expect(source.addResource).toHaveBeenLastCalledWith(subjectId, data, undefined);
    expect(order).toEqual([ 'lock write', 'addResource', 'unlock write' ]);

    order = [];
    await expect(store.addResource(auxiliaryId, data)).resolves.toBeUndefined();
    expect(locker.withWriteLock).toHaveBeenCalledTimes(2);
    expect(locker.withWriteLock.mock.calls[1][0]).toEqual(subjectId);
    expect(source.addResource).toHaveBeenCalledTimes(2);
    expect(source.addResource).toHaveBeenLastCalledWith(auxiliaryId, data, undefined);
    expect(order).toEqual([ 'lock write', 'addResource', 'unlock write' ]);
  });

  it('acquires a lock on the resource when setting its representation.', async(): Promise<void> => {
    await store.setRepresentation(subjectId, data);
    expect(locker.withWriteLock).toHaveBeenCalledTimes(1);
    expect(locker.withWriteLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.setRepresentation).toHaveBeenCalledTimes(1);
    expect(source.setRepresentation).toHaveBeenLastCalledWith(subjectId, data, undefined);
    expect(order).toEqual([ 'lock write', 'setRepresentation', 'unlock write' ]);

    order = [];
    await expect(store.setRepresentation(auxiliaryId, data)).resolves.toBeUndefined();
    expect(locker.withWriteLock).toHaveBeenCalledTimes(2);
    expect(locker.withWriteLock.mock.calls[1][0]).toEqual(subjectId);
    expect(source.setRepresentation).toHaveBeenCalledTimes(2);
    expect(source.setRepresentation).toHaveBeenLastCalledWith(auxiliaryId, data, undefined);
    expect(order).toEqual([ 'lock write', 'setRepresentation', 'unlock write' ]);
  });

  it('acquires a lock on the resource when deleting it.', async(): Promise<void> => {
    await store.deleteResource(subjectId);
    expect(locker.withWriteLock).toHaveBeenCalledTimes(1);
    expect(locker.withWriteLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.deleteResource).toHaveBeenCalledTimes(1);
    expect(source.deleteResource).toHaveBeenLastCalledWith(subjectId, undefined);
    expect(order).toEqual([ 'lock write', 'deleteResource', 'unlock write' ]);

    order = [];
    await expect(store.deleteResource(auxiliaryId)).resolves.toBeUndefined();
    expect(locker.withWriteLock).toHaveBeenCalledTimes(2);
    expect(locker.withWriteLock.mock.calls[1][0]).toEqual(subjectId);
    expect(source.deleteResource).toHaveBeenCalledTimes(2);
    expect(source.deleteResource).toHaveBeenLastCalledWith(auxiliaryId, undefined);
    expect(order).toEqual([ 'lock write', 'deleteResource', 'unlock write' ]);
  });

  it('acquires a lock on the resource when modifying its representation.', async(): Promise<void> => {
    await store.modifyResource(subjectId, data as Patch);
    expect(locker.withWriteLock).toHaveBeenCalledTimes(1);
    expect(locker.withWriteLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.modifyResource).toHaveBeenCalledTimes(1);
    expect(source.modifyResource).toHaveBeenLastCalledWith(subjectId, data, undefined);
    expect(order).toEqual([ 'lock write', 'modifyResource', 'unlock write' ]);

    order = [];
    await expect(store.modifyResource(auxiliaryId, data as Patch)).resolves.toBeUndefined();
    expect(locker.withWriteLock).toHaveBeenCalledTimes(2);
    expect(locker.withWriteLock.mock.calls[1][0]).toEqual(subjectId);
    expect(source.modifyResource).toHaveBeenCalledTimes(2);
    expect(source.modifyResource).toHaveBeenLastCalledWith(auxiliaryId, data, undefined);
    expect(order).toEqual([ 'lock write', 'modifyResource', 'unlock write' ]);
  });

  it('releases the lock if an error was thrown.', async(): Promise<void> => {
    source.getRepresentation = async(): Promise<any> => {
      order.push('bad get');
      throw new Error('dummy');
    };
    await expect(store.getRepresentation(subjectId, {})).rejects.toThrow('dummy');
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(order).toEqual([ 'lock read', 'bad get', 'unlock read' ]);
  });

  it('releases the lock on the resource when data has been read.', async(): Promise<void> => {
    // Read all data from the representation
    const representation = await store.getRepresentation(subjectId, {});
    representation.data.on('data', (): any => true);
    registerEventOrder(representation.data, 'end');

    // Provide opportunity for async events
    await flushPromises();

    // Verify the lock was acquired and released at the right time
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(source.getRepresentation).toHaveBeenLastCalledWith(subjectId, {}, undefined);
    expect(order).toEqual([ 'lock read', 'getRepresentation', 'end', 'unlock read' ]);
  });

  it('acquires the lock on the subject resource when reading an auxiliary resource.', async(): Promise<void> => {
    // Read all data from the representation
    const representation = await store.getRepresentation(auxiliaryId, {});
    representation.data.on('data', (): any => true);
    registerEventOrder(representation.data, 'end');

    // Provide opportunity for async events
    await flushPromises();

    // Verify the lock was acquired and released at the right time
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(source.getRepresentation).toHaveBeenLastCalledWith(auxiliaryId, {}, undefined);
    expect(order).toEqual([ 'lock read', 'getRepresentation', 'end', 'unlock read' ]);
  });

  it('destroys the resource and releases the lock when the readable errors.', async(): Promise<void> => {
    // Make the representation error
    const representation = await store.getRepresentation(subjectId, {});
    setImmediate((): any => representation.data.emit('error', new Error('Error on the readable')));
    registerEventOrder(representation.data, 'error');
    registerEventOrder(representation.data, 'close');

    // Provide opportunity for async events
    await flushPromises();

    // Verify the lock was acquired and released at the right time
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(representation.data.destroy).toHaveBeenCalledTimes(1);
    expect(order).toEqual([ 'lock read', 'getRepresentation', 'error', 'unlock read', 'close' ]);
  });

  it('releases the lock on the resource when readable is destroyed.', async(): Promise<void> => {
    // Make the representation close
    const representation = await store.getRepresentation(subjectId, {});
    representation.data.destroy();
    registerEventOrder(representation.data, 'close');

    // Provide opportunity for async events
    await flushPromises();

    // Verify the lock was acquired and released at the right time
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(order).toEqual([ 'lock read', 'getRepresentation', 'close', 'unlock read' ]);
  });

  it('releases the lock only once when multiple events are triggered.', async(): Promise<void> => {
    // Read all data from the representation and trigger an additional close event
    const representation = await store.getRepresentation(subjectId, {});
    representation.data.on('data', (): any => true);
    representation.data.prependListener('end', (): any => {
      order.push('end');
      representation.data.destroy();
    });

    // Provide opportunity for async events
    await flushPromises();

    // Verify the lock was acquired and released at the right time
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(order).toEqual([ 'lock read', 'getRepresentation', 'end', 'unlock read' ]);
  });

  it('releases the lock on the resource when readable times out.', async(): Promise<void> => {
    const representation = await store.getRepresentation(subjectId, {});
    registerEventOrder(representation.data, 'close');
    registerEventOrder(representation.data, 'error');

    timeoutTrigger.emit('timeout');

    // Provide opportunity for async events
    await flushPromises();

    // Verify the lock was acquired and released at the right time
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(representation.data.destroy).toHaveBeenCalledTimes(1);
    expect(representation.data.destroy).toHaveBeenLastCalledWith(new Error('timeout'));
    expect(order).toEqual([ 'lock read', 'getRepresentation', 'timeout', 'unlock read', 'error', 'close' ]);
  });

  it('throws an error if a timeout happens before getting a resource.', async(): Promise<void> => {
    jest.spyOn(source, 'getRepresentation').mockImplementation(async(): Promise<any> => {
      order.push('useless get');
      // This will never resolve
      return new Promise(emptyFn);
    });

    const prom = store.getRepresentation(subjectId, {});

    timeoutTrigger.emit('timeout');

    await expect(prom).rejects.toThrow('timeout');
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withReadLock.mock.calls[0][0]).toEqual(subjectId);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(order).toEqual([ 'lock read', 'useless get', 'timeout', 'unlock read' ]);
  });

  it('hasResource should only acquire and release the read lock.', async(): Promise<void> => {
    await store.hasResource(subjectId);
    expect(locker.withReadLock).toHaveBeenCalledTimes(1);
    expect(locker.withWriteLock).toHaveBeenCalledTimes(0);
    expect(source.hasResource).toHaveBeenCalledTimes(1);
    expect(source.hasResource).toHaveBeenLastCalledWith(subjectId);
    expect(order).toEqual([ 'lock read', 'hasResource', 'unlock read' ]);
  });
});

import { BaseFileIdentifierMapper } from '../../../../src/storage/mapping/BaseFileIdentifierMapper';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';
import { trimTrailingSlashes } from '../../../../src/util/PathUtil';

jest.mock('node:fs');

describe('An BaseFileIdentifierMapper', (): void => {
  const base = 'http://test.com/';
  const rootFilepath = 'uploads/';
  const mapper = new BaseFileIdentifierMapper(base, rootFilepath);

  describe('mapUrlToFilePath', (): void => {
    it('throws 404 if the input path does not contain the base.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: 'invalid' }, false)).rejects.toThrow(NotFoundHttpError);
    });

    it('throws 404 if the relative path does not start with a slash.', async(): Promise<void> => {
      const result = mapper.mapUrlToFilePath({ path: `${trimTrailingSlashes(base)}test` }, false);
      await expect(result).rejects.toThrow(BadRequestHttpError);
      await expect(result).rejects.toThrow('URL needs a / after the base');
    });

    it('throws 400 if the input path contains relative parts.', async(): Promise<void> => {
      let result = mapper.mapUrlToFilePath({ path: `${base}test/../test2` }, false);
      await expect(result).rejects.toThrow(BadRequestHttpError);
      await expect(result).rejects.toThrow('Disallowed /../ segment in URL');

      result = mapper.mapUrlToFilePath({ path: `${base}test/..` }, false);
      await expect(result).rejects.toThrow(BadRequestHttpError);
      await expect(result).rejects.toThrow('Disallowed /../ segment in URL');
    });

    it('returns the corresponding file path for container identifiers.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}container/` }, false)).resolves.toEqual({
        identifier: { path: `${base}container/` },
        filePath: `${rootFilepath}container/`,
        isMetadata: false,
      });
    });

    it('returns the default content-type.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}test` }, false)).resolves.toEqual({
        identifier: { path: `${base}test` },
        filePath: `${rootFilepath}test`,
        contentType: 'application/octet-stream',
        isMetadata: false,
      });
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false)).resolves.toEqual({
        identifier: { path: `${base}test.ttl` },
        filePath: `${rootFilepath}test.ttl`,
        contentType: 'application/octet-stream',
        isMetadata: false,
      });
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt`,
        contentType: 'application/octet-stream',
        isMetadata: false,
      });
    });

    it('generates a file path if supported content-type was provided.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false, 'text/turtle')).resolves.toEqual({
        identifier: { path: `${base}test.ttl` },
        filePath: `${rootFilepath}test.ttl`,
        contentType: 'text/turtle',
        isMetadata: false,
      });
    });

    it('returns the corresponding file path for metadata identifiers.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.meta` }, false, 'text/turtle')).resolves.toEqual({
        identifier: { path: `${base}test.meta` },
        filePath: `${rootFilepath}test.meta`,
        contentType: 'text/turtle',
        isMetadata: true,
      });
    });

    it('generates correct metadata file paths.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, true)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt.meta`,
        contentType: 'application/octet-stream',
        isMetadata: true,
      });
    });
  });

  describe('mapFilePathToUrl', (): void => {
    it('throws an error if the input path does not contain the root file path.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl('invalid', true)).rejects.toThrow(Error);
    });

    it('returns a generated identifier for directories.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}container/`, true)).resolves.toEqual({
        identifier: { path: `${base}container/` },
        filePath: `${rootFilepath}container/`,
        isMetadata: false,
      });
    });

    it('returns files with the default content-type.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test`, false)).resolves.toEqual({
        identifier: { path: `${base}test` },
        filePath: `${rootFilepath}test`,
        contentType: 'application/octet-stream',
        isMetadata: false,
      });
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.ttl`, false)).resolves.toEqual({
        identifier: { path: `${base}test.ttl` },
        filePath: `${rootFilepath}test.ttl`,
        contentType: 'application/octet-stream',
        isMetadata: false,
      });
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.txt`, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt`,
        contentType: 'application/octet-stream',
        isMetadata: false,
      });
    });

    it('identifies metadata files.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.meta`, false)).resolves.toEqual({
        identifier: { path: `${base}test` },
        filePath: `${rootFilepath}test.meta`,
        contentType: 'application/octet-stream',
        isMetadata: true,
      });
    });
  });
});

import fs from 'node:fs';
import {
  ExtensionBasedMapper,
  ExtensionBasedMapperFactory,
} from '../../../../src/storage/mapping/ExtensionBasedMapper';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';
import { trimTrailingSlashes } from '../../../../src/util/PathUtil';

jest.mock('node:fs');

describe('An ExtensionBasedMapper', (): void => {
  const base = 'http://test.com/';
  const rootFilepath = 'uploads/';
  const mapper = new ExtensionBasedMapper(base, rootFilepath);
  let fsPromises: Record<string, jest.Mock>;

  beforeEach(async(): Promise<void> => {
    jest.clearAllMocks();
    fs.promises = {
      readdir: jest.fn(),
    } as any;
    fsPromises = fs.promises as any;
  });

  describe('mapUrlToFilePath', (): void => {
    it('throws 404 if the input path does not contain the base.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: 'invalid' }, false)).rejects.toThrow(NotFoundHttpError);
    });

    it('throws 404 if the relative path does not start with a slash.', async(): Promise<void> => {
      const result = mapper.mapUrlToFilePath({ path: `${trimTrailingSlashes(base)}test` }, false);
      await expect(result).rejects.toThrow(BadRequestHttpError);
      await expect(result).rejects.toThrow('URL needs a / after the base');
    });

    it('throws 400 if the input path contains relative parts.', async(): Promise<void> => {
      const result = mapper.mapUrlToFilePath({ path: `${base}test/../test2` }, false);
      await expect(result).rejects.toThrow(BadRequestHttpError);
      await expect(result).rejects.toThrow('Disallowed /../ segment in URL');
    });

    it('returns the corresponding file path for container identifiers.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}container/` }, false)).resolves.toEqual({
        identifier: { path: `${base}container/` },
        filePath: `${rootFilepath}container/`,
        isMetadata: false,
      });
    });

    it('rejects URLs that end with "$.{extension}".', async(): Promise<void> => {
      const result = mapper.mapUrlToFilePath({ path: `${base}test$.txt` }, false);
      await expect(result).rejects.toThrow(NotImplementedHttpError);
      await expect(result).rejects.toThrow('Identifiers cannot contain a dollar sign before their extension');
    });

    it('determines content-type by extension when looking in a folder that does not exist.', async(): Promise<void> => {
      fsPromises.readdir.mockImplementation((): void => {
        throw new Error('does not exist');
      });
      await expect(mapper.mapUrlToFilePath({ path: `${base}no/test.txt` }, false)).resolves.toEqual({
        identifier: { path: `${base}no/test.txt` },
        filePath: `${rootFilepath}no/test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('determines content-type by extension when looking for a file that does not exist.', async(): Promise<void> => {
      fsPromises.readdir.mockReturnValue([ 'test.ttl' ]);
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('determines the content-type based on the extension.', async(): Promise<void> => {
      fsPromises.readdir.mockReturnValue([ 'test.txt' ]);
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('determines the content-type correctly for metadata files.', async(): Promise<void> => {
      fsPromises.readdir.mockReturnValue([ 'test.meta' ]);
      await expect(mapper.mapUrlToFilePath({ path: `${base}test` }, true)).resolves.toEqual({
        identifier: { path: `${base}test` },
        filePath: `${rootFilepath}test.meta`,
        contentType: 'text/turtle',
        isMetadata: true,
      });
    });

    it('matches even if the content-type does not match the extension.', async(): Promise<void> => {
      fsPromises.readdir.mockReturnValue([ 'test.txt$.ttl' ]);
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt$.ttl`,
        contentType: 'text/turtle',
        isMetadata: false,
      });
    });

    it('generates a file path if the content-type was provided.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false, 'text/plain')).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('adds an extension if the given extension does not match the given content-type.', async(): Promise<void> => {
      await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false, 'text/turtle')).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt$.ttl`,
        contentType: 'text/turtle',
        isMetadata: false,
      });
    });

    it(
      'falls back to custom extension for unknown types (for which no custom mapping exists).',
      async(): Promise<void> => {
        const result = mapper.mapUrlToFilePath({ path: `${base}test` }, false, 'unknown/content-type');
        await expect(result).resolves.toEqual({
          identifier: { path: `${base}test` },
          filePath: `${rootFilepath}test$.unknown`,
          contentType: undefined,
          isMetadata: false,
        });
      },
    );

    it('supports custom types.', async(): Promise<void> => {
      const customMapper = new ExtensionBasedMapper(base, rootFilepath, { cstm: 'text/custom' });
      await expect(customMapper.mapUrlToFilePath({ path: `${base}test.cstm` }, false))
        .resolves.toEqual({
          identifier: { path: `${base}test.cstm` },
          filePath: `${rootFilepath}test.cstm`,
          contentType: 'text/custom',
          isMetadata: false,
        });
    });

    it('supports custom extensions.', async(): Promise<void> => {
      const customMapper = new ExtensionBasedMapper(base, rootFilepath, { cstm: 'text/custom' });
      await expect(customMapper.mapUrlToFilePath({ path: `${base}test` }, false, 'text/custom'))
        .resolves.toEqual({
          identifier: { path: `${base}test` },
          filePath: `${rootFilepath}test$.cstm`,
          contentType: 'text/custom',
          isMetadata: false,
        });
    });
  });

  describe('mapFilePathToUrl', (): void => {
    it('throws an error if the input path does not contain the root file path.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl('invalid', true)).rejects.toThrow(Error);
    });

    it('returns a generated identifier for directories.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}container/`, true)).resolves.toEqual({
        identifier: { path: `${base}container/` },
        filePath: `${rootFilepath}container/`,
        isMetadata: false,
      });
    });

    it('returns a generated identifier for files with corresponding content-type.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.txt`, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('returns a generated identifier for metadata files.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.meta`, false)).resolves.toEqual({
        identifier: { path: `${base}test` },
        filePath: `${rootFilepath}test.meta`,
        contentType: 'text/turtle',
        isMetadata: true,
      });
    });

    it('removes appended extensions.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.txt$.ttl`, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}test.txt$.ttl`,
        contentType: 'text/turtle',
        isMetadata: false,
      });
    });

    it('sets the content-type to application/octet-stream if there is no extension.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}test`, false)).resolves.toEqual({
        identifier: { path: `${base}test` },
        filePath: `${rootFilepath}test`,
        contentType: 'application/octet-stream',
        isMetadata: false,
      });
    });

    it('supports custom extensions.', async(): Promise<void> => {
      const customMapper = new ExtensionBasedMapper(base, rootFilepath, { cstm: 'text/custom' });
      await expect(customMapper.mapFilePathToUrl(`${rootFilepath}test$.cstm`, false))
        .resolves.toEqual({
          identifier: { path: `${base}test` },
          filePath: `${rootFilepath}test$.cstm`,
          contentType: 'text/custom',
          isMetadata: false,
        });
    });
  });

  describe('An ExtensionBasedMapperFactory', (): void => {
    const factory = new ExtensionBasedMapperFactory();

    it('creates an ExtensionBasedMapper.', async(): Promise<void> => {
      await expect(factory.create('base', 'filePath')).resolves.toBeInstanceOf(ExtensionBasedMapper);
    });
  });
});

import { FixedContentTypeMapper } from '../../../../src/storage/mapping/FixedContentTypeMapper';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';
import { trimTrailingSlashes } from '../../../../src/util/PathUtil';

jest.mock('node:fs');

describe('An FixedContentTypeMapper', (): void => {
  const base = 'http://test.com/';
  const rootFilepath = 'uploads/';

  describe('without suffixes', (): void => {
    const mapper = new FixedContentTypeMapper(base, rootFilepath, 'text/turtle');

    describe('mapUrlToFilePath', (): void => {
      it('throws 404 if the input path does not contain the base.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: 'invalid' }, false)).rejects.toThrow(NotFoundHttpError);
      });

      it('throws 404 if the relative path does not start with a slash.', async(): Promise<void> => {
        const result = mapper.mapUrlToFilePath({ path: `${trimTrailingSlashes(base)}test` }, false);
        await expect(result).rejects.toThrow(BadRequestHttpError);
        await expect(result).rejects.toThrow('URL needs a / after the base');
      });

      it('throws 400 if the input path contains relative parts.', async(): Promise<void> => {
        const result = mapper.mapUrlToFilePath({ path: `${base}test/../test2` }, false);
        await expect(result).rejects.toThrow(BadRequestHttpError);
        await expect(result).rejects.toThrow('Disallowed /../ segment in URL');
      });

      it('returns the corresponding file path for container identifiers.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}container/` }, false)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('always returns the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test` }, false)).resolves.toEqual({
          identifier: { path: `${base}test` },
          filePath: `${rootFilepath}test`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false)).resolves.toEqual({
          identifier: { path: `${base}test.txt` },
          filePath: `${rootFilepath}test.txt`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('generates a file path if supported content-type was provided.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false, 'text/turtle')).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('throws 400 if the given content-type is not supported.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false, 'application/n-quads')).rejects
          .toThrow(
            new BadRequestHttpError(`Unsupported content type application/n-quads, only text/turtle is allowed`),
          );
      });
    });

    describe('mapFilePathToUrl', (): void => {
      it('throws an error if the input path does not contain the root file path.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl('invalid', true)).rejects.toThrow(Error);
      });

      it('returns a generated identifier for directories.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}container/`, true)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('returns files with the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test`, false)).resolves.toEqual({
          identifier: { path: `${base}test` },
          filePath: `${rootFilepath}test`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.ttl`, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.txt`, false)).resolves.toEqual({
          identifier: { path: `${base}test.txt` },
          filePath: `${rootFilepath}test.txt`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });
    });
  });

  describe('with path suffix', (): void => {
    // Internally, everything uses the .ttl extension, but it's exposed without.
    const mapper = new FixedContentTypeMapper(base, rootFilepath, 'text/turtle', '.ttl');

    describe('mapUrlToFilePath', (): void => {
      it('returns the corresponding file path for container identifiers.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}container/` }, false)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('always returns the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test` }, false)).resolves.toEqual({
          identifier: { path: `${base}test` },
          filePath: `${rootFilepath}test.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test.ttl.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt` }, false)).resolves.toEqual({
          identifier: { path: `${base}test.txt` },
          filePath: `${rootFilepath}test.txt.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('generates a file path if supported content-type was provided.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false, 'text/turtle')).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test.ttl.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('throws 400 if the given content-type is not supported.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false, 'application/n-quads')).rejects
          .toThrow(
            new BadRequestHttpError(`Unsupported content type application/n-quads, only text/turtle is allowed`),
          );
      });
    });

    describe('mapFilePathToUrl', (): void => {
      it('returns a generated identifier for directories.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}container/`, true)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('returns files with the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.ttl`, false)).resolves.toEqual({
          identifier: { path: `${base}test` },
          filePath: `${rootFilepath}test.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('throws 404 if the input path does not end with the suffix.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test`, false)).rejects.toThrow(NotFoundHttpError);
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.txt`, false)).rejects.toThrow(NotFoundHttpError);
      });

      it('returns a generated file path for metadata regardless of the suffix.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}.meta`, false)).resolves.toEqual({
          identifier: { path: base },
          filePath: `${rootFilepath}.meta`,
          contentType: 'text/turtle',
          isMetadata: true,
        });
      });
    });
  });

  describe('with url suffix', (): void => {
    // Internally, no extensions are used, but everything is exposed with the .ttl extension
    const mapper = new FixedContentTypeMapper(base, rootFilepath, 'text/turtle', undefined, '.ttl');

    describe('mapUrlToFilePath', (): void => {
      it('returns the corresponding file path for container identifiers.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}container/` }, false)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('always returns the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.txt.ttl` }, false)).resolves.toEqual({
          identifier: { path: `${base}test.txt.ttl` },
          filePath: `${rootFilepath}test.txt`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('generates a file path if supported content-type was provided.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false, 'text/turtle')).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('throws 404 if the url does not end with the suffix.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.nq` }, false, 'text/turtle')).rejects
          .toThrow(NotFoundHttpError);
        await expect(mapper.mapUrlToFilePath({ path: `${base}test` }, false, 'text/turtle')).rejects
          .toThrow(NotFoundHttpError);
      });

      it('throws 400 if the given content-type is not supported.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false, 'application/n-quads')).rejects
          .toThrow(
            new BadRequestHttpError(`Unsupported content type application/n-quads, only text/turtle is allowed`),
          );
      });
    });

    describe('mapFilePathToUrl', (): void => {
      it('returns a generated identifier for directories.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}container/`, true)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('returns files with the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test`, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.ttl`, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl.ttl` },
          filePath: `${rootFilepath}test.ttl`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.txt`, false)).resolves.toEqual({
          identifier: { path: `${base}test.txt.ttl` },
          filePath: `${rootFilepath}test.txt`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });
    });
  });

  describe('with path and url suffix', (): void => {
    // Internally, everything uses the .nq extension, but it's exposed with the .ttl extension.
    const mapper = new FixedContentTypeMapper(base, rootFilepath, 'text/turtle', '.nq', '.ttl');

    describe('mapUrlToFilePath', (): void => {
      it('returns the corresponding file path for container identifiers.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}container/` }, false)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('always returns the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.ttl` }, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test.nq`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('throws 404 if the url does not end with the suffix.', async(): Promise<void> => {
        await expect(mapper.mapUrlToFilePath({ path: `${base}test.nq` }, false, 'text/turtle')).rejects
          .toThrow(NotFoundHttpError);
        await expect(mapper.mapUrlToFilePath({ path: `${base}test` }, false, 'text/turtle')).rejects
          .toThrow(NotFoundHttpError);
      });
    });

    describe('mapFilePathToUrl', (): void => {
      it('returns a generated identifier for directories.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}container/`, true)).resolves.toEqual({
          identifier: { path: `${base}container/` },
          filePath: `${rootFilepath}container/`,
          isMetadata: false,
        });
      });

      it('returns files with the configured content-type.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.nq`, false)).resolves.toEqual({
          identifier: { path: `${base}test.ttl` },
          filePath: `${rootFilepath}test.nq`,
          contentType: 'text/turtle',
          isMetadata: false,
        });
      });

      it('throws 404 if the input path does not end with the suffix.', async(): Promise<void> => {
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test`, false)).rejects.toThrow(NotFoundHttpError);
        await expect(mapper.mapFilePathToUrl(`${rootFilepath}test.ttl`, false)).rejects.toThrow(NotFoundHttpError);
      });
    });
  });
});

import { SubdomainExtensionBasedMapper } from '../../../../src/storage/mapping/SubdomainExtensionBasedMapper';
import { ForbiddenHttpError } from '../../../../src/util/errors/ForbiddenHttpError';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';

function getSubdomain(subdomain: string): string {
  return `http://${subdomain}.test.com/`;
}

describe('A SubdomainExtensionBasedMapper', (): void => {
  const base = 'http://test.com/';
  const rootFilepath = 'uploads/';
  const mapper = new SubdomainExtensionBasedMapper(base, rootFilepath);

  describe('mapUrlToFilePath', (): void => {
    it('converts file paths to identifiers with a subdomain.', async(): Promise<void> => {
      const identifier = { path: `${getSubdomain('alice')}test.txt` };
      await expect(mapper.mapUrlToFilePath(identifier, false, 'text/plain')).resolves.toEqual({
        identifier,
        filePath: `${rootFilepath}alice/test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('adds the default subdomain to the file path for root identifiers.', async(): Promise<void> => {
      const identifier = { path: `${base}test.txt` };
      await expect(mapper.mapUrlToFilePath(identifier, false, 'text/plain')).resolves.toEqual({
        identifier,
        filePath: `${rootFilepath}www/test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('decodes punycode when generating a file path.', async(): Promise<void> => {
      const identifier = { path: `${getSubdomain('xn--c1yn36f')}t%20est.txt` };
      await expect(mapper.mapUrlToFilePath(identifier, false, 'text/plain')).resolves.toEqual({
        identifier,
        filePath: `${rootFilepath}點看/t est.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('errors if the path is invalid.', async(): Promise<void> => {
      const identifier = { path: `veryinvalidpath` };
      await expect(mapper.mapUrlToFilePath(identifier, false, 'text/plain')).rejects.toThrow(NotFoundHttpError);
    });

    it('errors if the subdomain matches the default one.', async(): Promise<void> => {
      const identifier = { path: `${getSubdomain('www')}test.txt` };
      await expect(mapper.mapUrlToFilePath(identifier, false, 'text/plain')).rejects.toThrow(ForbiddenHttpError);
    });
  });

  describe('mapFilePathToUrl', (): void => {
    it('uses the first folder in a relative path as subdomain for identifiers.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}alice/test.txt`, false)).resolves.toEqual({
        identifier: { path: `${getSubdomain('alice')}test.txt` },
        filePath: `${rootFilepath}alice/test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('correctly generates container identifiers.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}alice/test.txt`, true)).resolves.toEqual({
        identifier: { path: `${getSubdomain('alice')}test.txt/` },
        filePath: `${rootFilepath}alice/test.txt`,
        isMetadata: false,
      });
    });

    it('hides the subdomain if it matches the default one.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}www/test.txt`, false)).resolves.toEqual({
        identifier: { path: `${base}test.txt` },
        filePath: `${rootFilepath}www/test.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('encodes using punycode when generating the subdomain.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(`${rootFilepath}點看/t est.txt`, false)).resolves.toEqual({
        identifier: { path: `${getSubdomain('xn--c1yn36f')}t%20est.txt` },
        filePath: `${rootFilepath}點看/t est.txt`,
        contentType: 'text/plain',
        isMetadata: false,
      });
    });

    it('cannot convert the root filepath to an identifier.', async(): Promise<void> => {
      await expect(mapper.mapFilePathToUrl(rootFilepath, true)).rejects.toThrow(InternalServerError);
    });
  });
});

import type { Patch } from '../../../src/http/representation/Patch';
import type { Representation } from '../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../src/http/representation/RepresentationMetadata';
import { MonitoringStore } from '../../../src/storage/MonitoringStore';
import type { ChangeMap, ResourceStore } from '../../../src/storage/ResourceStore';
import { IdentifierMap } from '../../../src/util/map/IdentifierMap';
import { AS, SOLID_AS } from '../../../src/util/Vocabularies';

describe('A MonitoringStore', (): void => {
  let store: MonitoringStore;
  let source: ResourceStore;

  const id = { path: 'http://example.org/foo/bar/' };
  const idNew = { path: 'http://example.org/foo/bar/new' };
  const idOld = { path: 'http://example.org/foo/bar/old' };

  let changedCallback: () => void;
  let createdCallback: () => void;
  let updatedCallback: () => void;
  let deletedCallback: () => void;

  const addResourceReturnMock: ChangeMap = new IdentifierMap([
    [ idNew, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Create }) ],
    [ id, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Update }) ],
  ]);
  const setRepresentationReturnMock: ChangeMap = new IdentifierMap([
    [ idNew, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Update }) ],
  ]);
  const deleteResourceReturnMock: ChangeMap = new IdentifierMap([
    [ idNew, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Delete }) ],
    [ id, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Update }) ],
  ]);
  const modifyResourceReturnMock: ChangeMap = new IdentifierMap([
    [ idOld, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Delete }) ],
    [ idNew, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Create }) ],
    [ id, new RepresentationMetadata({ [SOLID_AS.activity]: AS.terms.Update }) ],
  ]);

  beforeEach(async(): Promise<void> => {
    source = {
      getRepresentation: jest.fn().mockResolvedValue({ success: true }),
      addResource: jest.fn().mockResolvedValue(addResourceReturnMock),
      setRepresentation: jest.fn().mockResolvedValue(setRepresentationReturnMock),
      deleteResource: jest.fn().mockResolvedValue(deleteResourceReturnMock),
      modifyResource: jest.fn().mockResolvedValue(modifyResourceReturnMock),
      hasResource: jest.fn().mockResolvedValue(true),
    };
    store = new MonitoringStore(source);

    changedCallback = jest.fn();
    createdCallback = jest.fn();
    updatedCallback = jest.fn();
    deletedCallback = jest.fn();
    store.on('changed', changedCallback);
    store.on(AS.Create, createdCallback);
    store.on(AS.Update, updatedCallback);
    store.on(AS.Delete, deletedCallback);
  });

  it('calls getRepresentation directly from the source.', async(): Promise<void> => {
    await expect(store.getRepresentation({ path: 'getPath' }, {})).resolves.toEqual({ success: true });
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: 'getPath' }, {}, undefined);
  });

  it('does not fire a change event after getRepresentation.', async(): Promise<void> => {
    expect(changedCallback).toHaveBeenCalledTimes(0);
    await store.getRepresentation(id, {});
    expect(changedCallback).toHaveBeenCalledTimes(0);
  });

  it('calls addResource directly from the source.', async(): Promise<void> => {
    await expect(store.addResource(id, {} as Representation))
      .resolves.toBe(addResourceReturnMock);
    expect(source.addResource).toHaveBeenCalledTimes(1);
    expect(source.addResource).toHaveBeenLastCalledWith(id, {}, undefined);
  });

  it('fires appropriate events according to the return value of source.addResource.', async(): Promise<void> => {
    const result = store.addResource(id, {} as Representation);
    expect(changedCallback).toHaveBeenCalledTimes(0);
    await result;
    expect(changedCallback).toHaveBeenCalledTimes(2);
    expect(changedCallback).toHaveBeenCalledWith(id, AS.terms.Update, addResourceReturnMock.get(id));
    expect(changedCallback).toHaveBeenCalledWith(idNew, AS.terms.Create, addResourceReturnMock.get(idNew));
    expect(createdCallback).toHaveBeenCalledTimes(1);
    expect(createdCallback).toHaveBeenCalledWith(idNew, addResourceReturnMock.get(idNew));
    expect(updatedCallback).toHaveBeenCalledTimes(1);
    expect(updatedCallback).toHaveBeenCalledWith(id, addResourceReturnMock.get(id));
    expect(deletedCallback).toHaveBeenCalledTimes(0);
  });

  it('calls setRepresentation directly from the source.', async(): Promise<void> => {
    await expect(store.setRepresentation(id, {} as Representation))
      .resolves.toEqual(setRepresentationReturnMock);
    expect(source.setRepresentation).toHaveBeenCalledTimes(1);
    expect(source.setRepresentation).toHaveBeenLastCalledWith(id, {}, undefined);
  });

  it('fires appropriate events according to the return value of source.setRepresentation.', async(): Promise<void> => {
    const result = store.setRepresentation(id, {} as Representation);
    expect(changedCallback).toHaveBeenCalledTimes(0);
    await result;
    expect(changedCallback).toHaveBeenCalledTimes(1);
    expect(changedCallback).toHaveBeenCalledWith(idNew, AS.terms.Update, setRepresentationReturnMock.get(idNew));
    expect(createdCallback).toHaveBeenCalledTimes(0);
    expect(updatedCallback).toHaveBeenCalledTimes(1);
    expect(updatedCallback).toHaveBeenCalledWith(idNew, setRepresentationReturnMock.get(idNew));
    expect(deletedCallback).toHaveBeenCalledTimes(0);
  });

  it('calls deleteResource directly from the source.', async(): Promise<void> => {
    await expect(store.deleteResource(id))
      .resolves.toEqual(deleteResourceReturnMock);
    expect(source.deleteResource).toHaveBeenCalledTimes(1);
    expect(source.deleteResource).toHaveBeenLastCalledWith(id, undefined);
  });

  it('fires appropriate events according to the return value of source.deleteResource.', async(): Promise<void> => {
    const result = store.deleteResource(id);
    expect(changedCallback).toHaveBeenCalledTimes(0);
    await result;
    expect(changedCallback).toHaveBeenCalledTimes(2);
    expect(changedCallback).toHaveBeenCalledWith(id, AS.terms.Update, deleteResourceReturnMock.get(id));
    expect(changedCallback).toHaveBeenCalledWith(idNew, AS.terms.Delete, deleteResourceReturnMock.get(idNew));
    expect(createdCallback).toHaveBeenCalledTimes(0);
    expect(updatedCallback).toHaveBeenCalledTimes(1);
    expect(updatedCallback).toHaveBeenCalledWith(id, deleteResourceReturnMock.get(id));
    expect(deletedCallback).toHaveBeenCalledTimes(1);
    expect(deletedCallback).toHaveBeenCalledWith(idNew, deleteResourceReturnMock.get(idNew));
  });

  it('calls modifyResource directly from the source.', async(): Promise<void> => {
    await expect(store.modifyResource(id, {} as Patch))
      .resolves.toEqual(modifyResourceReturnMock);
    expect(source.modifyResource).toHaveBeenCalledTimes(1);
    expect(source.modifyResource).toHaveBeenLastCalledWith(id, {}, undefined);
  });

  it('fires appropriate events according to the return value of source.modifyResource.', async(): Promise<void> => {
    const result = store.modifyResource(id, {} as Patch);
    expect(changedCallback).toHaveBeenCalledTimes(0);
    await result;
    expect(changedCallback).toHaveBeenCalledTimes(3);
    expect(changedCallback).toHaveBeenCalledWith(idNew, AS.terms.Create, modifyResourceReturnMock.get(idNew));
    expect(changedCallback).toHaveBeenCalledWith(id, AS.terms.Update, modifyResourceReturnMock.get(id));
    expect(changedCallback).toHaveBeenCalledWith(idOld, AS.terms.Delete, modifyResourceReturnMock.get(idOld));
    expect(createdCallback).toHaveBeenCalledTimes(1);
    expect(createdCallback).toHaveBeenCalledWith(idNew, modifyResourceReturnMock.get(idNew));
    expect(updatedCallback).toHaveBeenCalledTimes(1);
    expect(updatedCallback).toHaveBeenCalledWith(id, modifyResourceReturnMock.get(id));
    expect(deletedCallback).toHaveBeenCalledTimes(1);
    expect(deletedCallback).toHaveBeenCalledWith(idOld, modifyResourceReturnMock.get(idOld));
  });

  it('calls hasResource directly from the source.', async(): Promise<void> => {
    await expect(store.hasResource(id)).resolves.toBe(true);
    expect(source.hasResource).toHaveBeenCalledTimes(1);
    expect(source.hasResource).toHaveBeenLastCalledWith(id);
  });

  it('should not emit an event when the Activity is not a valid AS value.', async(): Promise<void> => {
    jest.spyOn(source, 'addResource').mockResolvedValue(new IdentifierMap([
      [{ path: 'http://example.org/path' }, new RepresentationMetadata({ [SOLID_AS.activity]: 'SomethingRandom' }) ],
    ]));

    await store.addResource(id, {} as Patch);

    expect(changedCallback).toHaveBeenCalledTimes(0);
    expect(createdCallback).toHaveBeenCalledTimes(0);
    expect(updatedCallback).toHaveBeenCalledTimes(0);
    expect(deletedCallback).toHaveBeenCalledTimes(0);
  });
});

