import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Patch } from '../../../../src/http/representation/Patch';
import type { Representation } from '../../../../src/http/representation/Representation';
import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import type {
  RepresentationConverter,
  RepresentationConverterArgs,
} from '../../../../src/storage/conversion/RepresentationConverter';
import { ConvertingPatcher } from '../../../../src/storage/patch/ConvertingPatcher';
import type {
  RepresentationPatcher,
  RepresentationPatcherInput,
} from '../../../../src/storage/patch/RepresentationPatcher';

describe('A ConvertingPatcher', (): void => {
  const intermediateType = 'internal/quads';
  const defaultType = 'text/turtle';
  const identifier: ResourceIdentifier = { path: 'http://test.com/foo' };
  const patch: Patch = new BasicRepresentation([], 'type/patch');
  const representation = new BasicRepresentation([], 'application/trig');
  const patchResult = new BasicRepresentation([], 'internal/quads');
  let args: RepresentationPatcherInput<Representation>;
  let converter: jest.Mocked<RepresentationConverter>;
  let patcher: jest.Mocked<RepresentationPatcher<Representation>>;
  let convertingPatcher: ConvertingPatcher;

  beforeEach(async(): Promise<void> => {
    args = { patch, identifier, representation };

    converter = {
      canHandle: jest.fn(),
      handle: jest.fn(async({ preferences }: RepresentationConverterArgs): Promise<any> =>
        new BasicRepresentation('converted', Object.keys(preferences.type!)[0])),
    } as any;

    patcher = {
      canHandle: jest.fn(),
      handle: jest.fn().mockResolvedValue(patchResult),
    } as any;

    convertingPatcher = new ConvertingPatcher(patcher, converter, intermediateType, defaultType);
  });

  it('rejects requests the converter cannot handle.', async(): Promise<void> => {
    converter.canHandle.mockRejectedValueOnce(new Error('unsupported type'));
    await expect(convertingPatcher.canHandle(args)).rejects.toThrow('unsupported type');
  });

  it('checks if the patcher can handle the input if there is no representation.', async(): Promise<void> => {
    delete args.representation;

    await expect(convertingPatcher.canHandle(args)).resolves.toBeUndefined();

    patcher.canHandle.mockRejectedValueOnce(new Error('unsupported patch'));
    await expect(convertingPatcher.canHandle(args)).rejects.toThrow('unsupported patch');
  });

  it('sends a mock representation with the correct type to the patcher to check support.', async(): Promise<void> => {
    await expect(convertingPatcher.canHandle(args)).resolves.toBeUndefined();
    expect(patcher.canHandle).toHaveBeenCalledTimes(1);
    expect(patcher.canHandle.mock.calls[0][0].representation?.metadata.contentType).toBe(intermediateType);
  });

  it('converts the representation before calling the patcher.', async(): Promise<void> => {
    const result = await convertingPatcher.handle(args);
    expect(result.metadata.contentType).toBe('application/trig');

    // Convert input
    expect(converter.handle).toHaveBeenCalledTimes(2);
    expect(converter.handle).toHaveBeenCalledWith({
      representation,
      identifier,
      preferences: { type: { [intermediateType]: 1 }},
    });

    // Patch
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle)
      .toHaveBeenLastCalledWith({ ...args, representation: await converter.handle.mock.results[0].value });

    // Convert back
    expect(converter.handle).toHaveBeenLastCalledWith({
      representation: patchResult,
      identifier,
      preferences: { type: { 'application/trig': 1 }},
    });
  });

  it('expects the patcher to create a new representation if there is none.', async(): Promise<void> => {
    delete args.representation;

    const result = await convertingPatcher.handle(args);
    expect(result.metadata.contentType).toBe(defaultType);

    // Patch
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(args);

    // Convert new Representation to default type
    expect(converter.handle).toHaveBeenCalledTimes(1);
    expect(converter.handle).toHaveBeenLastCalledWith({
      representation: patchResult,
      identifier,
      preferences: { type: { [defaultType]: 1 }},
    });
  });

  it('does no conversion if there is no intermediate type.', async(): Promise<void> => {
    convertingPatcher = new ConvertingPatcher(patcher, converter);
    const result = await convertingPatcher.handle(args);
    expect(result.metadata.contentType).toBe(patchResult.metadata.contentType);

    // Patch
    expect(converter.handle).toHaveBeenCalledTimes(0);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(args);
  });

  it('does not convert to a default type if there is none.', async(): Promise<void> => {
    delete args.representation;
    convertingPatcher = new ConvertingPatcher(patcher, converter);
    const result = await convertingPatcher.handle(args);
    expect(result.metadata.contentType).toBe(patchResult.metadata.contentType);

    // Patch
    expect(converter.handle).toHaveBeenCalledTimes(0);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(args);
  });
});

import 'jest-rdf';
import { DataFactory, Store } from 'n3';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Patch } from '../../../../src/http/representation/Patch';
import type { RdfDatasetRepresentation } from '../../../../src/http/representation/RdfDatasetRepresentation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import { ImmutableMetadataPatcher } from '../../../../src/storage/patch/ImmutableMetadataPatcher';
import type { RepresentationPatcherInput } from '../../../../src/storage/patch/RepresentationPatcher';
import type { SparqlUpdatePatcher } from '../../../../src/storage/patch/SparqlUpdatePatcher';
import { ConflictHttpError } from '../../../../src/util/errors/ConflictHttpError';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';
import { FilterPattern } from '../../../../src/util/QuadUtil';
import { guardedStreamFrom } from '../../../../src/util/StreamUtil';
import { SimpleSuffixStrategy } from '../../../util/SimpleSuffixStrategy';

const { namedNode, quad } = DataFactory;

function getPatch(): Patch {
  const prefixedQuery = `This is a valid patch query`;
  return {
    data: guardedStreamFrom(prefixedQuery),
    metadata: new RepresentationMetadata(),
    binary: true,
    isEmpty: false,
  };
}

describe('A ImmutableMetadataPatcher', (): void => {
  const base = 'http://test.com/';
  const identifier = { path: 'http://test.com/foo' };
  const metaIdentifier = { path: 'http://test.com/foo.meta' };

  let patch: Patch;
  let patcher: SparqlUpdatePatcher;
  let handler: ImmutableMetadataPatcher;
  let metaStrategy: SimpleSuffixStrategy;
  let store: Store;
  let input: RepresentationPatcherInput<RdfDatasetRepresentation>;
  let representation: RdfDatasetRepresentation;

  beforeEach(async(): Promise<void> => {
    patcher = {
      canHandle: jest.fn(),
      handle: jest.fn(async(patcherInput: RepresentationPatcherInput<RdfDatasetRepresentation>):
      Promise<RdfDatasetRepresentation> => {
        const patcherStore = new Store([
          quad(namedNode(`${base}foo`), namedNode(`${base}p`), namedNode(`${base}o`)),
        ]);
        patcherInput.representation!.dataset = patcherStore;
        return patcherInput.representation!;
      }),
    } as any;
    metaStrategy = new SimpleSuffixStrategy('.meta');
    store = new Store();
    patch = getPatch();
    representation = new BasicRepresentation() as RdfDatasetRepresentation;
    representation.dataset = store;

    input = { representation, patch, identifier: metaIdentifier };
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(`${base}foo`, `${base}b`, `${base}c`),
    ]);
  });

  it('throws an error when trying to handle a non metadata resource identifier.', async(): Promise<void> => {
    input.identifier = identifier;
    await expect(handler.handleSafe(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('throws an error when no representation is given as input.', async(): Promise<void> => {
    input.representation = undefined;
    await expect(handler.handle(input)).rejects.toThrow(InternalServerError);
  });

  it('handles patches if they do not change immutable metadata.', async(): Promise<void> => {
    const result = await handler.handleSafe(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode(`${base}foo`), namedNode(`${base}p`), namedNode(`${base}o`)),
    ]);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('handles patches if there are no immutable patterns.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [ ]);

    const result = await handler.handleSafe(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode(`${base}foo`), namedNode(`${base}p`), namedNode(`${base}o`)),
    ]);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('rejects patches that change immutable triples based on subject alone.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(`${base}foo`),
    ]);

    await expect(handler.handleSafe(input)).rejects.toThrow(ConflictHttpError);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('rejects patches that change immutable triples based on predicate alone.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(undefined, `${base}p`),
    ]);

    await expect(handler.handleSafe(input)).rejects.toThrow(ConflictHttpError);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('rejects patches that change immutable triples based on object alone.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(undefined, undefined, `${base}o`),
    ]);

    await expect(handler.handleSafe(input)).rejects.toThrow(ConflictHttpError);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('rejects patches that change immutable triples based on predicate and object.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(undefined, `${base}p`, `${base}o`),
    ]);

    await expect(handler.handleSafe(input)).rejects.toThrow(ConflictHttpError);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('handles patches that changes triples where only a part is immutable.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(undefined, `${base}p`, `${base}o`),
    ]);
    jest.spyOn(patcher, 'handle').mockImplementation(
      async(patcherInput: RepresentationPatcherInput<RdfDatasetRepresentation>): Promise<RdfDatasetRepresentation> => {
        const patcherStore = new Store([
          quad(namedNode(`${base}a`), namedNode(`${base}p`), namedNode(`${base}c`)),
          quad(namedNode(`${base}a`), namedNode(`${base}b`), namedNode(`${base}o`)),
        ]);
        patcherInput.representation!.dataset = patcherStore;
        return patcherInput.representation!;
      },
    );

    const result = await handler.handleSafe(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode(`${base}a`), namedNode(`${base}p`), namedNode(`${base}c`)),
      quad(namedNode(`${base}a`), namedNode(`${base}b`), namedNode(`${base}o`)),
    ]);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('rejects patches that replaces immutable triples.', async(): Promise<void> => {
    input.representation!.dataset.addQuad(namedNode(identifier.path), namedNode(`${base}p`), namedNode(`${base}o1`));
    jest.spyOn(patcher, 'handle').mockImplementation(
      async(patcherInput: RepresentationPatcherInput<RdfDatasetRepresentation>): Promise<RdfDatasetRepresentation> => {
        const patcherStore = new Store([
          quad(namedNode(identifier.path), namedNode(`${base}p`), namedNode(`${base}o2`)),
        ]);
        patcherInput.representation!.dataset = patcherStore;
        return patcherInput.representation!;
      },
    );
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(`${base}foo`, `${base}p`),
    ]);

    await expect(handler.handleSafe(input)).rejects.toThrow(ConflictHttpError);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('rejects patches that change immutable triples.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(`${base}foo`, `${base}p`, `${base}o`),
    ]);

    await expect(handler.handleSafe(input)).rejects.toThrow(ConflictHttpError);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });

  it('rejects everything when ImmutableTriple has no arguments.', async(): Promise<void> => {
    handler = new ImmutableMetadataPatcher(patcher, metaStrategy, [
      new FilterPattern(),
    ]);

    await expect(handler.handleSafe(input)).rejects.toThrow(ConflictHttpError);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith(input);
  });
});

import 'jest-rdf';
import { DataFactory, Store } from 'n3';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { N3Patch } from '../../../../src/http/representation/N3Patch';
import type { RdfDatasetRepresentation } from '../../../../src/http/representation/RdfDatasetRepresentation';
import type { SparqlUpdatePatch } from '../../../../src/http/representation/SparqlUpdatePatch';
import { N3Patcher } from '../../../../src/storage/patch/N3Patcher';
import type { RepresentationPatcherInput } from '../../../../src/storage/patch/RepresentationPatcher';
import { ConflictHttpError } from '../../../../src/util/errors/ConflictHttpError';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';

const { blankNode, namedNode, quad, variable } = DataFactory;

describe('An N3Patcher', (): void => {
  let patch: N3Patch;
  let input: RepresentationPatcherInput<RdfDatasetRepresentation>;
  const patcher = new N3Patcher();
  let store: Store;

  beforeEach(async(): Promise<void> => {
    patch = new BasicRepresentation() as N3Patch;
    patch.deletes = [];
    patch.inserts = [];
    patch.conditions = [];

    store = new Store();

    const representation = new BasicRepresentation() as RdfDatasetRepresentation;
    representation.dataset = store;
    input = {
      patch,
      identifier: { path: 'http://example.com/foo' },
      representation,
    };
  });

  it('can only handle N3 Patches.', async(): Promise<void> => {
    await expect(patcher.canHandle(input)).resolves.toBeUndefined();
    input.patch = { algebra: {}} as SparqlUpdatePatch;
    await expect(patcher.canHandle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('returns the input representation for an empty patch.', async(): Promise<void> => {
    patch.deletes = [];
    patch.inserts = [];
    patch.conditions = [];
    const result = await patcher.handle(input);
    expect(result.dataset).toBe(store);
  });

  it('throws an error when no representation is given as input.', async(): Promise<void> => {
    input.representation = undefined;
    await expect(patcher.handle(input)).rejects.toThrow(InternalServerError);
  });

  it('can delete and insert triples.', async(): Promise<void> => {
    patch.deletes = [ quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')) ];
    patch.inserts = [ quad(namedNode('ex:s2'), namedNode('ex:p2'), namedNode('ex:o2')) ];
    input.representation?.dataset.addQuads([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
      quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
    ]);
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
      quad(namedNode('ex:s2'), namedNode('ex:p2'), namedNode('ex:o2')),
    ]);
  });

  it('can create new representations using insert.', async(): Promise<void> => {
    patch.inserts = [ quad(namedNode('ex:s2'), namedNode('ex:p2'), namedNode('ex:o2')) ];
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode('ex:s2'), namedNode('ex:p2'), namedNode('ex:o2')),
    ]);
  });

  it('can use conditions to target specific triples.', async(): Promise<void> => {
    patch.conditions = [ quad(variable('v'), namedNode('ex:p1'), namedNode('ex:o1')) ];
    patch.deletes = [ quad(variable('v'), namedNode('ex:p1'), namedNode('ex:o1')) ];
    patch.inserts = [ quad(variable('v'), namedNode('ex:p2'), namedNode('ex:o2')) ];
    input.representation?.dataset.addQuads([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
      quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
    ]);
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
      quad(namedNode('ex:s1'), namedNode('ex:p2'), namedNode('ex:o2')),
    ]);
  });

  it('errors if the conditions find no match.', async(): Promise<void> => {
    patch.conditions = [ quad(variable('v'), namedNode('ex:p3'), namedNode('ex:o3')) ];
    input.representation?.dataset.addQuads([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
      quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
    ]);
    const prom = patcher.handle(input);
    await expect(prom).rejects.toThrow(ConflictHttpError);
    await expect(prom).rejects.toThrow(
      'The document does not contain any matches for the N3 Patch solid:where condition.',
    );
  });

  it('errors if the conditions find multiple matches.', async(): Promise<void> => {
    patch.conditions = [ quad(variable('v'), namedNode('ex:p0'), namedNode('ex:o0')) ];
    input.representation?.dataset.addQuads([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
      quad(namedNode('ex:s1'), namedNode('ex:p0'), namedNode('ex:o0')),
    ]);
    const prom = patcher.handle(input);
    await expect(prom).rejects.toThrow(ConflictHttpError);
    await expect(prom).rejects.toThrow(
      'The document contains multiple matches for the N3 Patch solid:where condition, which is not allowed.',
    );
  });

  it('errors if the delete triples have no match.', async(): Promise<void> => {
    patch.deletes = [ quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')) ];
    input.representation?.dataset.addQuads([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
    ]);
    const prom = patcher.handle(input);
    await expect(prom).rejects.toThrow(ConflictHttpError);
    await expect(prom).rejects.toThrow(
      'The document does not contain all triples the N3 Patch requests to delete, which is required for patching.',
    );
  });

  it('works correctly if there are duplicate delete triples.', async(): Promise<void> => {
    patch.conditions = [ quad(variable('v'), namedNode('ex:p1'), namedNode('ex:o1')) ];
    patch.deletes = [
      quad(variable('v'), namedNode('ex:p1'), namedNode('ex:o1')),
      quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
    ];
    input.representation?.dataset.addQuads([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
      quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
    ]);
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), namedNode('ex:o0')),
    ]);
  });

  it('can delete blank nodes.', async(): Promise<void> => {
    patch.conditions = [ quad(namedNode('ex:s0'), namedNode('ex:p0'), variable('v')) ];
    patch.deletes = [
      quad(variable('v'), namedNode('ex:p1'), namedNode('ex:o1')),
    ];
    input.representation?.dataset.addQuads([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), blankNode('b0')),
      quad(blankNode('b0'), namedNode('ex:p1'), namedNode('ex:o1')),
    ]);
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode('ex:s0'), namedNode('ex:p0'), blankNode('b0')),
    ]);
  });
});

import 'jest-rdf';
import { DataFactory } from 'n3';
import type { Quad } from '@rdfjs/types';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Patch } from '../../../../src/http/representation/Patch';
import type { RdfDatasetRepresentation } from '../../../../src/http/representation/RdfDatasetRepresentation';
import type { Representation } from '../../../../src/http/representation/Representation';
import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import { RdfPatcher } from '../../../../src/storage/patch/RdfPatcher';
import type {
  RepresentationPatcher,
  RepresentationPatcherInput,
} from '../../../../src/storage/patch/RepresentationPatcher';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { readableToQuads } from '../../../../src/util/StreamUtil';

const { quad, namedNode } = DataFactory;

describe('An RdfPatcher,', (): void => {
  let patcher: jest.Mocked<RepresentationPatcher<RdfDatasetRepresentation>>;
  let startQuads: Quad[];
  let rdfPatcher: RdfPatcher;
  let identifier: ResourceIdentifier;
  let representation: Representation;
  let patch: Patch;

  beforeEach((): void => {
    startQuads = [ quad(
      namedNode('http://test.com/startS1'),
      namedNode('http://test.com/startP1'),
      namedNode('http://test.com/startO1'),
    ), quad(
      namedNode('http://test.com/startS2'),
      namedNode('http://test.com/startP2'),
      namedNode('http://test.com/startO2'),
    ) ];
    patcher = {
      canHandle: jest.fn(),
      handle: jest.fn(),
      handleSafe: jest.fn(),
    };
    patcher.handle.mockImplementation(
      async(input: RepresentationPatcherInput<RdfDatasetRepresentation>):
      Promise<RdfDatasetRepresentation> => input.representation!,
    );

    rdfPatcher = new RdfPatcher(patcher);
    representation = new BasicRepresentation(startQuads, 'internal/quads');
  });

  it('errors when the representation is of the wrong content type.', async(): Promise<void> => {
    representation = new BasicRepresentation(startQuads, 'text/turtle');

    await expect(rdfPatcher.handleSafe({ identifier, patch, representation })).rejects.toThrow(InternalServerError);
    await expect(rdfPatcher.handleSafe({ identifier, patch, representation })).rejects
      .toThrow('Quad stream was expected for patching.');
    expect(patcher.handle).toHaveBeenCalledTimes(0);
  });

  it('uses a new store when there is no representation to patch.', async(): Promise<void> => {
    const result = await rdfPatcher.handleSafe({ identifier, patch });
    const store = await readableToQuads(result.data);
    expect(store).toBeRdfIsomorphic([]);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
  });

  it('transforms the representation to a store to patch.', async(): Promise<void> => {
    const result = await rdfPatcher.handleSafe({ identifier, patch, representation });
    const store = await readableToQuads(result.data);
    expect(store).toBeRdfIsomorphic(startQuads);
    expect(patcher.handle).toHaveBeenCalledTimes(1);
    expect(patcher.handle).toHaveBeenLastCalledWith({ identifier, patch, representation });
  });
});

import type { Representation } from '../../../../src';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { Patch } from '../../../../src/http/representation/Patch';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { PatchHandlerInput } from '../../../../src/storage/patch/PatchHandler';
import type { RepresentationPatcher } from '../../../../src/storage/patch/RepresentationPatcher';
import { RepresentationPatchHandler } from '../../../../src/storage/patch/RepresentationPatchHandler';
import type { ResourceStore } from '../../../../src/storage/ResourceStore';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';
import { ConflictHttpError } from '../../../../src/util/errors/ConflictHttpError';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';

describe('A RepresentationPatchHandler', (): void => {
  const identifier = { path: 'http://test.com/foo' };
  const representation = new BasicRepresentation('', 'text/turtle');
  const patch: Patch = new BasicRepresentation('', 'application/sparql-update');
  const patchResult = new BasicRepresentation('', 'application/trig');
  let input: PatchHandlerInput;
  let source: jest.Mocked<ResourceStore>;
  let patcher: jest.Mocked<RepresentationPatcher<Representation>>;
  let handler: RepresentationPatchHandler;

  beforeEach(async(): Promise<void> => {
    source = {
      getRepresentation: jest.fn().mockResolvedValue(representation),
      setRepresentation: jest.fn().mockResolvedValue({
        [identifier.path]: new RepresentationMetadata(identifier),
      }),
    } as any;

    input = { source, identifier, patch };

    patcher = {
      handleSafe: jest.fn().mockResolvedValue(patchResult),
    } as any;

    handler = new RepresentationPatchHandler(patcher);
  });

  it('calls the patcher with the representation from the store.', async(): Promise<void> => {
    await expect(handler.handle(input)).resolves.toEqual({
      [identifier.path]: new RepresentationMetadata(identifier),
    });

    expect(patcher.handleSafe).toHaveBeenCalledTimes(1);
    expect(patcher.handleSafe).toHaveBeenLastCalledWith({ identifier, patch, representation });

    expect(source.setRepresentation).toHaveBeenCalledTimes(1);
    expect(source.setRepresentation).toHaveBeenLastCalledWith(identifier, patchResult);
  });

  it('calls the patcher with no representation if there is none.', async(): Promise<void> => {
    source.getRepresentation.mockRejectedValueOnce(new NotFoundHttpError());

    await expect(handler.handle(input)).resolves.toEqual({
      [identifier.path]: new RepresentationMetadata(identifier),
    });

    expect(patcher.handleSafe).toHaveBeenCalledTimes(1);
    expect(patcher.handleSafe).toHaveBeenLastCalledWith({ identifier, patch });

    expect(source.setRepresentation).toHaveBeenCalledTimes(1);
    expect(source.setRepresentation).toHaveBeenLastCalledWith(identifier, patchResult);
  });

  it('errors if the store throws a non-404 error.', async(): Promise<void> => {
    const error = new BadRequestHttpError();
    source.getRepresentation.mockRejectedValueOnce(error);

    await expect(handler.handle(input)).rejects.toThrow(error);
  });

  it('errors if the target is a container.', async(): Promise<void> => {
    identifier.path = 'http://test.com/';
    await expect(handler.handle(input)).rejects.toThrow(ConflictHttpError);
  });
});

import 'jest-rdf';
import { DataFactory, Store } from 'n3';
import type { Quad } from '@rdfjs/types';
import type { Algebra } from 'sparqlalgebrajs';
import { translate } from 'sparqlalgebrajs';
import { BasicRepresentation } from '../../../../src/http/representation/BasicRepresentation';
import type { RdfDatasetRepresentation } from '../../../../src/http/representation/RdfDatasetRepresentation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { SparqlUpdatePatch } from '../../../../src/http/representation/SparqlUpdatePatch';
import type { RepresentationPatcherInput } from '../../../../src/storage/patch/RepresentationPatcher';
import { SparqlUpdatePatcher } from '../../../../src/storage/patch/SparqlUpdatePatcher';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { NotImplementedHttpError } from '../../../../src/util/errors/NotImplementedHttpError';
import { guardedStreamFrom } from '../../../../src/util/StreamUtil';

const { namedNode, quad } = DataFactory;

function getPatch(query: string): SparqlUpdatePatch {
  const prefixedQuery = `prefix : <http://test.com/>\n${query}`;
  return {
    algebra: translate(prefixedQuery, { quads: true }) as Algebra.Update,
    data: guardedStreamFrom(prefixedQuery),
    metadata: new RepresentationMetadata(),
    binary: true,
    isEmpty: false,
  };
}

describe('A SparqlUpdatePatcher', (): void => {
  let patcher: SparqlUpdatePatcher;
  let startQuads: Quad[];
  const identifier = { path: 'http://test.com/foo' };
  const fulfilledDataInsert = 'INSERT DATA { :s1 :p1 :o1 . :s2 :p2 :o2 . }';
  let store: Store;
  let input: RepresentationPatcherInput<RdfDatasetRepresentation>;
  let representation: RdfDatasetRepresentation;

  beforeEach(async(): Promise<void> => {
    startQuads = [ quad(
      namedNode('http://test.com/startS1'),
      namedNode('http://test.com/startP1'),
      namedNode('http://test.com/startO1'),
    ), quad(
      namedNode('http://test.com/startS2'),
      namedNode('http://test.com/startP2'),
      namedNode('http://test.com/startO2'),
    ) ];
    store = new Store(startQuads);

    representation = new BasicRepresentation() as RdfDatasetRepresentation;
    representation.dataset = store;
    input = { identifier, patch: { algebra: {}} as SparqlUpdatePatch, representation };

    patcher = new SparqlUpdatePatcher();
  });

  it('only accepts SPARQL updates.', async(): Promise<void> => {
    await expect(patcher.canHandle(input)).resolves.toBeUndefined();
    delete (input.patch as any).algebra;
    await expect(patcher.canHandle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('handles NOP operations by not doing anything.', async(): Promise<void> => {
    input.patch = getPatch('');
    await expect(patcher.handle(input)).resolves.toBe(representation);

    input.representation = undefined;
    input.patch = getPatch('');
    await expect(patcher.handle(input)).rejects.toThrow(InternalServerError);
  });

  it('handles INSERT DATA updates.', async(): Promise<void> => {
    input.patch = getPatch(fulfilledDataInsert);
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      ...startQuads,
      quad(namedNode('http://test.com/s1'), namedNode('http://test.com/p1'), namedNode('http://test.com/o1')),
      quad(namedNode('http://test.com/s2'), namedNode('http://test.com/p2'), namedNode('http://test.com/o2')),
    ]);
  });

  it('handles DELETE DATA updates.', async(): Promise<void> => {
    input.patch = getPatch('DELETE DATA { :startS1 :startP1 :startO1 }');
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(
        namedNode('http://test.com/startS2'),
        namedNode('http://test.com/startP2'),
        namedNode('http://test.com/startO2'),
      ),
    ]);
  });

  it('handles DELETE WHERE updates with no variables.', async(): Promise<void> => {
    input.patch = getPatch('DELETE WHERE { :startS1 :startP1 :startO1 }');
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(
        namedNode('http://test.com/startS2'),
        namedNode('http://test.com/startP2'),
        namedNode('http://test.com/startO2'),
      ),
    ]);
  });

  it('handles DELETE WHERE updates with variables.', async(): Promise<void> => {
    input.patch = getPatch('DELETE WHERE { :startS1 :startP1 ?o }');
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(
        namedNode('http://test.com/startS2'),
        namedNode('http://test.com/startP2'),
        namedNode('http://test.com/startO2'),
      ),
    ]);
  });

  it('handles DELETE/INSERT updates with empty WHERE.', async(): Promise<void> => {
    input.patch = getPatch('DELETE { :startS1 :startP1 :startO1 } INSERT { :s1 :p1 :o1 . } WHERE {}');
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(
        namedNode('http://test.com/startS2'),
        namedNode('http://test.com/startP2'),
        namedNode('http://test.com/startO2'),
      ),
      quad(
        namedNode('http://test.com/s1'),
        namedNode('http://test.com/p1'),
        namedNode('http://test.com/o1'),
      ),
    ]);
  });

  it('handles composite INSERT/DELETE updates.', async(): Promise<void> => {
    const query = 'INSERT DATA { :s1 :p1 :o1 . :s2 :p2 :o2 };' +
      'DELETE WHERE { :s1 :p1 :o1 . :startS1 :startP1 :startO1 }';
    input.patch = getPatch(query);
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(
        namedNode('http://test.com/startS2'),
        namedNode('http://test.com/startP2'),
        namedNode('http://test.com/startO2'),
      ),
      quad(
        namedNode('http://test.com/s2'),
        namedNode('http://test.com/p2'),
        namedNode('http://test.com/o2'),
      ),
    ]);
  });

  it('handles composite DELETE/INSERT updates.', async(): Promise<void> => {
    const query = 'DELETE DATA { :s1 :p1 :o1 . :startS1 :startP1 :startO1 } ;' +
      'INSERT DATA { :s1 :p1 :o1 . :s2 :p2 :o2 }';
    input.patch = getPatch(query);
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(
        namedNode('http://test.com/startS2'),
        namedNode('http://test.com/startP2'),
        namedNode('http://test.com/startO2'),
      ),
      quad(
        namedNode('http://test.com/s1'),
        namedNode('http://test.com/p1'),
        namedNode('http://test.com/o1'),
      ),
      quad(
        namedNode('http://test.com/s2'),
        namedNode('http://test.com/p2'),
        namedNode('http://test.com/o2'),
      ),
    ]);
  });

  it('rejects GRAPH inserts.', async(): Promise<void> => {
    const query = 'INSERT DATA { GRAPH :graph { :s1 :p1 :o1 } }';
    input.patch = getPatch(query);

    await expect(patcher.handle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('rejects GRAPH deletes.', async(): Promise<void> => {
    const query = 'DELETE DATA { GRAPH :graph { :s1 :p1 :o1 } }';
    input.patch = getPatch(query);

    await expect(patcher.handle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('rejects DELETE/INSERT updates with non-BGP WHERE.', async(): Promise<void> => {
    const query = 'DELETE { :s1 :p1 :o1 } INSERT { :s1 :p1 :o1 } WHERE { ?s ?p ?o. FILTER (?o > 5) }';
    input.patch = getPatch(query);

    await expect(patcher.handle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('rejects INSERT WHERE updates with a UNION.', async(): Promise<void> => {
    const query = 'INSERT { :s1 :p1 :o1 . } WHERE { { :s1 :p1 :o1 } UNION { :s1 :p1 :o2 } }';
    input.patch = getPatch(query);

    await expect(patcher.handle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('rejects non-DELETE/INSERT updates.', async(): Promise<void> => {
    const query = 'MOVE DEFAULT TO GRAPH :newGraph';
    input.patch = getPatch(query);

    await expect(patcher.handle(input)).rejects.toThrow(NotImplementedHttpError);
  });

  it('creates a new resource if it does not exist yet.', async(): Promise<void> => {
    const query = 'INSERT DATA { <http://test.com/s1> <http://test.com/p1> <http://test.com/o1>. }';
    input.patch = getPatch(query);
    input.representation!.dataset = new Store();
    const result = await patcher.handle(input);
    expect(result.dataset).toBeRdfIsomorphic([
      quad(namedNode('http://test.com/s1'), namedNode('http://test.com/p1'), namedNode('http://test.com/o1')),
    ]);
  });
});

import type { Patch } from '../../../src/http/representation/Patch';
import type { PatchHandler } from '../../../src/storage/patch/PatchHandler';
import { PatchingStore } from '../../../src/storage/PatchingStore';
import type { ResourceStore } from '../../../src/storage/ResourceStore';
import { NotImplementedHttpError } from '../../../src/util/errors/NotImplementedHttpError';

describe('A PatchingStore', (): void => {
  let store: PatchingStore;
  let source: jest.Mocked<ResourceStore>;
  let patcher: PatchHandler;
  let handleSafeFn: jest.Mock<Promise<void>, []>;

  beforeEach(async(): Promise<void> => {
    source = {
      modifyResource: jest.fn(async(): Promise<any> => 'modify'),
    } satisfies Partial<ResourceStore> as any;

    handleSafeFn = jest.fn(async(): Promise<any> => 'patcher');
    patcher = { handleSafe: handleSafeFn } as unknown as PatchHandler;

    store = new PatchingStore(source, patcher);
  });

  it('calls modifyResource directly from the source if available.', async(): Promise<void> => {
    await expect(store.modifyResource({ path: 'modifyPath' }, {} as Patch)).resolves.toBe('modify');
    expect(source.modifyResource).toHaveBeenCalledTimes(1);
    expect(source.modifyResource).toHaveBeenLastCalledWith({ path: 'modifyPath' }, {}, undefined);
  });

  it('calls its patcher if modifyResource is not implemented.', async(): Promise<void> => {
    jest.spyOn(source, 'modifyResource').mockImplementation(async(): Promise<any> => {
      throw new NotImplementedHttpError();
    });
    await expect(store.modifyResource({ path: 'modifyPath' }, {} as Patch)).resolves.toBe('patcher');
    expect(source.modifyResource).toHaveBeenCalledTimes(1);
    expect(source.modifyResource).toHaveBeenLastCalledWith({ path: 'modifyPath' }, {}, undefined);
    await expect(source.modifyResource.mock.results[0].value).rejects.toThrow(NotImplementedHttpError);
    expect(handleSafeFn).toHaveBeenCalledTimes(1);
    expect(handleSafeFn).toHaveBeenLastCalledWith({ source, identifier: { path: 'modifyPath' }, patch: {}});
  });

  it('rethrows source modifyResource errors.', async(): Promise<void> => {
    jest.spyOn(source, 'modifyResource').mockImplementation(async(): Promise<any> => {
      throw new Error('dummy');
    });
    await expect(store.modifyResource({ path: 'modifyPath' }, {} as Patch)).rejects.toThrow('dummy');
    expect(source.modifyResource).toHaveBeenCalledTimes(1);
    expect(source.modifyResource).toHaveBeenLastCalledWith({ path: 'modifyPath' }, {}, undefined);
    expect(handleSafeFn).toHaveBeenCalledTimes(0);
  });
});

import type { Patch } from '../../../src/http/representation/Patch';
import type { Representation } from '../../../src/http/representation/Representation';
import { ReadOnlyStore } from '../../../src/storage/ReadOnlyStore';
import type { ResourceStore } from '../../../src/storage/ResourceStore';
import { ForbiddenHttpError } from '../../../src/util/errors/ForbiddenHttpError';

describe('A ReadOnlyStore', (): void => {
  const source: jest.Mocked<ResourceStore> = {
    getRepresentation: jest.fn(async(): Promise<any> => 'get'),
    addResource: jest.fn(),
    setRepresentation: jest.fn(),
    deleteResource: jest.fn(),
    modifyResource: jest.fn(),
  } as any;
  let store: ReadOnlyStore;

  beforeAll((): void => {
    store = new ReadOnlyStore(source);
  });

  it('calls getRepresentation directly from the source.', async(): Promise<void> => {
    await expect(store.getRepresentation({ path: 'getPath' }, {})).resolves.toBe('get');
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(source.getRepresentation).toHaveBeenLastCalledWith({ path: 'getPath' }, {}, undefined);
  });

  it('throws an error when calling addResource.', async(): Promise<void> => {
    await expect(store.addResource({ path: 'addPath' }, {} as Representation))
      .rejects.toThrow(ForbiddenHttpError);
    expect(source.addResource).toHaveBeenCalledTimes(0);
  });

  it('throws an error when calling setRepresentation.', async(): Promise<void> => {
    await expect(store.setRepresentation({ path: 'setPath' }, {} as Representation))
      .rejects.toThrow(ForbiddenHttpError);
    expect(source.setRepresentation).toHaveBeenCalledTimes(0);
  });

  it('throws an error when calling deleteResource.', async(): Promise<void> => {
    await expect(store.deleteResource({ path: 'deletePath' }))
      .rejects.toThrow(ForbiddenHttpError);
    expect(source.deleteResource).toHaveBeenCalledTimes(0);
  });

  it('throws an error when calling modifyResource.', async(): Promise<void> => {
    await expect(store.modifyResource({ path: 'modifyPath' }, {} as Patch))
      .rejects.toThrow(ForbiddenHttpError);
    expect(source.modifyResource).toHaveBeenCalledTimes(0);
  });
});

import type { Representation } from '../../../src/http/representation/Representation';
import type { RepresentationPreferences } from '../../../src/http/representation/RepresentationPreferences';
import type { RepresentationConverter } from '../../../src/storage/conversion/RepresentationConverter';
import { RepresentationConvertingStore } from '../../../src/storage/RepresentationConvertingStore';
import type { ResourceStore } from '../../../src/storage/ResourceStore';
import { INTERNAL_QUADS } from '../../../src/util/ContentTypes';
import { SimpleSuffixStrategy } from '../../util/SimpleSuffixStrategy';

describe('A RepresentationConvertingStore', (): void => {
  const identifier = { path: 'identifier' };
  const metadata = { contentType: 'text/turtle' };
  const representation: Representation = { binary: true, data: 'data', metadata } as any;
  const preferences = { type: { 'text/plain': 1, 'text/turtle': 0 }};

  const sourceRepresentation = { data: 'data' };
  const source: ResourceStore = {
    getRepresentation: jest.fn().mockResolvedValue(sourceRepresentation),
    addResource: jest.fn(),
    setRepresentation: jest.fn(),
  } as any;

  const convertedIn = { in: true };
  const convertedOut = { out: true };
  const inConverter: RepresentationConverter = { handleSafe: jest.fn().mockResolvedValue(convertedIn) } as any;
  const outConverter: RepresentationConverter = { handleSafe: jest.fn().mockResolvedValue(convertedOut) } as any;

  const inPreferences: RepresentationPreferences = { type: { 'text/turtle': 1 }};
  const metadataStrategy = new SimpleSuffixStrategy('.meta');
  const store = new RepresentationConvertingStore(
    source,
    metadataStrategy,
    { inPreferences, inConverter, outConverter },
  );

  beforeEach(async(): Promise<void> => {
    jest.clearAllMocks();
  });

  it('calls the outgoing converter when retrieving a representation.', async(): Promise<void> => {
    await expect(store.getRepresentation(identifier, preferences)).resolves.toEqual(convertedOut);
    expect(source.getRepresentation).toHaveBeenCalledTimes(1);
    expect(outConverter.handleSafe).toHaveBeenCalledTimes(1);
    expect(outConverter.handleSafe).toHaveBeenNthCalledWith(1, {
      identifier,
      representation: sourceRepresentation,
      preferences,
    });
  });

  it('calls the incoming converter when adding resources.', async(): Promise<void> => {
    await expect(store.addResource(identifier, representation, 'conditions' as any)).resolves.toBeUndefined();
    expect(inConverter.handleSafe).toHaveBeenCalledTimes(1);
    expect(inConverter.handleSafe).toHaveBeenNthCalledWith(1, {
      identifier,
      representation,
      preferences: { type: { 'text/turtle': 1 }},
    });
    expect(source.addResource).toHaveBeenLastCalledWith(identifier, convertedIn, 'conditions');
  });

  it('calls the incoming converter when setting representations.', async(): Promise<void> => {
    await expect(store.setRepresentation(identifier, representation, 'conditions' as any)).resolves.toBeUndefined();
    expect(inConverter.handleSafe).toHaveBeenCalledTimes(1);
    expect(inConverter.handleSafe).toHaveBeenNthCalledWith(1, {
      identifier,
      representation,
      preferences: { type: { 'text/turtle': 1 }},
    });
    expect(source.setRepresentation).toHaveBeenLastCalledWith(identifier, convertedIn, 'conditions');
  });

  it('does not perform any conversions when constructed with empty arguments.', async(): Promise<void> => {
    const noArgStore = new RepresentationConvertingStore(source, metadataStrategy, {});
    await expect(noArgStore.getRepresentation(identifier, preferences)).resolves.toEqual(sourceRepresentation);
    await expect(noArgStore.addResource(identifier, representation)).resolves.toBeUndefined();
    await expect(noArgStore.setRepresentation(identifier, representation)).resolves.toBeUndefined();
  });

  it('converts metadata resources to internal quads.', async(): Promise<void> => {
    const resourceID = { path: 'identifier.meta' };

    await expect(store.setRepresentation(resourceID, representation)).resolves.toBeUndefined();
    expect(inConverter.handleSafe).toHaveBeenCalledTimes(1);
    expect(inConverter.handleSafe).toHaveBeenNthCalledWith(1, {
      identifier: resourceID,
      representation,
      preferences: { type: { [INTERNAL_QUADS]: 1 }},
    });
    expect(source.setRepresentation).toHaveBeenLastCalledWith(resourceID, convertedIn, undefined);
  });
});

import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import type { ResourceStore } from '../../../../src/storage/ResourceStore';
import { BaseUrlRouterRule } from '../../../../src/storage/routing/BaseUrlRouterRule';
import { NotFoundHttpError } from '../../../../src/util/errors/NotFoundHttpError';

describe('A BaseUrlRouterRule', (): void => {
  let stores: KeyValueStorage<string, ResourceStore>;
  const baseStore = 'baseStore!' as any;
  const aliceIdentifier = { path: 'http://alice.test.com/' };
  const aliceStore = 'aliceStore!' as any;
  let rule: BaseUrlRouterRule;

  beforeEach(async(): Promise<void> => {
    stores = new Map([[ aliceIdentifier.path, aliceStore ]]) as any;

    rule = new BaseUrlRouterRule(stores, baseStore);
  });

  it('returns the matching store if the request contains the correct identifier.', async(): Promise<void> => {
    await expect(rule.handle({ identifier: { path: 'http://alice.test.com/foo' }})).resolves.toEqual(aliceStore);
  });

  it('returns the base store if there is no matching identifier.', async(): Promise<void> => {
    await expect(rule.handle({ identifier: { path: 'http://bob.test.com/foo' }})).resolves.toEqual(baseStore);
  });

  it('errors if there is no match and no base store.', async(): Promise<void> => {
    rule = new BaseUrlRouterRule(stores);
    await expect(rule.handle({ identifier: { path: 'http://bob.test.com/foo' }})).rejects.toThrow(NotFoundHttpError);
  });
});

import type { Representation } from '../../../../src/http/representation/Representation';
import { RepresentationMetadata } from '../../../../src/http/representation/RepresentationMetadata';
import type { ResourceStore } from '../../../../src/storage/ResourceStore';
import { ConvertingRouterRule } from '../../../../src/storage/routing/ConvertingRouterRule';
import type { PreferenceSupport } from '../../../../src/storage/routing/PreferenceSupport';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';

describe('A ConvertingRouterRule', (): void => {
  let store1: jest.Mocked<ResourceStore>;
  let store2: jest.Mocked<ResourceStore>;
  let defaultStore: ResourceStore;
  let checker1: PreferenceSupport;
  let checker2: PreferenceSupport;
  let rule: ConvertingRouterRule;
  let representation: Representation;
  let metadata: RepresentationMetadata;

  beforeEach(async(): Promise<void> => {
    store1 = {
      name: 'turtleStore',
      hasResource: jest.fn(),
    } as any satisfies ResourceStore;
    store2 = {
      name: 'textStore',
      hasResource: jest.fn(),
    } as any satisfies ResourceStore;
    defaultStore = { name: 'defaultStore' } as any;

    checker1 = {
      async supports(input: { representation: Representation }): Promise<boolean> {
        return input.representation.metadata.contentType === 'text/turtle';
      },
    } as any;

    checker2 = {
      async supports(input: { representation: Representation }): Promise<boolean> {
        return input.representation.metadata.contentType === 'application/ld+json';
      },
    } as any;

    rule = new ConvertingRouterRule([
      { store: store1, supportChecker: checker1 },
      { store: store2, supportChecker: checker2 },
    ], defaultStore);

    metadata = new RepresentationMetadata();
    representation = { binary: true, data: 'data!' as any, metadata, isEmpty: false };
  });

  it('returns the corresponding store if it supports the input.', async(): Promise<void> => {
    metadata.contentType = 'text/turtle';
    await expect(rule.handle({ identifier: { path: 'identifier' }, representation })).resolves.toBe(store1);
    metadata.contentType = 'application/ld+json';
    await expect(rule.handle({ identifier: { path: 'identifier' }, representation })).resolves.toBe(store2);
  });

  it('returns the defaultStore if the converter does not support the input.', async(): Promise<void> => {
    await expect(rule.handle({ identifier: { path: 'identifier' }, representation })).resolves.toBe(defaultStore);
  });

  it('checks if the stores contain the identifier if there is no data.', async(): Promise<void> => {
    store1.hasResource.mockImplementationOnce((): any => true);
    await expect(rule.handle({ identifier: { path: 'identifier' }})).resolves.toBe(store1);
    expect(store1.hasResource).toHaveBeenCalledTimes(1);
  });

  it('returns the defaultStore if no other store has the resource.', async(): Promise<void> => {
    store1.hasResource.mockImplementationOnce((): any => false);
    store2.hasResource.mockImplementationOnce((): any => false);
    await expect(rule.handle({ identifier: { path: 'identifier' }})).resolves.toBe(defaultStore);
  });

  it('throws the error if a store had a non-404 error.', async(): Promise<void> => {
    store1.hasResource.mockRejectedValueOnce(new InternalServerError());
    await expect(rule.handle({ identifier: { path: 'identifier' }})).rejects.toThrow(InternalServerError);
  });
});

import type { Representation } from '../../../../src/http/representation/Representation';
import type { RepresentationPreferences } from '../../../../src/http/representation/RepresentationPreferences';
import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import type { RepresentationConverter } from '../../../../src/storage/conversion/RepresentationConverter';
import { PreferenceSupport } from '../../../../src/storage/routing/PreferenceSupport';
import { BadRequestHttpError } from '../../../../src/util/errors/BadRequestHttpError';

describe('A PreferenceSupport', (): void => {
  let preferences: RepresentationPreferences;
  let converter: RepresentationConverter;
  let support: PreferenceSupport;
  const type = 'internal/quads';
  const identifier: ResourceIdentifier = 'identifier' as any;
