import type { AsyncHandler } from '../../../../src/util/handlers/AsyncHandler';
import { WaterfallHandler } from '../../../../src/util/handlers/WaterfallHandler';
import { StaticAsyncHandler } from '../../../util/StaticAsyncHandler';

describe('A WaterfallHandler', (): void => {
  describe('with no handlers', (): void => {
    it('can never handle data.', async(): Promise<void> => {
      const handler = new WaterfallHandler([]);

      await expect(handler.canHandle(null)).rejects.toThrow(Error);
    });

    it('errors if its handle function is called.', async(): Promise<void> => {
      const handler = new WaterfallHandler([]);

      await expect(handler.handle(null)).rejects.toThrow(Error);
    });
  });

  describe('with multiple handlers', (): void => {
    let handlerTrue: AsyncHandler<any, any>;
    let handlerFalse: AsyncHandler<any, any>;
    let canHandleFn: jest.Mock<Promise<void>, [any]>;
    let handleFn: jest.Mock<Promise<void>, [any]>;

    beforeEach(async(): Promise<void> => {
      handlerTrue = new StaticAsyncHandler(true, null);
      handlerFalse = new StaticAsyncHandler(false, null);

      canHandleFn = jest.fn(async(input: any): Promise<any> => input);
      handleFn = jest.fn(async(input: any): Promise<any> => input);
      handlerTrue.canHandle = canHandleFn;
      handlerTrue.handle = handleFn;
    });

    it('can handle data if a handler supports it.', async(): Promise<void> => {
      const handler = new WaterfallHandler([ handlerFalse, handlerTrue ]);

      await expect(handler.canHandle(null)).resolves.toBeUndefined();
    });

    it('can not handle data if no handler supports it.', async(): Promise<void> => {
      const handler = new WaterfallHandler([ handlerFalse, handlerFalse ]);

      await expect(handler.canHandle(null)).rejects.toThrow('Not supported, Not supported');
    });

    it('throws unknown errors if no Error objects are thrown.', async(): Promise<void> => {
      handlerFalse.canHandle = async(): Promise<void> => {
        // eslint-disable-next-line @typescript-eslint/only-throw-error
        throw 'apple';
      };
      const handler = new WaterfallHandler([ handlerFalse, handlerFalse ]);

      await expect(handler.canHandle(null)).rejects.toThrow('Unknown error: apple, Unknown error: apple');
    });

    it('handles data if a handler supports it.', async(): Promise<void> => {
      const handler = new WaterfallHandler([ handlerFalse, handlerTrue ]);

      await expect(handler.handle('test')).resolves.toBe('test');
      expect(canHandleFn).toHaveBeenCalledTimes(1);
      expect(handleFn).toHaveBeenCalledTimes(1);
    });

    it('errors if the handle function is called but no handler supports the data.', async(): Promise<void> => {
      const handler = new WaterfallHandler([ handlerFalse, handlerFalse ]);

      await expect(handler.handle('test')).rejects.toThrow('All handlers failed');
    });

    it('only calls the canHandle function once of its handlers when handleSafe is called.', async(): Promise<void> => {
      const handler = new WaterfallHandler([ handlerFalse, handlerTrue ]);

      await expect(handler.handleSafe('test')).resolves.toBe('test');
      expect(canHandleFn).toHaveBeenCalledTimes(1);
      expect(handleFn).toHaveBeenCalledTimes(1);
    });

    it('throws the canHandle error when calling handleSafe if the data is not supported.', async(): Promise<void> => {
      const handler = new WaterfallHandler([ handlerFalse, handlerFalse ]);

      await expect(handler.handleSafe(null)).rejects.toThrow('Not supported, Not supported');
    });
  });
});

import type { HttpResponse } from '../../../src/server/HttpResponse';
import { BadRequestHttpError } from '../../../src/util/errors/BadRequestHttpError';
import { ContentType } from '../../../src/util/Header';
import {
  addHeader,
  hasScheme,
  matchesAuthorizationScheme,
  parseAccept,
  parseAcceptCharset,
  parseAcceptDateTime,
  parseAcceptEncoding,
  parseAcceptLanguage,
  parseContentType,
  parseForwarded,
  parseLinkHeader,
} from '../../../src/util/HeaderUtil';

describe('HeaderUtil', (): void => {
  describe('#parseAccept', (): void => {
    it('parses empty Accept headers.', async(): Promise<void> => {
      expect(parseAccept('')).toEqual([]);
    });

    it('parses Accept headers with a single entry.', async(): Promise<void> => {
      expect(parseAccept('audio/basic')).toEqual([
        { range: 'audio/basic', weight: 1, parameters: { mediaType: {}, extension: {}}},
      ]);
    });

    it('parses Accept headers with multiple entries.', async(): Promise<void> => {
      expect(parseAccept('audio/*; q=0.2, audio/basic')).toEqual([
        { range: 'audio/basic', weight: 1, parameters: { mediaType: {}, extension: {}}},
        { range: 'audio/*', weight: 0.2, parameters: { mediaType: {}, extension: {}}},
      ]);
    });

    it('parses complex Accept headers.', async(): Promise<void> => {
      expect(parseAccept(
        'text/html;q=0.7, text/html;level=1, text/html;level=2;q=0.4,text/x-dvi; q=0.8; mxb=100000; mxt',
      )).toEqual([
        { range: 'text/html', weight: 1, parameters: { mediaType: { level: '1' }, extension: {}}},
        { range: 'text/x-dvi', weight: 0.8, parameters: { mediaType: {}, extension: { mxb: '100000', mxt: '' }}},
        { range: 'text/html', weight: 0.7, parameters: { mediaType: {}, extension: {}}},
        { range: 'text/html', weight: 0.4, parameters: { mediaType: { level: '2' }, extension: {}}},
      ]);
    });

    it('parses Accept headers with double quoted values.', async(): Promise<void> => {
      expect(parseAccept('audio/basic; param1="val" ; q=0.5 ;param2="\\\\\\"valid"')).toEqual([
        {
          range: 'audio/basic',
          weight: 0.5,
          parameters: { mediaType: { param1: 'val' }, extension: { param2: '\\\\\\"valid' }},
        },
      ]);
    });

    it('ignores Accept Headers with invalid types.', async(): Promise<void> => {
      expect(parseAccept('*')).toEqual([]);
      expect(parseAccept('"bad"/text')).toEqual([]);
      expect(parseAccept('*/\\bad')).toEqual([]);
      expect(parseAccept('*/*')).toEqual([
        { parameters: { extension: {}, mediaType: {}}, range: '*/*', weight: 1 },
      ]);
    });

    it('ignores the weight of Accept Headers with q values it can not parse.', async(): Promise<void> => {
      expect(parseAccept('a/b; q=text')).toEqual([
        { range: 'a/b', weight: 1, parameters: { extension: {}, mediaType: {}}},
      ]);
      // Invalid Q value but can be parsed
      expect(parseAccept('a/b; q=0.1234')).toEqual([
        { range: 'a/b', weight: 0.1234, parameters: { extension: {}, mediaType: {}}},
      ]);
      expect(parseAccept('a/b; q=1.1')).toEqual([
        { range: 'a/b', weight: 1, parameters: { extension: {}, mediaType: {}}},
      ]);
      expect(parseAccept('a/b; q=1.000')).toEqual([
        { range: 'a/b', weight: 1, parameters: { extension: {}, mediaType: {}}},
      ]);
      expect(parseAccept('a/b; q=-5')).toEqual([
        { range: 'a/b', weight: 0, parameters: { extension: {}, mediaType: {}}},
      ]);
      expect(parseAccept('a/b; q=0.123')).toEqual([
        { range: 'a/b', weight: 0.123, parameters: { extension: {}, mediaType: {}}},
      ]);
    });

    it('ignores Accept Headers with invalid parameters.', async(): Promise<void> => {
      expect(parseAccept('a/b; a')).toEqual([
        { range: 'a/b', weight: 1, parameters: { extension: {}, mediaType: {}}},
      ]);
      expect(parseAccept('a/b; a=\\')).toEqual([
        { range: 'a/b', weight: 1, parameters: { extension: {}, mediaType: {}}},
      ]);
      expect(parseAccept('a/b; q=1 ; a=\\')).toEqual([
        { range: 'a/b', weight: 1, parameters: { extension: {}, mediaType: {}}},
      ]);
      expect(parseAccept('a/b; q=1 ; a')).toEqual([
        { range: 'a/b', weight: 1, parameters: { extension: { a: '' }, mediaType: {}}},
      ]);
    });

    it('rejects Accept Headers with quoted parameters.', async(): Promise<void> => {
      expect((): any => parseAccept('a/b; a="\\""')).not.toThrow();
      expect((): any => parseAccept('a/b; a="\\\u007F"')).toThrow('Invalid quoted string in header:');
    });

    it('rejects invalid values when strict mode is enabled.', async(): Promise<void> => {
      expect((): any => parseAccept('"bad"/text', true)).toThrow(BadRequestHttpError);
      expect((): any => parseAccept('a/b; q=text', true)).toThrow(BadRequestHttpError);
      expect((): any => parseAccept('a/b; a', true)).toThrow(BadRequestHttpError);
    });
  });

  describe('#parseCharset', (): void => {
    it('parses Accept-Charset headers.', async(): Promise<void> => {
      expect(parseAcceptCharset('iso-8859-5, unicode-1-1;q=0.8')).toEqual([
        { range: 'iso-8859-5', weight: 1 },
        { range: 'unicode-1-1', weight: 0.8 },
      ]);
    });

    it('ignores invalid Accept-Charset Headers.', async(): Promise<void> => {
      expect(parseAcceptCharset('a/b')).toEqual([]);
      expect(parseAcceptCharset('a; q=text')).toEqual([{ range: 'a', weight: 1 }]);
      expect(parseAcceptCharset('a; c=d')).toEqual([{ range: 'a', weight: 1 }]);
    });

    it('rejects invalid values when strict mode is enabled.', async(): Promise<void> => {
      expect((): any => parseAcceptCharset('a/b', true)).toThrow(BadRequestHttpError);
    });
  });

  describe('#parseEncoding', (): void => {
    it('parses empty Accept-Encoding headers.', async(): Promise<void> => {
      expect(parseAcceptCharset('')).toEqual([]);
    });

    it('parses Accept-Encoding headers.', async(): Promise<void> => {
      expect(parseAcceptEncoding('gzip;q=1.000, identity; q=0.5, *;q=0')).toEqual([
        { range: 'gzip', weight: 1 },
        { range: 'identity', weight: 0.5 },
        { range: '*', weight: 0 },
      ]);
    });

    it('ignores invalid Accept-Encoding Headers.', async(): Promise<void> => {
      expect(parseAcceptEncoding('a/b')).toEqual([]);
      expect(parseAcceptEncoding('a; q=text')).toEqual([{ range: 'a', weight: 1 }]);
      expect(parseAcceptCharset('a; c=d')).toEqual([{ range: 'a', weight: 1 }]);
    });

    it('rejects invalid values when strict mode is enabled.', async(): Promise<void> => {
      expect((): any => parseAcceptEncoding('a/b', true)).toThrow(BadRequestHttpError);
    });
  });

  describe('#parseLanguage', (): void => {
    it('parses Accept-Language headers.', async(): Promise<void> => {
      expect(parseAcceptLanguage('da, en-gb;q=0.8, en;q=0.7')).toEqual([
        { range: 'da', weight: 1 },
        { range: 'en-gb', weight: 0.8 },
        { range: 'en', weight: 0.7 },
      ]);
    });

    it('ignores invalid Accept-Language Headers.', async(): Promise<void> => {
      expect(parseAcceptLanguage('a/b')).toEqual([]);
      expect(parseAcceptLanguage('05-a')).toEqual([]);
      expect(parseAcceptLanguage('a--05')).toEqual([]);
      expect(parseAcceptLanguage('a-"a"')).toEqual([]);
      expect(parseAcceptLanguage('a-05')).toEqual([{ range: 'a-05', weight: 1 }]);
      expect(parseAcceptLanguage('a-b-c-d')).toEqual([{ range: 'a-b-c-d', weight: 1 }]);

      expect(parseAcceptLanguage('a; q=text')).toEqual([{ range: 'a', weight: 1 }]);
      expect(parseAcceptCharset('a; c=d')).toEqual([{ range: 'a', weight: 1 }]);
    });

    it('rejects invalid values when strict mode is enabled.', async(): Promise<void> => {
      expect((): any => parseAcceptLanguage('a/b', true)).toThrow(BadRequestHttpError);
    });
  });

  describe('#parseAcceptDateTime', (): void => {
    it('parses valid Accept-DateTime Headers.', async(): Promise<void> => {
      expect(parseAcceptDateTime('Wed, 30 May 2007 18:47:52 GMT')).toEqual([
        { range: 'Wed, 30 May 2007 18:47:52 GMT', weight: 1 },
      ]);
    });

    it('parses empty Accept-DateTime headers.', async(): Promise<void> => {
      expect(parseAcceptDateTime('')).toEqual([]);
      expect(parseAcceptDateTime('   ')).toEqual([]);
    });

    it('ignores invalid Accept-DateTime Headers.', async(): Promise<void> => {
      expect(parseAcceptDateTime('a/b')).toEqual([]);
      expect(parseAcceptDateTime('30 May 2007')).toEqual([]);
    });

    it('rejects invalid values when strict mode is enabled.', async(): Promise<void> => {
      expect((): any => parseAcceptLanguage('a/b', true)).toThrow(BadRequestHttpError);
    });
  });

  describe('#addHeader', (): void => {
    let response: HttpResponse;

    beforeEach(async(): Promise<void> => {
      const headers: Record<string, string | number | string[]> = {};
      response = {
        hasHeader: (name: string): boolean => Boolean(headers[name]),
        getHeader: (name: string): number | string | string[] | undefined => headers[name],
        setHeader(name: string, value: number | string | string[]): void {
          headers[name] = value;
        },
      } as any;
    });

    it('adds values if there are none already.', async(): Promise<void> => {
      expect(addHeader(response, 'name', 'value')).toBeUndefined();
      expect(response.getHeader('name')).toBe('value');

      expect(addHeader(response, 'names', [ 'value1', 'values2' ])).toBeUndefined();
      expect(response.getHeader('names')).toEqual([ 'value1', 'values2' ]);
    });

    it('appends values to already existing values.', async(): Promise<void> => {
      response.setHeader('name', 'oldValue');
      expect(addHeader(response, 'name', 'value')).toBeUndefined();
      expect(response.getHeader('name')).toEqual([ 'oldValue', 'value' ]);

      response.setHeader('number', 5);
      expect(addHeader(response, 'number', 'value')).toBeUndefined();
      expect(response.getHeader('number')).toEqual([ '5', 'value' ]);

      response.setHeader('names', [ 'oldValue1', 'oldValue2' ]);
      expect(addHeader(response, 'names', [ 'value1', 'values2' ])).toBeUndefined();
      expect(response.getHeader('names')).toEqual([ 'oldValue1', 'oldValue2', 'value1', 'values2' ]);
    });
  });

  describe('#parseContentType', (): void => {
    const contentTypeTurtle = 'text/turtle';
    const contentTypePlain: any = {
      value: 'text/plain',
      parameters: {
        charset: 'utf-8',
      },
    };

    it('handles single content-type parameter (with leading and trailing whitespaces).', (): void => {
      expect(parseContentType('text/turtle').value).toEqual(contentTypeTurtle);
      expect(parseContentType('text/turtle ').value).toEqual(contentTypeTurtle);
      expect(parseContentType(' text/turtle').value).toEqual(contentTypeTurtle);
      expect(parseContentType('text/plain; charset=utf-8')).toEqual(contentTypePlain);
      expect(parseContentType(' text/plain; charset=utf-8')).toEqual(contentTypePlain);
      expect(parseContentType('text/plain ; charset=utf-8')).toEqual(contentTypePlain);
      expect(parseContentType(' text/plain ; charset=utf-8')).toEqual(contentTypePlain);
      expect(parseContentType(' text/plain ; charset="utf-8"')).toEqual(contentTypePlain);
      expect(parseContentType(' text/plain ; charset = "utf-8"')).toEqual(contentTypePlain);
    });

    it('handles multiple content-type parameters.', (): void => {
      expect(parseContentType('text/turtle; charset=UTF-8').value).toEqual(contentTypeTurtle);
      contentTypePlain.parameters.test = 'value1';
      expect(parseContentType('text/plain; charset=utf-8;test="value1"')).toEqual(contentTypePlain);
    });

    it('errors on invalid content-types.', (): void => {
      expect((): any => parseContentType('invalid type')).toThrow(BadRequestHttpError);
    });
  });

  describe('#parseForwarded', (): void => {
    it('handles an empty set of headers.', (): void => {
      expect(parseForwarded({})).toEqual({});
    });

    it('handles empty string values.', (): void => {
      const headers = { forwarded: '', 'x-forwarded-host': '', 'x-forwarded-proto': '' };
      expect(parseForwarded(headers)).toEqual({});
    });

    it('parses a Forwarded header value.', (): void => {
      const headers = { forwarded: 'for=192.0.2.60;proto=http;by=203.0.113.43;host=example.org' };
      expect(parseForwarded(headers)).toEqual({
        by: '203.0.113.43',
        for: '192.0.2.60',
        host: 'example.org',
        proto: 'http',
      });
    });

    it('skips empty fields.', (): void => {
      const headers = { forwarded: 'for=192.0.2.60;proto=;by=;host=' };
      expect(parseForwarded(headers)).toEqual({
        for: '192.0.2.60',
      });
    });

    it('takes only the first value into account.', (): void => {
      const headers = { forwarded: 'host=pod.example, for=192.0.2.43, host=other' };
      expect(parseForwarded(headers)).toEqual({
        host: 'pod.example',
      });
    });

    it('should fall back to X-Forwarded-Host and X-Forwarded-Proto without Forward header.', (): void => {
      const headers = { 'x-forwarded-host': 'pod.example', 'x-forwarded-proto': 'https' };
      expect(parseForwarded(headers)).toEqual({
        host: 'pod.example',
        proto: 'https',
      });
    });

    it('should prefer Forwarded to X-Forwarded-Host and X-Forwarded-Proto with Forward header.', (): void => {
      const headers = {
        forwarded: 'proto=http;host=pod.example',
        'x-forwarded-host': 'anotherpod.example',
        'x-forwarded-proto': 'https',
      };
      expect(parseForwarded(headers)).toEqual({
        host: 'pod.example',
        proto: 'http',
      });
    });

    it('should properly handle multiple values with varying spaces for X-Forwarded-*.', (): void => {
      const headers = {
        'x-forwarded-host': ' pod.example ,192.0.2.60, 192.0.2.43',
        'x-forwarded-proto': ' https ,http',
      };
      expect(parseForwarded(headers)).toEqual({
        host: 'pod.example',
        proto: 'https',
      });
    });
  });

  describe('#parseLinkHeader', (): void => {
    it('handles an empty set of headers.', (): void => {
      expect(parseLinkHeader([])).toEqual([]);
    });

    it('handles empty string values.', (): void => {
      expect(parseLinkHeader([ '' ])).toEqual([]);
    });

    it('parses a Link header value as array.', (): void => {
      const link = [ '<http://test.com>; rel="myRel"; test="value1"' ];
      expect(parseLinkHeader(link)).toEqual([
        {
          target: 'http://test.com',
          parameters: {
            rel: 'myRel',
            test: 'value1',
          },
        },
      ]);
    });

    it('parses a Link header value as string.', (): void => {
      const link = '<http://test.com>; rel="myRel"; test="value1"';
      expect(parseLinkHeader(link)).toEqual([
        {
          target: 'http://test.com',
          parameters: {
            rel: 'myRel',
            test: 'value1',
          },
        },
      ]);
    });

    it('parses multiple Link header values delimited by a comma.', (): void => {
      const link = [ `<http://test.com>; rel="myRel"; test="value1", 
      <http://test2.com>; rel="myRel2"; test="value2"` ];
      expect(parseLinkHeader(link)).toEqual([
        {
          target: 'http://test.com',
          parameters: {
            rel: 'myRel',
            test: 'value1',
          },
        },
        {
          target: 'http://test2.com',
          parameters: {
            rel: 'myRel2',
            test: 'value2',
          },
        },
      ]);
    });

    it('parses multiple Link header values as array elements.', (): void => {
      const link = [
        '<http://test.com>; rel="myRel"; test="value1"',
        '<http://test2.com>; rel="myRel2"; test="value2"',
      ];
      expect(parseLinkHeader(link)).toEqual([
        {
          target: 'http://test.com',
          parameters: {
            rel: 'myRel',
            test: 'value1',
          },
        },
        {
          target: 'http://test2.com',
          parameters: {
            rel: 'myRel2',
            test: 'value2',
          },
        },
      ]);
    });

    it('ignores invalid syntax links.', (): void => {
      const link = [
        'http://test.com; rel="myRel"; test="value1"',
        '<http://test2.com>; rel="myRel2"; test="value2"',
      ];
      expect(parseLinkHeader(link)).toEqual([
        {
          target: 'http://test2.com',
          parameters: {
            rel: 'myRel2',
            test: 'value2',
          },
        },
      ]);
    });

    it('ignores invalid links (no rel parameter).', (): void => {
      const link = [
        '<http://test.com>; att="myAtt"; test="value1"',
        '<http://test2.com>; rel="myRel2"; test="value2"',
      ];
      expect(parseLinkHeader(link)).toEqual([
        {
          target: 'http://test2.com',
          parameters: {
            rel: 'myRel2',
            test: 'value2',
          },
        },
      ]);
    });

    it('ignores extra rel parameters.', (): void => {
      const link = [
        '<http://test.com>; rel="myRel1"; rel="myRel2"; test="value1"',
      ];
      expect(parseLinkHeader(link)).toEqual([
        {
          target: 'http://test.com',
          parameters: {
            rel: 'myRel1',
            test: 'value1',
          },
        },
      ]);
    });

    it('works with an empty argument.', (): void => {
      expect(parseLinkHeader()).toEqual([]);
    });
  });

  describe('#matchesAuthorizationScheme', (): void => {
    it('returns true if the provided authorization header value matches the provided scheme.', (): void => {
      const authorization = `Bearer Q0xXTzl1dTM4RF8xLXllSGx5am51WFUzbzZ2LTZ1WU1GWXpfMTBEajBjaw==`;
      expect(matchesAuthorizationScheme('Bearer', authorization)).toBeTruthy();
    });

    it('returns false if the provided authorization header value does not match the provided scheme.', (): void => {
      const authorization = `Basic YWxpY2U6YWxpY2U=`;
      expect(matchesAuthorizationScheme('Bearer', authorization)).toBeFalsy();
    });

    it('correctly detects scheme matches when a different casing is used.', (): void => {
      const authorization = `bAsIc YWxpY2U6YWxpY2U=`;
      expect(matchesAuthorizationScheme('Basic', authorization)).toBeTruthy();
    });

    it('escapes special regex characters in the scheme argument, resulting in a correct match.', (): void => {
      const authorization = `bA.*sIc$ YWxpY2U6YWxpY2U=`;
      expect(matchesAuthorizationScheme('bA.*sIc$', authorization)).toBeTruthy();
    });

    it('returns false if the authorization argument is undefined.', (): void => {
      expect(matchesAuthorizationScheme('Bearer')).toBeFalsy();
    });
  });

  describe('#hasScheme', (): void => {
    it('returns true if the provided url matches the provided scheme.', (): void => {
      expect(hasScheme('http://example.com', 'http')).toBeTruthy();
    });

    it('returns true if the provided url matches one of the provided schemes.', (): void => {
      expect(hasScheme('ws://example.com', 'http', 'https', 'ws')).toBeTruthy();
    });

    it('returns false if the provided url does not match the provided scheme.', (): void => {
      expect(hasScheme('http://example.com', 'https')).toBeFalsy();
    });

    it('returns false if the provided value is not a valid url.', (): void => {
      expect(hasScheme('not-a-URL:test', 'http')).toBeFalsy();
    });

    it('is case insensitive: schemes with different case, result in a correct match.', (): void => {
      expect(hasScheme('wss://example.com', 'http', 'WSS')).toBeTruthy();
    });
  });

  describe('A ContentType instance', (): void => {
    it('can serialize to a correct header value string with parameters.', (): void => {
      const contentType: ContentType = new ContentType(
        'text/plain',
        {
          charset: 'utf-8',
          extra: 'test',
        },
      );
      expect(contentType.toHeaderValueString()).toBe('text/plain; charset=utf-8; extra=test');
    });

    it('can serialize to a correct header value string without parameters.', (): void => {
      const contentType: ContentType = new ContentType('text/plain');
      expect(contentType.toHeaderValueString()).toBe('text/plain');
    });
  });
});

import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import { extractErrorTerms } from '../../../../src/util/errors/HttpErrorUtil';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { BaseIdentifierStrategy } from '../../../../src/util/identifiers/BaseIdentifierStrategy';

class DummyStrategy extends BaseIdentifierStrategy {
  public supportsIdentifier(identifier: ResourceIdentifier): boolean {
    return !identifier.path.endsWith('unsupported');
  }

  public isRootContainer(identifier: ResourceIdentifier): boolean {
    return identifier.path.endsWith('root');
  }
}

describe('A BaseIdentifierStrategy', (): void => {
  const strategy = new DummyStrategy();

  describe('getParentContainer', (): void => {
    it('returns the parent identifier.', async(): Promise<void> => {
      expect(strategy.getParentContainer({ path: 'http://example.com/foo/bar' })).toEqual({ path: 'http://example.com/foo/' });
      expect(strategy.getParentContainer({ path: 'http://example.com/foo//' })).toEqual({ path: 'http://example.com/' });
      expect(strategy.getParentContainer({ path: 'http://example.com/foo/bar/' })).toEqual({ path: 'http://example.com/foo/' });
      expect(strategy.getParentContainer({ path: 'http://example.com/foo/bar?q=5' })).toEqual({ path: 'http://example.com/foo/' });
    });

    it('errors when attempting to get the parent of an unsupported identifier.', async(): Promise<void> => {
      let error: unknown;
      try {
        strategy.getParentContainer({ path: '/unsupported' });
      } catch (err: unknown) {
        error = err;
      }
      expect(error).toEqual(expect.objectContaining({
        errorCode: 'E0001',
        message: 'The identifier /unsupported is outside the configured identifier space.',
      }));
      expect(InternalServerError.isInstance(error)).toBe(true);
      expect(extractErrorTerms((error as InternalServerError).metadata)).toEqual({ path: '/unsupported' });
    });

    it('errors when attempting to get the parent of a root container.', async(): Promise<void> => {
      expect((): any => strategy.getParentContainer({ path: 'http://example.com/root' }))
        .toThrow('Cannot obtain the parent of http://example.com/root because it is a root container.');
    });
  });

  describe('contains', (): void => {
    it('returns false if container parameter is not a container identifier.', async(): Promise<void> => {
      expect(strategy.contains({ path: 'http://example.com' }, { path: 'http://example.com/foo' }, false)).toBe(false);
    });

    it('returns false if container parameter is longer.', async(): Promise<void> => {
      expect(strategy.contains({ path: 'http://example.com/foo/' }, { path: 'http://example.com' }, false)).toBe(false);
    });

    it('returns false if container parameter is not the direct container.', async(): Promise<void> => {
      expect(strategy.contains({ path: 'http://example.com/' }, { path: 'http://example.com/foo/bar' }, false)).toBe(false);
    });

    it('returns true if the container parameter is the direct container.', async(): Promise<void> => {
      expect(strategy.contains({ path: 'http://example.com/' }, { path: 'http://example.com/foo/' }, false)).toBe(true);
      expect(strategy.contains({ path: 'http://example.com/' }, { path: 'http://example.com/foo' }, false)).toBe(true);
    });

    it('returns true for transtive calls if container parameter is a grandparent.', async(): Promise<void> => {
      expect(strategy.contains({ path: 'http://example.com/' }, { path: 'http://example.com/foo/bar' }, true)).toBe(true);
    });
  });
});

import { SingleRootIdentifierStrategy } from '../../../../src/util/identifiers/SingleRootIdentifierStrategy';

describe('A SingleRootIdentifierStrategy', (): void => {
  const baseUrl = 'http://test.com/';
  const strategy = new SingleRootIdentifierStrategy(baseUrl);

  it('verifies if identifiers are in its domain.', async(): Promise<void> => {
    expect(strategy.supportsIdentifier({ path: 'http://notest.com/' })).toBe(false);
    expect(strategy.supportsIdentifier({ path: baseUrl })).toBe(true);
    expect(strategy.supportsIdentifier({ path: `${baseUrl}foo/bar` })).toBe(true);
  });

  it('checks for the root container by comparing with the base URL.', async(): Promise<void> => {
    expect(strategy.isRootContainer({ path: 'http://notest.com/' })).toBe(false);
    expect(strategy.isRootContainer({ path: baseUrl })).toBe(true);
    expect(strategy.isRootContainer({ path: `${baseUrl}foo/bar` })).toBe(false);
  });
});

import { SubdomainIdentifierStrategy } from '../../../../src/util/identifiers/SubdomainIdentifierStrategy';

describe('A SubdomainIdentifierStrategy', (): void => {
  const baseUrl = 'http://test.com/foo/';
  const strategy = new SubdomainIdentifierStrategy(baseUrl);

  it('supports URLs in its domain.', async(): Promise<void> => {
    expect(strategy.supportsIdentifier({ path: 'http://test.com/foo/' })).toBe(true);
    expect(strategy.supportsIdentifier({ path: 'http://alice.test.com/foo/' })).toBe(true);
    expect(strategy.supportsIdentifier({ path: 'http://a.b.c.test.com/foo/' })).toBe(true);

    expect(strategy.supportsIdentifier({ path: 'http://test.com/foo/bar' })).toBe(true);
    expect(strategy.supportsIdentifier({ path: 'http://alice.test.com/foo/bar' })).toBe(true);
    expect(strategy.supportsIdentifier({ path: 'http://a.b.c.test.com/foo/bar' })).toBe(true);
  });

  it('does not support URLs outside of its domain.', async(): Promise<void> => {
    expect(strategy.supportsIdentifier({ path: 'http://fake.com/http://test.com/foo/' })).toBe(false);
    expect(strategy.supportsIdentifier({ path: 'http://fake.com/test.com/foo/' })).toBe(false);
    expect(strategy.supportsIdentifier({ path: 'http://faketest.com/foo/' })).toBe(false);
    expect(strategy.supportsIdentifier({ path: 'http://test.com/foo' })).toBe(false);
    expect(strategy.supportsIdentifier({ path: 'ftp://test.com/foo/' })).toBe(false);
  });

  it('identifiers the base and all subdomains as root containers.', async(): Promise<void> => {
    expect(strategy.isRootContainer({ path: 'http://test.com/foo/' })).toBe(true);
    expect(strategy.isRootContainer({ path: 'http://alice.test.com/foo/' })).toBe(true);

    expect(strategy.isRootContainer({ path: 'http://test.com/foo/bar' })).toBe(false);
    expect(strategy.isRootContainer({ path: 'http://alice.test.com/foo/bar' })).toBe(false);
  });
});

import { asyncToArray, concat, filter, find, map, reduce, sortedAsyncMerge } from '../../../src/util/IterableUtil';

describe('IterableUtil', (): void => {
  describe('#map', (): void => {
    it('maps the values to a new iterable.', async(): Promise<void> => {
      const input = [ 1, 2, 3 ];
      expect([ ...map(input, (val): number => val + 3) ]).toEqual([ 4, 5, 6 ]);
    });
  });

  describe('#filter', (): void => {
    it('filters the values of the iterable.', async(): Promise<void> => {
      const input = [ 1, 2, 3 ];
      expect([ ...filter(input, (val): boolean => val % 2 === 1) ]).toEqual([ 1, 3 ]);
    });
  });

  describe('#concat', (): void => {
    it('concatenates all the iterables.', async(): Promise<void> => {
      const input = [[ 1, 2, 3 ], [ 4, 5, 6 ], [ 7, 8, 9 ]];
      expect([ ...concat(input) ]).toEqual([ 1, 2, 3, 4, 5, 6, 7, 8, 9 ]);
    });
  });

  describe('#find', (): void => {
    it('finds the matching value.', async(): Promise<void> => {
      const input = [[ 1, 2, 3 ], [ 4, 5, 6 ], [ 7, 8, 9 ]];
      expect(find(input, (entry): boolean => entry.includes(5))).toEqual([ 4, 5, 6 ]);
    });

    it('returns undefined if there is no match.', async(): Promise<void> => {
      const input = [[ 1, 2, 3 ], [ 4, 5, 6 ], [ 7, 8, 9 ]];
      expect(find(input, (entry): boolean => entry.includes(0))).toBeUndefined();
    });
  });

  describe('#reduce', (): void => {
    it('reduces the values in an iterable.', async(): Promise<void> => {
      const input = [ 1, 2, 3 ];
      expect(reduce(input, (acc, cur): number => acc + cur)).toBe(6);
    });

    it('can take a starting value.', async(): Promise<void> => {
      const input = [ 1, 2, 3 ];
      expect(reduce(input, (acc, cur): number => acc + cur, 4)).toBe(10);
    });

    it('throws an error if the iterable is empty and there is no initial value.', async(): Promise<void> => {
      const input: number[] = [];
      expect((): number => reduce(input, (acc, cur): number => acc + cur)).toThrow(TypeError);
    });
  });

  describe('#sortedAsyncMerge', (): void => {
    it('sorts the iterables.', async(): Promise<void> => {
      // eslint-disable-next-line unicorn/consistent-function-scoping
      async function* left(): AsyncIterator<number> {
        yield* [ 1, 3, 5, 7, 9 ];
      }
      // eslint-disable-next-line unicorn/consistent-function-scoping
      async function* right(): AsyncIterator<number> {
        yield* [ 0, 2, 3, 4 ];
      }
      await expect(asyncToArray(sortedAsyncMerge([ left(), right() ]))).resolves
        .toEqual([ 0, 1, 2, 3, 3, 4, 5, 7, 9 ]);
    });

    it('accepts a custom comparator.', async(): Promise<void> => {
      // eslint-disable-next-line unicorn/consistent-function-scoping
      async function* left(): AsyncIterator<string> {
        yield* [ 'apple', 'citrus', 'date' ];
      }
      // eslint-disable-next-line unicorn/consistent-function-scoping
      async function* right(): AsyncIterator<string> {
        yield* [ 'banana', 'donut' ];
      }
      await expect(asyncToArray(sortedAsyncMerge([ left(), right() ]))).resolves
        .toEqual([ 'apple', 'banana', 'citrus', 'date', 'donut' ]);
    });
  });
});

import { EventEmitter } from 'node:events';
import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import { BaseReadWriteLocker } from '../../../../src/util/locking/BaseReadWriteLocker';
import type { ResourceLocker } from '../../../../src/util/locking/ResourceLocker';
import { flushPromises } from '../../../util/Util';

// A simple ResourceLocker that keeps a queue of lock requests
class MemoryLocker implements ResourceLocker {
  private readonly locks: Record<string, (() => void)[]>;

  public constructor() {
    this.locks = {};
  }

  public async acquire(identifier: ResourceIdentifier): Promise<void> {
    const { path } = identifier;
    if (this.locks[path]) {
      return new Promise((resolve): void => {
        this.locks[path].push(resolve);
      });
    }
    this.locks[path] = [];
  }

  public async release(identifier: ResourceIdentifier): Promise<void> {
    const { path } = identifier;
    if (this.locks[path].length > 0) {
      this.locks[path].shift()!();
    } else {
      delete this.locks[path];
    }
  }
}

class SimpleReadWriteLocker extends BaseReadWriteLocker {
  private readonly countMap: Map<string, number>;

  public constructor(resourceLocker: ResourceLocker, countLocker: ResourceLocker) {
    super(resourceLocker, countLocker);
    this.countMap = new Map<string, number>();
  }

  protected getCountLockIdentifier(identifier: ResourceIdentifier): ResourceIdentifier {
    return identifier;
  }

  protected modifyCount(identifier: ResourceIdentifier, mod: number): number {
    const count = (this.countMap.get(identifier.path) ?? 0) + mod;
    this.countMap.set(identifier.path, count);
    return count;
  }
}

/* eslint-disable @typescript-eslint/no-floating-promises */
describe('A BaseReadWriteLocker', (): void => {
  let resourceLocker: ResourceLocker;
  let countLocker: ResourceLocker;
  const resourceId = { path: 'http://test.com/resource' };
  const resource2Id = { path: 'http://test.com/resource2' };
  let locker: BaseReadWriteLocker;

  beforeEach(async(): Promise<void> => {
    resourceLocker = new MemoryLocker();
    countLocker = new MemoryLocker();

    locker = new SimpleReadWriteLocker(resourceLocker, countLocker);
  });

  it('does not block single read operations.', async(): Promise<void> => {
    await expect(locker.withReadLock(resourceId, (): number => 5)).resolves.toBe(5);
  });

  it('does not block single write operations.', async(): Promise<void> => {
    await expect(locker.withWriteLock(resourceId, (): number => 5)).resolves.toBe(5);
  });

  it('does not block multiple read operations.', async(): Promise<void> => {
    const order: string[] = [];
    const emitter = new EventEmitter();

    const unlocks = [ 0, 1, 2 ].map((num): any => new Promise((resolve): any => emitter.on(`release${num}`, resolve)));
    const promises = [ 0, 1, 2 ].map((num): any => locker.withReadLock(resourceId, async(): Promise<number> => {
      order.push(`start ${num}`);
      await unlocks[num];
      order.push(`finish ${num}`);
      return num;
    }));

    // Allow time to attach listeners
    await flushPromises();

    emitter.emit('release2');
    await expect(promises[2]).resolves.toBe(2);
    emitter.emit('release0');
    await expect(promises[0]).resolves.toBe(0);
    emitter.emit('release1');
    await expect(promises[1]).resolves.toBe(1);

    expect(order).toEqual([ 'start 0', 'start 1', 'start 2', 'finish 2', 'finish 0', 'finish 1' ]);
  });

  it('blocks multiple write operations.', async(): Promise<void> => {
    // Previous test but with write locks
    const order: string[] = [];
    const emitter = new EventEmitter();

    const unlocks = [ 0, 1, 2 ].map((num): any => new Promise((resolve): any => emitter.on(`release${num}`, resolve)));
    const promises = [ 0, 1, 2 ].map((num): any => locker.withWriteLock(resourceId, async(): Promise<number> => {
      order.push(`start ${num}`);
      await unlocks[num];
      order.push(`finish ${num}`);
      return num;
    }));

    // Allow time to attach listeners
    await flushPromises();

    emitter.emit('release2');

    // Allow time to finish write 2
    await flushPromises();

    emitter.emit('release0');
    emitter.emit('release1');
    await Promise.all([ promises[2], promises[0], promises[1] ]);
    expect(order).toEqual([ 'start 0', 'finish 0', 'start 1', 'finish 1', 'start 2', 'finish 2' ]);
  });

  it('allows multiple write operations on different resources.', async(): Promise<void> => {
    // Previous test but with write locks
    const order: string[] = [];
    const emitter = new EventEmitter();

    const resources = [ resourceId, resource2Id ];
    const unlocks = [ 0, 1 ].map((num): any => new Promise((resolve): any => emitter.on(`release${num}`, resolve)));
    const promises = [ 0, 1 ].map((num): any => locker.withWriteLock(resources[num], async(): Promise<number> => {
      order.push(`start ${num}`);
      await unlocks[num];
      order.push(`finish ${num}`);
      return num;
    }));

    // Allow time to attach listeners
    await flushPromises();

    emitter.emit('release1');
    await expect(promises[1]).resolves.toBe(1);
    emitter.emit('release0');
    await expect(promises[0]).resolves.toBe(0);

    expect(order).toEqual([ 'start 0', 'start 1', 'finish 1', 'finish 0' ]);
  });

  it('blocks write operations during read operations.', async(): Promise<void> => {
    const order: string[] = [];
    const emitter = new EventEmitter();

    const promRead = new Promise((resolve): any => {
      emitter.on('releaseRead', resolve);
    });

    // We want to make sure the write operation only starts while the read operation is busy
    // Otherwise the internal write lock might not be acquired yet
    const delayedLockWrite = new Promise<void>((resolve): void => {
      emitter.on('readStarted', (): void => {
        locker.withWriteLock(resourceId, (): any => {
          order.push('write');
          resolve();
        });
      });
    });

    const lockRead = locker.withReadLock(resourceId, async(): Promise<void> => {
      emitter.emit('readStarted');
      order.push('read start');
      await promRead;
      order.push('read finish');
    });

    // Allow time to attach listeners
    await flushPromises();

    const promAll = Promise.all([ delayedLockWrite, lockRead ]);

    emitter.emit('releaseRead');
    await promAll;
    expect(order).toEqual([ 'read start', 'read finish', 'write' ]);
  });

  it('allows write operations on different resources during read operations.', async(): Promise<void> => {
    const order: string[] = [];
    const emitter = new EventEmitter();

    const promRead = new Promise((resolve): any => {
      emitter.on('releaseRead', resolve);
    });

    const delayedLockWrite = new Promise<void>((resolve): void => {
      emitter.on('readStarted', (): void => {
        locker.withWriteLock(resource2Id, (): any => {
          order.push('write');
          resolve();
        });
      });
    });

    const lockRead = locker.withReadLock(resourceId, async(): Promise<void> => {
      emitter.emit('readStarted');
      order.push('read start');
      await promRead;
      order.push('read finish');
    });

    // Allow time to attach listeners
    await flushPromises();

    const promAll = Promise.all([ delayedLockWrite, lockRead ]);

    emitter.emit('releaseRead');
    await promAll;
    expect(order).toEqual([ 'read start', 'write', 'read finish' ]);
  });

  it('prioritizes read operations when a read operation is waiting.', async(): Promise<void> => {
    // This test is very similar to the previous ones but adds an extra read lock
    const order: string[] = [];
    const emitter = new EventEmitter();

    const promRead1 = new Promise((resolve): any => emitter.on('releaseRead1', resolve));
    const promRead2 = new Promise((resolve): any => emitter.on('releaseRead2', resolve));

    const delayedLockWrite = new Promise<void>((resolve): void => {
      emitter.on('readStarted', (): void => {
        locker.withWriteLock(resourceId, (): any => {
          order.push('write');
          resolve();
        });
      });
    });

    const delayedLockRead2 = new Promise<void>((resolve): void => {
      emitter.on('readStarted', (): void => {
        locker.withReadLock(resourceId, async(): Promise<void> => {
          order.push('read 2 start');
          await promRead2;
          order.push('read 2 finish');
          resolve();
        });
      });
    });

    const lockRead = locker.withReadLock(resourceId, async(): Promise<void> => {
      emitter.emit('readStarted');
      order.push('read 1 start');
      await promRead1;
      order.push('read 1 finish');
    });

    // Allow time to attach listeners
    await flushPromises();

    const promAll = Promise.all([ delayedLockWrite, lockRead, delayedLockRead2 ]);

    emitter.emit('releaseRead1');

    // Allow time to finish read 1
    await flushPromises();

    emitter.emit('releaseRead2');
    await promAll;
    expect(order).toEqual([ 'read 1 start', 'read 2 start', 'read 1 finish', 'read 2 finish', 'write' ]);
  });

  it('blocks read operations during write operations.', async(): Promise<void> => {
    // Again similar but with read and write order switched
    const order: string[] = [];
    const emitter = new EventEmitter();

    const promWrite = new Promise((resolve): any => {
      emitter.on('releaseWrite', resolve);
    });

    // We want to make sure the read operation only starts while the write operation is busy
    const delayedLockRead = new Promise<void>((resolve): void => {
      emitter.on('writeStarted', (): void => {
        locker.withReadLock(resourceId, (): any => {
          order.push('read');
          resolve();
        });
      });
    });

    const lockWrite = locker.withWriteLock(resourceId, async(): Promise<void> => {
      emitter.emit('writeStarted');
      order.push('write start');
      await promWrite;
      order.push('write finish');
    });

    // Allow time to attach listeners
    await flushPromises();

    const promAll = Promise.all([ delayedLockRead, lockWrite ]);

    emitter.emit('releaseWrite');
    await promAll;
    expect(order).toEqual([ 'write start', 'write finish', 'read' ]);
  });
});

import { EqualReadWriteLocker } from '../../../../src/util/locking/EqualReadWriteLocker';
import type { ResourceLocker } from '../../../../src/util/locking/ResourceLocker';

describe('An EqualReadWriteLocker', (): void => {
  let sourceLocker: ResourceLocker;
  let locker: EqualReadWriteLocker;
  let emptyFn: () => void;
  const identifier = { path: 'http://test.com/res' };

  beforeEach(async(): Promise<void> => {
    emptyFn = jest.fn();

    sourceLocker = {
      acquire: jest.fn(),
      release: jest.fn(),
    };
    locker = new EqualReadWriteLocker(sourceLocker);
  });

  it('locks and unlocks a resource for a read lock.', async(): Promise<void> => {
    const prom = locker.withReadLock(identifier, emptyFn);
    expect(sourceLocker.acquire).toHaveBeenCalledTimes(1);
    expect(sourceLocker.acquire).toHaveBeenLastCalledWith(identifier);
    expect(emptyFn).toHaveBeenCalledTimes(0);
    expect(sourceLocker.release).toHaveBeenCalledTimes(0);

    await expect(prom).resolves.toBeUndefined();
    expect(sourceLocker.acquire).toHaveBeenCalledTimes(1);
    expect(emptyFn).toHaveBeenCalledTimes(1);
    expect(sourceLocker.release).toHaveBeenCalledTimes(1);
    expect(sourceLocker.release).toHaveBeenLastCalledWith(identifier);
  });

  it('locks and unlocks a resource for a write lock.', async(): Promise<void> => {
    const prom = locker.withWriteLock(identifier, emptyFn);
    expect(sourceLocker.acquire).toHaveBeenCalledTimes(1);
    expect(sourceLocker.acquire).toHaveBeenLastCalledWith(identifier);
    expect(emptyFn).toHaveBeenCalledTimes(0);
    expect(sourceLocker.release).toHaveBeenCalledTimes(0);

    await expect(prom).resolves.toBeUndefined();
    expect(sourceLocker.acquire).toHaveBeenCalledTimes(1);
    expect(emptyFn).toHaveBeenCalledTimes(1);
    expect(sourceLocker.release).toHaveBeenCalledTimes(1);
    expect(sourceLocker.release).toHaveBeenLastCalledWith(identifier);
  });

  it('unlocks correctly if the whileLocked function errors.', async(): Promise<void> => {
    emptyFn = jest.fn().mockRejectedValue(new Error('bad data!'));
    const prom = locker.withWriteLock(identifier, emptyFn);
    expect(sourceLocker.acquire).toHaveBeenCalledTimes(1);
    expect(sourceLocker.acquire).toHaveBeenLastCalledWith(identifier);
    expect(emptyFn).toHaveBeenCalledTimes(0);
    expect(sourceLocker.release).toHaveBeenCalledTimes(0);

    await expect(prom).rejects.toThrow('bad data!');
    expect(sourceLocker.acquire).toHaveBeenCalledTimes(1);
    expect(emptyFn).toHaveBeenCalledTimes(1);
    expect(sourceLocker.release).toHaveBeenCalledTimes(1);
    expect(sourceLocker.release).toHaveBeenLastCalledWith(identifier);
  });
});

import { readdir } from 'fs-extra';
import { FileSystemResourceLocker, InternalServerError, joinFilePath } from '../../../../src';
import { getTestFolder, removeFolder } from '../../../integration/Config';

// Due to the nature of using a file locking library, this is a unit test that writes to disk.
// In the future ( = if someone has time) we might want to split this up into a unit test with a `proper-lockfile` mock,
// and an integration test that tests the behaviour of the library.
const rootFilePath = getTestFolder('FileSystemResourceLocker');
const lockFolder = joinFilePath(rootFilePath, '.internal/locks/');

describe('A FileSystemResourceLocker', (): void => {
  let locker: FileSystemResourceLocker;
  const identifier = { path: 'http://test.com/foo' };

  beforeEach(async(): Promise<void> => {
    locker = new FileSystemResourceLocker({ rootFilePath, attemptSettings: { retryCount: 19, retryDelay: 100 }});
    await locker.initialize();
  });

  afterEach(async(): Promise<void> => {
    try {
      // Release to be sure
      await locker.release(identifier);
    } catch {
      // Do nothing
    }
  });

  afterAll(async(): Promise<void> => {
    await locker.finalize();
    await removeFolder(rootFilePath);
  });

  it('can lock and unlock a resource.', async(): Promise<void> => {
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).resolves.toBeUndefined();
  });

  it('can lock and unlock a resource with a locker with indefinite retry.', async(): Promise<void> => {
    const locker2 = new FileSystemResourceLocker({ rootFilePath, attemptSettings: { retryCount: -1 }});
    await expect(locker2.acquire(identifier)).resolves.toBeUndefined();
    await expect(locker2.release(identifier)).resolves.toBeUndefined();
    await locker2.finalize();
  });

  it('can lock a resource again after it was unlocked.', async(): Promise<void> => {
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).resolves.toBeUndefined();
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
  });

  it('errors when unlocking a resource that was not locked.', async(): Promise<void> => {
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).rejects.toThrow(InternalServerError);
    await expect(locker.release(identifier)).rejects.toThrow('Lock is not acquired/owned by you');
  });

  it('errors when max retries has been reached.', async(): Promise<void> => {
    await locker.acquire(identifier);
    await expect(locker.acquire(identifier)).rejects
      .toThrow(
        /Error trying to acquire lock for .*\. The operation did not succeed after the set maximum of tries \(\d+\)\./u,
      );
    await locker.release(identifier);
  });

  it('blocks lock acquisition until they are released.', async(): Promise<void> => {
    const results: number[] = [];
    const lock1 = locker.acquire(identifier);
    const lock2 = locker.acquire(identifier);
    const lock3 = locker.acquire(identifier);

    // Note the different order of calls
    const prom2 = lock2.then(async(): Promise<void> => {
      results.push(2);
      return locker.release(identifier);
    });
    const prom3 = lock3.then(async(): Promise<void> => {
      results.push(3);
      return locker.release(identifier);
    });
    const prom1 = lock1.then(async(): Promise<void> => {
      results.push(1);
      return locker.release(identifier);
    });
    await Promise.all([ prom2, prom3, prom1 ]);
    expect(results[0]).toBe(1);
    expect(results).toContain(2);
    expect(results).toContain(3);
  });

  it('can acquire different keys simultaneously.', async(): Promise<void> => {
    const results: number[] = [];
    const lock1 = locker.acquire({ path: 'path1' });
    const lock2 = locker.acquire({ path: 'path2' });
    const lock3 = locker.acquire({ path: 'path3' });
    await lock2.then(async(): Promise<void> => {
      results.push(2);
      return locker.release({ path: 'path2' });
    });
    await lock3.then(async(): Promise<void> => {
      results.push(3);
      return locker.release({ path: 'path3' });
    });
    await lock1.then(async(): Promise<void> => {
      results.push(1);
      return locker.release({ path: 'path1' });
    });
    expect(results).toEqual([ 2, 3, 1 ]);
  });

  it('throws an error when #tryFn() throws an error.', async(): Promise<void> => {
    await locker.acquire(identifier);
    await expect(locker.acquire(identifier)).rejects.toThrow(InternalServerError);
  });

  it('clears the files in de lock directory upon calling initialize.', async(): Promise<void> => {
    await locker.acquire(identifier);
    await expect(readdir(lockFolder)).resolves.toHaveLength(1);
    await locker.initialize();
    await expect(readdir(lockFolder)).resolves.toHaveLength(0);
  });

  it('stops proper-lock from throwing errors after finalize was called.', async(): Promise<void> => {
    locker = new FileSystemResourceLocker({
      rootFilePath,
      attemptSettings: { retryCount: 19, retryDelay: 100 },
      throwOnCompromise: true,
    });
    // Tests should never access private fields, so we need to change this after splitting the test as mentioned above.
    // Once we have a mock we can check which parameters `unlock` was called with and extract the function from there.
    expect((): void => (locker as any).customOnCompromised(new Error('test'))).toThrow('test');
    await locker.finalize();
    expect((locker as any).customOnCompromised(new Error('test'))).toBeUndefined();
  });

  it('by default does not throw an error if the lock is compromised.', async(): Promise<void> => {
    // See comments above
    expect((locker as any).customOnCompromised(new Error('test'))).toBeUndefined();
    await locker.finalize();
    expect((locker as any).customOnCompromised(new Error('test'))).toBeUndefined();
  });
});

import type { KeyValueStorage } from '../../../../src/storage/keyvalue/KeyValueStorage';
import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { GreedyReadWriteLocker } from '../../../../src/util/locking/GreedyReadWriteLocker';
import type { ResourceLocker } from '../../../../src/util/locking/ResourceLocker';

describe('A GreedyReadWriteLocker', (): void => {
  let resourceLocker: jest.Mocked<ResourceLocker>;
  let storageMap: Map<string, number>;
  let storage: KeyValueStorage<string, number>;
  const resourceId = { path: 'http://test.com/resource' };
  let locker: GreedyReadWriteLocker;

  beforeEach(async(): Promise<void> => {
    resourceLocker = {
      acquire: jest.fn(),
      release: jest.fn(),
    };

    storageMap = new Map<string, number>();
    storage = storageMap as any;

    locker = new GreedyReadWriteLocker(resourceLocker, storage);
  });

  it('deletes count resources once locking is finished.', async(): Promise<void> => {
    await expect(locker.withReadLock(resourceId, (): number => 5)).resolves.toBe(5);
    expect(storageMap.size).toBe(0);
    expect(resourceLocker.acquire).toHaveBeenCalledTimes(3);
    expect(resourceLocker.acquire).toHaveBeenNthCalledWith(1, { path: `${resourceId.path}.read` });
    expect(resourceLocker.acquire).toHaveBeenNthCalledWith(2, resourceId);
    expect(resourceLocker.acquire).toHaveBeenNthCalledWith(3, { path: `${resourceId.path}.read` });
    expect(resourceLocker.release).toHaveBeenCalledTimes(3);
    expect(resourceLocker.release).toHaveBeenNthCalledWith(1, { path: `${resourceId.path}.read` });
    expect(resourceLocker.release).toHaveBeenNthCalledWith(2, resourceId);
    expect(resourceLocker.release).toHaveBeenNthCalledWith(3, { path: `${resourceId.path}.read` });
  });

  it('errors if the read counter has an unexpected value.', async(): Promise<void> => {
    jest.spyOn(storage, 'get').mockResolvedValue(0);
    await expect(locker.withReadLock(resourceId, (): number => 5)).rejects.toThrow(InternalServerError);
  });
});

import { InternalServerError } from '../../../../src/util/errors/InternalServerError';
import { MemoryResourceLocker } from '../../../../src/util/locking/MemoryResourceLocker';

describe('A MemoryResourceLocker', (): void => {
  let locker: MemoryResourceLocker;
  const identifier = { path: 'http://test.com/foo' };

  beforeEach(async(): Promise<void> => {
    locker = new MemoryResourceLocker();
  });

  it('can lock and unlock a resource.', async(): Promise<void> => {
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).resolves.toBeUndefined();
  });

  it('can lock a resource again after it was unlocked.', async(): Promise<void> => {
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).resolves.toBeUndefined();
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
  });

  it('errors when unlocking a resource that was not locked.', async(): Promise<void> => {
    await expect(locker.acquire(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).resolves.toBeUndefined();
    await expect(locker.release(identifier)).rejects.toThrow(InternalServerError);
  });

  it('blocks lock acquisition until they are released.', async(): Promise<void> => {
    const results: number[] = [];
    const lock1 = locker.acquire(identifier);
    const lock2 = locker.acquire(identifier);
    const lock3 = locker.acquire(identifier);

    // Note the different order of calls
    const prom2 = lock2.then(async(): Promise<void> => {
      results.push(2);
      return locker.release(identifier);
    });
    const prom3 = lock3.then(async(): Promise<void> => {
      results.push(3);
      return locker.release(identifier);
    });
    const prom1 = lock1.then(async(): Promise<void> => {
      results.push(1);
      return locker.release(identifier);
    });
    await Promise.all([ prom2, prom3, prom1 ]);
    expect(results).toEqual([ 1, 2, 3 ]);
  });

  it('can acquire different keys simultaneously.', async(): Promise<void> => {
    const results: number[] = [];
    const lock1 = locker.acquire({ path: 'path1' });
    const lock2 = locker.acquire({ path: 'path2' });
    const lock3 = locker.acquire({ path: 'path3' });
    await lock2.then(async(): Promise<void> => {
      results.push(2);
      return locker.release({ path: 'path2' });
    });
    await lock3.then(async(): Promise<void> => {
      results.push(3);
      return locker.release({ path: 'path3' });
    });
    await lock1.then(async(): Promise<void> => {
      results.push(1);
      return locker.release({ path: 'path1' });
    });
    expect(results).toEqual([ 2, 3, 1 ]);
  });
});

