import type { ResourceIdentifier } from '../../../../src/http/representation/ResourceIdentifier';
import type { ReadWriteLocker } from '../../../../src/util/locking/ReadWriteLocker';
import { WrappedExpiringReadWriteLocker } from '../../../../src/util/locking/WrappedExpiringReadWriteLocker';
import type { PromiseOrValue } from '../../../../src/util/PromiseUtil';

jest.useFakeTimers();

describe('A WrappedExpiringReadWriteLocker', (): void => {
  const identifier = { path: 'path' };
  let syncCb: () => string;
  let asyncCb: () => Promise<string>;
  let wrappedLocker: jest.Mocked<ReadWriteLocker>;
  let locker: WrappedExpiringReadWriteLocker;
  const expiration = 1000;

  beforeEach(async(): Promise<void> => {
    wrappedLocker = {
      withReadLock: jest.fn(async<T>(id: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>):
      Promise<T> => whileLocked()) satisfies ReadWriteLocker['withReadLock'] as any,
      withWriteLock: jest.fn(async<T>(id: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>):
      Promise<T> => whileLocked()) satisfies ReadWriteLocker['withWriteLock'] as any,
    };

    syncCb = jest.fn((): string => 'sync');
    asyncCb = jest.fn(async(): Promise<string> => new Promise((resolve): void => {
      setImmediate((): void => resolve('async'));
    }));

    locker = new WrappedExpiringReadWriteLocker(wrappedLocker, expiration);
  });

  it('calls the wrapped locker for locking.', async(): Promise<void> => {
    let prom = locker.withReadLock(identifier, syncCb);
    await expect(prom).resolves.toBe('sync');
    expect(wrappedLocker.withReadLock).toHaveBeenCalledTimes(1);
    expect(wrappedLocker.withReadLock.mock.calls[0][0]).toBe(identifier);

    prom = locker.withWriteLock(identifier, syncCb);
    await expect(prom).resolves.toBe('sync');
    expect(wrappedLocker.withWriteLock).toHaveBeenCalledTimes(1);
    expect(wrappedLocker.withWriteLock.mock.calls[0][0]).toBe(identifier);
  });

  it('calls the functions that need to be locked through the wrapped locker.', async(): Promise<void> => {
    let prom = locker.withReadLock(identifier, syncCb);
    await expect(prom).resolves.toBe('sync');
    expect(syncCb).toHaveBeenCalledTimes(1);

    prom = locker.withReadLock(identifier, asyncCb);

    // Execute promise (without triggering timeout)
    jest.advanceTimersByTime(100);

    await expect(prom).resolves.toBe('async');
    expect(asyncCb).toHaveBeenCalledTimes(1);
  });

  it('throws an error if the locked function resolves too slow.', async(): Promise<void> => {
    async function slowCb(): Promise<void> {
      return new Promise((resolve): any => setTimeout(resolve, 5000));
    }
    const prom = locker.withReadLock(identifier, slowCb);
    jest.advanceTimersByTime(1000);
    await expect(prom).rejects.toThrow(`Lock expired after ${expiration}ms on ${identifier.path}`);
  });

  it('can reset the timer within the locked function.', async(): Promise<void> => {
    async function refreshCb(maintainLock: () => void): Promise<string> {
      return new Promise((resolve): any => {
        setTimeout(maintainLock, 750);
        setTimeout((): void => resolve('refresh'), 1500);
      });
    }
    const prom = locker.withReadLock(identifier, refreshCb);
    jest.advanceTimersByTime(1500);
    await expect(prom).resolves.toBe('refresh');
  });

  it('can still error after resetting the timer.', async(): Promise<void> => {
    async function refreshCb(maintainLock: () => void): Promise<void> {
      return new Promise((resolve): any => {
        setTimeout(maintainLock, 750);
        setTimeout(maintainLock, 1500);
        setTimeout(resolve, 5000);
      });
    }
    const prom = locker.withReadLock(identifier, refreshCb);
    jest.advanceTimersByTime(5000);
    await expect(prom).rejects.toThrow(`Lock expired after ${expiration}ms on ${identifier.path}`);
  });
});

import { setJitterTimeout } from '../../../src/util/LockUtils';

jest.useFakeTimers();

describe('LockUtil', (): void => {
  describe('#setJitterTimout', (): void => {
    it('works without jitter.', async(): Promise<void> => {
      let result = '';
      const promise = setJitterTimeout(1000).then((): void => {
        result += 'ok';
      });
      expect(result).toHaveLength(0);
      jest.advanceTimersByTime(1000);
      await expect(promise).resolves.toBeUndefined();
      expect(result).toBe('ok');
    });

    it('works with jitter.', async(): Promise<void> => {
      jest.spyOn(globalThis.Math, 'random').mockReturnValue(1);
      let elapsed = Date.now();
      const promise = setJitterTimeout(1000, 100).then((): void => {
        elapsed = Date.now() - elapsed;
      });
      jest.runAllTimers();
      await expect(promise).resolves.toBeUndefined();
      expect(elapsed).toBe(1100);
      // Clean up
      jest.spyOn(globalThis.Math, 'random').mockRestore();
    });
  });
});

import { HashMap } from '../../../../src/util/map/HashMap';

type KeyType = { field1: string; field2: number };
type ValueType = { field3: string; field4: number };

function hashFn(key: KeyType): string {
  return `${key.field1}${key.field2}`;
}

describe('A HashMap', (): void => {
  const key1: KeyType = { field1: 'key', field2: 123 };
  const key1Eq: KeyType = { field1: 'key', field2: 123 };
  const key2: KeyType = { field1: 'key', field2: 321 };
  const unknownKey: KeyType = { field1: 'key', field2: 999 };
  const value1: ValueType = { field3: 'value', field4: 123 };
  const value2: ValueType = { field3: 'value', field4: 321 };

  let map: HashMap<KeyType, ValueType>;

  beforeEach(async(): Promise<void> => {
    map = new HashMap(hashFn);

    map.set(key1, value1);
    map.set(key2, value2);
  });

  it('can check if the map has a key.', async(): Promise<void> => {
    expect(map.has(key1)).toBe(true);
    expect(map.has(key1Eq)).toBe(true);
    expect(map.has(key2)).toBe(true);
    expect(map.has(unknownKey)).toBe(false);
  });

  it('can get the values from the map.', async(): Promise<void> => {
    expect(map.get(key1)).toBe(value1);
    expect(map.get(key1Eq)).toBe(value1);
    expect(map.get(key2)).toBe(value2);
    expect(map.get(unknownKey)).toBeUndefined();
  });

  it('can set values.', async(): Promise<void> => {
    map.set(key1Eq, value2);
    expect(map.get(key1)).toBe(value2);
  });

  it('can set values in the constructor.', async(): Promise<void> => {
    map = new HashMap<KeyType, ValueType>(hashFn, [[ key1, value1 ]]);
    expect(map.get(key1)).toBe(value1);
    expect(map.has(key2)).toBe(false);
  });

  it('can remove values.', async(): Promise<void> => {
    map.delete(key1Eq);
    expect(map.has(key1)).toBe(false);
    expect(map.has(key2)).toBe(true);
  });

  it('can clear the map.', async(): Promise<void> => {
    map.clear();
    expect(map.has(key1)).toBe(false);
    expect(map.has(key2)).toBe(false);
  });

  it('can iterate over the map.', async(): Promise<void> => {
    expect([ ...map ]).toEqual([[ key1, value1 ], [ key2, value2 ]]);
    expect([ ...map.entries() ]).toEqual([[ key1, value1 ], [ key2, value2 ]]);
    expect([ ...map.keys() ]).toEqual([ key1, key2 ]);
    expect([ ...map.values() ]).toEqual([ value1, value2 ]);
  });

  it('supports a forEach call.', async(): Promise<void> => {
    const result: string[] = [];
    // eslint-disable-next-line unicorn/no-array-for-each
    map.forEach((value): void => {
      result.push(value.field3);
    });
    expect(result).toEqual([ 'value', 'value' ]);
  });

  it('can return the size.', async(): Promise<void> => {
    expect(map.size).toBe(2);
    map.delete(key1);
    expect(map.size).toBe(1);
    map.clear();
    expect(map.size).toBe(0);
  });

  it('returns a string tag.', async(): Promise<void> => {
    expect(map[Symbol.toStringTag]).toBe('HashMap');
  });
});

import { getDefault, modify } from '../../../../src/util/map/MapUtil';
import { WrappedSetMultiMap } from '../../../../src/util/map/WrappedSetMultiMap';
import { compareMaps } from '../../../util/Util';

describe('MapUtil', (): void => {
  const key1 = 'key1';
  const key2 = 'key2';
  const key3 = 'key3';

  describe('#modify', (): void => {
    it('modifies the map as specified.', async(): Promise<void> => {
      const map = new WrappedSetMultiMap(undefined, [
        [ key1, 123 ],
        [ key2, 123 ],
      ]);
      const add: Iterable<[string, number]> = [[ key1, 456 ], [ key3, 123 ]];
      const remove = [ key2 ];

      const expected = new WrappedSetMultiMap(undefined, [
        [ key1, 123 ],
        [ key1, 456 ],
        [ key3, 123 ],
      ]);

      modify(map, { add, remove });
      compareMaps(map, expected);
    });

    it('defaults to empty add and delete Iterables.', async(): Promise<void> => {
      const map = new WrappedSetMultiMap(undefined, [
        [ key1, 123 ],
        [ key2, 123 ],
      ]);

      const expected = new WrappedSetMultiMap(undefined, [
        [ key1, 123 ],
        [ key2, 123 ],
      ]);

      modify(map, {});
      compareMaps(map, expected);
    });
  });

  describe('#getDefault', (): void => {
    it('returns the value it finds in the Map for the given key.', async(): Promise<void> => {
      const map = new Map([[ key1, 123 ]]);
      expect(getDefault(map, key1, (): number => 999)).toBe(123);
    });

    it('returns the default value if it finds no value for the given key.', async(): Promise<void> => {
      const map = new Map([[ key1, 123 ]]);
      expect(getDefault(map, key2, (): number => 999)).toBe(999);
    });

    it('can handle async default functions.', async(): Promise<void> => {
      const map = new Map([[ key1, 123 ]]);
      await expect(getDefault(map, key2, async(): Promise<number> => 999)).resolves.toBe(999);
    });
  });
});

import { WrappedSetMultiMap } from '../../../../src/util/map/WrappedSetMultiMap';

describe('A WrappedSetMultiMap', (): void => {
  const key = 'key';
  let map: WrappedSetMultiMap<string, number>;

  beforeEach(async(): Promise<void> => {
    map = new WrappedSetMultiMap();
  });

  it('can set values and check their existence.', async(): Promise<void> => {
    expect(map.set(key, 123)).toBe(map);
    expect(map.has(key)).toBe(true);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123 ]));
    expect(map.size).toBe(1);
  });

  it('can set multiple values simultaneously.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456, 789 ]))).toBe(map);
    expect(map.has(key)).toBe(true);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.hasEntry(key, 456)).toBe(true);
    expect(map.hasEntry(key, 789)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123, 456, 789 ]));
    expect(map.size).toBe(3);
  });

  it('overwrites values when setting them.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    expect(map.set(key, new Set([ 456, 789 ]))).toBe(map);
    expect(map.has(key)).toBe(true);
    expect(map.hasEntry(key, 123)).toBe(false);
    expect(map.hasEntry(key, 456)).toBe(true);
    expect(map.hasEntry(key, 789)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 456, 789 ]));
    expect(map.size).toBe(2);
  });

  it('can set entries in the constructor.', async(): Promise<void> => {
    map = new WrappedSetMultiMap(undefined, [[ key, 123 ], [ key, new Set([ 456, 789 ]) ]]);
    expect(map.has(key)).toBe(true);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.hasEntry(key, 456)).toBe(true);
    expect(map.hasEntry(key, 789)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123, 456, 789 ]));
    expect(map.size).toBe(3);
  });

  it('can add a single value.', async(): Promise<void> => {
    expect(map.set(key, 123)).toBe(map);
    expect(map.add(key, 456)).toBe(map);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.hasEntry(key, 456)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123, 456 ]));
    expect(map.size).toBe(2);
  });

  it('can add multiple values.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    expect(map.add(key, 789)).toBe(map);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.hasEntry(key, 456)).toBe(true);
    expect(map.hasEntry(key, 789)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123, 456, 789 ]));
    expect(map.size).toBe(3);
  });

  it('can add a a value to a non-existent key.', async(): Promise<void> => {
    expect(map.add(key, 123)).toBe(map);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123 ]));
    expect(map.size).toBe(1);
  });

  it('correctly updates if the new value already exists.', async(): Promise<void> => {
    expect(map.set(key, 123)).toBe(map);
    expect(map.add(key, 123)).toBe(map);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123 ]));
    expect(map.size).toBe(1);
  });

  it('correctly updates if some new values already exist.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    expect(map.add(key, new Set([ 456, 789 ]))).toBe(map);
    expect(map.hasEntry(key, 123)).toBe(true);
    expect(map.hasEntry(key, 456)).toBe(true);
    expect(map.hasEntry(key, 789)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 123, 456, 789 ]));
    expect(map.size).toBe(3);
  });

  it('removes the key if it is being set to an empty Set.', async(): Promise<void> => {
    expect(map.set(key, 123)).toBe(map);
    expect(map.set(key, new Set())).toBe(map);
    expect(map.has(key)).toBe(false);
    expect(map.size).toBe(0);
  });

  it('can delete a key.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    expect(map.delete(key)).toBe(true);
    expect(map.has(key)).toBe(false);
    expect(map.hasEntry(key, 123)).toBe(false);
    expect(map.hasEntry(key, 456)).toBe(false);
    expect(map.get(key)).toBeUndefined();
    expect(map.delete(key)).toBe(false);
    expect(map.size).toBe(0);
  });

  it('can delete a single entry.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    expect(map.deleteEntry(key, 123)).toBe(true);
    expect(map.has(key)).toBe(true);
    expect(map.hasEntry(key, 123)).toBe(false);
    expect(map.hasEntry(key, 456)).toBe(true);
    expect(map.get(key)).toEqual(new Set([ 456 ]));
    expect(map.deleteEntry(key, 123)).toBe(false);
    expect(map.size).toBe(1);
  });

  it('removes the key if the last entry is deleted.', async(): Promise<void> => {
    expect(map.set(key, 123)).toBe(map);
    expect(map.deleteEntry(key, 123)).toBe(true);
    expect(map.has(key)).toBe(false);
    expect(map.hasEntry(key, 123)).toBe(false);
    expect(map.get(key)).toBeUndefined();
    expect(map.delete(key)).toBe(false);
    expect(map.size).toBe(0);
  });

  it('can clear the entire Map.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    map.clear();
    expect(map.has(key)).toBe(false);
    expect(map.size).toBe(0);
  });

  it('can iterate over the Map.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    expect([ ...map ]).toEqual([[ key, 123 ], [ key, 456 ]]);
    expect([ ...map.entries() ]).toEqual([[ key, 123 ], [ key, 456 ]]);
    expect([ ...map.entrySets() ]).toEqual([[ key, new Set([ 123, 456 ]) ]]);
    expect([ ...map.keys() ]).toEqual([ key, key ]);
    expect([ ...map.distinctKeys() ]).toEqual([ key ]);
    expect([ ...map.values() ]).toEqual([ 123, 456 ]);
    expect([ ...map.valueSets() ]).toEqual([ new Set([ 123, 456 ]) ]);
  });

  it('exposes a readonly view on the internal Map for iteration.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    expect([ ...map.asMap() ]).toEqual([[ key, new Set([ 123, 456 ]) ]]);
  });

  it('supports a forEach call.', async(): Promise<void> => {
    expect(map.set(key, new Set([ 123, 456 ]))).toBe(map);
    const result: number[] = [];
    // eslint-disable-next-line unicorn/no-array-for-each
    map.forEach((value): void => {
      result.push(value);
    });
    expect(result).toEqual([ 123, 456 ]);
  });
});

import { promises as fsPromises } from 'node:fs';
import type { TargetExtractor } from '../../../src/http/input/identifier/TargetExtractor';
import type { ResourceIdentifier } from '../../../src/http/representation/ResourceIdentifier';
import type { HttpRequest } from '../../../src/server/HttpRequest';
import { BadRequestHttpError } from '../../../src/util/errors/BadRequestHttpError';
import { extractErrorTerms } from '../../../src/util/errors/HttpErrorUtil';
import {
  absoluteFilePath,
  createSubdomainRegexp,
  decodeUriPathComponents,
  encodeUriPathComponents,
  ensureLeadingSlash,
  ensureTrailingSlash,
  extractScheme,
  getExtension,
  getModuleRoot,
  getRelativeUrl,
  isContainerIdentifier,
  isContainerPath,
  joinFilePath,
  joinUrl,
  modulePath,
  normalizeFilePath,
  resolveAssetPath,
  resolveModulePath,
  toCanonicalUriPath,
  trimTrailingSlashes,
} from '../../../src/util/PathUtil';

describe('PathUtil', (): void => {
  describe('#normalizeFilePath', (): void => {
    it('normalizes POSIX paths.', (): void => {
      expect(normalizeFilePath('/foo/bar/../baz')).toBe('/foo/baz');
    });

    it('normalizes Windows paths.', (): void => {
      expect(normalizeFilePath('c:\\foo\\bar\\..\\baz')).toBe('c:/foo/baz');
    });
  });

  describe('#joinFilePath', (): void => {
    it('joins POSIX paths.', (): void => {
      expect(joinFilePath('/foo/bar/', '..', '/baz')).toBe('/foo/baz');
    });

    it('joins Windows paths.', (): void => {
      expect(joinFilePath('c:\\foo\\bar\\', '..', '/baz')).toBe(`c:/foo/baz`);
    });
  });

  describe('#absoluteFilePath', (): void => {
    it('does not change absolute posix paths.', (): void => {
      expect(absoluteFilePath('/foo/bar/')).toBe('/foo/bar/');
    });

    it('converts absolute win32 paths to posix paths.', (): void => {
      expect(absoluteFilePath('C:\\foo\\bar')).toBe('C:/foo/bar');
    });

    it('makes relative paths absolute.', (): void => {
      expect(absoluteFilePath('foo/bar/')).toEqual(joinFilePath(process.cwd(), 'foo/bar/'));
    });
  });

  describe('#ensureTrailingSlash', (): void => {
    it('makes sure there is always exactly 1 slash.', (): void => {
      expect(ensureTrailingSlash('http://test.com')).toBe('http://test.com/');
      expect(ensureTrailingSlash('http://test.com/')).toBe('http://test.com/');
      expect(ensureTrailingSlash('http://test.com//')).toBe('http://test.com/');
      expect(ensureTrailingSlash('http://test.com///')).toBe('http://test.com/');
    });
  });

  describe('#trimTrailingSlashes', (): void => {
    it('removes all trailing slashes.', (): void => {
      expect(trimTrailingSlashes('http://test.com')).toBe('http://test.com');
      expect(trimTrailingSlashes('http://test.com/')).toBe('http://test.com');
      expect(trimTrailingSlashes('http://test.com//')).toBe('http://test.com');
      expect(trimTrailingSlashes('http://test.com///')).toBe('http://test.com');
    });
  });

  describe('#ensureLeadingSlash', (): void => {
    it('makes sure there is always exactly 1 slash.', (): void => {
      expect(ensureLeadingSlash('test')).toBe('/test');
      expect(ensureLeadingSlash('/test')).toBe('/test');
      expect(ensureLeadingSlash('//test')).toBe('/test');
      expect(ensureLeadingSlash('///test')).toBe('/test');
    });
  });

  describe('#getExtension', (): void => {
    it('returns the extension of a path.', (): void => {
      expect(getExtension('/a/b.txt')).toBe('txt');
      expect(getExtension('/a/btxt')).toBe('');
    });
  });

  describe('#toCanonicalUriPath', (): void => {
    it('encodes only the necessary parts.', (): void => {
      expect(toCanonicalUriPath('/a%20path&*/name')).toBe('/a%20path%26*/name');
    });

    it('leaves the query string untouched.', (): void => {
      expect(toCanonicalUriPath('/a%20path&/name?abc=def&xyz')).toBe('/a%20path%26/name?abc=def&xyz');
    });
  });

  describe('#decodeUriPathComponents', (): void => {
    it('decodes all parts of a path.', (): void => {
      expect(decodeUriPathComponents('/a%20path&/name')).toBe('/a path&/name');
    });

    it('leaves the query string untouched.', (): void => {
      expect(decodeUriPathComponents('/a%20path&/name?abc=def&xyz')).toBe('/a path&/name?abc=def&xyz');
    });

    it('ignores URL-encoded path separator characters.', (): void => {
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%2F')).toBe('/a path&/c1/c2/t1%2F');
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%5C')).toBe('/a path&/c1/c2/t1%5C');
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%252F')).toBe('/a path&/c1/c2/t1%252F');
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%255C')).toBe('/a path&/c1/c2/t1%255C');
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%25%252F')).toBe('/a path&/c1/c2/t1%%252F');
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%25%255C')).toBe('/a path&/c1/c2/t1%%255C');
    });

    it('normalizes to uppercase encoding.', (): void => {
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%2f')).toBe('/a path&/c1/c2/t1%2F');
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%5c')).toBe('/a path&/c1/c2/t1%5C');
    });

    it('accepts paths with mixed lowercase and uppercase encoding.', (): void => {
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%2F%2f')).toBe('/a path&/c1/c2/t1%2F%2F');
      expect(decodeUriPathComponents('/a%20path&/c1/c2/t1%5C%5c')).toBe('/a path&/c1/c2/t1%5C%5C');
    });

    it('takes sequences of encoded percent signs into account.', (): void => {
      expect(decodeUriPathComponents('/a%2Fb')).toBe('/a%2Fb');
      expect(decodeUriPathComponents('/a%252Fb')).toBe('/a%252Fb');
      expect(decodeUriPathComponents('/a%25252Fb')).toBe('/a%25252Fb');
      expect(decodeUriPathComponents('/a%2525252Fb')).toBe('/a%2525252Fb');
    });

    it('ensures illegal path characters are encoded.', async(): Promise<void> => {
      expect(decodeUriPathComponents('/a<path%3F%3E/*:name?abc=def&xyz'))
        .toBe('/a%3Cpath%3F%3E/%2A%3Aname?abc=def&xyz');
    });
  });

  describe('#encodeUriPathComponents', (): void => {
    it('encodes all parts of a path.', (): void => {
      expect(encodeUriPathComponents('/a%20path&/name')).toBe('/a%2520path%26/name');
    });

    it('leaves the query string untouched.', (): void => {
      expect(encodeUriPathComponents('/a%20path&/name?abc=def&xyz')).toBe('/a%2520path%26/name?abc=def&xyz');
    });

    it('does not double-encode URL-encoded path separator characters.', (): void => {
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%2F')).toBe('/a%2520path%26/c1/c2/t1%2F');
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%5C')).toBe('/a%2520path%26/c1/c2/t1%5C');
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%252F')).toBe('/a%2520path%26/c1/c2/t1%252F');
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%255C')).toBe('/a%2520path%26/c1/c2/t1%255C');
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%%252F')).toBe('/a%2520path%26/c1/c2/t1%25%252F');
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%%255C')).toBe('/a%2520path%26/c1/c2/t1%25%255C');
    });

    it('normalizes to uppercase encoding.', (): void => {
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%2f')).toBe('/a%2520path%26/c1/c2/t1%2F');
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%5c')).toBe('/a%2520path%26/c1/c2/t1%5C');
    });

    it('accepts paths with mixed lowercase and uppercase encoding.', (): void => {
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%2F%2f')).toBe('/a%2520path%26/c1/c2/t1%2F%2F');
      expect(encodeUriPathComponents('/a%20path&/c1/c2/t1%5C%5c')).toBe('/a%2520path%26/c1/c2/t1%5C%5C');
    });

    it('takes sequences of encoded percent signs into account.', (): void => {
      expect(encodeUriPathComponents('/a%2Fb')).toBe('/a%2Fb');
      expect(encodeUriPathComponents('/a%252Fb')).toBe('/a%252Fb');
      expect(encodeUriPathComponents('/a%25252Fb')).toBe('/a%25252Fb');
      expect(encodeUriPathComponents('/a%2525252Fb')).toBe('/a%2525252Fb');
    });
  });

  describe('#isContainerPath', (): void => {
    it('returns true if the path ends with a slash.', (): void => {
      expect(isContainerPath('/a/b')).toBe(false);
      expect(isContainerPath('/a/b/')).toBe(true);
    });
  });

  describe('#isContainerIdentifier', (): void => {
    it('works af isContainerPath but for identifiers.', (): void => {
      expect(isContainerIdentifier({ path: '/a/b' })).toBe(false);
      expect(isContainerIdentifier({ path: '/a/b/' })).toBe(true);
    });
  });

  describe('#extractScheme', (): void => {
    it('splits a URL.', (): void => {
      expect(extractScheme('http://test.com/foo')).toEqual({ scheme: 'http://', rest: 'test.com/foo' });
    });
  });

  describe('#getRelativeUrl', (): void => {
    const baseUrl = 'http://test.com/foo/';
    const request: HttpRequest = { url: '/resource' } as any;
    let targetExtractor: jest.Mocked<TargetExtractor>;

    beforeEach((): void => {
      targetExtractor = {
        handleSafe: jest.fn(({ request: req }): ResourceIdentifier => ({ path: joinUrl(baseUrl, req.url) })),
      } as any;
    });

    it('returns the relative path.', async(): Promise<void> => {
      await expect(getRelativeUrl(baseUrl, request, targetExtractor)).resolves.toBe('/resource');
    });

    it('errors if the target is outside of the server scope.', async(): Promise<void> => {
      targetExtractor.handleSafe.mockResolvedValueOnce({ path: 'http://somewhere.else/resource' });
      let error: unknown;
      try {
        await getRelativeUrl(baseUrl, request, targetExtractor);
      } catch (err: unknown) {
        error = err;
      }
      expect(error).toEqual(expect.objectContaining({ errorCode: 'E0001' }));
      expect(BadRequestHttpError.isInstance(error)).toBe(true);
      expect(extractErrorTerms((error as BadRequestHttpError).metadata)).toEqual({ path: 'http://somewhere.else/resource' });
    });
  });

  describe('#createSubdomainRegexp', (): void => {
    it('creates a regex to match the URL and extract a subdomain.', (): void => {
      const regex = createSubdomainRegexp('http://test.com/foo/');
      expect(regex.exec('http://test.com/foo/')![1]).toBeUndefined();
      expect(regex.exec('http://test.com/foo/bar')![1]).toBeUndefined();
      expect(regex.exec('http://alice.test.com/foo/')![1]).toBe('alice');
      expect(regex.exec('http://alice.bob.test.com/foo/')![1]).toBe('alice.bob');
      expect(regex.exec('http://test.com/')).toBeNull();
      expect(regex.exec('http://alicetest.com/foo/')).toBeNull();
    });
  });

  describe('#getModuleRoot', (): void => {
    it('returns the root folder of the module.', async(): Promise<void> => {
      // Note that this test only makes sense as long as the dist folder is on the same level as the src folder
      const root = getModuleRoot();
      const packageJson = joinFilePath(root, 'package.json');
      await expect(fsPromises.access(packageJson)).resolves.toBeUndefined();
    });
  });

  describe('#modulePath', (): void => {
    it('transforms the empty input into "@css:".', (): void => {
      expect(modulePath()).toBe('@css:');
    });

    it('prefixes a path with "@css".', (): void => {
      expect(modulePath('foo/bar.json')).toBe('@css:foo/bar.json');
    });
  });

  describe('#resolveModulePath', (): void => {
    it('transforms the empty input into the module root path.', (): void => {
      expect(resolveModulePath()).toBe(getModuleRoot());
    });

    it('prefixes a path with the module root path.', (): void => {
      expect(resolveModulePath('foo/bar.json')).toBe(`${getModuleRoot()}foo/bar.json`);
    });
  });

  describe('#resolveAssetPath', (): void => {
    it('interprets paths relative to the module root when starting with "@css:".', (): void => {
      expect(resolveAssetPath('@css:foo/bar')).toBe(joinFilePath(getModuleRoot(), '/foo/bar'));
    });

    it('handles ../ paths with "@css":.', (): void => {
      expect(resolveAssetPath('@css:foo/bar/../baz')).toBe(joinFilePath(getModuleRoot(), '/foo/baz'));
    });

    it('leaves absolute paths as they are.', (): void => {
      expect(resolveAssetPath('/foo/bar/')).toBe('/foo/bar/');
    });

    it('handles other paths relative to the cwd.', (): void => {
      expect(resolveAssetPath('foo/bar/')).toBe(joinFilePath(process.cwd(), 'foo/bar/'));
    });

    it('handles other paths with ../.', (): void => {
      expect(resolveAssetPath('foo/bar/../baz')).toBe(joinFilePath(process.cwd(), 'foo/baz'));
    });
  });
});

import { promiseSome } from '../../../src/util/PromiseUtil';

describe('PromiseUtil', (): void => {
  describe('#promiseSome', (): void => {
    const resultTrue = Promise.resolve(true);
    const resultFalse = Promise.resolve(false);
    const resultError = Promise.reject(new Error('generic error'));
    const resultInfinite = new Promise<boolean>((): void => { /* Empty */ });

    it('returns false if no promise is provided.', async(): Promise<void> => {
      await expect(promiseSome([])).resolves.toBe(false);
    });

    it('returns false if no promise returns true.', async(): Promise<void> => {
      await expect(promiseSome([ resultFalse, resultFalse, resultFalse ])).resolves.toBe(false);
    });

    it('returns true if at least a promise returns true.', async(): Promise<void> => {
      await expect(promiseSome([ resultFalse, resultTrue, resultFalse ])).resolves.toBe(true);
    });

    it('does not propagate errors.', async(): Promise<void> => {
      await expect(promiseSome([ resultError, resultFalse, resultFalse ])).resolves.toBe(false);
    });

    it('works with a combination of promises.', async(): Promise<void> => {
      await expect(promiseSome([ resultError, resultTrue, resultInfinite ])).resolves.toBe(true);
    });
  });
});

import 'jest-rdf';
import { DataFactory, Store } from 'n3';
import { parseQuads, serializeQuads, solveBgp, termToInt, uniqueQuads } from '../../../src/util/QuadUtil';
import { guardedStreamFrom, readableToString } from '../../../src/util/StreamUtil';
import variable = DataFactory.variable;

const { literal, namedNode, quad } = DataFactory;

describe('QuadUtil', (): void => {
  describe('#serializeQuads', (): void => {
    it('converts quads to the requested format.', async(): Promise<void> => {
      const quads = [ quad(
        namedNode('pre:sub'),
        namedNode('pre:pred'),
        literal('obj'),
      ) ];
      const stream = serializeQuads(quads, 'application/n-triples');
      await expect(readableToString(stream)).resolves.toMatch('<pre:sub> <pre:pred> "obj" .');
    });
  });

  describe('#parseQuads', (): void => {
    it('parses quads.', async(): Promise<void> => {
      const stream = guardedStreamFrom([ '<pre:sub> <pre:pred> "obj".' ]);
      await expect(parseQuads(stream)).resolves.toEqualRdfQuadArray([ quad(
        namedNode('pre:sub'),
        namedNode('pre:pred'),
        literal('obj'),
      ) ]);
    });

    it('parses quads with the given options.', async(): Promise<void> => {
      const stream = guardedStreamFrom([ '<> <pre:pred> "obj".' ]);
      await expect(parseQuads(stream, { baseIRI: 'pre:sub' })).resolves.toEqualRdfQuadArray([ quad(
        namedNode('pre:sub'),
        namedNode('pre:pred'),
        literal('obj'),
      ) ]);
    });
  });

  describe('#uniqueQuads', (): void => {
    it('filters out duplicate quads.', async(): Promise<void> => {
      const quads = [
        quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
        quad(namedNode('ex:s2'), namedNode('ex:p2'), namedNode('ex:o2')),
        quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
      ];
      expect(uniqueQuads(quads)).toBeRdfIsomorphic([
        quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
        quad(namedNode('ex:s2'), namedNode('ex:p2'), namedNode('ex:o2')),
      ]);
    });
  });

  describe('#termToInt', (): void => {
    it('returns undefined if the input is undefined.', async(): Promise<void> => {
      expect(termToInt()).toBeUndefined();
    });

    it('converts the term to a number.', async(): Promise<void> => {
      expect(termToInt(namedNode('5'))).toBe(5);
      expect(termToInt(namedNode('0xF'), 16)).toBe(15);
    });
  });

  describe('#solveBgp', (): void => {
    it('finds all matching bindings.', async(): Promise<void> => {
      const bgp = [
        quad(namedNode('ex:s1'), namedNode('ex:p1'), variable('v1')),
        quad(variable('v1'), namedNode('ex:p2'), variable('v2')),
        quad(variable('v1'), variable('v3'), variable('v2')),
      ];
      const data = new Store([
        quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o1')),
        quad(namedNode('ex:o1'), namedNode('ex:p2'), namedNode('ex:o2')),
        quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o2')),
        quad(namedNode('ex:o2'), namedNode('ex:p2'), namedNode('ex:o2')),
        quad(namedNode('ex:s1'), namedNode('ex:p1'), namedNode('ex:o3')),
        quad(namedNode('ex:o4'), namedNode('ex:p2'), namedNode('ex:o2')),
      ]);
      const bindings = solveBgp(bgp, data);
      expect(bindings).toHaveLength(2);
      expect(bindings[0]).toEqual({
        v1: namedNode('ex:o1'),
        v2: namedNode('ex:o2'),
        v3: namedNode('ex:p2'),
      });
      expect(bindings[1]).toEqual({
        v1: namedNode('ex:o2'),
        v2: namedNode('ex:o2'),
        v3: namedNode('ex:p2'),
      });
    });
  });
});

