import type { Logger } from '../../../src/logging/Logger';
import { setSafeInterval } from '../../../src/util/TimerUtil';
import { flushPromises } from '../../util/Util';

jest.useFakeTimers();

describe('TimerUtil', (): void => {
  describe('#setSafeInterval', (): void => {
    let logger: jest.Mocked<Logger>;
    let callback: jest.Mock;

    beforeEach(async(): Promise<void> => {
      logger = { error: jest.fn() } as any;
      callback = jest.fn();
    });

    it('creates a working interval.', async(): Promise<void> => {
      const timer = setSafeInterval(logger, 'message', callback, 1000, 'argument');

      jest.advanceTimersByTime(1000);

      expect(callback).toHaveBeenCalledTimes(1);
      expect(callback).toHaveBeenLastCalledWith('argument');
      expect(logger.error).toHaveBeenCalledTimes(0);

      clearInterval(timer);
    });

    it('logs an error if something went wrong in the callback.', async(): Promise<void> => {
      const timer = setSafeInterval(logger, 'message', callback, 1000, 'argument');
      callback.mockImplementationOnce((): never => {
        throw new Error('callback error');
      });

      jest.advanceTimersByTime(1000);

      expect(callback).toHaveBeenCalledTimes(1);
      expect(callback).toHaveBeenLastCalledWith('argument');
      expect(logger.error).toHaveBeenCalledTimes(1);
      expect(logger.error).toHaveBeenLastCalledWith('Error during interval callback: message - callback error');

      clearInterval(timer);
    });

    it('correctly handles errors in async callbacks.', async(): Promise<void> => {
      const promCallback = jest.fn().mockRejectedValue(new Error('callback error'));
      const timer = setSafeInterval(logger, 'message', promCallback, 1000, 'argument');

      jest.advanceTimersByTime(1000);
      await flushPromises();

      expect(promCallback).toHaveBeenCalledTimes(1);
      expect(logger.error).toHaveBeenCalledTimes(1);
      expect(logger.error).toHaveBeenLastCalledWith('Error during interval callback: message - callback error');

      clearInterval(timer);
    });
  });
});

import { DataFactory } from 'n3';
import { createVocabulary, extendVocabulary } from '../../../src/util/Vocabularies';

describe('Vocabularies', (): void => {
  const vocabulary = createVocabulary('http://www.w3.org/ns/ldp#', 'contains', 'Container');

  describe('createVocabulary', (): void => {
    it('contains its own URI.', (): void => {
      expect(vocabulary.namespace).toBe('http://www.w3.org/ns/ldp#');
    });

    it('contains its own URI as a term.', (): void => {
      expect(vocabulary.terms.namespace).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#'));
    });

    it('exposes the defined URIs.', (): void => {
      expect(vocabulary.contains).toBe('http://www.w3.org/ns/ldp#contains');
      expect(vocabulary.Container).toBe('http://www.w3.org/ns/ldp#Container');
    });

    it('exposes the defined URIs as terms.', (): void => {
      expect(vocabulary.terms.contains).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#contains'));
      expect(vocabulary.terms.Container).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#Container'));
    });
  });

  describe('extendVocabulary', (): void => {
    const extended = extendVocabulary(vocabulary, 'extended', 'extra');

    it('still contains all the original values.', async(): Promise<void> => {
      expect(extended.namespace).toBe('http://www.w3.org/ns/ldp#');
      expect(extended.terms.namespace).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#'));
      expect(extended.contains).toBe('http://www.w3.org/ns/ldp#contains');
      expect(extended.Container).toBe('http://www.w3.org/ns/ldp#Container');
      expect(extended.terms.contains).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#contains'));
      expect(extended.terms.Container).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#Container'));
    });

    it('contains the new values.', async(): Promise<void> => {
      expect(extended.extended).toBe('http://www.w3.org/ns/ldp#extended');
      expect(extended.extra).toBe('http://www.w3.org/ns/ldp#extra');
      expect(extended.terms.extended).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#extended'));
      expect(extended.terms.extra).toEqual(DataFactory.namedNode('http://www.w3.org/ns/ldp#extra'));
    });

    it('does not modify the original vocabulary.', async(): Promise<void> => {
      expect((vocabulary as any).extended).toBeUndefined();
    });
  });
});

import { joinUrl } from '../../src/util/PathUtil';

export type User = {
  email: string;
  password: string;
  webId?: string;
  podName: string;
  settings?: Record<string, unknown>;
};

/**
 * Registers an account for the given user details and creates one or more pods.
 *
 * @param baseUrl - Base URL of the server.
 * @param user - User details to register.
 */
export async function register(baseUrl: string, user: User):
Promise<{ pod: string; webId: string; authorization: string; controls: any }> {
  // Get controls
  let res = await fetch(joinUrl(baseUrl, '.account/'));
  let { controls } = await res.json();

  // Create account
  res = await fetch(controls.account.create, { method: 'POST' });
  expect(res.status).toBe(200);
  const authorization = `CSS-Account-Token ${(await res.json()).authorization}`;

  // Get account controls
  res = await fetch(controls.account.create, {
    headers: { authorization },
  });
  if (res.status !== 200) {
    throw new Error(`Error creating account: ${await res.text()}`);
  }
  const json = await res.json();
  ({ controls } = json);

  // Add login method
  res = await fetch(controls.password.create, {
    method: 'POST',
    headers: { authorization, 'content-type': 'application/json' },
    body: JSON.stringify({
      email: user.email,
      password: user.password,
    }),
  });
  if (res.status !== 200) {
    throw new Error(`Error adding login method: ${await res.text()}`);
  }

  // Create pod(s)
  res = await fetch(controls.account.pod, {
    method: 'POST',
    headers: { authorization, 'content-type': 'application/json' },
    body: JSON.stringify({ name: user.podName, settings: { webId: user.webId, ...user.settings }}),
  });
  if (res.status !== 200) {
    throw new Error(`Error creating pod: ${await res.text()}`);
  }

  return { ...await res.json(), controls, authorization };
}

import type { ResourceStore } from '../../src/';
import { BasicRepresentation } from '../../src/';
import type { AclPermissionSet } from '../../src/authorization/permissions/AclPermissionSet';

export type AclHelperInput = {
  permissions: AclPermissionSet;
  agentClass?: 'agent' | 'authenticated';
  agent?: string;
  accessTo?: boolean;
  default?: boolean;
};

export class AclHelper {
  public readonly store: ResourceStore;

  public constructor(store: ResourceStore) {
    this.store = store;
  }

  public async setSimpleAcl(
    resource: string,
    options: AclHelperInput | AclHelperInput[],
  ): Promise<void> {
    options = Array.isArray(options) ? options : [ options ];

    const acl: string[] = [
      '@prefix   acl:  <http://www.w3.org/ns/auth/acl#>.\n',
      '@prefix  foaf:  <http://xmlns.com/foaf/0.1/>.\n',
    ];

    for (const [ i, option ] of options.entries()) {
      acl.push(`\n<http://test.com/#auth${i}> a acl:Authorization`);

      if (!option.agentClass && !option.agent) {
        throw new Error('At least one of agentClass or agent have to be provided.');
      }
      if (!option.accessTo && !option.default) {
        throw new Error('At least one of accessTo or default have to be true.');
      }

      for (const perm of [ 'Read', 'Append', 'Write', 'Control' ]) {
        if (option.permissions[perm.toLowerCase() as keyof AclPermissionSet]) {
          acl.push(`;\n acl:mode acl:${perm}`);
        }
      }
      if (option.accessTo) {
        acl.push(`;\n acl:accessTo <${resource}>`);
      }
      if (option.default) {
        acl.push(`;\n acl:default <${resource}>`);
      }
      if (option.agentClass) {
        acl.push(
          `;\n acl:agentClass ${
            option.agentClass === 'agent' ? 'foaf:Agent' : 'foaf:AuthenticatedAgent'
          }`,
        );
      }
      if (option.agent) {
        acl.push(`;\n acl:agent ${option.agent}`);
      }

      acl.push('.');
    }

    await this.store.setRepresentation({ path: `${resource}.acl` }, new BasicRepresentation(acl, 'text/turtle'));
  }
}

import type { IAccessControl, IAccessControlledResource, IMatcher, IPolicy } from '@solid/access-control-policy';
import { v4 } from 'uuid';
import { BasicRepresentation } from '../../src/http/representation/BasicRepresentation';
import type { ResourceIdentifier } from '../../src/http/representation/ResourceIdentifier';
import type { ResourceStore } from '../../src/storage/ResourceStore';
import { joinUrl } from '../../src/util/PathUtil';

export type CreateMatcherInput = { publicAgent: true } | { agent: string };

export type CreatePolicyInput = {
  allow?: Iterable<'read' | 'append' | 'write' | 'control'>;
  deny?: Iterable<'read' | 'append' | 'write' | 'control'>;
  allOf?: Iterable<IMatcher>;
  anyOf?: Iterable<IMatcher>;
  noneOf?: Iterable<IMatcher>;
};

export type CreateAcrInput = {
  resource: string | ResourceIdentifier;
  policies?: Iterable<IPolicy>;
  memberPolicies?: Iterable<IPolicy>;
};

const baseUrl = 'http://acp.example.com/';

/**
 * Helper class for setting permissions through ACP.
 */
export class AcpHelper {
  public readonly store: ResourceStore;

  public constructor(store: ResourceStore) {
    this.store = store;
  }

  public createMatcher(input: CreateMatcherInput): IMatcher {
    return {
      iri: joinUrl(baseUrl, v4()),
      // Prefixed URI as this will be inserted into turtle below
      agent: (input as any).publicAgent ? [ 'acp:PublicAgent' ] : [ (input as any).agent ],
      client: [],
      issuer: [],
      vc: [],
    };
  }

  public createPolicy({ allow, deny, allOf, anyOf, noneOf }: CreatePolicyInput): IPolicy {
    return {
      iri: joinUrl(baseUrl, v4()),
      // Using the wrong identifiers so the turtle generated below uses the prefixed version
      allow: new Set(this.convertModes(allow ?? []) as any),
      deny: new Set(this.convertModes(deny ?? []) as any),
      allOf: [ ...allOf ?? [] ],
      anyOf: [ ...anyOf ?? [] ],
      noneOf: [ ...noneOf ?? [] ],
    };
  }

  private* convertModes<T extends string>(modes: Iterable<T>):
  Iterable<`acl:${Capitalize<T>}`> {
    for (const mode of modes) {
      // Node.js typings aren't fancy enough yet to correctly type this
      yield `acl:${mode.charAt(0).toUpperCase() + mode.slice(1)}` as any;
    }
  }

  public createAcr({ resource, policies, memberPolicies }: CreateAcrInput): IAccessControlledResource {
    return {
      iri: (resource as ResourceIdentifier).path ?? resource,
      accessControlResource: {
        iri: joinUrl(baseUrl, v4()),
        accessControl: policies ?
            [{
              iri: joinUrl(baseUrl, v4()),
              policy: [ ...policies ],
            }] :
            [],
        memberAccessControl: memberPolicies ?
            [{
              iri: joinUrl(baseUrl, v4()),
              policy: [ ...memberPolicies ],
            }] :
            [],
      },
    };
  }

  public async setAcp(
    id: string | ResourceIdentifier,
    resources: IAccessControlledResource[] | IAccessControlledResource,
  ): Promise<void> {
    const turtle = this.toTurtle(resources);
    await this.store.setRepresentation(
      { path: `${(id as ResourceIdentifier).path ?? id}.acr` },
      new BasicRepresentation(turtle, 'text/turtle'),
    );
  }

  public toTurtle(resources: IAccessControlledResource[] | IAccessControlledResource): string {
    if (!Array.isArray(resources)) {
      resources = [ resources ];
    }
    const result: string[] = [
      '@prefix acp: <http://www.w3.org/ns/solid/acp#>.',
      '@prefix acl: <http://www.w3.org/ns/auth/acl#>.',
    ];

    const added = new Set<string>();
    const acs: IAccessControl[] = [];
    const policies: IPolicy[] = [];
    const matchers: IMatcher[] = [];

    for (const resource of resources) {
      result.push(`<${resource.accessControlResource.iri}> a acp:AccessControlResource`);
      result.push(`  ; acp:resource <${resource.iri}>`);
      for (const key of [ 'accessControl', 'memberAccessControl' ] as const) {
        if (resource.accessControlResource[key].length > 0) {
          result.push(`  ; acp:${key} ${resource.accessControlResource[key].map((ac): string => {
            acs.push(ac);
            return `<${ac.iri}>`;
          }).join(', ')}`);
        }
      }
      result.push('  .');
    }

    for (const ac of acs) {
      if (added.has(ac.iri)) {
        continue;
      }

      result.push(`<${ac.iri}> a acp:AccessControl`);
      result.push(`  ; acp:apply ${ac.policy.map((policy): string => {
        policies.push(policy);
        return `<${policy.iri}>`;
      }).join(', ')}`);
      result.push('  .');
      added.add(ac.iri);
    }

    for (const policy of policies) {
      if (added.has(policy.iri)) {
        continue;
      }

      const { policyString, requiredMatchers } = this.policyToTurtle(policy);
      result.push(policyString);
      matchers.push(...requiredMatchers);
      added.add(policy.iri);
    }

    for (const matcher of matchers) {
      if (added.has(matcher.iri)) {
        continue;
      }

      result.push(this.matcherToTurtle(matcher));
      added.add(matcher.iri);
    }

    return result.join('\n');
  }

  private policyToTurtle(policy: IPolicy): { policyString: string; requiredMatchers: IMatcher[] } {
    const result: string[] = [];

    result.push(`<${policy.iri}> a acp:Policy`);

    for (const key of [ 'allow', 'deny' ] as const) {
      if (policy[key].size > 0) {
        result.push(`  ; acp:${key} ${[ ...policy[key] ].join(', ')}`);
      }
    }

    const requiredMatchers: IMatcher[] = [];
    for (const key of [ 'allOf', 'anyOf', 'noneOf' ] as const) {
      if (policy[key].length > 0) {
        result.push(`  ; acp:${key} ${policy[key].map((matcher): string => {
          requiredMatchers.push(matcher);
          return `<${matcher.iri}>`;
        }).join(', ')}`);
      }
    }

    result.push('  .');

    return { policyString: result.join('\n'), requiredMatchers };
  }

  private matcherToTurtle(matcher: IMatcher): string {
    const result: string[] = [];

    result.push(`<${matcher.iri}> a acp:Matcher`);
    for (const key of [ 'agent', 'client', 'issuer', 'vc' ] as const) {
      if (matcher[key].length > 0) {
        result.push(`  ; acp:${key} ${matcher[key].join(', ')}`);
      }
    }
    result.push('  .');

    return result.join('\n');
  }
}

import 'jest-rdf';
import type { Response } from 'cross-fetch';
import fetch from 'cross-fetch';
import type { Quad } from 'n3';
import { Parser } from 'n3';
import { isContainerPath } from '../../src/util/PathUtil';
import { LDP } from '../../src/util/Vocabularies';

/**
 * This is specifically for GET requests which are expected to succeed.
 */
export async function getResource(
  url: string,
  options?: { accept?: string },
  expected?: { contentType?: string },
): Promise<Response> {
  const isContainer = isContainerPath(url);
  const response = await fetch(url, { headers: options });
  expect(response.status).toBe(200);
  expect(response.headers.get('link')).toContain(`<${LDP.Resource}>; rel="type"`);
  expect(response.headers.get('link')).toContain(`<${url}.acl>; rel="acl"`);

  if (isContainer) {
    expect(response.headers.get('link')).toContain(`<${LDP.Container}>; rel="type"`);
    expect(response.headers.get('link')).toContain(`<${LDP.BasicContainer}>; rel="type"`);
  } else {
    expect(response.headers.get('accept-patch')).toBe('text/n3, application/sparql-update');
  }
  if (expected?.contentType) {
    expect(response.headers.get('content-type')).toBe(expected.contentType);
  } else if (isContainer) {
    expect(response.headers.get('content-type')).toBe('text/turtle');
  }

  return response;
}

/**
 * This is specifically for PUT requests which are expected to succeed.
 */
export async function putResource(url: string, options: { contentType: string; body?: string; exists?: boolean }):
Promise<Response> {
  const init: RequestInit = {
    method: 'PUT',
    headers: { 'content-type': options.contentType },
    body: options.body,
  };
  if (isContainerPath(url)) {
    (init.headers as Record<string, string>).link = '<http://www.w3.org/ns/ldp#Container>; rel="type"';
  }
  const response = await fetch(url, init);
  expect(response.status).toBe(options.exists ? 205 : 201);
  if (!options.exists) {
    expect(response.headers.get('location')).toBe(url);
  }
  await expect(response.text()).resolves.toHaveLength(0);
  return response;
}

export type CreateOptions = {
  contentType: string;
  isContainer?: boolean;
  slug?: string;
  body?: string;
};
/**
 * This is specifically for POST requests which are expected to succeed.
 */
export async function postResource(container: string, options: CreateOptions): Promise<Response> {
  const init: RequestInit = {
    method: 'POST',
    headers: { 'content-type': options.contentType },
    body: options.body,
  };
  if (options.isContainer) {
    (init.headers as Record<string, string>).link = '<http://www.w3.org/ns/ldp#Container>; rel="type"';
  }
  if (options.slug) {
    (init.headers as Record<string, string>).slug = options.slug;
  }
  const response = await fetch(container, init);
  await expect(response.text()).resolves.toHaveLength(0);
  expect(response.status).toBe(201);
  const regex = new RegExp(`^${container}[^/]+${options.isContainer ? '/' : ''}`, 'u');
  expect(response.headers.get('location')).toMatch(regex);
  return response;
}

/**
 * This is specifically for PATCH requests which are expected to succeed.
 */
export async function patchResource(url: string, query: string, type: 'sparql' | 'n3', exists?: boolean):
Promise<Response> {
  const contentTypes = { sparql: 'application/sparql-update', n3: 'text/n3' };
  const response = await fetch(url, {
    method: 'PATCH',
    headers: {
      'content-type': contentTypes[type],
    },
    body: query,
  });
  await expect(response.text()).resolves.toHaveLength(0);
  expect(response.status).toBe(exists ? 205 : 201);
  if (!exists) {
    expect(response.headers.get('location')).toBe(url);
  }

  return response;
}

export async function deleteResource(url: string): Promise<void> {
  let response = await fetch(url, { method: 'DELETE' });
  expect(response.status).toBe(205);
  response = await fetch(url);
  expect(response.status).toBe(404);
}

/**
 * Verifies if the body of the given Response contains the expected Quads.
 * If `exact` is true, a 1-to-1 match is expected, if not, the expected quads should be a subset of the body.
 */
export async function expectQuads(response: Response, expected: Quad[], exact?: boolean): Promise<void> {
  const parser = new Parser({ baseIRI: response.url });
  const quads = parser.parse(await response.text());
  if (exact) {
    expect(quads).toBeRdfIsomorphic(expected);
  } else {
    for (const expectedQuad of expected) {
      expect(quads.some((entry): boolean => entry.equals(expectedQuad))).toBe(true);
    }
  }
}

import { fetch } from 'cross-fetch';

/**
 * Subscribes to a notification channel.
 *
 * @param type - The type of the notification channel, e.g., "NOTIFY.WebhookChannel2023".
 * @param webId - The WebID to spoof in the authorization header. This assumes the config uses the debug auth import.
 * @param subscriptionUrl - The subscription URL to which the request needs to be sent.
 * @param topic - The topic to subscribe to.
 * @param features - Any extra fields that need to be added to the subscription body.
 */
export async function subscribe(
  type: string,
  webId: string,
  subscriptionUrl: string,
  topic: string,
  features: Record<string, unknown> = {},
): Promise<unknown> {
  const channel = {
    '@context': [ 'https://www.w3.org/ns/solid/notification/v1' ],
    type,
    topic,
    ...features,
  };

  const response = await fetch(subscriptionUrl, {
    method: 'POST',
    headers: { authorization: `WebID ${webId}`, 'content-type': 'application/ld+json' },
    body: JSON.stringify(channel),
  });
  expect(response.status).toBe(200);
  expect(response.headers.get('content-type')).toBe('application/ld+json');
  const jsonResponse = await response.json();
  expect(jsonResponse.type).toBe(type);
  return jsonResponse;
}

/**
 * Verifies if a notification has the expected format.
 *
 * @param notification - The (parsed) notification.
 * @param topic - The topic of the notification.
 * @param type - What type of notification is expected.
 */
export function expectNotification(notification: unknown, topic: string, type: string): void {
  const expected: any = {
    '@context': [
      'https://www.w3.org/ns/activitystreams',
      'https://www.w3.org/ns/solid/notification/v1',
    ],
    id: expect.stringContaining(topic),
    type,
    object: topic,
    published: expect.anything(),
  };
  if (type !== 'Delete') {
    expected.state = expect.anything();
  }
  expect(notification).toEqual(expected);
}

import { setGlobalLoggerFactory } from '../../src/logging/LogUtil';
